(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["540"] = {"atoms": {"540.1": {"x": [[1, "/\r\rأصول الإيمان\rعبد القاهر أبو منصور التميمي 429\rترجمة المؤلف (1)\rهو عبد القاهر بن طاهر بن محمد بن عبد الله التميمي أبو منصور الفقيه الشافعي. ولد ببغداد ونشأ بها وسافر مع أبيه إلى خراسان وسكنا بنيسابور إلى أن ماتا.\rتفقه أبو منصور علي أبي إسحاق إبراهيم بن محمد الأسفراييني. وقرأ عليه أصول الدين، وكان ماهرا في فنون عديدة خصوصا في علم الحساب. وله تواليف نافعة منها كتاب (التكملة) وكان يدرس في سبعة وعشرين فنا، وكان عارفا بالفرائض والنحو والشعر، وكان ذا مال وثروة ولم يكتسب بعلمه مالا، وأربى على أقرانه في الفنون، وجلس بعد أستاذه أبي إسحاق للإملاء في مسجد عقيل، فأملى سنين واختلف إليه الأئمة فقرءوا عليه مثل ناصر المروزي وزين الإسلام القشيري، وتوفي سنة عشرين وأربعمائة، وأكثر المصادر على أن وفاته كانت سنة 429 بمدينة إسفرايين ودفن إلى جانب شيخه رحمهما الله تعالى.\rومن شعره:\rطلبت من الحبيب زكاة حسن ... على صغر من الحسن البهي ...\rفقال: وهل على مثلي زكاة ... على قول العراقي الزكي ...\rفقلت: الشافعي لنا إمام ... وقد فرض الزكاة على الصبي\r__________________\r(1) عن فوات الوفيات والذيل عليها لمحمد بن شاكر الكتبي (764) تحقيق د. إحسان عباس ج 2 ص 371/ 372.\r\rوهذا مثل قول الأمير أبي الفضل الميكالي:\rأقول لشاذان في الحسن فرد ... يصيد بلحظة قلب الكمي ...\rملكت الحسن أجمع في نصاب ... ناد زكاة منظرك البهي ...\rوذاك بأن تجود لمستهام ... برشف من مقبلك الشهي ...\rفقال: أبو حنيفة لي إمام ... وعندي لا زكاة على الصبي\r\rوتممها سيدنا ومولانا قاضي القضاة تقي الدين السبكي (أدام الله أيامه) بقوله:\rفقال: اذهب إذن فاقبض زكاتي ... برأي الشافعي من الوليّ ...\rفقلت فديتك من فقيه ... أيطلب بالوفاء سوى المليّ ...\rنصاب الحسن عندك ذو امتناع ... بلحظك والقوام السمهري ...\rفإن أعطيتنا طوعا وإلا ... أخذناه بقول الحنبلي\r\rومن شعر أبي منصور:\rشبابي وشيبتي دليلا رحيلي ... مسمعا لذاك وذا من دليل ..."], [2, "وقد مات من كان لي عديل ... وحسبي دليلا رحيل العديل\r\rومنه أيضا:\rيا سائلي عن قصتي ... دعني أمت في غصتي ...\rأعال في أيدي الورى ... واليأس منه حصّتي\r\rومن تصانيفه:\r1 ـ تفسير القرآن.\r2 ـ تأويل متشابه الأخبار.\r3 ـ فضائح المعتزلة.\r4 ـ الكلام في الوعد والوعيد.\r5 ـ الفاخر في الأوائل والأواخر.\r6 ـ إبطال القول بالتولد.\r7 ـ فضائح الكرامية.\r\r8 ـ معيار النظر.\r9 ـ تغفيل الفقير الصابر على الغني الشاكر.\r10 ـ الإيمان وأصوله.\r11 ـ الملل والنحل.\r12 ـ التحصيل في أصول الفقه.\r13 ـ الفرق بين الفرق.\r14 ـ بلوغ المدى في أصول الهدى.\r15 ـ نفي خلق القرآن.\r16 ـ الصفات.\r\rبسم الله الرّحمن الرّحيم\rالحمد لله ذي الحكم البوالغ والنعم السوابغ والنّقم الدوامغ والصلاة والسلام على ذي الفضائل والفواضل محمد وآله الافضال.\rقال الاستاذ أبو منصور عبد القاهر بن طاهر التميمي البغدادي رحمة الله عليه: هذا كتاب ذكرنا فيه خمسة عشر أصلا من أصول الدين وشرحنا كل أصل منها بخمس عشرة مسألة من مسائل العدل والتوحيد والوعد والوعيد وما يليق بها من مسائل النبوّات والمعجزات وشروط الإمامة والزعامة من الأولياء وأهل الكرامة وأشرنا في كل مسألة منها إلى أصولها بالتحصيل دون التطويل ليكون مجموعها للعالم تذكرة وللمتعلم تبصرة بعون الله وتوفيقه.\rذكر الأصول الخمسة عشر\r"]], "pg": [1, 2]}, "540.2": {"x": [[2, "الأصل الأول: في بيان الحقائق والعلوم على الخصوص والعموم.\r"]], "pg": [2, 2]}, "540.3": {"x": [[2, "الأصل الثاني: في حدوث العالم على أقسامه من أعراضه وأجسامه.\r"]], "pg": [2, 2]}, "540.4": {"x": [[2, "الأصل الثالث: في معرفة صانع العالم ونعوته في ذاته.\r"]], "pg": [2, 2]}, "540.5": {"x": [[2, "الأصل الرابع: في معرفة صفاته القائمة بذاته.\r"]], "pg": [2, 2]}, "540.6": {"x": [[2, "الأصل الخامس: في معرفة أسمائه وأوصافه.\r"]], "pg": [2, 2]}, "540.7": {"x": [[2, "الأصل السادس: في معرفة عدله وحكمه.\r"]], "pg": [2, 2]}, "540.8": {"x": [[2, "الأصل السابع: في معرفة رسله وأنبيائه.\r\r"]], "pg": [2, 2]}, "540.9": {"x": [[2, "الأصل الثامن: في معرفة معجزات أنبيائه وكرامات أوليائه.\r"]], "pg": [2, 2]}, "540.10": {"x": [[2, "الأصل التاسع: في معرفة أركان شريعة الإسلام.\r"]], "pg": [2, 2]}, "540.11": {"x": [[2, "الأصل العاشر: في معرفة أحكام التكليف في الأمر والنهي والخبر."]], "pg": [2, 2]}, "540.12": {"x": [[3, "الأصل الحادي عشر: في معرفة أحكام العباد في المعاد.\r"]], "pg": [3, 3]}, "540.13": {"x": [[3, "الأصل الثاني عشر: في بيان أصول الإيمان.\r"]], "pg": [3, 3]}, "540.14": {"x": [[3, "الأصل الثالث عشر: في بيان أحكام الإمامة وشروط الزعامة.\r"]], "pg": [3, 3]}, "540.15": {"x": [[3, "الأصل الرابع عشر: في معرفة أحكام العلماء والأئمة.\rالأصل الخامس عشر: في بيان أحكام الكفر وأهل الأهواء الفجرة.\r"]], "pg": [3, 3]}, "540.16": {"x": [[3, "فهذه جملة أصول الدين على قواعد فريقي الرّأي والحديث دون من يشتري لهو الحديث، وقد جاءت في الشريعة أحكام مرتبة على خمسة عشر من العدد. وأجمعت الأمة على بعضها واختلفوا في بعضها. فمنها على اختلاف سنّ البلوغ لأنها عند الشافعيّ في الذكور والإناث خمس عشرة سنة بسني العرب دون سني الروم والعجم. ومنها مدة أكثر الحيض عند الشافعي وفقهاء المدينة خمسة عشر يوما بلياليها. ومنها أول الطهر الفاصل بين الحيضتين فإنه عند أكثر الأئمة خمسة عشر وهذا كله على أصل الشافعي وموافقيه. فأما على أصل أبي حنيفة رحمه الله وأتباعه فإن كلمات الأذان عندهم خمس عشرة. ومقدار مدة الإقامة التي توجب عنده إتمام الصلاة خمسة عشر يوما وعند الشافعي أربعة أيام. وأجمعوا على وجوب خمسة عشر درهما في زكاة ستمائة درهم وخمسة عشر دينارا في زكاة ستمائة دينار. فإذا بلغت الإبل السائمة ستمائة وجب فيها خمس عشرة بنت لبون أو اثنا عشر من الحقاق. وإذا بلغت البقر السائمة ستمائة وجب فيها خمس عشرة مسنّة أو عشرون تبيعا أو تبيعة. فإن كانت أربعمائة وخمسين بقرة وجب خمسة عشر تبيعا أو تبيعة. وأجمعوا على أن الواجب في منقّلة الرجل الحرّ خمس عشرة من"], [4, "الإبل وفي ثلاثة من أسنان الرجل الحر خمسة عشر بعيرا وفي ستة من أسنان المرأة خمسة عشر بعيرا وفي ثلاث أصابع المرأة الحرّة خمسة عشر بعيرا. ومثل هذا كثير من أحكام الشريعة ولأجلها لم يكره تقسيم قواعد الدين على خمسة عشر أصلا وتقسيم كل منها خمس عشرة مسألة. فاشتمل الكتاب لأجل ذلك على مائتين وخمس وعشرين مسألة في كل مسألة منها المذهب والخلاف. وأشرنا فيها إلى نصرة الحق بدليل يكشف عنه على الإيجاز من غير تطويل بحمد الله ومنته.\r\rذكر الأصل الأول\rفي بيان الحقائق والعلوم على الخصوص والعلوم\rهذا الأصل مشتمل على خمس عشرة مسألة هذه ترجمتها:\rمسألة في بيان حد العلم وحقيقته. مسألة في إثبات العلوم والحقائق. مسألة في أن لعلوم معان [قائمة بالعلماء] غير العلماء. مسألة في أقسام العلوم وأنواعها [وأساميها]. مسألة في بيان أقسام الحواس. مسألة في إثبات النظر والاستدلال. مسألة في أن الخبر المتواتر يوجب العلم. مسألة في أقسام الأخبار على التفصيل. مسألة في أقسام العلوم النظرية. مسألة في بيان مأخذ العلوم الشرعية [الشريفة]. مسألة في شروط الأخبار. مسألة في بيان ما يعلم بالعقل قبل الشرع وما لا يعلم إلا بالشرع. مسألة في شروط العلوم والإدراكات. مسألة في بيان ما يصح تعلق العلم به. مسألة في صحة ورود التكليف بالعلوم والمعارف.\rفهذه مسائل الأصل من الأول من اصول هذا الكتاب وسنذكر في كل مسألة منها مقتضاها إن شاء الله تعالى.\rالمسألة الأولى من الأصل الأول\r"]], "pg": [3, 4]}, "540.17": {"x": [[4, "في حد العلم وحقيقته\rاختلفوا في حد العلم وحقيقته: فمن أصحابنا من قال: العلم صفة يصير الحي بها عالما خلاف قول من أجاز وجود العلم في الأموات والجمادات كما ذهب إليه الصالحيّ والكرامية وخلاف قول القدرية في دعواها أن الله عالم بلا علم وخلاف قول من يزعم أن العلم وكلّ موجد أجسام لا صفات. ومن أصحابنا من"], [5, "قال: إن العلم صفة تصح بها من الحي القادر إحكام الفعل وإتقانه. وفائدة هذا القول إبطال قول القدرية في دعواها أن كثيرا من الأفعال المحكمة المتقنة يقع ممن لا علم له بها على سبيل التولّد. واختلفت القدرية في حد العلم: فزعم الكعبي إنه اعتقاد الشيء على ما هو به وزعم الجبائيّ أنه اعتقاد الشيء على ما هو به عن ضرورة أو دلالة وزعم ابنه أبو هاشم أنه اعتقاد الشيء على ما هو به مع سكون النفس إليه. وهذه الحدود الثلاثة منتقضة بالعلم باستحالة المحالات فإن العلم بها ليس هو علم بشيء لأن المحال ليس بشيء ومع ذلك يتعلق العلم بكون المحال محالا وإن كان ليس بشيء بالاتفاق لأن المعدوم عندهم إنما يكون شيئا إذا كان جائز الوجود مثل الجوهر والعرض فأما ما يستحيل وجوده فلا يكون شيئا مثل الزوجة والأولاد والشريك لله تعالى. وقيل لهم أيضا لو كان العلم اعتقادا على وجه مخصوص لوجب أن يكون كلّ عالم معتقدا والله سبحانه وتعالى عالم وليس بمعتقد فبطل تحديد العلم بالاعتقاد. وزعم النظّام أن العلم حركة من حركات القلب والإرادة عنده من حركات القلب أيضا. فقد خلط العلم بالإرادة مع اختلاف جنسهما.\rالمسألة الثانية من هذا الأصل\r"]], "pg": [4, 5]}, "540.18": {"x": [[5, "في إثبات العلم والحقائق\rوالخلاف في هذه المسألة مع السوفسطائية. وهم فرق:\rـ فرقة زعمت أنه لا حقيقة لشيء ولا علم بشيء وهؤلاء معاندون وينبغي أن يعاملوا بالضرب والتأديب وأخذ الأموال منهم فإذا اشتكوا من ألم الضرب وطالبوا أموالهم قيل لهم إن لم يكن لكم ولا لأموالكم حقيقة لما تشتكون من الألم فما هذا الضّجر ولم تطلبون ما لا حقيقة له؟ وقيل لهم: هل لنفي الحقائق حقيقة؟ فإن قالوا: نعم، أثبتوا بعض الحقائق وإن قالوا لا قيل لهم إذا لم يكن لنفي الحقائق حقيقة ولم يصحّ نفيها فقد صح ثبوتها وقيل لهم هل تعلمون أنه لا علم فإن قالوا"], [6, "نعم فقد أثبتوا علما وعالما ومعلوما وإن قالوا: لا نعلم أنه لا علم قيل لم حكمتم بأن لا علم وأنتم لا تعلمون أنه لا علم له.\rـ والفرقة الثانية منهم: أهل شك قالوا: لا نعلم هل للأشياء والعلوم حقائق أم لا حقائق. وهؤلاء إن شكّوا في وجود أنفسهم لحقوا بالفرقة الأولى منهم وإن علموا وجود أنفسهم فقد أثبتوا بعض الحقائق.\rـ والفرقة الثالثة منهم: قالوا للأشياء حقائق تابعة للاعتقادات وزعموا أن كل من اعتقد شيئا فمعتقده على ما اعتقده وهؤلاء يلزمهم أن يكون العالم قديما محدثا لأن قوما اعتقدوا حدوثه وآخرين اعتقدوا قدمه ويلزمهم أن يكون قولهم باطلا لاعتقادنا بطلان قولهم إن كانت الاعتقادات كلها صحيحة بزعمهم. ويسألون عن اعتقاد المعاندين من السوفسطائية فإن زعموا أن اعتقادهم لنفي الحقائق اعتقاد صحيح لحقوا بهم وإن أبطلوا اعتقادهم نقضوا قولهم بتصحيح الاعتقادات كلها.\rالمسألة الثالثة من هذا الأصل الأول\r"]], "pg": [5, 6]}, "540.19": {"x": [[6, "في أن العلوم معان [قائمة بالعلماء]\rوالخلاف في هذه المسألة مع نفاة الأعراض من الدهرية ومع الأصمّ من جملة القدرية فإنه وافق الأعراض في نفي الأعراض. وهؤلاء كلّهم ينفون العلم ويثبتون كلّ عالم بلا علم وكلّ متحرك ومتلون متحركا ومتلونا بلا حركة ولا لون. ودليلنا عليهم أنّا وجدنا العالم منّا عالما مرة وغير عالم مرة ولا يجوز أن يكون عالما بنفسه لوجود نفسه في أحوال لا يكون فيها عالما فوجب لذلك أن يكون إنما صار عالما لمعنى سواه وذلك المعنى هو المراد بقولنا علم فمن أثبته ونازعنا في اسمه فالخلاف معه في العبارة. فبهذا الدليل أثبتنا سائر الأعراض.\rالمسألة الرابعة من الأصل الأول\r"]], "pg": [6, 6]}, "540.20": {"x": [[6, "في بيان أقسام العلوم وأسمائها\rالعلوم عندنا قسمان: أحدهما علم الله تعالى وهو علم قديم ليس بضروري"], [7, "ولا مكتسب ولا واقع عن حسّ ولا عن فكر ونظر وهو مع ذلك محيط بجميع المعلومات على التفصيل والله عالم بكل ما كان وكل ما يكون وكل ما لا يكون أن لو كان كيف كان يكون بعلم واحد أزليّ غير حادث. والقسم الثاني من قسمي العلوم: علوم الناس وسائر الحيوانات وهي ضربان: ضروري ومكتسب. والفرق بينهما من جهة قدرة العالم على علمه المكتسب واستدلاله عليه ووقوع الضروري فيه من غير استدلال منه ولا قدرة له عليه.\rوالعلم الضروري قسمان: أحدهما علم بديهيّ والثاني علم حسيّ. والبديهيّ قسمان: أحدهما علم بديهيّ في الإثبات كعلم العالم منا بوجود نفسه وبما يجد في نفسه من ألم ولذة وجوع وعطش وحرّ وبرد وغمّ وفرح ونحو ذلك. والثاني: علم بديهيّ في النفي كعلم العالم منا باستحالة المحالات وذلك كعلمه بأنّ شيئا واحدا لا يكون قديما ومحدثا وأن الشخص لا يكون حيا وميتا في حال واحدة وإن العالم بالشيء لا يكون جاهلا به من الوجه الذي علمه في حال واحدة.\rوأما العلوم الحسية فمدركة من جهة الحواس الخمس كما نبيّنها بعد هذا. والعلوم النظرية نوعان: عقليّ وشرعيّ. وكل واحد منهما مكتسب للعالم به واقع له باستدلال منه عليه وبعضها أجلى من بعض كما نثبته بعد هذا إن شاء الله تعالى.\rالمسألة الخامسة من الأصل الأول\r"]], "pg": [6, 7]}, "540.21": {"x": [[7, "في أقسام الحواس وفوائدها\rالحواس عند أصحابنا وأكثر العقلاء خمس يدرك بها العلوم الحسية.\rأولاها: حاسّة البصر ويدرك بها الأجسام والألوان وحسن التركيب في الصّور ويجوز عندنا إدراك كل موجود بها خلاف قول من قال من المعتزلة أنه لا يدرك بها الا الأجسام والألوان كما ذهب إليه أبو هاشم بن الجبائي [و] خلاف قول الجبائي أنه لا يدرك بها إلا الأجسام والألوان والأكوان وخلاف قول من زعم من الفلاسفة أن البصر لا يدرك به شيء غير اللون.\r\rوالحاسة الثانية: حاسة السمع ويدرك بها الكلام والأصوات كلها.\rوالثالثة: حاسة الذوق ويدرك بها الطعوم."], [8, "والرابعة: حاسة الشمّ ويدرك بها الروائح.\rوالخامسة: حاسة اللمس ويدرك بها الجسم والحرارة والبرودة والرطوبة واليبوسة واللين والخشونة. وادّعى قوم أن الذوق من جملة حاسة اللمس. وزاد النظّام حاسة أخرى يدرك بها لذة النكاح وقوله في هذا كقول من يدعي حاسة سابعة يدرك بها الم الضرب والجراح (1).\rواختلف أصحابنا في الفاضل من العلوم الحسية والنظرية: فقدّم أبو العباس القلانسي العلوم النظرية على الحسية وقدّم أبو الحسن الأشعري العلوم الحسية على العلوم النظرية لأنها أصول لها. واختلفوا في الفاضل من حاسّتي السمع والبصر: فزعمت الفلاسفة أن السمع أفضل من البصر لأنه يدرك بالسمع من الجهات الست وفي الضوء والظلمة ولا يدرك بالبصر عندهم إلا من جهة المقابلة وبواسطة من ضياء شعاع. وقال أكثر المتكلمين بتفضيل البصر على السمع لأن السمع لا يدرك به إلا الصوت والكلام والبصر يدرك به الأجسام والألوان والهيئات كلها. ويجوز عندنا إدراك جميع الموجودات بالبصر وأجاز أصحابنا الإدراك بالبصر من الجهات الست كما نثبته بعد هذا إن شاء الله تعالى\rالمسألة السادسة من هذا الأصل الأول\r"]], "pg": [7, 8]}, "540.22": {"x": [[8, "في إثبات العلوم النظرية\rوالخلاف في هذه المسألة مع السّمنيّة الذين زعموا أنه لا يعلم شيء إلا من طريق الحواس الخمس وأبطلوا العلوم النظرية وزعموا أن المذاهب كلها باطلة، ويلزمهم على هذا القول إبطال مذهبهم لأن القول بإبطال المذهب مذهب. وقلنا لهم: بما ذا عرفتم صحة مذهبكم؟ فإن قالوا: بالنظر والاستدلال لزمهم إثبات النظر\r__________________\r(1) [وكلا القولين فاسد.]."], [9, "والاستدلال طريقا إلى العلم بصحة شيء ما، وهذا خلاف قولهم، وإن قالوا: بالحس قيل لهم: إن العلوم بالحس يشترك في معرفته أهل الحواس السليمة فما بالنا لا نعرف صحة قولكم بحواسنا؟ فإن قالوا: إنكم قد عرفتم صحة قولنا بالحس ولكنكم جحدتم ما عرفتموه لم ينفصلوا (1) ممن عكس عليهم هذه الدعوى وقال لهم بل أنتم عارفون بصحة قول مخالفيكم وفساد قولكم بالضرورة الحسية لكنكم جحدتم ما عرفتموه حسّا وإذا تعارض القولان بطلا وصح أن الطريق إلى العلم بصحة الأديان إنما هو النظر والاستدلال.\rالمسألة السابعة من الأصل الأول\r"]], "pg": [8, 9]}, "540.23": {"x": [[9, "في إثبات الخبر المتواتر طريقا إلى العلم\rوالخلاف في هذه المسألة من وجهين: أحدهما مع البراهمة والسّمنيّة في إنكارهما وقوع العلم من جهة الأخبار المتواترة ويكذّبهم في ذلك علمهم بالبلدان التي لم يدخلوها والأمم والملوك الماضية وبظهور المدّعين للنبوات (2) فإنهم وإن نازعوا في صدقهم عالمون بظهورهم وظهور دعاويهم وعلمهم بذلك كله ضروري لا شك لهم فيه ولا طريق لهم إليه إلا من جهة الخبر المتواتر الذي لا يصح التواطي عليه. والخلاف الثاني: مع قوم أثبتوا وقوع العلم من جهة التواتر لكنهم زعموا أن العلم الواقع عنه يكون مكتسبا لا ضروريا. ودليل كونه ضروريا امتناع وقوع الشك في المعلوم به كما يمتنع ذلك في المعلوم بالحواس والبداءة.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [9, 9]}, "540.24": {"x": [[9, "في بيان أقسام الأخبار\rوالأخبار عندنا على ثلاثة أقسام: تواتر وآحاد ومتوسط بينهما مستفيض جار مجرى التواتر في بعض أحكامه.\r__________________\r(1) [لم يتفصوا].\r(2) [ومع النظامية حيث قالوا يجوز ان يجتمع الأمة على الخطباء فإن الأخبار المتواترة لا حجة فيها لأنها يجوز ان يكون وقوعها كذبا فطعنوا في الصحابة وابطلوا القياس في الشريعة]."], [10, "فالمتواتر هو الذي يستحيل التواطؤ على وضعه وهو موجب للعلم الضروري بصحة مخبره. وأخبار الآحاد متى صح إسنادها وكانت متونها غير مستحيلة في العقل كانت موجبة للعمل بها دون العلم وكانت بمنزلة شهادة العدول عند الحاكم يلزمه الحكم بها في الظاهر وإن لم يعلم صدقهم في الشهادة.\rوأما المتوسط بين التواتر والآحاد فإنه شارك التواتر في إيجابه للعلم والعمل ويفارقه من حيث أن العلم الواقع عنه يكون مكتسبا والعلم الواقع عن التواتر ضروري غير مكتسب. وهذا النوع المستفيض المتوسط بين التواتر والآحاد على أقسام:\rأحدهما: خبر من دلّت المعجزة على صدقه كأخبار الأنبياء عليهم السلام.\rوالثاني: خبر من أخبر عن صدقه صاحب معجزة.\rوالثالث: خبر رواه في الأصل قوم ثقات ثم انتشر بعدهم رواته في الأعصار حتى بلغوا حدّ التواتر (1) كالأخبار في الرؤية والشفاعة والحوض والميزان والرجم والمسح على الخفين وعذاب القبر ونحوه. والقسم الرابع منه: خبر من أخبار الآحاد في كل عصر قد أجمعت الأمّة على الحكم به كالخبر في أن لا وصية لوارث وفي أن لا ينكح المرأة على عمّتها ولا على خالتها وفي أن السارق لما دون النصاب ومن غير حرز لا يقطع. ولا اعتبار في مثل هذا بخلاف أهل الأهواء من الروافض والقدرية والخوارج والجهمية والنجارية لأن أهل الأهواء لا اعتبار بخلافهم في أحكام الفقه وإن اعتبرنا خلافهم في أبواب علم الكلام (2).\rواعلموا أسعدكم الله أن الخبر في أصله منقسم إلى صدق وكذب. والصدق منه واقع على وفق مخبره والكذب ما كان بخلاف مخبره. وليس في الأخبار ما هو صدق كذب معا إلّا خبر واحد وهو إخبار من لم يكذب قطّ عن نفسه بأنه كاذب\r__________________\r(1) [وإن كانوا في العصر الأول محصورين ومن هذا الجنس أخبار الرؤية]\r(2) [وكل انواع هذا المستفيض موجب للعمل والعلم المكتسب]"], [11, "وإن هذا الخبر كذب منه والكاذب إذا أخبر عن نفسه بأنه كاذب كان صادقا فصار هذا الخبر الواحد صدقا وكذبا وفاعله واحد. وفيه دليل على إبطال قول الثنويّة إنّ فاعل الصدق لا يجوز أن يكون فاعلا للكذب.\rالمسألة التاسعة من الأصل الأول\r"]], "pg": [9, 11]}, "540.25": {"x": [[11, "في بيان أقسام العلوم النظرية\rالعلوم النظرية على أربعة أقسام:\rأحدها: استدلال بالعقل من جهة القياس والنظر.\rالثاني: معلوم من جهة التجارب والعادات.\rوالثالث: معلوم من جهة الشرع.\rوالرابع: معلوم من جهة الإلهام في بعض الناس أو بعض الحيوانات دون بعض. فأما المعلوم بالنظر والاستدلال من جهة العقول العلم بحدوث العالم وقدم صانعه وتوحيده وصفاته وعدله وحكمته وجواز ورود التكليف منه على عباده وصحة نبوة رسله بالاستدلال عليها بمعجزاتهم ونحو ذلك من المعارف العقلية النظرية. وأما المعلوم بالتجارب والرياضات فكعلم الطبّ في الأدوية والمعالجات وكذلك العلم بالحرف والصناعات، وقد يقع في هذا النوع ما يستدرك (1) بالقياس على المعتاد غير أن أصولها مأخوذة عن التجارب والعادات. وأما المعلوم بالشرع فكالعلم بالحلال والحرام والواجب والمسنون والمكروه (2).\rوإنما أضيف العلوم الشرعية إلى النظر لأن صحة الشريعة مبنية على صحة النبوة وصحة النبوة معلومة من طريق النظر والاستدلال ولو كانت معلومة بالضرورة من حسّ أو بديهة لما اختلف فيها أهل الحواس والبديهة ولما صار المخالف فيها\r__________________\r(1) [يستدل]\r(2) (وسائر أحكام الفقه]"], [12, "معاندا كالسوفسطائية المنكرة للمحسوسات. وأما المعلوم بالإلهام على التخصيص فكالعلم بذوق الشعر وأوزان أبياته في بحوره وقد يعلم هذا الوزن أعرابيّ بوّال على عقبيه ويذهب عن معرفته حكيم يعرف قوانين أكثر العلوم النظرية وقد احتال أهل العروض في استنباط أصول عرفوا بها أوزان بحور الشعر غير أن الشعر قد طبع على ذوق من لم يعرف العروض ولا القياس في بابه وما ذاك إلّا تخصيص من الله تعالى له به. وكذلك العلم بصناعة الألحان غير مستنبط بالقياس ولا مدرك بالضرورة التي يشترك فيها العقلاء ولكنها من الخصائص التي يعلمها قوم دون قوم. وكل علم نظري يجوز عندنا أن يجعل الله ضروريا فينا على قلب هذه العادة كما خلق في آدم عليه السلام علوما ضرورية عرف بها الأسماء من غير استدلال منه عليها ولا قراءة منه لها في كتاب، كذلك القول في سائر العلوم النظرية عندنا وأما المعلوم بالضرورة فمن أصحابنا من قال: يجوز أن يعلمها كلها بالنظر والاستدلال ومنهم من قال ما علمناه منها بالحواس الخمس فجائز استدراكه بالاستدلال عليه عند غيبته عن الحس وما علمناه بالبديهة فلا يصح الاستدلال عليه لأن البداءة مقدّمات الاستدلال فلا بد من حصولها في المستدلّ قبل استدلاله. هذا قول أصحابنا، وزعم النظّام وأتباعه من القدرية أن المعلوم بالقياس والنظر لا يجوز أن يصير معلوما بالضرورة، وما كان معلوما بحس لا يجوز أن يصير معلوما من جهة النظر والخبر، فلزمه على هذا القول أن يكون المعرفة بالله عزوجل في الآخرة نظرية استدلالية غير ضرورية وأن تكون الجنة دار استدلال ونظر وأن يكون لاعتراض السيئة فيها على أهل النظر مجال وأن يكونوا مكلّفين أبدا وأن يستحقوا على أداء ما كلّفوا فيها ثوابا في دار غيرها."], [13, "وقيل له في المعلوم بالحواس: ألسنا نعلم البلدان التي لم ندخلها بالتواتر وإن كانت معلومة للذين أخبروا عنها بالعيان؟ وكذلك كل جسم يعلمه من رآه عيانا ويعلمه الأعمى بلمس أو بتواتر الخبر عنه. فأجاب عن هذا بأنّ المخبرين عما عاينوه قد اتصل بعيونهم أجزاء من محسوساتهم فعلموا المحسوس باللمس ثم لما أخبروا غيرهم بما عاينوه انفصلت من الأجزاء التي اتصلت بعيونهم وأرواحهم بعضها فاتصلت\r\rبأرواح السامعين لأخبارهم فعلمه السامعون منهم باللمس أيضا وكذلك القول في السامع. فقيل له على هذا يلزمك إذا سمع أهل الجنة بالخبر عن أهل النار وما هم فيه من الصديد والزقّوم أن يكون أجزاء من أهل النار وأجزاء من زقّومهم وصديدهم قد انفصلت واتصلت بأبدان أهل الجنة في الجنة وإذا سمع أهل النار بالخبر عن أهل الجنة ونعيمهم أن يكون أجزاء من أهل الجنة قد انفصلت عنهم واتصلت بأبدان أهل النار فيكون بعض أبدان أهل الجنة في النار وبعض أبدان أهل النار في الجنة وهذا قول يليق بقائله وكفاه به خزيا.\rالمسألة العاشرة من الأصل الأول\r"]], "pg": [11, 13]}, "540.26": {"x": [[13, "في بيان مأخذ العلوم الشرعية\rالأحكام الشرعية مأخوذة من أربعة أصول وهي: الكتاب والسنة والإجماع والقياس.\rفالكتاب: هو القرآن الذي لا يأتيه الباطل من بين يديه ولا من خلفه وفيه عام وخاص ومجمل ومفسر ومطلق ومقيد وأمر ونهي وخبر واستخبار وناسخ ومنسوخ وصريح وكناية وفيه أيضا: دليل الخطاب ومفهومه وكل هذه الوجوه منه أدلة على مراتبها وإن كان بعضها في الاستدلال به على مدلوله أجلى من بعض. وما غمض منه وجه دلالته على الضعيف في نظره يعلمه المستنبط الموفق لقول الله عزوجل: (لَعَلِمَهُ الَّذِينَ يَسْتَنْبِطُونَهُ مِنْهُمْ) (1)."], [14, "وأما السنة التي يؤخذ عنها أحكام الشريعة فهي المنقولة عن النبي صلىلله عليه وسلم إما بتواتر يوجب العلم الضروري كنقل أعداد الركعات وأركان الصلاة ونحوها، وإما بخبر مستفيض يوقع العلم المكتسب كنقلهم نصب الزكاة وأركان الحج، وإما برواية آحاد توجب روايتهم العمل دون العلم. ووجوه دلائل السنة على أحكام كوجوه دلائل القرآن من عام وخاص ومجمل ومفسر وصريح وكناية وناسخ ومنسوخ ودليل خطاب ومفهومه وأمر ونهي وخبر ونحوها.\r__________________\r(1) [سورة النساء آية 84].\r\rوأما الإجماع المعتبر في الحكم الشرعي فمقصور على إجماع أهل عصر من أعصار هذه الأمة على حكم شرعي فإنها لا تجتمع على ضلالة. وأما القياس في الشرعيات فإنما يستدرك به معرفة حكم الشيء الذي ليس فيه نص ولا إجماع على حكمه. وهذا النوع من القياس على أقسام:\rأحدها: قياس جلي، وهو الذي يكون فرعه أولى بحكمه من أصله كتحريم ضرب الأبوين لقياسه على ما حرّم الله عزوجل من قول الولد لهما أفّ.\rوالثاني: قياس في معرفة الأصل المقيس عليه من كل وجه كقياس العبد على الأمة في تنصيف الحد لتساويهما في الرّقّ وقياس الأمة على العبد في التّقوّم على أحد الشريكين إذا أعتق نصيبه منه وهو موسر وكما حرّم الله عزوجل البيع في وقت النداء للجمعة، ثم قسنا عليه عقد الإجارة وسائر العقود في ذلك الوقت وليس الأصل في هذه الأحكام بأكثرهما شبها.\rوالقسم الثالث (1): قياس علة من أصل واحد كالعلة في الربا على اختلاف القائسين في علة الربا.\rوفي هذه الجملة خلاف من وجوه:\rأحدها: مع البراهمة في إنكارها شرائع الأنبياء عليهم السلام. والكلام يأتي عليهم في باب إثبات النبوات."], [15, "والثاني: مع الخوارج في إنكارها حجة الإجماع والسنن الشرعية وقد زعمت أنه لا حجة في شيء من أحكام الشريعة إلا من القرآن ولذلك أنكروا الرجم والمسح على الخفين لأنهما لأنهما ليسا في القرآن وقطعوا السارق في القليل والكثير لأن الأمر بقطع السارق في القرآن مطلق ولم يقبلوا الرواية في نصاب القطع ولا الرواية\r__________________\r(1) [من القياس الشرعي قياس شبه في فرع بين أصلين متعلق بأكثرهما شبها، وقياس خفي كالعلة في فروع الربا إذا قيس فيه الفروع، منها على الحنطة والشعير والتمر والملح والذهب والورق، وهذه وجوه مدارك أحكام الشريعة على أصول أهل السنة].\r\rفي اعتبار الحرز فيه. هذا قول أكثرهم وقد أجازت النّجدات منهم الاجتهاد في فروع الشريعة.\rوالخلاف الثالث: مع الروافض الذين قالوا لا حجة في القياس والسنة ولا في شيء من القرآن لدعواهم وقوع التحريف فيه من الصحابة وقد زعموا أن الحجة إنما هو قول الإمام الذي ينتظرونه وهم قبل ظهوره في التيه حيارى إلى أن يستنقذهم الإمام الذي ينتظرونه إذا ظهر بزعمهم.\rوالخلاف الرابع: مع النظامية من القدرية في إبطالهم القياس الشرعيّ وإبطالهم حجة الإجماع. وقد زعم النظام أن هذه الأمة من عهد نبيها عليه السلام إلى أن تقوم القيامة لو أجمعت على حكم شرعي جاز أن يكون إجماعها خطأ وضلالا. وزعم أيضا أنه لا حجة في الخبر المتواتر وأجاز وقوعه كذبا وأبطل القياس في الأحكام الشرعية وطعن في الصحابة الذين أفتوا باجتهادهم في فروع الشريعة، والطاعن فيهم مطعون في دينه ونسبه.\rوالخلاف الخامس: مع نفاة العمل باخبار الآحاد من القدرية.\rوالخلاف السادس: مع من يزعم من أهل الظاهر أن لا حجة في إجماع أهل عصر بعد الصحابة وإنما الحجة في إجماع الصحابة دون من بعدهم.\rوالخلاف السابع: مع من اعتبر حجة الإجماع إذا انعقد عن نص أو ظاهر من الكتاب أو السنة ولم ير الاجماع المنعقد عن القياس حجة."], [16, "والخلاف الثامن: مع نفاة القياس الشرعي من أهل الظاهر وقد استقصينا الرد على هؤلاء المخالفين في هذه الوجوه في كتبنا الموضوعة في أصول الفقه.\rالمسألة الحادية عشرة من الاصل الأول\r"]], "pg": [13, 16]}, "540.27": {"x": [[16, "في بيان شروط الاخبار الموجبة للعلم والعمل\rأما التواتر الموجب للعلم الضروري فمن شروطه أن يكون رواته في كل عصر من اعصاره على جهة يستحيل التواطؤ منهم على الكذب. وان كان رواته في بعض الأعصار قوما يصح على مثلهم التواطؤ عليه لم يكن خبرهم للعلم الضروري"], [17, "ولذلك لم يكن خبر اليهود والنصارى عن قتل عيسى وصلبه موجبا للعلم ولا خبر المجوس عن إعلام زردشت موجبا للعلم لأن النّصارى وإن تواتر نقلهم في الأعصار المتأخرة فإنهم يعزون خبرهم إلى أربعة زعموا أنهم هم الذين كانوا مع المسيح في الوقت الذي أقدم عليه اليهود بالقتل بزعمهم. ولو كان أتباع المسيح عليه السلام في ذلك الوقت عدد أهل التواتر لدفعوا عنه اليهود لا سيما وقد زعموا أن الذين قصدوه من اليهود كانوا ثلاثين والتواطؤ على هذا المقدار من العدد جائز والتواطؤ على ضعف هؤلاء جائز فضلا عنهم. فأما نقلهم عن مشاهدة شخص مصلوب فهو صحيح وإنما الكلام في ذات المصلوب هل كان عيسى أو المشبّه به في الصورة، وبعضهم يزعم أن الذي دل عليه من أصحابه هذا الذي ألقي عليه شبهه فقتل دونه ثم أن دعاويهم في المسيح منافية لنقلهم قتله لأن منهم من يزعم أنه إله، ومنهم من يزعم أنه أحد أقانيم الإله القديم، وأيهما كان بزعمهم وجب استحالة حلول القتل به. وأما نقل المجوس أعلام زردشت فمنسوب إلى كشتاسب أنه أخبرهم بأنه شاهد أعلام زردشت والخبر الراجع في أصله إلى واحد أو طائفة يجوز عليها التواطؤ لا يكون موجبا للعلم الضروري. ومن شروط التواتر أيضا أن يكون ناقلوه في العصر الأول قد نقلوه عن مشاهدة أو علم بما نقلوه ضرورة كنقلهم أخبار البلدان التي شاهدوها ونقلهم أخبار الأمم [التي] (1) شاهدها أهل العصر الأول من المخبرين عنهم وكنقلهم الأخبار عن الزلازل في الحر والبرد وسائر الأحداث في الأزمنة الماضية ونحوها (2).\rفأما أن تواتر الخبر في شيء يعرف صحته بالنظر والاستدلال فإنه لا يوجب العلم ولهذا لا يقع للدهرية وسائر الكفرة العلم بصدق أخبار المسلمين عن صحة دين الإسلام لأن صحة الدين معلومة بالنظر والاستدلال دون الضرورة (3).\r__________________\r(1) في المطبوع «الذين»."], [18, "(2) فإن تواتر النقل في شيء وطريق العلم به الاستدلال والنظر وطريق الخطأ الشبهة فإن ذلك التواتر لا يوجب علما].\r(3) [ولذلك أهل الكفر كل صنف منهم يتواتر نقلهم الخبر عن صحة أديانهم بشبه، اعترضت\r\rوأما أخبار الآحاد الموجبة للعمل دون العلم فلوجوب العمل بها شروط:\rأحدها اتصال الإسناد (1).\rوالشرط الثاني: عدالة الرّواة فإن كان في رواته مبتدع في نحلته أو مجروح في فعله أو مدلّس في روايته فلا حجة في روايته.\rوالشرط الثالث: أن يكون متن الخبر مما يجوز في العقل كونه. فإن روى الراوي ما يحيله العقل ولم يحتمل تأويلا صحيحا فخبره مردود [و] لهذا رددنا خبر أبي مهزم عن يزيد [بن أبي سفيان عن أبي هريرة أن الله تعالى أجرى فرسا ثم خلق نفسه عن عرقه لأن هذا يستحيل كونه مع كون رواته وهو أبو مهزم اسمه سعيد ضعيفا فكانت روايته مردودة عليه] لاستحالة هذا في العقول. وإن كان ما رواه الراوي الثّقة يروع ظاهره في العقول ولكنه يحتمل تأويلا يوافق قضايا العقول قبلنا روايته وتأوّلنا على موافقة العقول كما روى أن الله خلق آدم على صورته وتأويله أنه خلقه حين خلقه على الصورة التي كان عليها في الدنيا لئلا يتوهّم متوهّم أنه لما أخرج من الجنة عوقب بتغيير صورته كما عوقبت الحيّة بتغيير صورتها عند إخراجها من الجنة. وكذلك ما روي أن الجبّار يضع قدمه في النار صحيح وتأويله محمول على الجبار المذكور في قوله تعالى: (وَخابَ كُلُّ جَبَّارٍ عَنِيدٍ، مِنْ وَرائِهِ جَهَنَّمُ) (2) ومثل هذا كثير [قد أوردناه في كتبنا]. ومتى صح الخبر ولم يكن متنه مستحيلا في العقل ولم يقم دلالة على نسخ حكمه وجب العمل به كما يجب على الحاكم الحكم بشهادة العدول إذا لم يعلم جرحهم مع إمكان الخطأ أو الكذب على شهود والحكم جار على الظاهر.\r__________________"], [19, "ـ لهم ولأسلافهم فيها ولا يقع من خبرهم علم ومتى وقع التواتر في أصله عن شيء علمه الناقلون بالحس أو الضرورة وقع العلم بخبرهم على العادة المعتادة فيه].\r(1) [في قول الشافعي وأصحابه لأنهم لا يرون الاستدلال بالمرسل صحيحا ورأي مالك: مراسيل الصحابة حجة، وأما أبو حنيفة رأى الاحتجاج بالمراسيل كلها في الثقات صحيحا].\r(2) سورة ابراهيم آية 15.\r\rالمسألة الثانية عشرة من هذا الأصل\r"]], "pg": [16, 19]}, "540.28": {"x": [[19, "في بيان ما يعلم بالعقل وما لا يعلم إلا بالشرع"], [20, "قال أصحابنا: إنّ العقول تدل على حدوث العالم وتوحيد صانعه وقدمه وصفاته الأزلية وعلى جواز إرساله الرّسل إلى عباده وعلى جواز تكليفه عباده ما شاء، وفيها دلالة على صحة جواز حدوث كل ما يصح حدوثه وعلى استحالة كل ما يستحيل كونه. فأما وجوب الأفعال وحظرها وتحريمها على العباد فلا يعرف إلا من طريق الشرع فان أوجب الله عزوجل على عباده شيئا بخطابه إياهم بلا واسطة أو بإرسال رسول إليهم وجب، وكذلك أن نهاهم عن شيء بلا واسطة أو على لسان رسول حرم عليهم، وقبل الخطاب والإرسال لا يكون شيء واجبا ولا حراما على أحد، وكل عاقل فعل فعلا قبل ورود الشرع لا يستحق به ثوابا ولا عقابا فإن استدل العاقل قبل ورود الشرع عليه على حدوث العالم وتوحيد صانعه وقدمه وصفاته وعدله وحكمته فعرف ذلك واعتقده كان موحّدا مؤمنا ولم يكن بذلك مستحقا من الله تعالى ثوابا عليه فإن أنعم الله عليه بالجنة ونعيمها كان ذلك فضلا منه عليه ولو أنه اعتقد قبل ورود الشرع عليه الكفر والضلال لكان كافرا ملحدا ولم يكن مستحقا للعقاب على ذلك فإن عذّبه الله عزوجل بالنار على التأبيد فله ذلك [و] ليس بعقاب وإنما ابتداء منه لإيلام كإيلام البهائم والأطفال في الدنيا من غير استحقاق وذلك عدل من الله تعالى. ووجه هذا القول أن الثواب إنما يكون على الطاعة والطاعة موافقة الأمر والعقاب إنما يكون على المعصية، [والمعصية] موافقة النهي ومخالفة الأمر."], [21, "والمسألة مصوّرة في حالة لم يرد فيها أمر الله عزوجل ولا نهي على أحد من خلقه فاستحال الحكم في تلك الحال بالثواب والعقاب على شيء من الأفعال هذا تقدير مذهب شيخنا أبي الحسن الأشعري في هذا الباب وبه قال مالك والشافعي والأوزاعي والثوري وأبو ثور وأحمد بن حنبل وداود وأهل الظاهر والضرارية جملة أفعال العقلاء في العقل ثلاثة أقسام: واجب ومحظور ومتوسط بينهما فما دل العقل على وجوبه لا يتغير ولا يتبدل كوجوب معرفة الله تعالى وتوحيده وصفاته ووجوب شكره على نعمه. وما دل العقل على حظر لا يتغيّر عن"], [22, "ذلك كتحريم الكفر وكفران نعم المنعم. واختلف هؤلاء فيما توسط بين هذين القسمين فمنهم من قال فيها بالحظر وبه قال عيسى بن أبان وابن أبي هريرة ومنهم من قال فيه بالإباحة وهم أصحاب الرأي وقد قال أبو بكر بن داود في كتابه كل ما لم يأمر الله تعالى به فيكون لازما ولم ينه عنه فيكون حراما فهو مباح لا يأثم فاعله في فعله ولا يحرج في تركه. وزعمت النجارية كلها وكذلك رواه بشر بن غياث عن أبي حنيفة وصاحبيه أبي يوسف ومحمد بن الحسن. وزعمت المعتزلة والبراهمة أن العقول طريق إلى معرفة الواجب والمحظور وزعم أكثرهم أن القبيح في العقل هو الضرر [الضرب] الذي ليس فيه نفع ولا هو مستحقّ [وفيهم من ادعى معرفة وجوب شكر المنعم وقبح الضرب ليس فيه نفع ولا هو مستحق في ضرورة العقل وبداهته خ] واختلف هؤلاء فيما بينهم في وجه تعليق الإيجاب والحظر على العقول. فأما البراهمة فإنهم أقرّوا بتوحيد الصانع وأنكروا الرسل وزعموا أن فرض الله على عباده المعرفة والاستدلال عليه ووجوب شكره وأنّ قلب كل عاقل لا يخلو من خاطرين أحدهما: من قبل الله عزوجل ينبّهه به على ما يوجبه عقله من معرفة الله تعالى ووجوب شكره ويدعوه إلى النظر والاستدلال عليه بآياته ودلائله. والخاطر الثاني: من قبل شيطان يصرفه به عن طاعة الخاطر الذي من قبل الله عزوجل. وأثبتوا الخاطرين عرضين وقالوا إنما وقع التكليف بهذين الخاطرين لأنه لو انفرد فيه أحد الخاطرين دون الآخر صار ملجأ إلى طاعة الخاطر الذي فيه ولا تكليف مع الإلجاء. وأما المعتزلة فإنهم وافقوا البراهمة في دعاء الخواطر إلى النظر والاستدلال وفارقوهم في إجازة بعث الرسل لغرض الدعوة [وإباحة ما حظره العقل كذبح البهائم وتسخيرهم وإيلامهم لغرض ادّعوه فيه خ]. قال أبو هاشم بن الجبائي لو لا ورود الشرع بذبح البهائم وإيلامها لم يكن معلوما بالعقل جواز حسنه لأجل الغرض."], [23, "ثم اختلف المعتزلة في صفة الخواطر الداعية فزعم النظّام أن الخواطر أجسام محسوسة وأن الله خلق خاطري الطاعة والمعصية في قلب العاقل ودعاه بخاطر الطاعة إلى الطاعة ليفعلها ودعا بخاطر المعصية إلى المعصية لا ليفعلها ولكن ليتم له الاختيار بين الخاطرين. فهذا القدريّ الذي كان يكفّر من\r\rيقول بأن الله يخلق أعمال العباد خيرها وشرّها قد صار إلى القول بأن الله عزوجل قد خلق الخاطر الداعي الى المعاصي وصار أيضا إلى القول بأنه دعا إلى المعصية بأحد الخاطرين ونهى عنها بالخاطر الثاني فصار داعيا إلى ما هو ناه عنه وناهيا عما هو داع إليه. وزعم أبو الهذيل أن الخواطر أعراض وأن الخاطر الداعي إلى النظر والاستدلال يورده الله تعالى على قلب العاقل يدعوه به إلى طاعته ويحرك به دواعيه على الاستدلال عليه بتخويفه وترهيبه والخاطر الثاني: من قبل الشيطان يصدّه به عن طاعة الخاطر الأول. ووافقه الجبّائي وابنه على وجود الخاطرين وإنهما عرضان غير أن ابن الجبّائي زعم أن الخاطر الداعي إلى النظر والاستدلال من قبل الله تعالى جار مجرى الأمر وهو قول خفيّ يلقيه الله تعالى في قلب العاقل أو يرسل ملكا يلقي ذلك في قلبه وكذلك الخاطر الذي يلقيه الشيطان قول خفي يخاطبه به وأنكر قول أبيه وأبي الهذيل في [كون] صفة الخاطر أنه على معنى علم أو فكر."], [24, "وقول ابن الجبائي في هذا مثل قولنا في المعنى لأنه قد أقرّ بأنّ الإيحاء من الله تعالى إنما يكون بالقول الذي ليس من جنس الوساوس إلا أنّا قلنا أنه قول جلي مضاف إلى الله تعالى بلا واسطة أو إلى رسول متوسط، واضافه هو إلى الله تعالى أو إلى ملك ولكن لا ننكر أن يكون الرسول من الله إلى عبده ملكا غير أنّا نوجب كونه مقرونا بمعجزة تدل على صدقه وقلنا لمن اشترط منهم في جواز التكليف القاء خاطر من شيطان في قلبه إن كان ذلك الشيطان غير مكلّف فلم ذممتموه ولعنتموه وإن كان مكلفا وجب أن يكون بدأ تكليفه بإلقاء خاطرين في قلبه: أحدهما: من قبل الله تعالى، والثاني: من قبل شيطان سواه وكان الكلام في تكليف الشيطان الثاني كالكلام في تكليف الشيطان الأول حتى يتسلسل ذلك إلى شياطين بلا نهاية أو يثبت مكلّف بلا خاطر وفيه نقض أصولهم. وقلنا لأهل الحظر يلزمكم أن يكون اعتقاد الحظر محظورا [وقلنا لأهل الإباحة يلزمكم إباحة اعتقاد الحظر ومن المحال أن يبيح الله تعالى اعتقاد حظر ما ليس بمحظور. وهذا مما لا انفصال لهم عنه].\r\rالمسألة الثالثة عشرة من الأصل الأول\r"]], "pg": [19, 24]}, "540.29": {"x": [[24, "في بيان شروط العلم والإدراكات"], [25, "ليس لوجود العلم والرؤية والسمع والإرادة والقدرة في الشيء عندنا شرط غير وجود الحياة في محله ويصح عندنا وجود الحياة في الجوهر الواحد وكل ما صح وجود الحياة فيه صح وجود العلم والقدرة والإرادة والإدراكات فيه. وإنما اختلف أصحابنا في كون الحياة شرطا في وجود الكلام فيما ليس بحي فاشترطها الأشعري فيه وأجاز القلانسي وجود الكلام لما ليس بحي، واختلفت القدرية في هذا، وأجاز الصالحي منهم وجود العلم والقدرة والإرادة والإدراكات في الميّت، وأجازت الكرامية وجود العلم والإرادة والإدراكات في الأموات (1) [فلا يأمنون على هذا الأصل أن يكون جدران وكل موات علماء سامعة مبصرة مريدة معتقدة لمذاهب غير أنها لا تنطق ولا تقدر على فعل] ولم يجيزوا وجود القدرة إلا في حيّ واشترط أكثر المعتزلة في وجود الحياة في الشيء أن يكون ذا بنية مخصوصة أقل أجزائها ثمانية أو ستة أو أكثر على حسب اختلافهم في عدد أجزاء الجسم. وكذلك اشترطوا البنية في كل ما يكون الحياة شرطا في وجوده كالعلم والقدرة والإرادة والإدراك وزعموا أن الجملة الواحدة من الشاهد حي بحياة في جزء منه وقد علم هؤلاء أن الشّلل موت في بعض الأعضاء فيلزمهم أن يكون من له عضو أشلّ، حيّا بحياة في بعضه وميتا بموت في بعضه [فإن استدلوا بانتفاء الحياة عند نقض البنية قوبل بأن ذلك منتف كانتفائها عند عدم الغذاء وإن صحت حياتها بلا غذاء على نقض العادة كذلك يصح حياة الجزء بلا بنية وإن جرت العادة بذهاب الحياة عند نقض البنية على أنّا نقول إن الحيّة تقطع إربا إربا ويكون كل جزء منها متحركا حركة الأحياء إلا أن يفصل موضع الحياة من رأسها ولو ردّت الجملة إلى أقل أجزاء الجسم عندهم لبطلت حياتها في العادة وإن صح كونها حية في المقدور كذلك القول في الجزء عندنا] وقلنا للكرّامية إذا أجزتم وجود العلم والإرادة وكل\r__________________"], [26, "(1) [فلا يأمنون على هذا الأصل ان يكون جدران وكل موات علماء سامعة مبصرة مريدة معتقدة لمذاهب غير انها لا تنطق ولا تقدر على فعل].\r\rإدراك في الميت والجمادات فما يؤمنكم أن تكون جميع الجمادات عالمة سامعة مبصرة معتقدة لتكفيركم لكنها لا تنطق ولا تقدر على فعل لأنه ليس فيها حياة ولا قدرة وهذا يؤدي إلى الشك في الأموات والأحياء وذلك فاسد.\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [24, 26]}, "540.30": {"x": [[26, "في بيان ما يصح تعلق العلم به\rقال أصحابنا: إن علم الله عزوجل محيط بكل شيء معلوم على التفصيل ومعلومات علومنا محصورة لله تعالى [فيه تعالى] واختلف أصحابنا في تعلق العلم المحدث بمعلومين وأكثر فأجازه بعضهم وقال أبو الحسن الباهلي بجواز ذلك في العلم الضروري دون المكتسب. والصحيح عندنا أن كل علم متعلّق بمعلومين لأن من علم شيئا كان عالما به وبأنه عالم به ولو كان علمه بالشيء غير علمه بأنه عالم لجاز وجود أحد العلمين فيه مع عدم الآخر وكان يعلم الشيء من لا يعرف أنه عالم به وهذا محال فما يؤدي إليه مثله. وأحالت المعتزلة تعلق علم واحد بمعلومين على التفصيل [وأنكروا علم الله تعالى وقالوا لو كان له علم لما علم به إلّا معلوما واحدا كما أنّا لا نعلم معلومين إلّا بعلمين. فقلنا لهم إن جاز عندكم أن يعلم معلوماته بنفس واحدة خلاف العلم في الشاهد جاز أن يعلم المعلومات بعلم واحد خلاف العلم في الشاهد] وقال بعض الكرّامية: إنّ الله تعالى يعلم معلوماته بعلمه ويعلم علمه بعلم آخر، وقال بعضهم: إنّه يعلم معلومات علمه ولا يعلم علمه والناس يعلمون علمه فأثبت الإنسان عالما بما لا يعلمه الله تعالى. وزعم بعضهم أنه يعلم علمه بعلم آخر. ويجب على هؤلاء أن يعلم العلم الثاني بعلم ثالث والثالث برابع حتى يثبت له علوم لا نهاية لها وهذا محال فما يؤدي إليه مثله.\rالمسألة الخامسة عشرة من الأصل الأول\r"]], "pg": [26, 26]}, "540.31": {"x": [[26, "في ورود التكليف بالمعارف"], [27, "قد ورد التكليف بالمعارف النظرية عند أصحابنا في العلوم العقلية والأحكام الشرعية. وزعم صالح فيه أن المعارف كلها ضرورية يبتديها الله عزوجل في\r\rالقلوب اختراعا من غير سبب يتقدّمها من نظر واستدلال وزعم أن الإنسان غير مأمور بالمعرفة لكن من عرف الله عزوجل بالضرورة صار بالإقرار والطاعة مأمورا، وزعم بعض الروافض: أن المعارف كلها ضرورية إلا أن الله تعالى لا يفعلها في العبد إلّا بعد نظر واستدلال كما أن الولد من فعله غير أنه لا يخلقه إلّا بعد وطئ الوالدين [وزعموا أن من لم يخلق الله له المعرفة لم يكن مأمورا وصار كالمخلوق للسحرة ولا اعتبار له يعني أنه يخلق لهم السحر بعد أخذهم بالعلم به ومن خلق له المعرفة صار بالطاعة مأمورا وعن أضداده مزجورا] وقالوا فيمن لم يعرف الله تعالى بالضرورة أنه غير مكلف وزعم آخرون منهم أن المعارف ضرورية غير أن من لم يعرف الله تعالى مأمور بالإقرار والطاعة [سواء عرف الله أو لم يعرفه ولا سبيل لمن لم يعرفه إلى العلم بمعرفته ولا إلى العلم بأنه قد كلفه] وزعم الجاحظ وثمامة أن المعارف ضرورية وأن الله عزوجل ما كلف أحدا بمعرفته وإنّما أوجب على من عرفه طاعته وكفاهما خزيا نجاة الجاحدين لله من عذابه مع قولهما بخلود الفاسق من عارفيه في النار. وزعم غيلان القدري أن معرفة الإنسان بأنه مصنوع وأن صانعه غيره ضروري [قد طبع عليه الإنسان في خلقته] وهو مأمور بعد ذلك بالمعارف في العدل والتوحيد والوعد والوعيد والشرعيات، وقال أبو الهذيل: معرفة الله ومعرفة الدليل الداعي إلى معرفته بالضرورة وما بعدهما من العلوم الحسية والقياسية فهو علم اختيار وجائز أن يجعله الله تعالى ضروريا على نقض العادة. ويلزم غيلان وأبا الهذيل أن يكون الدهرية عارفة بالله تعالى ضرورة فيكونوا كمنكري الضرورات من السوفسطائية ولو كانوا كذلك لسقطت المناظرة معهم وهذا خلاف الدين فما يؤدي إليه خلافه أيضا.\r\rالأصل الثاني"]], "pg": [26, 27]}, "540.32": {"x": [[28, "من أصول هذا الكتاب في بيان حدوث العالم\rوهذا الأصل مشتمل على خمس عشرة مسألة. ترجمتها:\rمسألة في بيان معنى العالم وحقيقته.\rمسألة في بيان أجزائه المفردة.\rمسألة في بيان أجزائه المركبة.\rمسألة في إثبات الأعراض.\rمسألة في بيان أقسام الأعراض.\rمسألة في اختلاف أجناس الأعراض.\rمسألة في إحالة بقاء الأعراض.\rمسألة في تجانس الأجسام والجواهر.\rمسألة في حدوث الأعراض\rمسألة في أن الأجسام لا يخلو من الأعراض\rمسألة في تصحيح حدوث الأجسام.\rمسألة في وقوف الأرض ونهايتها.\rمسألة في وقوف السموات وعددها.\rمسألة في إثبات نهاية العالم.\rمسألة في جواز الفناء على العالم جملة وتفصيلا.\rفهذه المسائل للأصل الثاني وسنذكر في كل مسألة مقتضاها إن شاء الله تعالى.\r\rالمسألة الأولى من الأصل الثاني\r"]], "pg": [28, 28]}, "540.33": {"x": [[28, "في بيان معنى العالم وحقيقته"], [29, "العالم عند أصحابنا كل شيء هو غير الله عزوجل. والعالم نوعان: جواهر وأعراض. والجواهر كل ذي لون. والأعراض هي الصفات القائمة بالجواهر من الحركة والسكون والطعم والرائحة والحرارة والبرودة والرطوبة واليبوسة وسائر الأعراض [فإذا قلنا العالم محدث أردنا به حدوث الجواهر والأعراض] وزعم بعض أهل اللغة أن العالم كل ما له علم وحس [ولم يجعل الجمادات من العالم]. وقال آخرون انه مأخوذ من العلم الذي هو العلامة وهذا أصح لأن كل ما في العالم علامة [دالة] على صانعه وقد اختلف المفسرون في العالم فمنهم من قال لله تعالى ثمانية عشر ألف عالم واحد منها مثل العالم المحسوس [أو أكبر منه] ومنهم من قال بتسعين ألف عالم ومنهم من قال بألف عالم وتأولوا على ما ذكروا من العدد قوله عزوجل: (رَبِّ الْعالَمِينَ). وقولنا إن العالم جملة الجواهر والأعراض شامل للأعداد التي ذكروها. وقد قال بعض الحكماء إن كل شيء في العالم الكبير له نظير في العالم الصغير الذي هو بدن الإنسان. ولذلك قال الله تعالى (لَقَدْ خَلَقْنَا الْإِنْسانَ فِي أَحْسَنِ تَقْوِيمٍ) (1) قال أيضا (وَفِي أَنْفُسِكُمْ أَفَلا تُبْصِرُونَ) (2) (3) فحواس الإنسان أشرف من الكواكب المضيئة. والسمع والبصر منها بمنزلة الشمس والقمر في إدراك المدركات بهما وأعضاؤه تصير عند البلى ترابا من جنس الأرض وفيه من جنس الماء العرق وسائر رطوبات البدن ومن جنس الهواء فيه الريح والنّفس ومن جنس النار فيه مرّة الصفراء. وعروقه بمنزلة الأنهار في الأرض وكبده بمنزلة العيون التي تستمدّ منها الأنهار لأن العروق تستمد من الكبد ومثانته بمنزلة البحر لانصباب ما في أوعية البدن إليها كما ينصبّ الأنهار إلى البحر وعظامه بمنزلة الجبال التي هي أوتاد الأرض وأعضاؤه كالأشجار فكما أن لكل شجرة ورقا وثمرة فكذلك لكل عضو فعل وأثر.\r__________________\r(1) وردت في المطبوع «ودلالة».\r(2) سورة التين آية 4."], [30, "(3) سورة الذاريات آية 21.\r\rوالشعر على البدن بمنزلة النبات والحشيش على الأرض. ثم إن الإنسان يحكي بلسانه صوت كل حيوان ويحاكي بأعضائه صنيع كل حيوان فهو العالم الصغير وهو مع العالم الكبير مخلوق محدث لصانع واحد كما نثبته بعد هذا إن شاء الله تعالى.\rالمسألة الثانية من الأصل الثاني\r"]], "pg": [28, 30]}, "540.34": {"x": [[30, "في بيان الأجزاء المفردة من العالم.\rالمفردات من العالم نوعان: أحدهما: مفرد في ذاته؟؟؟ تفي الانقسام عنه."], [31, "والثاني: مفرد في الجنس دون الذات. فالمفرد في ذاته نوعان أحدهما جوهر وهو الجزء الذي لا يتجزأ وكل جسم من أجسام العالم ينتهي بالقسمة إلى جزء لا يتجزأ. والنوع الثاني مما لا يتجزأ: كل عرض في نفسه فإنه شيء واحد مفتقر إلى محل واحد. وأما المفرد بالجنس فكقول أصحابنا أن الجواهر جنس واحد وإن اختلفت في الصور والهيئات لاختلاف ما فيها من الأعراض. وكل نوع من الأعراض جنس مخصوص. ومن أجناسها ما يشترك فيه أنواع كثيرة كاللون المشتمل على السواد والبياض وغيرهما فأما السواد وكل جنس مخصوص من اللون، فأكثر أصحابنا على أنه جنس واحد وقال بعض أصحابنا في السواد إنه أجناس مختلفة وكذلك كل جنس من اللون أجناس مختلفة في بابه [وكل قدرة محدثة عند شيخنا أبي الحسن خلاف سائر القدر المحدثة فإن قدرة الإله على خلاف مثل كل قدرة وكذا العلمان المحدثان إذا تعلقا بمعلومين فهما مختلفان] والكلام في اختلاف أجناس الأعراض يأتي بعد هذا. فأما إثبات الجوهر جزأ لا يتجزأ فعليه جمهور المسلمين غير النظام فإنه زعم أنه لا نهاية لأجزاء الجسم الواحد وبه قال أكثر الفلاسفة ولو كان كما قالوه لم يكن الجبل أعظم من الخردلة إذا لم يكن لأجزاء كل واحد منهما نهاية لأن ما لا نهاية له في الوجود لا يزيد على ما لا نهاية له في الوجود. فإن عارضونا على هذا بمعلومات الله تعالى ومقدوراته وقالوا لا نهاية لكل واحد منهما ومعلوماته مع ذلك أكثر من مقدوراته لأن كل مقدور له معلوم له وذاته معلوم له غير مقدور. قيل ما وجد من معلوماته أكثر مما وجد من\r\rمقدوراته وكلاهما في الوجود محصور عنده. وأما الذي لم يوجد من معلوماته ومقدوراته فلا يقال فيها إن بعضها أكثر من بعض لأنها غير موجودة. وقيل للنظام إن كنت مقرا بالقرآن ففيه قوله (وَأَحْصى كُلَّ شَيْءٍ عَدَداً) (1) ولو لم يكن أجزاء كل جنس من الخلق محصورة عنده ما أحصاها عددا.\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [30, 31]}, "540.35": {"x": [[31, "في إثبات الأعراض"], [32, "الخلاف في إثبات الأعراض مع الأصم ومع طوائف من الدهرية والسمنية نفوها كلها وزعموا أن المتحرك متحرك لا بحركة والأسود أسود لا لسواد يقوم به ونفوا جميع الأعراض. ودليلنا عليهم وجودنا الجسم يتحرك بعد كونه ساكنا ولا يجوز أن يكون تحركه لعينه لوجود عينه في حال سكونه غير متحرك فعلمنا بذلك أن تحركه كان لمعنى فيه غير ذاته وكذلك رأينا الجسم أسود بعد أن كان أبيض ولم يكن أسود لعينه لوجود عينه في حال لم يكن فيها أسود فعلمنا أنه كان أسود لمعنى قام به فمن سلم لنا قيام معنى به ونازع في اسمه والخلاف معه في الاسم دون المعنى. وهذه الدلالة صحيحة مستمرة على أصولنا ولا تستمر على أصول البهشمية من القدرية وذلك أنهم ينفون الإدراكات وإن صار الإنسان رائيا سامعا بعد أن لم يكن كذلك [وزعموا أن الموت ليس بمعنى وإن صار الجسم ميتا بعد أن كان حيّا] فأفسدوا على أنفسهم بذلك طريق الاستدلال على إثبات الأعراض. ومما يدل على إثبات الأعراض حصول فوائد الأعداد في الأفعال كقول القائل: ضربت زيدا عشرين سوطا وقد علمنا أن الضارب واحد والمضروب واحد والسوط واحد، فعلمنا أن العشرين عدد راجع إلى غير الضارب والمضروب والسوط وذلك هو الضرب فصح أن الضرب أعراض غير الضارب والمضروب والآلة التي يقع بها الضرب [ولولاها بطلت فائدة هذا العدد وهذه الدلالة أيضا لا تستمر على أصل من نفي الإدراك من القدرية لأن القائل قد يقول أيضا: رأيت زيدا عشرين مرة والرائي\r__________________\r(1) سورة الجن آية 28.\r\rوالمرئي واحد ولم يرجع العدد عنده إلى غيرهما فأبطل على نفسه دلالة ثبوت الأعراض من هذه الجهة].\rالمسألة الرابعة من الأصل الثاني\r"]], "pg": [31, 32]}, "540.36": {"x": [[32, "في بيان الأجزاء المركبة من العالم\rالتركيب إنما يصح في الجواهر والأجسام. والأعراض لا يصح فيها تركيب ولا مماسة ولا انتقال من مكان إلى مكان. والأجسام المركبة نوعان:"], [33, "نام وغير نام. فالذي لا ينمو ولا يزيد كالسماوات والكواكب لأنها على مقدار واحد من حين خلقه الله تعالى إلى وقتنا هذا ما زاد فيه شيء ولا نقص منها شيء. فأما نقصان ضوء القمر وزيادته فذلك في ضوئه دون جرمه والله سبحانه قادر على الزيادة في الأجرام السماوية وعلى النقصان منها وعلى إفنائها كلها. وأما الذي ينمو ويزيد وينقص على مجرى العادة فنوعان:\rحيوان ونبات. والنبات نوعان نجم وشجر. والشجر ما نبت على ساق والنجم ما نبت على غير ساق. والحيوان نوعان:\rأحدهما محسوس لنا في العادة\rوالثاني غير محسوس الآن لنا مع جواز رؤيتهم في الآخرة وفي بعض الأحوال. وذلك أربعة أنواع: الملائكة والحور العين والجن والشياطين. والأنبياء قد رأوا الملائكة وربما رآهم المحتضر عند موته وأما الحيوان المحسوس في العادة فأربعة أنواع:\rأحدها: حيوان ماش إما على رجل أو رجلين أو على أرجل.\rوالثاني: حيوان يطير بجناحين أو أكثر.\rوالثالث: حيوان يغوص في الماء.\rوالرابع: حيوان يدب على بطنه كالحية والدود ونحوهما [وجملة المركبات من الأجسام نوعان: أحدهما: ما ركبت أجزائه من جنس واحد كتركيب أجزاء اللبن. والثاني ما ركب من أجزاء مختلفة في الجنس لاختلاف أعراض أجسامه\r\rكالغالية]. والحيوانات المحسوسة أيضا نوعان منها ما يحدث ابتداء لا عن نسل كدود الفاكهة والجبن والخل وكذلك نوع من الحيات يتولد في جوف الكمأة والعقارب يتولد من تحت الآجر والتبن وكذلك فارة الطين تحدث من الطين من غير تناسل. ومنها ما يحدث عن تناسل إما بالولادة وإما عن البيض.\rوالمتناسل بالولادة نوعان:"], [34, "أحدهما: متناسل من جنسه كالناس والحمر والخيل وأكثر الحيوان. ولكل جنس منها أول من غير إن كان له أصل من جنسه كآدم أب البشر. وكذلك أصل كل جنس من الحيوان في الابتداء. والنوع الثاني: من المتناسل ما خرج من بين جنسين مختلفين كالخارج من بين الفرس والحمار وكالسّمع والعسان الخارجين من بين الضبع والذيب والبختي الخارج من بين التركي والعربي والراعني الخارج من بين الحمام والورشان (1) ونحو ذلك. وقد جرت العادة بأن كل ذات أذن شرفاء ولود وكل ذات أذن صكّاء بيوض إلا العقرب فإنها لا تلد ولا تبيض لكن الولد يشق بطن أمه فيخرج منها. وكل نوع من الحيوان المتناسل وغير المتناسل فالله خالقه والله قادر على خلق أمثاله من غير تناسل. والخلاف في هذه المسألة مع الدهرية الذين زعموا أنه لا إنسان إلا من إنسان قبله وإن كل حيوان متولد من حيوان قبله وهو من جنس الفار المتناسل. وشاهدوا تولد الحية من جوف الكمأة العفنة وهي من جنس الحيات المتناسلة ورأوا تولد الضفادع في الماء وقد رأوا أيضا حدوث الضفادع في أرقة وقع فيها ماء المطر وصفقتها الرياح وفي هذا دليل على أن المتناسل يجوز حدوث مثله ابتداء من غير جنسه.\rالمسألة الخامسة من الأصل الثاني\r"]], "pg": [32, 34]}, "540.37": {"x": [[34, "في بيان أقسام الأعراض\rالأعراض عندنا أنواع مختلفة أولها: الأكوان ويدخل في جملتها الحركة\r__________________\r(1) الورشان: طائر، وهو ساق حرّ، وفي المثل: بعلة الورشان تأكل رطب المشان."], [35, "والسكون والتأليف ولا يخلو الجوهر من جنس الكون فإن كان مجتمعا مع غيره فالكون الذي فيه اجتماع وتأليف. وإن كان في مكان فالكون الذي فيه سكون أو تحول إلى مكان آخر فأول كون له في المكان الثاني سكون فيه وحركة عن الأول. هذا قول شيخنا أبي الحسن الأشعري. وذهب القلانسي من أصحابنا إلى أن السكون كونان متواليان في مكان واحد. والحركة كونان متواليان أحدهما في المكان الأول والثاني في المكان الثاني. وزعم أبو الهذيل وأتباعه من القدرية أن الكون معنى غير الحركة والسكون والاجتماع والافتراق. واجتهد في أن يجعله معنى معقولا فلم يجد إليه سبيلا.\rوالنوع الثاني من الأعراض: الألوان ولا يخلو الجوهر من واحد منها عندنا واختلفوا في عددها. فزعمت الثنوية أنها في الأصل نوعان: سواد وبياض وسائر الألوان مركبة منهما. وزعم بعض أهل الطبائع أنها أربعة أنواع على عدد الطبائع بزعمهم وهن السواد والبياض والحمرة والصفرة. وزعم البهشمية من القدرية أنها في الأصل أجناس: البياض والسواد والحمرة والصفرة والخضرة وما عداها من الألوان يظهر من امتزاج. وكل لون من اختلاط صبغين فقد خلق الله عزوجل مثله ابتداء في نبات أو جوهر معدني من غير اختلاط صبغين قبله. ومن مذهبنا أيضا لا نهاية لما في مقدورات الله عزوجل من الألوان المختلفة وإن لم نعرف أسماء ما لم يخلق منها. وزعم بعض البهشمية من القدرية أنه ليس في مقدوره لون خلاف الألوان الموجودة وكفاه بهذه البدعة خزيا.\rوالنوع الثالث من الأعراض: الحرارة.\rوالرابع: البرودة.\rوالخامس: الرطوبة.\rوالسادس: اليبوسة. وكل نوع من هذه الأنواع الأربعة في جنسه أنواع فإن رطوبة الدهن ليست من جنس رطوبة الماء ولا حرارة الشمس من جنس حرارة النار. ولا بد على أصل شيخنا أبي الحسن الأشعري من أن يكون في كل جزء من\r\rأجزاء الجسم حرارة أو برودة ولا بد من أن يكون فيه رطوبة أو يبوسة كما لا بد من أن يكون فيه لون أو كون."], [36, "والنوع السابع من الأعراض: الرائحة ولا يخلو الجسم من واحدة منها عندنا.\rوالنوع الثامن منها: الطعوم ولا يخلو الجسم عندنا من طعم ما. واختلفوا في عدد الطعوم، فقال أصحابنا: لا نهاية لما في مقدور الله تعالى منها. وزعمت الأطباء أن الطعوم ثمانية وهي: الحلاوة والمرارة والمزازة والدسومة والحموضة والتفاهة والعفص والمالح. وزعم بعضهم أن أصولها أربع كعدد الطبائع عندهم وقالوا إنّ الحلاوة للدم والهواء. والمرارة للصفراء والنار والحموضة للسوداء والملوحة للبلغم وسائرها مركب منها [ويكذبهم في هذه الدعاوي حدوث طعوم سوى ما ذكروه منها في المفردات قبل حصول التركيب فيها].\rوالنوع التاسع من الأعراض: الصوت وجنسه عندنا غير جنس الكلام. وأنواعه مختلفة فإن صوت الرعد خلاف سائر الأصوات.\rوالنوع العاشر منها: البقاء وهو عرض يحدث في الجوهر في الحالة الثانية من حدوثه ولهذا أحلنا بقاء الأعراض. واختلفوا في إثبات البقاء معنى: فأثبته أصحابنا وكثير من المعتزلة كأبي الهذيل ومعمر وبشر بن المعتمر وهشام الفوطي والكعبي. وأنكره قوم منهم كالنظام وابن شبيب والجبائي وابنه وكل من أثبت البقاء معنى منع من بقاء الأعراض.\rوالنوع الحادي عشر من الأعراض: الحياة وهي عندنا خلاف القدرة والعلم والإرادة والروح. وزعم بعض الفلاسفة أن الحياة هى الروح وإنها جوهر واحد. وزعم قوم أن الحياة اعتدال مزاج الطبائع في البدن. وزعم عباد بن سليمان الضمري أن الحياة في معنى القدرة وهذا كقول أكثر النصارى. وزعم بعض الكرامية أن الحياة من جملة القدرة وإن القدرة اسم جامع لكل ما لا يصح الفعل دونه كالحياة والعلم وصحة الجارحة. وكل من زعم أن الحياة هي القدرة وأن\r\rالحي هو القادر يلزمه أن لا يكون المغشى عليه حيّا لأنه في حال غشيته غير قادر على شيء."], [37, "والنوع الثاني عشر منها: الموت وهو عندنا عرض. وزعم بعض الفلاسفة أن الموت ليس بأكثر من عدم الحياة. وزعم هؤلاء أن الحركة معنى والسكون عدم ذلك المعنى وأن الضياء معنى والظلمة عدم الضياء. ويقال لهؤلاء: يلزمكم أن يكون كل ما ليس بمتحرك ساكنا وكل ما ليس بحي ميتا لعدم الحركة ولا حياة فيه ويجب من هذا أن يكون العرض ميتا ساكنا لأنه ليس فيه حركة ولا حياة. وإذا رجعنا إلى أصلنا في تحقيق الموت معنى قلنا إنه عرض ينافي الحياة والجمادية. وقد اختلفوا في المقتول هل يحله موت أم لا فقال أصحابنا لا بد من موت يخلقه الله تعالى فيه لأن القتل عندنا يقوم بالقاتل والموت يقوم بالمقتول. وقال بعض المعتزلة يحل في المقتول معنيان: أحدهما: قتل من فعل القاتل والثاني: موت من فعل الله تعالى وزعم الكعبي أن المقتول لا موت فيه. وخالف بهذه البدعة قول الله عزوجل: (كُلُّ نَفْسٍ ذائِقَةُ الْمَوْتِ) (1).\rوالنوع الثالث عشر من الأعراض: العلم وهو عندنا معنى غير الاعتقاد وتأثيره في الفعل من جهة أحكامه وإتقانه وزعم أكثر القدرية أن العلم اعتقاد مخصوص. ويلزمهم أن يكون كل عالم معتقدا والله تعالى عالم ليس بمعتقد وبطل بذلك قولهم.\rوالنوع الرابع عشر منها: الجهل وهو عند القدرية من جنس الاعتقاد ويلزمهم على هذا أن لا يكون الجاهل بما بطن الحامل جاهلا به إذا لم يعتقد فيه شيئا.\rوالنوع الخامس عشر منها: النظر.\rوالسادس عشر: الشك وزعم ابن الجبائي أن الشك ليس بمعنى.\r__________________\r(1) سورة آل عمران آية 185.\r\rوالسابع عشر: السهو والنوم من جنسه لأنه سهو عام.\rوالثامن عشر: القدرة وهي عندنا عرض غير الحياة والصحة وزعم النظام أنها جسم.\rوالتاسع عشر: العجز\rوالعشرون: الإرادة والكراهية داخلة في جنسها لأن الإرادة وجود الشيء كراهية لعدمه.\rوالحادي والعشرون: السمع وهو إدراك المسموع غير العلم به. وزعم الكعبي أن السمع إنما هو علم بالسّمع."], [38, "والثاني والعشرون: الصّمم الذي هو ضد السمع.\rوالثالث والعشرون: البصر الذي هو الرؤية وهي غير العلم بالمرئي وزعم الكعبيّ أنها العلم بالمرئي.\rوالرابع والعشرون: العمى وهو ضد الرؤية.\rوالخامس والعشرون: الكلام وهو عندنا غير الصوت وزعم أكثر القدرية أنه صوت مخصوص.\rوالسادس والعشرون: الخاطر وهو عندنا عرض خلاف قول النظام أنه جسم.\rوالسابع والعشرون: الألم.\rوالثامن والعشرون: اللذة وهي عندنا معنى غير نيل المنى وغير الراحة من مؤلم وزعم ابن زكريا المتطبب أنها راحة من مؤلم وزعم ابن الجبائي أنها نيل المنى.\rوالتاسع والعشرون: الفكر الواقع بعد الخاطر.\rوالثلاثون: كل اعتقاد صحيحا كان أو فاسدا فإن الاعتقاد عندنا ليس من\r\rجنس العلم ولا من جنس الجهل. فهذه أنواع الأعراض عندنا واختلف أصحابنا في الإعادة فأثبتها القلانسي معنى يقوم بالمعاد ولذلك منع إعادة الأعراض وقال أبو الحسن إن الإعادة وجود الفاني بعد عدمه مرة ثانية وأجاز إعادة الأعراض كما يجوز إعادة الأجسام. واختلفوا أيضا في الفناء فأثبته القلانسي عرضا يقوم بالجسم الفاني فيفنى به في الحالة الثانية من حال حدوث الفناء فيه. وزعم الجبائي وابنه أن الفناء عرض يخلقه الله عزوجل لا في محل فيفنى به جميع الأجسام وزعم أن الله تعالى غير قادر على إفناء بعض الأجسام مع بقاء بعضها. وقال شيخنا أبو الحسن الأشعري إنّ فناء الجسم يكون بأن لا يخلق الله فيه بقاء وأما العرض فإنما يفنى في الثاني من حالة حدوثه لاستحالة بقائه (1). واختلفوا في الثقل والخفة فأنكرهما أبو الحسن الأشعري وقال إنّ الثقيل إنما يثقل على غيره بزيادة أجزائه والخفيف يكون أخف من غيره بقلة أجزائه وأثبت القلانسي الثقل عرضا غير الثقيل وبه قال ابن الجبائي مع نفيه كون الخفة معنى. والرحمة عندنا إرادة الإنعام. والغضب إرادة العقاب. والمحبة والرضا إرادة الخير بالمحبوب والمرضي. فهذا كله داخل في معنى الإرادة"], [39, "المسألة السادسة من هذا الأصل\r"]], "pg": [34, 39]}, "540.38": {"x": [[39, "في بيان ان الأعراض مختلفة الأجناس\rاختلفوا في هذه المسألة فذهب أكثر مثبتي الأعراض إلى أنها أجناس مختلفة وأنها ليست من جنس الأجسام ولا من أبعاضها وخالفهم في ذلك النظام وضرار والنجار. أما النظام فإنه قال: لا عرض إلّا الحركة وزعم أيضا أن السكون من جنس الحركة غير أنه حركة اعتماد وزعم أيضا أن العلوم والإرادات من جملة حركات القلوب وزعم أن كل شيء من العالم ليس بحركة فهو جسم وأدخل الألوان والطعوم والأصوات والاستطاعة في جملة الأجسام. وزعم أيضا أن الجسم الكثيف\r__________________\r(1) [وكان القاضي أبو بكر محمد بن الطيب يقول: إذا أراد الله افناء الجسم قطع الاكوان عنه وليس البقاء ولا الفناء معنى]."], [40, "هو اللون والطعم والرائحة وما أشبهها وقال إن هذه الأشياء في أنفسها أجسام وقد اجتمعت وتداخلت فصارت جسما كثيفا وزعم أيضا أن مكان اللون مكان الطعم والرائحة وأجاز لذلك كون جسمين في مكان واحد على سبيل المداخلة ولم يجز ذلك على سبيل المجاورة. وأما ضرار فإنه زعم أن الجسم أعراض اجتمعت فاحتملت أعراضا سواها (1) [وأما الأعراض التي في حيز واحد ومكان واحد فيقال له هل يجوز انفراد تلك الأجسام اللطيفة عن الامتزاج فإن أجاز ذلك أجاز وجود لون لا لمتلون وذلك خلاف قول الجميع وإن منع من ذلك لزمه أن يكون الله تعالى قادرا على الجمع بين جسمين غير قادر على التفريق بينهما وقيل له إذا كان كل جسم ذا أجزاء غير متناهية وكان اللون والطعم الذي يتركب منها الجسم هي التي لا يخلو الجسم منها ومن اضدادها] وأن الأعراض [التي] تركب الجسم منها هي التي لا يخلو الجسم منها ومن أضدادها كاللون والطعم والرائحة والحياة والموت الذي هو ضده. وأما الذي ينفك الجسم منه ومن ضده كالعلم والقدرة والكلام فليس ببعض للجسم وأحال وجود أبعاض الجسم مفترقة فوافق النجار ضرارا في هذا القول وزاد عليه أن أجاز كون الشيء الواحد عرضا في حال وجسما في حال أخرى ولهذا زعم أن كلام الله تعالى إذا قرئ فهو عرض وإذا كتب فهو جسم. وزعم النظام أن لا عرض إلّا الحركة وزعم أيضا أن الأعراض كلها جنس واحد والذي ألجأه إلى ذلك قوله بأن الحيوانات كلها جنس واحد لاتفاقها في توليد الإدراك. ثم زعم أن الجنس الواحد لا يقع منه عملان مختلفان كما لا يقع من النار تسخين وتبريد ولا من الثلج تبريد وتسخين. وزعم أيضا أن الاجسام ضربان حي وميت وأن الحي محال أن يصير ميتا والميت محال أن يصير حيا وأن\r__________________"], [41, "(1) [وأما الأعراض التي في حيز واحد ومكان واحد فيقال له: هل يجوز انفراد تلك الأجسام اللطيفة عن الامتزاج، فإن أجاز ذلك أجاز وجود لون لا لمتلون، وذلك خلاف قول الجميع وإن منع من ذلك لزمه أن يكون الله تعالى قادرا على الجمع بين جسمين غير قادر على التفريق بينهما، وقيل له إذا كان كل جسم ذا أجزاء غير متناهية وكان اللون والطعم الذي يتركب منها الجسم هي التي لا يخلو الجسم منها ومن أضدادها]."], [42, "الحيوان كله جنس واحد وفعله جنس واحد وفي ضمن هذا القول أنواع من الإلحاد: أحدهما إذا زعم أن أفعال الحيوانات كلها جنس واحد وهي كلها حركات والحركات منها (متماثلة (1) عنده لزمه من ذلك أن يكون الكفر من جنس الإيمان والقول من جنس السكوت والعلم من جنس الجهل والحب من [جنس] البغض وأن يكون فعل النبي صلىلله عليه وسلم بالمؤمنين مثل فعل إبليس بهم ولزمه على هذا القول أن لا يغضب النظام على من لعنه وشتمه لأن قول القائل لعن الله النظام مثل قوله رحمه الله. والوجه الثاني من إلحاده في هذا الفصل أن قوله إن الحي لا يصير ميتا والميت لا يصير حيا مأخوذ من قول الديصانية إن النور حي لا يجوز عليه الموت والظلام ميت لا يصير حيا وإنما تفعل الشر طباعا. والوجه الثالث من إلحاده فيه أن قوله: لا يقع من فاعل واحد عملان مختلفان نتيجة قول الثنوية أن الخير والشر لا يقعان من أصل واحد كما لا يقع التسخين والتبريد من أصل واحد. ويقال له في قوله بتداخل الاجسام اللطيفة في حيز واحد هل يجوز انفراد تلك الأجسام اللطيفة عن الامتزاج فإن أجاز ذلك أجاز وجود لون لا لمتلون وذلك خلاف قول الجميع وإن منع منه لزمه أن يكون الله عزوجل قادرا على الجمع بين جسمين غير قادر على التفريق بينهما [وقيل له: إذا كان كل جسم ذا أجزاء غير متناهية وكان اللون والطعم والرائحة عندك أجساما وكل واحد منها في نفسه ذو أجزاء بلا نهاية فيجب أن يكون كل واحد منها جسما كثيفا في نفسه لكثرة أجزائه وخروجها عن الحصر ولزمك على هذا الأصل إبطال المداخلة فيها لأنك لا تجيز تداخل الأجسام الكثيفة وليست الكثافة معنى أكثر من اجتماع الأجزاء."], [43, "فإن قلت إنما يحصل الكثافة باجتماع الأجزاء المختلفة وأجزاء اللون متجانسة وكذلك أجزاء الطعم والرائحة فلذلك لم يكثف في أنفسها قيل يلزمك على هذا أن تقول في الجسمين الكثيفين إذا اجتمعا ولونهما وطعمهما ورائحتهما واحد أن لا يصيرا كثيفين لأنهما من جنس واحد في جميع أجزائهما ووجب من هذا أن لا يكثف الشيئان بضم أحدهما إلى الآخر وقيل له إذا كان اللون والطعم والرائحة عندك\r__________________\r(1) وردت في المطبوع «ثلة».\r\rأجساما متداخلة فهل مكانها أعيانها أم غيرها وليس من أصله أن يكون مكانها غيرها وإذا قال مكانها أعيانها وجب منه أن يكون كل واحد منهما مكان الآخر فيكون المستكنّ في المكان مكان مكانه] وقيل له: قد سلّمت لنا أن الحركة عرض تحلّ الجسم ومحلّها عندك جسم هو لون وطعم ورائحة فإن حلت الحركة فيها كلها صار عرضا واحدا في محلين وأكثر وإن حلت في بعضها تحرك بها بعض الجسم دون كله. ويقال لمن زعم أن الجسم أعراض هل اجتمعت لأنفسها أو لمعنى سواها فإن اجتمعت في أنفسها استحال الافتراق عليها وقد يتبدل لون الجسم مع كونه على الطعم الأول ويتبدل طعمه مع كونه على الوصف الأول في جنسه فإن كان اللون والطعم يجتمعان باجتماع يقوم بهما وجب من هذا قيام العرض بالعرض وإذا كان الاجتماع عرضا وقد اجتمع مع اللون والطعم وجب عليهم أن يكون اجتماع هذه الثلاثة لاجتماع آخر ثم كذلك حتى يتسلسل إلى اجتماعات لا نهاية لها. وأما قول النّجار أن الكلام عرض إذا قرئ وجسم إذا كتب فكفى في خزيه هذا القول لأن الدّم الذي يكتب به بعض الآيات يصير كلاما لله تعالى عنده وهذا قول إن رضيه لنفسه رضينا بأن يكون هو من أهله.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [39, 43]}, "540.39": {"x": [[43, "في بقاء الأعراض"], [44, "اختلفوا في بقاء الأعراض: فأحاله أصحابنا والكعبي وأجازت الكرّامية بقاء جميع الأعراض وقالوا: إن حدوث كل حادث في العالم إنما هو بقول الله تعالى كن وإرادته لحدوثه وعدمه بقول له افن وإرادته لعدمه. فإذا خلق جسما أو عرضا وجب بقاؤه إلى أن يقول له افن ويريد عدمه. واختلفت المعتزلة في هذه المسألة: فقال النظّام لا عرض إلا الحركة ومحال بقاء الحركة فأما الألوان والطعوم والروائح والأصوات والخواطر فهي أجسام يصح بقاؤها. وقال أبو الهذيل الأعراض منها ما يبقى ومنها ما لا يبقى والذي لا يبقى منها الحركة والإرادة وأجاز بقاء اللون والطعم والرائحة والتأليف والحياة والعلم والقدرة وحكى الإسكافي عنه أن سكون الحي لا"], [45, "يبقى وسكون الميت باق والمشهور عنه أن سكون أهل الجنة وسكون أهل النار في آخر الأمر باق على الدوام. وكان يزعم أن ما يبقى من الأجسام والأعراض فإنما يبقى من أجل بقاء لا في محل وزعم أن ذلك البقاء هو قول الله ابق. وقال بشر بن المعتمر: السكون كله باق لا يفنى إلا بالخروج منه إلى حركة. وكذلك كل لون لا يفنى إلا بخروج الجسم منه إلى ضده. وأحال محمد بن شبيب بقاء الحركة والسكون. وقال الجبائي وابنه إنّ الصوت والألم والحركات والفكر والإرادات والكراهات أعراض غير باقية وأجازا بقاء الحرارة والبرودة والرطوبة واليبوسة والاعتماد والتأليف واللون والحياة والقدرة والعجز والعلوم والاعتقادات، وقال الجبّائي: السكون الذي يفعله الحيّ في نفسه غير باق وكل ما يفعله في نفسه مباشرا غير باق وأجاز بقاء الكلام ومنع ابنه من بقاء الكلام. وقال ضرار والنجّار: الأعراض التي هي أبعاض الجسم عندهما باقية وما سواها من الأعراض يستحيل بقاؤه. ودليلنا على استحالة بقاء الأعراض أن القول ببقائها يؤدي إلى إحالة عدمها [لأن العرض إذا بقي ولم يكن بقاؤه من أجل حدوث بقاء فيه ـ حتى إذا قطع عنه البقاء فني كما يقول أصحابنا في فناء الجسم إذا لم يخلق فيه البقاء ـ وجب أن يكون باقيا إلى أن يوجد ضد له يوجب عدمه ولو كان كذلك لم يكن طريان ضده عليه بأن يوجب عدمه أولى من أن يكون وجوده مانعا من طريان ضده عليه وهذا يحيل جواز العدم على الأعراض وإحالة عدمها يوجب إحالة حدوثها وفي إحالة حدوثها وجوب قدمها وقدم الأجسام معها وإذا بطل القول بقدم الأجسام بطل القول بما يؤدي إليه] لأن العرض لو بقي ولم يكن بقاؤه لحدوث معنى فيه حتى إذا قطع عنه ذلك المعنى فني لوجب أن لا يجوز عدمه، لطريان ضده عليه بأن يوجب عدمه، أولى من أن يكون وجوده مانعا من طريان ضده عليه."], [46, "وقلنا للكرّامية إذا كان عدم العرض عندكم بقول الله تعالى افن وإرادته لعدمه وصح وجود المقول له مع هذا القول وهذه الإرادة في حال حدوثها عندكم فهلا صح بقاء هذه الثلاثة أحوالا كثيرة لأن كل شيئين لا يتنافى وجودهما في حالة واحدة لا يتنافيان بعد ذلك. وقلنا لأبي الهذيل إذا كان بقاء الباقي عندك بقول الله ابق وهذا القول حادث عندك لا في\r\rمحل فما الذي يمنعه من أن يقول للإرادة ابق وللحركة ابق فيلزمك على هذا إجازة بقاء الحركة والإرادة وذلك خلاف أصلك.\rالمسألة الثامنة من الأصل الثاني\r"]], "pg": [43, 46]}, "540.40": {"x": [[46, "في تجانس الأجسام"], [47, "اختلفوا في هذه المسألة على مذاهب: فأما الدهرية النافية للأعراض فقد زعموا أن الأجسام منها مختلفة ومنها متفقة. ما اتفق منها في الجنس فهي لأنفسها متفقة وما اختلف منها في الجنس فهي لأنفسها مختلفة. وزعم أصحاب التناسخ أن الروح جسم خلاف الأجسام المحسوسة. واختلف أصحاب الهيولى في هذه المسألة: منهم من زعم أن هيولى العالم جوهر واحد من جنس واحد وإنما اختلفت أجزاؤه عند حدوث الأعراض المختلفة فيها. ومنهم من زعم أن لكل نوع من انواع العالم هيولى مخصوصة فهيولى الذهب غير هيولى الخشب ونحو ذلك والهيولات (1) من أصولها اجناس مختلفة. واختلف أصحاب الطبائع في هذا: فمنهم من زعم أن الأجسام في الأصل أربعة أجناس فهي الأرض والماء والنار والهواء وسائر الأجسام مركبة منها. ومنهم من قال بجنس خامس وهو الريح وزعم أن الريح غير الهواء المتحرك. ومنهم من جعل الخامس الفلك وزعم أنه طبيعة خامسة غير قابلة للكون والفساد ومنهم من أثبت في هذه الخمسة روحا سابحة فيها هي خلافها في الجنس. وأما الثنوية فإن المانوية منهم زعمت أن الأجسام في الأصل نوعان قديمان وهما النور والظلمة وهما متضادان في الصورة والفعل ولكل واحد منهما خمسة أبدان مختلفة فأبدان النور النار والنور والريح والماء وروحه النسيم وأبدان الظلمة الحريق والظلمة والسّموم والضباب وروحها الدخان وزعموا أن أبدان النور كل واحد منها مخالف للآخر وإن أبدان الظلمة مخالف بعضها بعضا فصارت الأجسام عندهم عشرة أجناس نصفها من جملة النور ونصفها من جملة الظلام.\rوزعمت الديصانية منهم أن الأجسام كلها نوعان نور وظلمة وإن النور حي\r__________________\r(1) [فهؤلاء يزعمون ان الأجناس في اصولها مختلفة الأجناس]."], [48, "والظلمة موات وكل واحد منهما جنس مخالف للآخر في ذاته وفعله. وزعمت المرقونية منهم أن الأجسام ثلاثة أجناس نور وظلمة ومعدل ثالث بينهما وهو سبب المزاج بينهما. وزعم النظام ومن تبعه من القدرية أن الأجسام أنواع مختلفة ومتضادة وبناه على دعواه أن الألوان والطعوم والأصوات والخواطر أجسام. وقال أصحابنا بتجانس الأجسام كلها وقالوا إنّ اختلافها في الصورة وفي سائر الأحكام إنما هو لاختلاف الأعراض القائمة بها ووافقهم على هذا من المعتزلة الجبّائي وابنه أبو هاشم. ودليل هذا القول إن أعظم أنواع الاختلافات بين الأجسام ما نراه من الاختلافات بين الأرض والماء والنار والهواء وما نراه لا من الاختلافات بين الحيوان والجمادات وأنواع النبات وهذه الأنواع مع اختلافها في الصورة واللون والطعم والرائحة والوزن يستحيل بعضها إلى بعض لأن الأرض تنحل فتصير ماء كالملح إذا ذاب والماء في بعض البقاع يجمد فيصير حجرا والحجر من جنس الأرض. وقد ينعقد الماء فيصير ملحا والملح من جنس الأرض السّبخة المالحة. والصاعقة تقع على الأرض. فتغوص فيها إلى الماء فتصير في الماء قطعة حديد والحديد من جنس الأرض. والهواء قد ينعقد فيصير بخارا وسحابا ثم يقطر منه المطر. والقطرة من الماء إذا صبت على الصفحة المحماة بالنار صارت بخارا وهواء. والحيوان والنبات إذا أحرقا صارا رمادين والرماد من جنس الأرض. فدلت استحالة هذه الأصول بعضها إلى بعض أنها في الأصل جنس واحد وأنّ اختلافها في الصورة لاختلاف الأعراض القائمة بها [كما بيناه].\rالمسألة التاسعة من الأصل الثاني\r"]], "pg": [46, 48]}, "540.41": {"x": [[48, "في إثبات حدوث الأعراض\rاختلف الذين أثبتوا الأعراض في حدوثها: فقال المسلمون وكل من أقر بشريعة بحدوثها. واختلفت الدهرية الذين أثبتوا الأعراض في حدوثها فمنهم من قال بحدوث الأعراض وزعم أن الأجسام (1) سابقة لها وهذا قول أصحاب الهيولى.\r__________________\r(1) [الجواهر]."], [49, "ومنهم من قال إنّ الأعراض حوادث إلا أنه [لا] حادث منها إلا وقبله حادث ولا حركة إلا وقبلها حركة أو سكون ولا سكون إلا وقبله حركة (1) وزعم آخرون منهم أن الأعراض قديمة في الأجسام غير أنّها تكمن في الأجسام وتظهر فإذا ظهرت الحركة في الجسم كمن السكون [فيه] وإذا ظهر السكون [فيه] كمنت الحركة [فيه] وكذلك كل عرض ظهر كمن ضده في محله. والكلام على الأزلية وأهل الهيولى يأتي بعد هذا في الفصل الذي يلي هذا الفصل. فقلنا لأصحاب الكمون والظهور لو كان العرض يظهر ويكمن لوجب أن يكمن بعد ظهوره لمعنى يقوم به (2) وهذا يؤدي إلى قيام عرض بعرض وذلك محال فما يؤدي إليه مثله. وإذا استحال ذلك استحال الظهور والكمون على الأعراض فصح أنها كلها حوادث في الأجسام.\rالمسألة العاشرة من الأصل الثاني\r"]], "pg": [48, 49]}, "540.42": {"x": [[49, "في استحالة تعري الأجسام من الأعراض\rذهب شيخنا أبو الحسن الأشعري إلى استحالة تعري الأجسام من الألوان والأكوان والطعوم والروائح. وقال لا بد أن يكون في كل جوهر لون وكون وطعم ورائحة وحرارة وبرودة ورطوبة ويبوسة وحياة أو ضدها وإذا وجد في حالين فلا بد من وجود بقاء فيه في كل حال بعد حال حدوثه. وزعم الكعبي [وأتباعه من القدرية] أن الجوهر يجوز تعريه عن الأعراض كلها إلا من اللون. وزعم أبو هاشم وأتباعه من القدرية أن الجوهر في حال حدوثه يجوز تعريه من الأعراض كلها إلا من الكون وكل عرض حدث فيه بعد الكون فإنه لا يخلو منه بعد حدوثه إلا بضده.\r__________________\r(1) [وهذا قول طائفة أزلية الدهرية]."], [50, "(2) [لأن الموجود إذا تغير عليه الوصف تغير عليه الوصف في ذاته لمعنى قام به فإن اجابوا الى ذلك لزمهم إجازة قيام عرض بعرض وهذا خلاف أصولهم، وإذا بطل الظهور والكمون في الاعراض وصح تغير الأجسام بها من حال الى حال وبطل انتقال العرض من جسم الى جسم لاستحالة قيام الانتقال والحركة بالعرض صح ان قيام العرض بالجوهر إنما هو حدوثه فيه، وصح بهذا الدليل حدوث جميع الأعراض]."], [51, "وزعم الصالحيّ وأتباعه من القدرية: أنه يجوز وجود الجوهر خاليا من الأعراض كلّها. وزعم المعروف منهم بابن المعتمر أنّ الجوهر الواحد لا يحتمل الأعراض فإذا اجتمعت ثمانية أجزاء وصارت جسما أحدثت في أنفسها الأعراض طباعا. وزعم أصحاب الهيولى أن هيولى العالم كان شيئا واحدا خاليا من الأعراض ثم حدثت فيه الأعراض [فتجانست وتنوعت واختلفت الأجزاء] فتركب منها العالم عند حدوث الأعراض فيها. فيقال لهم هل كانت الهيولى في الأصل جوهرا واحدا أو جواهر؟ فإن قالوا كانت جوهرا واحدا قيل فكيف صارت بحدوث الأعراض فيه جواهر كثيرة وحدوث العرض في الشيء إنما يغير صفته ولا يزيد في عدده. وإن قالوا كانت الهيولى قبل حدوث الأعراض فيها جواهر وأشياء قيل الجواهر لا يخلو من اجتماع وافتراق وهما عرضان. وفي هذا بطلان قولهم بتعريها من الأعراض."], [52, "[وقيل أخبرونا كيف حدثت الأعراض في الهيولى فإن زعموا أنّها حدثت فيها بنفسها قيل كيف يحدث الشيء بنفسه وإن قالوا حدثت فيها بقوة لها أثبتوا في الهيولى قوة قبل حدوث الأعراض ونقضوا قولهم بتعري الهيولى عن الأعراض فإن قالوا بصانع أحدث الأعراض في الهيولى قيل فاعل العرض بالجسم إنما يغير بالعرض صفة الجسم ولا يجعل الجسم الواحد جسمين وقيل لهم أيّ العرضين أسبق إلى الهيولى، الاجتماع أو الافتراق؟ فإن زعموا أن الافتراق يسبق إليها وجب كونها قبل ذلك مجتمعة الأجزاء حتى تفترق بالافتراق وفي هذا بطلان قولهم أن الهيولى لم تكن مجتمعة ولا مفترقة قبل حدوث الأعراض فيها فإن استدلوا] و [إن] استدل أهل الهيولى على إثبات الهيولى بأن قالوا لم نجد حادثا حدث إلا من أصل له ولم نجد في الشاهد فاعلا فعل شيئا إلا من شيء كالخاتم المصوغ من (1) الفضة أو الذهب والباب المصنوع من الخشب والثوب من القطن ونحو ذلك فيقال لهم إن الصانعين في الشاهد لا يصنعون أجساما وإنما أفعالهم أعراض وكل عرض يحدث في الشاهد لا من أصل له [وقلنا للهاشمية والكعبية إذا أجزتم تعرّي الجواهر من جميع الأعراض إلا من الألوان أو من الأكوان في الابتداء وإن استحال تعريها منها بعد\r__________________\r(1) وردت في المطبوع «في»."], [53, "وجودها فيها فبم ينفصلون من أصحاب الهيولى إذا قالوا إنّها قبل حدوث الأعراض فيها كانت خالية من الأعراض وإن استحال تعريها منها بعد حدوث الأعراض فيها. وقيل للصالحي منهم إذا صح عندك وجود الجوهر خاليا من الأعراض كلها فما الذي يفسد به قول أصحاب الهيولى وما الذي كان يكون دليلا على حدوث الجوهر الواحد لو خلقه فيه تعالى منفردا ولم يخلق فيه عرضا وهذا لا سبيل إلى الاستدلال عليه وكل قول لا يصح معه الاستدلال على حدوث الأجسام وعلى حدوث الجوهر فهو فاسد] فإذا ثبت لنا حدوث الأجسام وجب أن يكون حدوثها لا من أصل كما أن حدوث الأعراض لا من أصل لها. وقلنا للصالحي إذا خرق تعري الجواهر من الأعراض فبم تنفصل من أهل الهيولى إذا ادعوا من قدم الهيولى وزعموا أنها كانت في الأزل خالية من الأعراض ثم حدثت الأعراض فيها وكل قول يلزمك عليه مقالة فاسدة فهو فاسد مثلها.\rالمسألة الحادية عشرة من الأصل الثاني\r"]], "pg": [49, 53]}, "540.43": {"x": [[53, "في تحقيق حدوث الأجسام"], [54, "والخلاف في حدوث الأجسام مع فرق: إحداها الدهرية المعروفة بالأزلية لدعواها أن العالم كان في الأزل على هذه الصورة في أفلاكه وكواكبه وسائر أركانه وإن الحيوانات متناسلة كما هي الآن كذلك. والخلاف الثاني مع أصحاب الهيولى في قولهم هيولى العالم قديمة وأعراضها حادثة. والخلاف الثالث مع الثنوية في قولهم: بقدم النور والظلمة. والخلاف الرابع مع أهل الطبائع الذين قالوا بقدم الأرض والماء والنار والهواء. والخلاف الخامس مع من قال بقدم هذه الأربعة وبقدم الأفلاك معها. وقال أهل الحق بحدوث جميع الأجسام والأعراض. ودليل ذلك: إنا قد دللنا قبل هذا على حدوث الأعراض في الأجسام ودللنا أيضا على استحالة تعري الأجسام من الأعراض الحادثة فيها فإذا صح أن الأجسام لم تسبق الأعراض الحادثة وجب حدوثها لأن ما لم يسبق الحوادث كان محدثا كما أن ما لم يسبق حادثا واحدا كان محدثا ولا معنى لاعتراضهم على هذه الأدلة بأن الأجسام لم تسبق الألوان والأعراض ولا يجب\r\rكونها ألوانا ولا أعراضا كذلك لم تسبق الحوادث ولا يجب كونها حوادث. لأنا نقابل الجملة بالتفصيل فإذا جاز أن لا يسبق لونا واحدا وعرضا واحدا ما لا يكون لونا وعرضا جاز أن لا يسبق الألوان والأعراض ما لا يكون لونا ولا عرضا وكل ما لم يسبق حادثا واحدا وجب كونه حادثا كذلك ما لم يسبق الحوادث كونه حادثا [وقد دخل في حكم هذه الدلالة حكم النار والأرض والهواء والماء والأفلاك والكواكب وسائر الأجسام من حيوان ونبات لأنها كلها أجسام غير سابقة الأعراض الحادثة فيها فوجب حدوث جميعها كما بيناه].\rالمسألة الثانية عشر من الأصل الثاني\r"]], "pg": [53, 54]}, "540.44": {"x": [[54, "في بيان وقوف الأرض ونهايتها"], [55, "اختلفوا في هذه المسألة [على مذاهب]: فقال المسلمون وأهل الكتاب بوقوف الأرض وسكونها وإن حركتها إنما تكون في العادة بزلزلة تصيبها. وبه قال جماعة من الفلاسفة منهم أفلاطون وأرسطاطاليس وبطليموس وأقليدس. وزعم بعض السمنية أن الأرض تهوي أبدا بما عليها. وزعم قنادوس [وحكى عن ميلاوش] أن الأرض تتحرك حركة دورية لكنها لا تزول عن مركزها. وحكى أرسطاطاليس في كتاب (السماء والعالم) عن قوم من الفلاسفة أن الفلك ساكن وأن الأرض هي التي تدور بما عليها من المشرق إلى المغرب في كل يوم وليلة دورة واحدة. وهذا عكس قول المنجمين أن الفلك يدور حول الأرض في كل يوم وليلة دورة واحدة. واختلف القائلون بوقوفها في علة وقوفها: فقال أصحابنا إنّ الله تعالى وقفها لا على جسم وليس الهواء المحيط بها حاملا لها وأجازوا وقوف كل جسم لا في مكان. [وزعمت الدهرية الذين زعموا أنه لا نهاية للأرض إلا من جهة الصفحة العليا منها إن] وزعمت القدرية النافية لنهاية العالم من تحت ومن الأطراف أن علة وقوف الأرض أنه ليس تحتها خلاء ولا عن جانب منها خلاء. وزعم أرسطاطاليس أن علة وقوفها أنها تطلب مركزها الذي في وسطها. وزعم قوم من الفلاسفة أن علة وقوفها سرعة دوران الفلك حولها [من وقوف في الفلك] قالوا: ولو وقف الفلك لسقطت الأرض من وسط الفلك إلى الجانب الأسفل منه. وقال آخرون علة\r\rوقوف الأرض جذب الفلك لها من كل جانب إلى نفسه. وقال آخرون علة وقوفها دفع الفلك لها عن نفسه من كل جانب."], [56, "وزعم ابن الراوندي أن علة وقوفها أن تحت الأرض جسما صعادا كالريح الصعادة وهي منحدرة فاعتدل الهاوي والصاعد في الجرم والقوة فلذلك وقفت فتوافقا. وزعم آخرون أن الأرض مركبة من جسمين أحدهما منحدر والآخر مصعد فاعتدلا فيها فلذلك وقفت. ودليل بطلان قول من زعم أن الأرض تهوي أبدا وصول ما نلقيه من اليد إلى الأرض والخفيف لا يلحق ما هو أثقل منه في الانحدار ما لم يكن للأثقل منها وقوف. ولو كانت للأرض حركة دورية لأحسسنا بذلك كما نحسّ بحركتها عند الزلزلة ثم إنا لو جعلنا قطعة من الأرض على طبق لم تدر عليه ولو رمينا بها في الهواء لنزلت على الاستواء ولم تدر على نفسها فإذا كانت كل قطعة منها لا تدور فكيف دارت جملتها. وقول من جعل علة وقوفها نفي النهاية عنها من غير جهة الصفحة العليا منها باطل لأن تناهيها من جهة دليل على تناهيها من سائر الجهات [ومن سار في قبلة الشرق كان ما خلّف وراءه من جهة المغرب في كل يوم أكثر مما خلفه قبل ذلك وما زاد على غيره فالمزيد عليه متناه في نفسه] ولو كانت علة وقوفها طلبها للمركز الذي في وسطها لوجب أن لو حفرنا بئرا على سمت ذلك المركز نافذة إلى الصفحة السفلى منها أن يقف الماء عند ذلك المركز لا على قرار منها وهذا محال عندهم. ومن زعم أن علة وقوفها سرعة دوران الفلك حولها (1)، سلم له دوران الفلك حول الأرض والسموات عند طباق فوق الأرض ساكنة وإنما تتحرك الكواكب فيها ولو سلمنا لهم دوران الفلك حول الأرض والهواء لم يجب بذلك وقوف الأرض لأن هذه العلة لو صحت لما صح دوران الطيور في الهواء فوق الأرض لأن الفلك يدور حولها كما يدور حول الأرض. ولو كان علة وقوفها جذب الفلك لها إلى نفسه من كل جانب لوجب إذا رمينا بقطعة من الأرض في الهواء أن\r__________________"], [57, "(1) [فمن سلم لهم دوران الفلك حول الأرض أو ما علموا من قولنا أن الفلك فوق الأرض كالطبق، وانه ليس تحت الأرض سماء وأن الفلك ساكن وأن الكواكب متحركة فيه].\r\rيذهب إلى الفلك ولا يرجع إلى الأرض. ولو كان علة وقوفها ريح صعادة تحتها كما قال ابن الراوندي لوجب أن لا ينحدر إلى الأرض ما يرمى به في الهواء عند هبوب الريح. ولو كانت الأرض مركبة من جزءين أحدهما منحدر والآخر مصعد لوجب إذا رمينا بقطعة منها في الهواء أن يقف في الهواء لأنها مركبة من منحدر وصعاد [فلما لم يكن كذلك بطلت هذه العلة وسائر العلل التي حكيناها عن مخالفينا وصح بما قلنا إن الأرض واقفة بقدرة الله تعالى وإنها متناهية من كل جهة كما بيناه] وإذا بطل (1) قول مخالفينا في هذه المسألة صح قولنا فيه.\rالمسألة الثالثة عشر من الأصل الثاني\r"]], "pg": [54, 57]}, "540.45": {"x": [[57, "في وقوف السماوات وأعدادها"], [58, "زعم قوم من الفلكية أن الفلك قديم لا صانع له. وزعم آخرون أنه قديم وله صانع. وزعم قوم من الفلكية أنه من العناصر الأربعة وإن القول فيها كالقول في الأرض والماء والنار والهواء. وزعم آخرون منهم أنه طبيعة (خامدة) (2) ليست فيها حرارة ولا برودة وليس هو بخفيف ولا ثقيل ولا يجوز عليه الزيادة والنقصان. ومنع ارسطاطاليس من طريان الفساد على الأفلاك وأجاز ذلك آخرون منهم وزعم أكثرهم أن شكل الفلك (كرى) (3). وزعم قوم أنه كنصف بيضة أو كنصف كرة ومنهم من قال إنّه كرة زعموا أنه يتحرك من جهة المشرق إلى المغرب حركة دورية في كل يوم وليلة مرة واحدة وأنّ الكواكب التي فيه تتحرك من المغرب إلى المشرق على خلاف سمت حركة الفلك. وزعم أكثرهم أن أعداد الأفلاك تسعة، منها سبعة للكواكب السبعة التي هي زحل والمشتري والمرّيخ والشمس والزهرة وعطارد والقمر وقالوا: إن أدناها إلينا فلك القمر وأبعدها فلك زحل. وفوق الأفلاك السبعة فلك البروج وفيها الكواكب الثابتة وفوقه الفلك الأعظم الذي سموه مدبر الكل [وزعم آخرون منهم أن الأفلاك ثمانية وليس فوق فلك البروج فلك].\r__________________\r(1) وردت في المطبوع «بطلت».\r(2) وردت في المطبوع «خامسة».\r(3) كروي."], [59, "وذهب المسلمون وأهل الكتاب إلى أن الأفلاك سبعة طباق بعضها فوق بعض وقالوا إنها ساكنة وإنما يتحرك فيها الكواكب وهي كلها في السماء السفلى دون ما فوقها [ودليل حدوث الأفلاك في جملة دليل حدوث الأجسام والعلم بأعداد الأفلاك واقع من طريق الشرع لا مجال للحس فيه. ومن زعم أن الأفلاك متحركة حركة دورية أبطل كون العرش والملائكة فوق الأفلاك وبناه على كون الأفلاك (كريّة) (1) ولا دليل معه على ذلك. ومن زعم أن لكل كوكب من الكواكب فلكا مخصوصا استدل عليه بأن كل كوكبين عند اقترانهما يرى الأسفل منهما دون الأعلى وهذه العلة منتقضة بالشمس فإن كل كوكب يقارن الشمس لا يرى عند مقارنته للشمس ولا عند محاذاته لها في النقطة الواحدة من برج واحد ومع ذلك فقد زعموا أن بعض الكواكب تحتها وفي هذا نقض اعتلالهم وإذا لم يسلم لهم كون الفلك كرة وقلنا إنه طبق مبسوط بطل دعواهم وجوب حركته وإن كانت جائزة في العقل، وقد استقصينا هذه المسألة وأشكالها في كتابنا الذي سميناه (كتاب هيئة العالم)] وقد دللنا على حدوث الأفلاك والكواكب بالدلالة على حدوث الأجسام كلها. ومن زعم أن الأفلاك متحركة حركة دورية أبطل كون العرش والملائكة فوق السموات وفيما بينها. ومن زعم أن الكواكب السبعة في سبعة أفلاك استدل بأن الكواكب عند اقترانها يرى الأسفل منها دون الأعلى. وهذه العلة منتقضة بالشمس فإنها إذا قارنت كوكبا أيّها كان فهي المرئية دون ذلك الكوكب وإن كان المقارن لها عندهم تحت الشمس كالقمر والزهرة وعطارد.\rالمسألة الرابعة عشرة من الأصل الثاني\r"]], "pg": [57, 59]}, "540.46": {"x": [[59, "في إثبات نهاية العالم\rوزعم القدرية [الدهرية] أن الأرض لا نهاية لها من خمس جهات وإنما لها نهاية من الوجه الذي تلاقي منه الهواء من فوق. وزعموا أيضا أن السموات لا نهاية لها في الأقطار. وقد دللنا قبل هذا على نهاية الأرض ودليل نهاية السموات\r__________________\r(1) كروية."], [60, "[السماء] دوران الشمس والقمر والكواكب في كل دور لها إلى أن يعود كل واحد منها إلى مشرقه الذي منه سار فإن [كان] كل كوكب ينتهي إلى مشرقه بقطعه الفلك وجب بذلك تناهي الفلك وإن كانت الكواكب ترى من الفلك في بعض أقطار الأرض وتدور تحت الأرض إلى أن يرجع إلى مشرقه ثبت بذلك كون الأرض متناهية ولأن الماء والهواء اللذين هما بين الأرض والفلك متناهيان من كل جهة وإذا تناهى ركنان من العالم من كل جهة فكذلك سائر أركانه متناهية من كل جهة.\rالمسألة الخامسة عشرة من الأصل الثاني\r"]], "pg": [59, 60]}, "540.47": {"x": [[60, "في إجازة الفناء على العالم\rواختلفوا في هذه المسألة: فمن قال بقدم الأجسام أحال عدمها وكل من قال بحدوثها أجاز الفناء عليها إلا الجاحظ فإنه أحال عدم الأجسام والذين أجازوا فناءها اختلفوا في كيفية فنائها: فقال شيخنا أبو الحسن الأشعري إنّ الله عزوجل إذا أراد فناء جسم لم يخلق البقاء فيه. وقال بعض أصحابنا (1) وهو القاضي أبو بكر ابن الطيب (2) إنّ الله عزوجل يفني الجسم بقطع الأكوان عنه فإذا لم يخلق في الجسم لونا ولا كونا فني ذلك الجسم. وزعم القلانسي من أصحابنا أن الله تعالى يخلق في الجسم فناء يفني [به] في الحال الثانية من حال حدوث الفناء فيه. وزعم الجبائي وابنه أن الله تعالى يخلق فناء لا في محل فيفني به جميع الأجسام وزعم أن الله ليس بقادر على إفناء بعض الأجسام مع بقاء بعضها. وقول الجاحظ كفر عند سلف الأمة لأنه أحال أن يبقى الإله سبحانه فردا كما كان في الأزل فردا. ودليل فساد قول القلانسي أن الجسم إذا لم يفن بالفناء في حال حدوثه فكيف يفنى به في الثاني من حال حدوثه. وقول الجبائي وابنه صريح في الكفر لأنهما وصفا الله تعالى بالقدرة على فناء كل لا يقدر على فناء بعضه. والحمد لله على العصمة من كل بدعة\r__________________\r(1) أصحابه."], [61, "(2) [ان الأجسام لا تعرى عن الأكوان والألوان فإذا أراد الله إفناء جسم قطع عنه الأكوان والأجسام وإذا لم يخلق في الجسم الكون واللون صار معدوما].\r\rالأصل الثالث\r"]], "pg": [60, 61]}, "540.48": {"x": [[61, "من أصول هذا الكتاب في معرفة صانع العالم\rومعرفة نعوته الذاتية\rوفي هذا الأصل أيضا خمس عشرة مسألة هذه ترجمتها:\rمسألة في أن الحوادث لا بد لها من محدث.\rمسألة في أن صانعها صنعها لا من شيء.\rمسألة في أن الصانع قديم.\rمسألة في أنه قائم بنفسه.\rمسألة في نفي الحدّ والنهاية عنه.\rمسألة في إحالة الأجزاء والأبعاض عليه.\rمسألة في إحالة كونه في مكان دون مكان.\rمسألة في إحالة وصفه بالألوان والطعوم.\rمسألة في إحالة الآفات عليه.\rمسألة في إحالة العدم عليه.\rمسألة في إحالة الحجر عليه فيما يخلق.\rمسألة في غناه عن خلقه وعن اجترار نفع إلى نفسه.\rمسألة في كونه خالقا لأنواع الحوادث.\rمسألة في أنه هو المفني لما يفنى.\rمسألة في بيان أوصافه الذاتية. وسنذكر في كل واحد من هذه المسائل مقتضاها إن شاء الله تعالى.\r\rالمسألة الأولى من الأصل الثالث\r"]], "pg": [61, 61]}, "540.49": {"x": [[61, "في أن الحوادث لا بد لها من محدث"], [62, "وزعم قوم من الكفرة الدهرية: أن كل حادث يحدث في نفسه لا من صانع وادعوا ذلك في الثمار الخارجة من الأشجار وقد أقروا بحدوثها وأنكروا محدثها وأنكروا الأعراض. وفرقة منهم قالت بحدوث الأثمار لا من صانع وأثبتوا للأعراض فاعلا. ومن قال من الدهرية بأن الطبع هو الفاعل ولم يصف الطبع بصفة الصانع الحي القادر العالم فهو أيضا من جملة منكري الصانع والدليل على أن الحادث لا بد له من محدث أنه يحدث في وقت ويحدث ما هو من جنسه في وقت آخر فلو كان حدوثه في وقته لاختصاصه لوجب أن يحدث في وقته كل ما هو من جنسه وإذا بطل اختصاصه بوقته لأجل الوقت صح أن اختصاصه به لأجل مخصص خصصه به لو لا تخصيصه إياه به لم يكن حدوثه في وقته أولى من حدوثه قبل ذلك أو بعده ولأنه إذا لم يصح حدوث كتابة لا من كاتب ونسج لا من ناسج وبناء لا من بان كذلك لا يصح وقوع حادث لا من محدث [فإن قيل لم لا يجوز أن يكون محدثه الطبع؟ قيل إنّ الطبع المضاف إليه الفعل لو أريد به فاعل حي قادر عالم فهو الصانع الذي أثبتناه وإن أريد به ما ليس بحيّ ولا موجود أصلا فما ليس بموجود لا يكون فاعلا. فإن قيل لم لا يكون فاعله طبعا موجودا إلا أنه ليس بحي قيل أن الموجود الذي ليس بحي إن كان قائما بنفسه فهو جسم أو جوهر وقد دللنا على حدوث الجواهر والأجسام وافتقارهما إلى صانع وإن كان غير قائم بنفسه فهو عرض ولا يصح كون العرض فاعلا. فإن قيل لم لا يجوز أن يكون الحادث أحدث نفسه؟ قيل لأنه يستحيل من المعدوم إحداث نفسه لاستحالة كون المعدوم فاعلا وإذا حدث فحدوثه يغنيه عن إحداث نفسه فبطل إحداث نفسه وصح أن محدثه غيره].\rالمسألة الثانية من الأصل الثالث\r"]], "pg": [61, 62]}, "540.50": {"x": [[62, "في أن صانع الحوادث أحدثها لا من شيء\rذهب الموحدون إلى أن الصانع خلق الأجسام والأعراض ابتداء لا من"], [63, "شيء. وقالوا: لم يكن الحوادث قبل حدوثها أشياء ولا أعيانا ولا جواهر ولا عوارض وبعد أن أحدثها صانعها يصح منه نقلها من صورة إلى صورة وإخراج جنس مخصوص من بين جنسين مختلفين في الصورة كإخراجه البغل من بين الفرس والحمار والسّمع والعسبان بين الذيب والضّبع ونحو ذلك. وفي هذه الجملة خلاف من وجوه:\rأحدها: مع قوم من أصحاب الهيولى أثبتوا الصانع ولكنهم زعموا أن الصانع صنع هذا العالم من هيولى قديمة [وقالوا لم نر صانعا صنع شيئا لا من أصل فإن الصانع يصنع الخاتم من الفضة أو الذهب أو أصل آخر والنجار يصنع الباب من خشب ونحو ذلك].\rوالخلاف الثاني: مع قوم زعموا أن الصانع ركّب المركبات من الطبائع الأربع وعناصرها التي هي الأرض والماء والنار والهواء وقالوا بقدم هذه الأربع.\rوالخلاف الثالث: مع المعتزلة الذين قالوا إنّ الحوادث كانت قبل حدوثها أشياء وأعيانا وزعموا أن السواد كان في حال عدمه سوادا وأثبتوا للمعدوم في حال عدمه كلّ اسم يستحق الموجود لنفسه أو لجنسه. ومنهم من أثبت الجسم في حال عدمه جسما. وقد دللنا قبل هذا على حدوث الأرض والماء والنار والهواء ووجب من ذلك أن صانع هذه الأربع غيرها وأبطلنا قول أصحاب الهيولي أيضا من قبل. فأما قول المعتزلة بأن المعدوم شيء، وقول من قال بأن السواد في حال عدمه سواد والجوهر في حال عدمه جوهر، فيوجب عليهم القول بقدم الجواهر والأعراض لأنهم قد أثبتوا لهما في الأزل كل صفة نفسية والوجود ليس بمعنى زائد على النفس لأن المحدث لا يكون محدثا لمعنى غير نفسه فإذا لم يزل الجواهر والأعراض عندهم في الأزل جواهر وأعراضا وجب أن يكون في الأزل موجودة لأن وجودها ليس بأكثر من ذواتها، وقد قال المسلمون: خلق الله عزوجل الشيء لا من شيء. وقالت المعتزلة: إنّه خلق الشيء من شيء فأضمروا قدم الأشياء لقولهم بما يؤدي إليه [كأنهم أضمروا قدم العالم ولم يجسروا على إظهاره فقالوا بما يؤدي إليه]."], [64, "المسألة الثالثة من الأصل الثالث\r"]], "pg": [62, 64]}, "540.51": {"x": [[64, "في أن الصانع قديم\rأجمع الموحدون على أن الصانع للعالم قديم وخالفهم في ذلك فرق:\rأحدها: المجوس، فإنهم قالوا للعالم صانعان أحدهما إله قديم، والثاني شيطان حادث من فكرة الإله القديم، وزعموا أن صانع الشرور حادث. والفرقة الثانية: حلولية الرافضة فإنهم وإن قالوا بأن الإله قديم فقد زعموا أو روح الإله انتقلت إلى الأئمة وزعموا أن الإمام بعد حلول روح الإله فيه يصير صانعا وإلها وهو حادث بنفسه. والفرقة الثالثة: حائطيّة من المعتزلة من أصحاب أحمد بن حائط زعموا أن للعالم صانعين أحدهما الإله القديم والآخر المسيح وهو محدث خلقه الله أولا ثم فوض إليه تدبير العالم وهو الذي يحاسب الخلق في الآخرة [وإنما سمي مسيحا لأنه يذرع جسد الإنسان]. والكلام على المجوس يأتي في باب توحيد الصانع. وقول الحلولية باطل لأنا قد دللنا على أن الإله ليس من جنس الجواهر والأعراض ولأنه قد ثبت عندنا أنه حي بلا روح فيستحيل وصفه بانتقال روح منه إلى غيره ولو كان الصانع محدثا لافتقر إلى محدث له ولو كان محدثه أيضا محدثا لافتقر إلى محدث ثالث وهذا يتسلسل لا إلى نهاية وهو محال وما أدّى إلى محال فهو محال [وصح باستحالة ذلك وجوب كون الصانع قديما].\rالمسألة الرابعة من الأصل الثالث\r"]], "pg": [64, 64]}, "540.52": {"x": [[64, "في قيام الصانع بنفسه\rودليل هذه المسألة أنه لو لم يقم بنفسه لافتقر إلى محل وكان محله بكونه صانعا أولى منه وإذا صح وجود الصانع وبطل افتقاره إلى محل صحّ إنه قائم بنفسه.\rالمسألة الخامسة من الأصل الثالث\r"]], "pg": [64, 64]}, "540.53": {"x": [[64, "في نفي الحد والنهاية عن الصانع\rوهذه المسألة مع فرق: منها الهشامية من غلاة الروافض الذين زعموا أن"], [65, "معبودهم سبعة أشبار بشبر نفسه. ومنهم من قال إنّ الجبل أعظم منه كما حكي عن هشام بن الحكم. والخلاف الثاني: مع الكرّامية الذين زعموا أن له حدا واحدا من جهة السفل ومنها يلاقي العرش. والخلاف الثالث: مع من زعم من مشبهة الرافضة أنه على مقدار مساحة العرش لا يفضل من أحدهما عن الآخر شيء. فقلنا لهم لو كان الإله مقدرا بحدّ ونهاية لم يخل من أن يكون مقداره مثل أقل المقادير فيكون كالجزء الذي لا يتجزّأ أو يختص ببعض المقادير فيتعارض فيه المقادير فلا يكون بعضها أولى من بعض إلا بمخصص خصه ببعضها وإذا بطل هذان الوجهان صح أنه بلا حد ولا نهاية. وقول من أثبت له حدا من جهة السفل وحدها كقول الثنوية بتناهي النور من الجهة التي يلاقي الظلام منها وكفى بهذا خزيا.\rالمسألة السادسة من الأصل الثالث\r"]], "pg": [64, 65]}, "540.54": {"x": [[65, "في إحالة الأبعاض على الصانع\rوالخلاف في هذا مع فرق. منها البيانية من الرافضة زعموا أن معبودهم رجل من نور وأعضاؤه كأعضاء الرجل وزعموا أيضا أن أعضائه كلها تفنى إلا وجهه واستدلّوا بقوله: (وَيَبْقى وَجْهُ رَبِّكَ) (1). والخلاف الثاني مع المغيرية من الرافضة وهم أصحاب المغيرة بن سعيد العجلي الذي زعم أن أعضاء معبوده على صورة حروف الهجاء وزعم أيضا أن الله تعالى كتب بإصبعه على كفه أعمال عباده من طاعة ومعصية ونظر فيها فغضب من معاصيهم فعرق فاجتمع من عرقه بحران أحدهما عذب نيّر خلق منه المؤمنين والآخر مالح مظلم خلق منه الكفرة ثم اطلع في البحر فرأى ظلّ نفسه فانتزع عيني ظلّه وخلق منهما الشمس والقمر وأفنى باقي ظلّه وقال لا ينبغي أن يكون معي إله غيري وزعم أيضا أن الله تعالى تكلم باسمه الأعظم فطار وصار تاجا على رأسه وزعم أن ذلك تأويل قوله: (سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى) (2). والخلاف الثالث: مع داود الجواربي الذي أضاف إلى معبوده جميع\r__________________\r(1) سورة الرحمن آية 27.\r(2) سورة الاعلى آية 1."], [66, "أعضاء الإنسان إلا الفرج واللحية. ومثله الخلاف مع هشام بن سالم الجواليقي الذي زعم أن معبوده على صورة الإنسان غير أن نصفه الأعلى مجوّف ونصفه الأسفل مصمت وزعم أن له شعرا أسود هو نور أسود. وقال هؤلاء شبهناه بصورة الإنسان لقوله تعالى: (لَقَدْ خَلَقْنَا الْإِنْسانَ فِي أَحْسَنِ تَقْوِيمٍ) (1)، وقالوا أحسن تقويم، ما كان على صورة الإله واستدلّوا أيضا بقول النبي صلىلله عليه وسلم: «إن الله خلق آدم على صورته»، واستدلّوا على إثبات الأعضاء له بقوله: (وَيَبْقى وَجْهُ رَبِّكَ) (2) و (خَلَقْتُ بِيَدَيَ) (3)، وفي الحديث: يضع الجبّار قدمه في النّار، وروي: قلب المؤمن بين إصبعين من أصابع الرحمن (4). ودليلنا على أن الله واحد في ذاته ليس بذي أجزاء وأبعاض إنه قد صح أنه حي قادر عالم مريد فلو كان ذا أجزاء وأبعاض لم يخل من أن يكون في كل جزء منه حياة وقدرة وعلم وإرادة أو يكون هذه الصفات في بعض أجزائه فإن كان في كل جزء منه مثل هذه الصفات كان كل جزء منه حيا قادرا عالما مريدا بانفراده ولو كان كذلك لصح وقوع الخلاف بين أعضائه حتى يريد بعضه شيئا وبعضه يريد ضد ذلك المراد وخلافه [فتتمانع أعضاؤه] وإن كانت تلك الصفات في بعض أعضائه وجب قيام أضداد تلك الصفات بالباقية من أعضائه فكان يكون بعضه حيا قادرا عالما مريدا وبعضه ميتا وعاجزا وجاهلا ساهيا ولم يكن الحي منها بالحياة أولى من غيره إلا بمخصص خصه بها وهذا يقتضي افتقار الصانع إلى صانع سواه وهذا محال فما يؤدي إليه مثله. وإذا قالت البيانية إنّ معبودهم يفنى كله إلا وجهه فما يؤمنهم من فناء وجهه إن جاز الفناء على بعضه."], [67, "وأما قوله: (لَقَدْ خَلَقْنَا الْإِنْسانَ فِي أَحْسَنِ تَقْوِيمٍ) (5)، فليس التقويم في هذه الآية مضافة إلى الله عزوجل وإنما معناه أنه ليس فيما خلق الله عزوجل أحسن صورة وتقويما من الإنسان ومعنى قول النبي صلىلله عليه وسلم: «إن الله خلق آدم على صورته» هو أنه خلقه حين خلقه على الصورة التي كان عليها في الدنيا، لم ينقله\r__________________\r(1) سورة التين آية 4. (2) سورة الرحمن آية 27. (3) سورة ص آية 75. (4) أخرجه الحاكم بلفظ «قلب ابن آدم ... » 2/ 289. (5) سورة التين آية 4.\r\rفي الأصلاب والأرحام على اختلاف الأحوال من نطفة إلى علقة ومضغة وجنين كما فعل ذلك بنسله ولم يشوّه خلقه عند إخراجه من الجنة كما فعل بالحيّة حين أخرجها من الجنة فشوه صورتها بأن مسخ قوائمها حتى مشت على بطنها وشق أسنانها وسوّد لسانها أيضا ولم يشوّه شيئا من صورة آدم عليه السلام. فذلك معنى قوله: خلقه على صورته والكناية راجعة إلى آدم عليه السلام. وأما قوله: (وَيَبْقى وَجْهُ رَبِّكَ) (1)، فمعناه ويبقى ربك لأنه قال عقيبه (ذُو الْجَلالِ وَالْإِكْرامِ) وهذا نعت الوجه فلو كان الوجه مضافا إليه لقال ذي الجلال خفضا بالإضافة. وأما الجبار الذي يضع قدمه في النار فهو الذي قال الله تعالى فيه: (جَبَّارٍ عَنِيدٍ مِنْ وَرائِهِ جَهَنَّمُ) (2). والإصبع المذكورة في الخبر بمعنى النعمة وقلب المؤمن بين نعمتي الخوف والرجاء. واليد المضافة إلى الله تعالى صفة له خاصة وقدرة له بها فعله. والحمد لله على العصمة من التشبيه والتعطيل.\rالمسألة السابعة من الأصل الثالث\r"]], "pg": [65, 67]}, "540.55": {"x": [[67, "في إحالة كون الإله في مكان دون مكان"], [68, "والخلاف في هذه المسألة مع فرق، أحدها: مع قوم زعموا أن الإله في مكان مخصوص متمكن فيه [مماس له] (3). وهذا قول الكرّامية والهشامية من الروافض وزعموا جميعا إنه ملاق لعرشه من فوقه على وجه لا يكون بينهما واسطة إلا بأن يحط العرش إلى أسفل حتى يسع بينهما شيء من غيرهما.\rوالخلاف الثاني: مع الحلولية الذين زعموا أنّ الإله يدخل في الصورة الحسنة وربما سجد الواحد منهم للصورة الحسنة إذا رآها فوهم أنه فيها.\r__________________\r(1) سورة الرحمن آية 27. (2) [مماس له، كما ذهب إليه الهشامية من الروافض والكرامية في دعواهم انه مماس للعرش من فوق العرش. ومن الكرامية من يقول: لا أقول أنه مماس بعرشه لكن أقول أنه ملاق للعرش على وجه لا يصح ان يكون بينهما واسطة إلا بأن ينزل العرش الى اسفل بحيث يصح أن يتحصل بينهما جسم متوسط]. (3) سورة إبراهيم آية 16."], [69, "والخلاف الثالث: مع المعتزلة في قولهم إنّ الله في كل مكان على معنى إنه عالم بما في كل مكان مدبر. ودليلنا على أنه ليس في مكان بمعنى المماسة قيام الدلالة على أنه ليس بجوهر ولا جسم ولا ذي حد ونهاية والمماسة لا تصح إلا من الأجسام والجواهر التي لها حدود. وقد دللنا قبل هذا على أن الإله غير محدود بحد ونهاية فلذلك لم يجز المماسة عليه. وأما الحلولية فإن أرادوا بحلول الإله في الأشخاص مماسّته أو مجاورته لها فقد أبطلنا ذلك وإن أرادوا حلولا مثل حلول الأعراض في الأجسام فقد أوجبوا كون الإله عرضا غير قائم بنفسه وما لا يقوم بنفسه لا يصح كونه صانعا وإن أرادوا بالحلول وقوع ضوء منه على الصورة فليس الإله جسما ذا شعاع وإنما وصفناه بأنه نور السموات والأرض على معنى أنه منوّرهما. وأما قول المعتزلة أنه (1) في كل مكان بمعنى التدبير له والعلم فيه فيلزمه على هذا القول أن يقول في المسجد والحمام وفي بطن المرأة لأنه عالم بما في هذه الأمكنة مدبر لها وهذا فاسد فما يؤدي إليه مثله (2). واستدل من أثبت له مكانا بقوله: (الرَّحْمنُ عَلَى الْعَرْشِ اسْتَوى) (3). ومعناه عندنا: على الملك استوى أي استوى الملك للإله والعرش هاهنا بمعنى الملك من قولهم: ثلّ عرش فلان، إذا ذهب ملكه ومنه قول الشاعر:\rبعد ابن جفنة وابن هاتك عرشه ... والحارثين يؤمّلون فلاحا\r\rوأراد بالعرش الملك. وقد استقصينا هذه المسألة في كتاب مفرد.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [67, 69]}, "540.56": {"x": [[69, "في إحالة وصف الله تعالى بالألوان والطعوم والروائح\rقال أصحابنا: لا نثبت لله عزوجل من الصفات القائمة بذاته إلا م"]], "pg": [69, 69]}, "540.57": {"x": [[69, "ا دل عليه\r__________________\r(1) [أي علمه في كل مكان ومدبر لما فيه].\r(2) وإذا بطلت هذه الأقوال صح أن الله تعالى لا يقلّه مكان ولا يجري عليه].\r(3) سورة طه آية 15."], [70, "فعله أو كان في رفعه إثبات نقص له أو ما كان [إثباته شرطا في صفة سواه] شرطا في صفة له. فصفاته التي تدل عليها أفعاله القدرة والعلم والإرادة. لأن وقوع الفعل منه دليل على قدرته وترتيب أفعاله دليل على علمه واختصاص فعله بحال دون حال دليل على قصده وإرادته. وأما صفته المشروطة لصفة سواها فحياته التي هي شرط قدرته وعلمه وإرادته. والصفات الواجبة لأجل نفي النقائص عنه فالسمع والبصر والكلام لنفي السكوت والصمم والعمى عنه وليس اللون والطعم والرائحة مما يدل عليه فعل ولا هو مما يكون شرطا في صفة سواه ولا ينفي نقصا مخصوصا فلذلك لم يجوّز وصف الله به.\rالمسألة التاسعة من هذا الأصل\r"]], "pg": [69, 70]}, "540.58": {"x": [[70, "في إحالة الآفات والسرور والغم عليه\rأجمع الموحدون على نفي الآفات والغموم والآلام واللذات عن الله تعالى. وحكي عن أبي أشعث وابن شعيب الناسك أنهما أجازا عليه السرور والغم والتعب والاستراحة. وأجازت الهشامية من الرافضة عليه الحركة. وزعم بعضهم أن إرادته من حركاته. وهؤلاء مضاهون للمجوس الذين زعموا أن الإله اهتمّ لما تفكر في خروج ضد له فتولّد من اهتمامه الشيطان. واستدل من أجاز ذلك عليه بما روي: أن الله تعالى خلق الخلق في ستة أيام واستراح يوم السبت (وقال اليهود:) (1) يستريح في السبت لذلك. وفي الحديث: «أن الله تعالى لا يملّ حتى تملوا» وفي حديث آخر: «لله أفرح بتوبة العبد من الواجد ضالّته». وروي: أن الله تعالى يضحك إلى رجلين يقتل أحدهما الآخر وكلاهما يدخل الجنة. واستدلوا بقوله تعالى: (نَسُوا اللهَ فَنَسِيَهُمْ) (2). واستدلوا في الحياء بقوله: (إِنَّ اللهَ لا يَسْتَحْيِي أَنْ يَضْرِبَ) (3). وفي الحديث: إن الله يستحي أن يرفع العبد إليه يديه فيردهما\r__________________\r(1) وردت في المطبوع «وقالوا أن اليهود».\r(2) سورة التوبة آية 67.\r(3) سورة البقرة آية 26."], [71, "صفرا (1). قلنا لهم: إن السبت لم يسمّ سبتا للراحة فيه وإنما سمي بذلك لقطع العمل فيه. ويجوز أن يكون الله تعالى أكمل خلق العالم يوم الجمعة فلم يخلق يوم السبت شيئا من أركان العالم دون أعراضه فإنه يجدد الأعراض في كل حال. وأما حديث الملالة فإنما سمي فيه الفعلان مللّا والملل في أحدهما للازدواج بينهما كقوله: (وَإِنْ عاقَبْتُمْ فَعاقِبُوا بِمِثْلِ ما عُوقِبْتُمْ بِهِ) (2)، والعقاب هو الثاني دون الأول. وأما الفرح فعلى ثلاثة أوجه: أحدها السرور الذي ذكروه والثاني البطر ومنه قوله: (إِنَّ اللهَ لا يُحِبُّ الْفَرِحِينَ) (3) وهذان الوجهان لا يليقان بالله عزوجل. والثالث: الفرح بمعنى الرضا كقوله: (كُلُّ حِزْبٍ بِما لَدَيْهِمْ فَرِحُونَ) (4)، أي راضون وهذا معنى الفرح المضاف إلى الله تعالى في توبة عبده. والضحك المضاف إليه على معنى الإبانة والإظهار من قولهم هذا طريق ضاحك إذا كان بيّنا واضحا ومنه قول الأعشى في صفة النبات:\r«يضاحك الشمس منها كوكب شرق ... مؤزّر بعميم النّبت مكتهل»\r\rومعنى الخبر فيه أن الله تعالى يظهر من برّه لعبده ما كان مستورا عن غيره.\rوأما النسيان المضاف إليه في القرآن فمعناه الترك لأن قوله (نَسُوا اللهَ)، أي تركوا العمل بطاعته وجزاؤهم أيضا ترك الثواب والغفران لهم. وأما السهو فلا يكون عليه العقاب.\rالمسألة العاشرة من هذا الأصل\r"]], "pg": [70, 71]}, "540.59": {"x": [[71, "في إحالة العدم على الله تعالى\rكل من قال بقدم الصانع أحال عليه العدم إلا بيان بن سمعان الرافضي،\r__________________\r(1) أخرجه الحاكم في المستدرك عن سلمان بلفظ: ان الله يستحي ان يبسط العبد ...\r1/ 497.\r(2) سورة النحل آية 126.\r(3) سورة القصص آية 76.\r(4) سورة المؤمنون آية 53."], [72, "زعم أن معبوده يفنى كل شيء منه إلا وجهه. والدليل على استحالة عدم القديم أنه لو عدم لم يخل من ثلاثة أوجه: إما أن يعدم لاستحالة بقائه كما يعدم الحركة بعد حدوثها لاستحالة بقائها ولو كان عدم القديم على هذا الوجه لبطل قدمه لأن ما يستحيل بقاؤه لا يكون قديما وإما أن يعدم لقطع إحداث البقاء فيه كما يقول أصحابنا في الجسم إذا لم يخلق فيه البقاء عدم فهذا محال في وصف القديم لاستحالة كونه محلا للحوادث وإما أن يعدم لطريان ضد عليه وهذا محال لأنه ليس عدم الشيء بضد يطرأ عليه أولى من عدم ذلك في محله بضده الطارئ عليه. ولسنا نقول إنّ العرض عدم لضده وإنما عدم في الثاني من حال حدوثه لاستحالة بقائه وإنما طرأ ضده عقيبه لأن المحل لا يخلو من العرض وضده.\rالمسألة الحادية عشرة من هذا الأصل\r"]], "pg": [71, 72]}, "540.60": {"x": [[72, "في إحالة الحجر على الله عزوجل\rنقول: إن الله تعالى عادل في كل أفعاله غير محجور عليه في شيء، ما شاء فعل وما شاء ترك له الخلق والأمر لا يسأل عما يفعل. وقد حجرت القدرية عليه في قولها: إنّه ليس له خلق أعمال العباد [وهم في ذلك شر من المجوس الذين زعموا أنه ليس له خلق الشرور من الأعمال وأضافوا إليه اختراع الخيرات كلها واستقصاء هذه المسألة يأتي في مسألة التعديل والتجوير بعد هذا إن شاء الله تعالى] وفي قولهم إنّه ليس له منع اللطف ولا له التكليف من غير تعويض للمنفعة وليس له إسقاط التكليف عن العقلاء في الدنيا. وقلنا لو فعل ذلك لجاز وكان حكمة منه لا يسأل عما يفعل وهم يسألون.\rالمسألة الثانية عشرة من هذا الأصل\r"]], "pg": [72, 72]}, "540.61": {"x": [[72, "في بيان غنى الصانع من خلقه\rمن أصلنا أن الله تعالى غني عن خلقه ما خلق الخلق لاجتلاب نفع إلى نفسه ولا لدفع ضرر عن نفسه ولو لم يخلقهم لجاز ولو أدام حياتهم جاز ولو أفناهم"], [73, "في حال واحدة جاز. وزعمت المجوس أن الإله إنما خلق الملائكة ليدفع بهم عن نفسه أذى الشيطان وأعوانه. وزعمت القدرية أنه إنما خلقهم [للعبادة وليشكروه] مع علمه بكفر الكثير منهم وقالوا لو لم يكلفهم معرفته وشكره لم يكن حكيما. وهذا يوجب عليهم أن يكون إنما كلفهم لحفظ الحكمة على نفسه وفي هذا اجتلاب نفع (1) إلى نفسه. تعالى عن ذلك علوا كبيرا.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [72, 73]}, "540.62": {"x": [[73, "في أن الصانع صانع لأنواع الحوادث كلها\rمن أصلنا أن صانع الأجسام هو صانع الأعراض كلها [خيرها وشرها]. وفي هذا اختلاف من وجوه:\rأحدها: مع الثنوية (2) [الذين زعموا أن النور خالق الخيرات والمنافع وأن الظلام خالق الشرور والمضار. وزعمت المجوس أن الشرور والمضار من خلق شيطان سموه أهرمن، وزعموا أن أهرمن حدث من فكرة الإله في نفسه فلما حدث حارب الإله حتى صالحه على مدة سبعة آلاف سنة ثم يرجعان إلى المحاربة ويظفر به الإله ويحبسه في خندق فيستريح منه العباد والبلاد] في دعواها أن خالق الشرور غير خالق الخيرات.\rوالخلاف الثاني: مع الفلكية الذين نسبوا تدبير العالم وتقدير الحوادث إلى الكواكب السبعة والطبائع الأربع.\rوالخلاف الثالث: مع من قال من القدرية إنّ الله عزوجل إنما خلق الأجسام\r__________________\r(1) [ودفع ضرر].\r(2) الذين زعموا أن النور خالق الخيرات والمنافع وإن الظلام خالق الشرور والمضار. وزعمت المجوس أن الشرور والمضار من خلق شيطان سموه أهرمن، وزعموا ان اهرمن حدث من فكرة الإله في نفسه فلما حدث حارب الإله حتى صالحه على مدة سبعة آلاف سنة ثم يرجعان الى المحاربة ويظفر به الإله ويحبسه في خندق فيستريح منه العباد والبلاد].\r\rدون الأعراض كما ذهب إليه [ابن] معتمر [حيث زعم أن الجوهر الواحد لا يحتمل العرض].\rوالخلاف الرابع (1): مع القدرية الذين زعموا أن المتولدات وسائر أكساب العباد ليست مخلوقة لله عزوجل."], [74, "والخلاف الخامس (2): مع معمر في قوله إن المتولدات أفعال لا فاعل لها بحال وقول معمر تصريح بأن الله عزوجل لم يخلق لونا ولا طعما ولا رائحة ولا سمعا ولا بصرا ولا سقما ولا مرضا ولا حياة ولا موتا وفيه إبطال فائدة وصف الله عزوجل بأنه يحيي ويميت [وقيل له: هل تثبت لله كلاما؟ فإن قال لا، أبطل الشرع بإبطاله أمر الله ونهيه وإن أثبت له كلاما قيل له هل كلامه صفة له أزلية كما ذهب إليه أصحاب الحديث أو فعل من أفعاله كما قال أصحابكم في الاعتزال؟ فإن زعم إنه صفة له قائمة به ترك أصله في نفي الصفات عن الله تعالى وإن قال له كلام هو فعله أبطل قوله بأن الله لم يخلق شيئا من الأعراض. فأما الكلام في توحيد الصانع وانفراده] وإذا لم يكن كلامه عنده من فعله ولا صفة قائمة به لنفيه الصفات لم يكن له كلام أصلا وفيه إبطال الأمر والنهي منه وفي ذلك إبطال أحكام الشريعة وما أضمر غيره؟ لأنه قال بما يؤدي إليه. وأما الدلالة على توحيد الصانع وانفراده بخلق العالم كله أعراضه وأجسامه فمن حيث أنه لو كان للعالم صانعان قديمان لوجب أن يكونا حيين قادرين عالمين مختارين لأن من لم يكن بهذه الصفة لم يكن صانعا ولو كانا حيين قادرين مريدين عالمين جاز اختلافهما في المراد وكان اختلافهما في المراد بأن يريد أحدهما حياة جسم ويريد الآخر موته ولم يخل حينئذ من أن يتم مرادهما معا أو لا يتم مرادهما معا أو يتم مراد أحدهما دون الآخر ومحال تمام مرادهما لاستحالة\r__________________\r(1) [مع من قال: ان الفاعل المخلوق إنما يحدث الإرادة وما سواها من الحوادث فعل الإله كما ذهب إليه الجاحظ والنظام].\r(2) [مع جمهور القدرية في دعواها ان المتولدات وسائر الأعمال المكتسبة ليست من خلق الله تعالى، والكلام في خلق الأعمال يأتي بعد هذا إن شاء الله، وقول معمر تصريح منه]."], [75, "كون الشيء حيا أو ميتا في حالة واحدة وإن لم يتم مرادهما ظهر عجزهما وإن تم مراد أحدهما دون الآخر ظهر عجز الذي لم يتم مراده والعاجز لا يكون إلها فإن قيل فما أنكرتم أن لا يختلفا في المراد؟ قيل إذا كانا مختارين ولم يكن أحدهما مكرها على موافقة صاحبه في مراده أمكن الخلاف بينهما [ولو كان كل واحد منهما مضطرا إلى موافقة الآخر في المراد كانا مقهورين ولم يجز أن يكونا إلهين وإذا صح اختلافهما في المراد مع التمانع بينهما وفي صحته صحة عجزهما أو عجز أحدهما فلا يصح كون الإله عاجزا] وفي جواز ذلك جواز ظهور عجز أحدهما ومن جاز عجزه لم يكن إلها. وهذه الدلالة لا تستمر على أصول القدرية لأن البغداديين منهم زعموا إن الصانع ليس بمريد على الحقيقة وإنه يفعل لا بإرادة فلا ينفصلون من الثنوية إذا قالوا لهم ما أنكرتم من صانعين قديمين لا يختلفان في المراد لأنهما غير مريدين كما زعمتم أن القديم الواحد فاعل لأفعاله بغير إرادة. وأما البصريون منهم زعموا أن الله مريد بإرادة حادثة لا في محل فلا ينفصلون ممن قال بصانعين إرادة كل واحد منهما لا في محل والإرادة إذا لم تكن في محل لم تختص بأحدهما وصارا بها مريدين ولم يختلفا في الإرادة والمراد، وليس لهم أن يقولوا إنّ الإرادة تختص بفاعلها لأن الإنسان قد يريد بإرادة يخلقها الله عزوجل فيه فيكون هو المريد بها دون فاعلها [ولم يصح لهم مع تمسكهم بأصولهم الاستدلال بدلالة التمانع على توحيد الصانع] ويقال للثنوية إذا نسبتم الخيرات والصدق إلى النور والكذب والشرور إلى الظلام (1) فأخبرونا عمن سألناه عن نفسه من هو؟ فقال أنا ظلام شرير من هذا القائل؟ فإن زعموا أنه الظلام فقد نسبوا الصدق إليه وإن زعموا إنه النور فقد نسبوا الكذب إليه وبانت مناقضتهم فيه.\r__________________"], [76, "(1) [فإنا نسألهم عمن جنى جناية ثم تاب واعتذر الى المجني عليه وقال: قد أخطأت وتبت، فإن زعموا ان هذا القول من فعل النور الذي في بدن الإنسان بزعمهم نسبوا النور الى الكذب، لأن النور عندهم ما جنى فيكون قوله: جنيت وأخطأت كذبا، وإن زعموا ان ذلك من فعل ما في البدن من الظلمة بزعمهم قيل لهم: هو صدق الظلام؟ وعندكم لا يصح منه الصدق، وسألنا أيضا عن قول القائل: انا الظلام الشرير، من القائل ذلك؟ فإن قالوا الخ].\r\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [73, 76]}, "540.63": {"x": [[76, "في صحة إفناء العالم من صانعه"], [77, "[اختلف الذين أثبتوا حدوث العالم وقالوا بقدم صانعه وتوحيده في إفنائه للعالم] وقال أصحابنا في الأعراض: إن كل واحد منها يفنى في الثاني من حال حدوثه لاستحالة بقائه [وأما الأجسام فكل جزء منها يصح إبقاؤه ويصح أيضا إفناؤه] واختلف أصحابنا في [علة] حد فناء الجسم فقال القلانسي، إنّ الله عزوجل يخلق في الجسم فناء فيفنى الجسم به في الثاني من حال حدوث الفناء فيه. وقال أبو الحسن الأشعري رحمة الله عليه، إنّ الله يفني الجسم بقطع البقاء عنه وقال أبو القاضي أبو بكر محمد بن الطيب إنه يفنيه بقطع الأكوان والألوان عنه. واختلفت القدرية في هذا الباب: فصار الكعبي منهم إلى قول أبي الحسن وزعم المعروف منهم بمعمر أن كل جسم يبقى ببقاء ويفنى بفناء وزعم أن للبقاء بقاء وللفناء فناء لا إلى نهاية وأحال فناء العالم كله حتى لا يبقى منه شيء. وكان المعروف منهم بمحمد بن شبيب في الفناء يميل إلى قول القلانسي في أنه يحدث في الجسم فناء فيفنى به في الحال الثانية من حال حلوله فيه وفي الحالة الثانية سماه فناء. وزعم الجاحظ منهم أنه يستحيل إفناء الأجسام وزعم الجبائي وابنه أن الله يخلق للأجسام فناء لا في محل فيفني به جميع الأجسام وقالا إنّ الله [إنما يقدر على إفناء الأجسام جملة ولا يقدر على إفناء بعضها مع بقاء البعض. وفي قول من أحال منهم فناء الأجسام تعجيز الإله عن إفناء ما خلق وفي قول من أحال فناء بعض مع بقاء بعض تعجيز له عن إفناء بعض العالم على الانفراد] غير قادر على إفناء بعض الأجسام مع بقاء بعضها. وزعمت الكرّامية أن الحوادث عندهم في ذات الباري يستحيل عدمها [وكل ما خلق الله تعالى فهو قادر على إفنائه سواء أفناه أو أبقاه والجنة والنار لا تفنيان وإن كان فناؤهما ممكنا في قدرة الله تعالى]."], [78, "وأحال الجاحظ فناء الأجسام، قلنا: كل من لم يصف الله تعالى بالقدرة على إفناء خلقه أو إفناء بعضه فقد زعم أن قدرته متناهية في مقدورها وكفاه بذلك خزيا.\r\rالمسألة الخامسة عشرة\r"]], "pg": [76, 78]}, "540.64": {"x": [[78, "في بيان أوصاف الصانع في ذاته\rأجمع أصحابنا على أن صانع العالم قائم بذاته غير مفتقر إلى محل وأجمعوا على أنه موجود لذاته خلاف قول سليمان بن جرير في دعواه أنه موجود لمعنى يقوم به. ووصفه بأنه شيء وذات لنفسه وبأنه غني لذاته عن الأماكن والأزمان وعن سائر خلقه ولا يصح عليه المنافع والمضار وإنما خلق المنافع والمضار لغيره لا لنفسه [وأجمعوا على أنه واحد لذاته في ذاته وعلى أنه مخالف لجميع الخلق بذاته وأجمعوا على أن وصفه بالعظيم والخبير والجميل لذاته وكذا وصفه بأنه وتر لذاته واختلفوا في وصفه بالقدم فقال أبو الحسن الأشعري إنه قديم لذاته وقال عبد الله بن سعيد والقلانسي إنه قديم بقدم [بمعنى] هو قائم به [ومرادنا بقولنا إنه يستحق بعض الأوصاف لنفسه نريد إنه يستحقه لا لمعنى يقوم به ولا لمعنى هو فعله وأما أوصافه التي يستحقها لمعان قائمة به فسنذكرها في مسائل الأصل الرابع "]], "pg": [78, 78]}, "540.65": {"x": [[78, "من أصول هذا الكتاب إن شاء الله تعالى] فهذا أصل هذا الباب فاعرفه.\r\rالأصل الرابع\rمن أصول هذا الكتاب في بيان الصفات\rالقائمة بالإله سبحانه\rوهذا الفصل خمس عشرة مسألة هذه ترجمتها:\rمسألة في عدد صفاته الأزلية.\rمسألة في صفة قدرته ومقدوراته.\rمسألة في علمه ومعلوماته.\rمسألة في سمعه ومسموعاته.\rمسألة في رؤيته ومرئياته.\rمسألة في إرادته ومراداته.\rمسألة في تفصيل مراداته.\rمسألة في حياته.\rمسألة في كلامه.\rمسألة في وجوه كلامه.\rمسألة في بقائه.\rمسألة في بقاء صفاته.\rمسألة في تأويل الوجه والعين.\rمسألة في تأويل اليد المضافة إليه.\rمسألة في تأويل الاستواء المضاف إليه.\rوسنذكر في كل مسألة منها مقتضاها إن شاء الله تعالى.\r\rالمسألة الأولى من هذا الأصل\r"]], "pg": [78, 78]}, "540.66": {"x": [[78, "في بيان عدد الصفات الأزلية"], [79, "أجمع أصحابنا على أن قدرة الله عزوجل وعلمه وحياته وإرادته وسمعه وبصره وكلامه صفات له أزلية [واختلفوا في البقاء فأثبته صفة لله أزلية جميع أصحابه سوى القاضي أبي بكر محمد بن [الطيب] الباقلاني رحمه الله فإنه منع من كون البقاء معنى زائدا على وجود ذات الباقي شاهدا وغائبا وزعم أن فناء الجسم ليس من أجل قطع البقاء عنه ولكن من جهة قطع الأكوان عنه. واختلفوا في القدم فأثبته عبد الله بن سعيد القطان معنى. وقال أبو الحسن إن الله قديم لنفسه وأصحابنا مجمعون على أن الله تعالى حي بحياة وقادر بقدرة وعالم بعلم ومريد بإرادة وسامع بسمع لا بأذن وباصر ببصر هو رؤية لا عين ومتكلم بكلام لا من جنس الأصوات والحروف وأجمعوا على أن هذه الصفات السبع أزلية وسموها قديمة وامتنع عبد الله بن سعيد والقلانسي من وصفها بالقدم مع اتفاقهم على أنّها كلها أزلية ونفت المعتزلة] وأثبت البقاء له صفة أزلية جميع أصحابنا غير القاضي [أبي بكر] محمد بن الطيب فإنه أثبته باقيا لذاته وأثبت القلانسي وعبد الله بن سعيد القدم معنى قائما بالقديم. وقال أبو الحسن الأشعري: إنه قديم لنفسه. ونفت المعتزلة جميع الصفات الأزلية وزعمت أن كلام الله حادث واختلفوا في إرادته فنفاها النظام والكعبي وقالا إذا قلنا إنّ الله أراد من العبد شيئا أردنا به إنه أمره. وزعم البصريون من المعتزلة أن الله سبحانه وتعالى مريد بإرادة حادثة لا في محل. وزعم النجار أن الله لم يزل مريدا لنفسه كما زعم أنّه لم يزل عالما قادرا حيّا لنفسه. واختلفت المعتزلة في فائدة وصف الله عزوجل بأنه عالم قادر فزعم النظام أن معنى وصفه بأنه عالم قادر يفيد أنه ليس بجاهل ولا عاجز. فألزم على هذا كون الجمادات والأعراض عالمة قادرة لأنها ليست بجاهلة ولا عاجزة."], [80, "فعلم أبو الهذيل لزوم هذا الإلزام فخالف النظام في ذلك وقال: أنا أقول إنّ الله عالم بعلم إلا أنّ علمه هو نفسه وقادر بقدرة وقدرته نفسه فألزمه أصحابنا إذا\r\rكان علمه وقدرته نفسه أن يكون نفسه علما وقدرة وإذا كان نفسه علما وقدرة استحال كونه عالما قادرا لأن العلم لا يكون عالما والقدرة لا تكون قادرة وألزموه أيضا إذا كان علمه نفسه وقدرته نفسه أن يكون علمه قدرته وأن يكون معلوماته كلها مقدورة له وهذا يوجب كون ذاته مقدورا له كما كان معلوما له فانقطع أبو الهذيل في هذا الإلزام (1) وخالفه الجبائي فقال إن الله عالم لنفسه وقادر لنفسه فألزمه أصحابنا أن يكون نفسه (2) [أي قدرته] علما وقدرة لأن حقيقة العلم ما به يعلم العالم والقدرة ما بها يقدر القادر. وعلم أبو هاشم ابن الجبائي فساد قول أبيه بأن جعل نفس الباري علة لكونه عالما وقادرا (3) [فخالف أباه وزعم] فزعم أن الله عالم لكونه على حال قادر لكونه على حال [وزعم أن لكونه عالما بكل معلوم (4) حالا دون الحال التي لأجلها كان عالما بالمعلوم الآخر وكذلك لكونه قادرا على كل مقدور حال لا يقال إنّها الحال التي لكونها عليها كان قادرا على المقدور الآخر وزعم أن خ] وزعم أن له في كل معلوم حالا مخصوصا وفي كل مقدور حالا مخصوصا وزعم أن الأحوال لا موجودة ولا معدومة ولا معلومة ولا أشياء [مع قوله إن المعدوم معلوم] وزعم أيضا إنها غير مذكورة وقد ذكرها بقوله إنها غير مذكورة [فناقض بأوّل كلامه آخره] وهذا مذهب لا يعقله هو عن نفسه فكيف يناظر في تصحيحه [خصمه] وقد شهد القرآن بإثبات علم الله عزوجل في قوله: (أَنْزَلَهُ بِعِلْمِهِ) (5) وقوله: (لا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ) (6) وقوله: (عِنْدَهُ عِلْمُ السَّاعَةِ) (7). فإن\r__________________\r(1) [وعلم الجبائي وجه الإلزام عليه فترك قوله فقال].\r(2) [أي قدرته].\r(3) فخالف اباه وزعم]."], [81, "(4) وزعم لكونه عالما بكل معلوم حالا دون الحال التي لأجلها كان عالما بالمعلوم الآخر، وكذلك لكونه قادرا على كل مقدور حال لا يقال انها الحال التي لكونها عليها كان قادرا على المقدور الآخر، وزعم أن.].\r(5) سورة النساء آية 166.\r(6) سورة البقرة آية 255.\r(7) سورة لقمان آية 34.\r\rعارضوه بقوله: (وَفَوْقَ كُلِّ ذِي عِلْمٍ عَلِيمٌ) (1) [وقالوا لو كان لله تعالى علم لوجب أن يكون فوقه عالم] قيل لسنا نقول إنّ الله ذو علم على التنكير وإنما نقول إنه ذو العلم على التعريف كما نقول إنه ذو الجلال والإكرام على التعريف ولا نقول ذو جلال وإكرام على التنكير [ومن كان ذا علم منكر ففوقه عليم وذو العلم على الإطلاق هو الله سبحانه وتعالى وليس فوقه عليم].\rالمسألة الثانية من هذا الأصل\r"]], "pg": [78, 81]}, "540.67": {"x": [[81, "في قدرة الله تعالى ومقدوراته"], [82, "أجمع أصحابنا [أهل الحق] على أن لله تعالى قدرة واحدة يقدر بها على جميع المقدورات. وخالفهم فيها ثلاث فرق: إحداها زرارية من أصحاب زرارة بن أعين الرافضي زعموا أن لله تعالى في كل مقدور قدرة حادثة لم يكن قبل حدوثها قادرا على مقدورها. فقلنا لهم إن كان قد خلق قدرة لا بقدرة عليها فهلا جاز أن يخلق سائر ما قد خلق بلا قدرة. والفرقة الثانية: كرّامية زعموا أن الله عزوجل إنما يقدر بقدرته على الحوادث الحادثة وهي ملاقاته للعرش وأقواله وإرادته وإدراكه للمسموعات وإدراكه للمرئيات فزعموا أن مقدوراته خمسة أجناس من الأعراض فأما أجسام العالم وأعراضه فزعموا أنه غير قادر عليها وأنّه إنما خلقها بقوله وإرادته [فخالفونا من وجهين أحدهما بقولهم إن الله تعالى لا يقدر على كل معدوم بقدرته. والوجه الثاني: بحلول تلك الحوادث المقدورة لله تعالى في ذاته وقد بينا ما يلزم عليه قبل هذا]. والفرقة الثالثة: قدرية زعمت أن الله قادر بلا قدرة [بل لنفسه وخالفنا البصريون منهم في مقدوراته وزعموا] أنه لا يقدر على مقدورات غيره وإن كان هو الذي أقدرهم عليها وهم في هذا كمن زعم أن الله يخلق عموم العباد بمعلوماتهم ولا يعلم معلوماتهم. وزعم المعروف منهم بمعمر أن الله إنما قدر على خلق الأجسام ولم يخلق شيئا من الأعراض ولا قدرة عليها [ويلزمه على هذا الأصل أن يكون كل حيوان أقدر من ربه لأن الواحد منا عنده يقدر على أنواع\r__________________\r(1) سورة يوسف آية 76."], [83, "لا نهاية لها من الأعراض والله تعالى لا يقدر إلا على الأجسام فحسب فالقادر على أجناس مختلفة ينبغي أن يكون أقدر ممن لا يقدر إلا على جنس واحد]. وزعم المعروف بأبي الهذيل أن مقدورات الله تعالى تفنى ويبقى أهل الجنة وأهل النار حينئذ خمودا في سكون دائم ولا يقدر الله بعد ذلك على ضر ولا على نفع. وزعم الاسواري منهم أن الله إنما يقدر على إحداث ما قد علم إنه يحدثه ولا يقدر على إحداث ما علم إنه لا يحدثه وإن كان من جنس ما قد أحدث فجعل مقدوراته متناهية من هذا الوجه، تعالى الله عن أقوال هؤلاء الكفرة علوّا كبيرا.\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [81, 83]}, "540.68": {"x": [[83, "في علم الله ومعلوماته\rقال أصحابنا: [أجمع أهل الحق] أن علم الله واحد (1) قد علم به جميع معلوماته ما كان منها وما يكون وما لا يكون إن لو كان كيف كان يكون وقد علم به أيضا استحالة المحالات وعلم علمه بنفسه وخالفهم في هذا الأصل (2) فرق: منهم الزرارية والجهمية في دعواهما حدوث علم الله تعالى وإنه لا يعلم [الأشياء قبل حدوثها وقيل لهم إن جاز أن يحدث معلومه قبل علمه به فهلا جاز أن يحدث كل شيء ولا يكون عالما به وهذا يغني عن كونه عالما] الشيء قبل حدوث علمه به. والخلاف الثاني: مع معمر القدري (3) [في قوله لا يجوز] فإنه لا يجوّز أن يقال إنّ الله عالم بنفسه [ونفسه معلومة له لأن من شرط المعلوم عنده كونه غير عالم به] ومن العجائب عالم بغيره وهو غير عالم بنفسه.\rوالخلاف الثالث: مع فرقة من الكرّامية زعمت أن لله علمين يعلم بأحدهما معلوماته ويعلم هذا العلم بالعلم الآخر ولا ينفصل هؤلاء ممن أثبت له علوما كثيرة [بعدد المعلومات وذلك فاسد فما يؤدي إليه مثله].\r__________________\r(1) [ليس بضروري ولا مكتسب ولا عن استدلال ونظر وأجمعوا على أنه محيط بجميع المعلومات يعلم به ما كان].\r(2) [في هذه الجملة].\r(3) [في قوله لا يجوز].\r\rالمسألة الرابعة من هذا الأصل\r"]], "pg": [83, 83]}, "540.69": {"x": [[83, "في سمع الإله ومسموعاته"], [84, "قال أصحابنا (1): إن سمعه صفة [واحدة] أزلية وهو يسمع بها (2) كل مسموع سمع إدراك لا سمع علم به من غير أذن ولا جارحة. وزعم الكعبي والنظام أن كون الإله سامعا إنما يفيد كونه عالما بالمسموع [وليس بمدرك له على الحقيقة وهذا باطل لأن الواحد منا يسمع الصوت فيكون عالما به في حال السماع ثم يكون عالما به في الحالة الثانية ولا يكون سامعا وصح بهذا إن السمع للشيء غير العلم به]. وزعمت الزرارية من الرافضة أنه لا يسمع للشيء حتى يخلق لنفسه سمعا له (3) [كما قالوا بحدوث علمه وقدرته]. وزعمت الكرّامية أن سمع الإله قدرته على إدراك مسموعاته وزعموا أن السمع هو إدراكه للمسموع وهو حادث فيه وزعموا إنه لو لم يحدث فيه السمع لم يكن سامعا. [والفرقة الرابعة قدرية البصرة قالوا إنّ الله تعالى لم يزل سميعا بصيرا على معنى أنه كان حيّا لا آفة به تمنعه من إدراك المسموع إذا وجد. وقال الجبائي إنه كان في الأزل سميعا ولم يكن سامعا إلا عند وجود المسموع ولا يدرى من أين أخذ فرقه بين السامع والسميع وهل أخذ من لغة العرب أو العجم أو من لغة شيطانه الذي أغواه وإلى الضلال دعاه. واختلف أصحابنا] وزعم الجبائي وابنه أن الله لم يزل سميعا بمعنى أنه كان حيّا لا آفة به تمنعه من إدراك المسموع إذا وجد وقالا إنه لم يكن في الأزل سامعا فكذلك زعما أنه كان في الأزل بصيرا ولم يكن مبصرا وإنما صار سامعا مبصرا عند وجود المسموع والمرئي. واختلف أصحابنا فيما يصح كونه مسموعا: فقال أبو الحسن الأشعري كل موجود يجوز كونه مسموعا [مرئيا]. وقال القلانسي: لا يسمع إلا ما كان كلاما أو صوتا وهو الصحيح [وقال عبد الله بن سعيد: المسموع هو التكلم وما له صوت\r__________________\r(1) [أهل الحق].\r(2) [جميع المسموعات من الأصوات والكلام وخالفهم في ذلك فرق: منهم النظام والكعبي واتباعهما من القدرية في دعواهم ان كون الاله ... ].\r(3) كما قالوا بحدوث علمه وقدرته]."], [85, "وبناه على أصل في أن الأعراض لا تدرك بالحواس. والذي يصح عندنا في هذه المسألة قول القلانسي وعليه أكثر الأمة].\rالمسألة الخامسة من هذا الأصل\r"]], "pg": [83, 85]}, "540.70": {"x": [[85, "في رؤية الإله ومرئياته\rقال أصحابنا: [أجمع أهل الحق على] أن الله راء برؤية أزلية يرى بها جميع المرئيات [و] لم يزل رائيا لنفسه. واختلف أصحابنا فيما يجوز كونه مرئيا: فقال أبو الحسن الأشعري يجوز رؤية كل موجود [وأحال رؤية المعدوم]. وقال عبد الله بن سعيد والقلانسي بجواز رؤية ما هو قائم بنفسه (1) ومنعا من رؤية الأعراض. وزعم البغداديون من المعتزلة أن الله لا يرى شيئا ولا يرى [وتأولوا ما في القرآن من ذكر رؤيته وبصره على معنى إنه عالم بالأشياء] وقالوا إن وصفنا بأنه رأى شيئا ما فمعناه إنه عالم به. وزعم البصريون منهم أن الله يرى غيره ولا يرى نفسه ويستحيل أن يكون مرئيا. ثم إن النظام منهم زعم أنه لا مرئي إلا اللون واللون عنده جسم. وزعم الجبائي أن المرئيات جواهر وألوان وأكوان. وزعم ابنه أبو الهاشم أن المرئيات جنسان جواهر وألوان. ودليلنا على رؤية الأعراض التمييز بالبصر بين الأسود والأبيض وبين المجتمع والمفترق. وفي هذا دليل على إدراك الألوان والأكوان بالبصر. وقول من زعم أن الله عزوجل يرانا ولا يرى نفسه كقول من زعم أنه يعلم غيره ولا يعلم نفسه. والدليل على جواز كونه مرئيا [وجوده لأنا نرى المرئيات في الشاهد ولم يجز أن يكون جواز رؤية الجوهر لكونه جوهرا] إنا سبرنا المرئيات فلم يكن جواز رؤية الجوهر لكونه جوهرا أو قائما بنفسه لأنا نرى اللون وليس بجوهر ولا قائم بنفسه. ولم يكن جواز رؤية اللون لكونه لونا ولا لكونه عرضا لأنا نرى الأجسام وليست بألوان ولا أعراض. ولم يكن جواز رؤية الشيء لكونه معلوما أو مذكورا لأن ذلك يوجب جواز رؤية المعدوم. ولم يكن جواز رؤية الشيء الحادث لكونه حادثا لأن من يقول بذلك يلزمه إجازة رؤية كل حادث وذلك\r__________________\r(1) [وأحالا رؤية]."], [86, "خلاف قول مخالفينا وإذا بطلت هذه الأقسام ولم يبق إلا الوجود صح جواز رؤية الشيء لوجوده فصح بذلك جواز رؤية كل موجود [والله سبحانه وتعالى موجود فصح جواز رؤيته]. ويدل عليه من الشرع إخبار الله عزوجل عن موسى عليه السلام في قوله: (رَبِّ أَرِنِي أَنْظُرْ إِلَيْكَ) (1)، ولا يخلو من موسى في حال هذا السؤال من اعتقاد جواز الرؤية عليه أو اعتقاد استحالتها فإن اعتقد استحالتها وسألها فهو كمن سأله أن يتخذه ولدا أو شريكا مع علمه باستحالة ذلك عليه وإن كان اعتقد جواز الرؤية عليه فقد صح جوازها عليه لأن الأنبياء معصومون عن اعتقاد ما لا يليق بالله عزوجل في صفاته. فإن قالوا إنما سأل الرؤية لقومه لأن قومه قالوا: (لَنْ نُؤْمِنَ لَكَ حَتَّى نَرَى اللهَ جَهْرَةً) (2). قيل لو كان كذلك لقال إن قومي يسألونك أن ينظروا إليك ولقال الله في جوابه بهم: إنهم لن يروني على أن قومه لما سألوا المحال بقولهم: (اجْعَلْ لَنا إِلهاً كَما لَهُمْ آلِهَةٌ) (3) أجابهم فقال: (إِنَّكُمْ قَوْمٌ تَجْهَلُونَ) (4) ولم يرجع إلى الله في جوابهم فلو كانت الرؤية مستحيلة عليه لأجاب قومه ولم يرجع فيها إلى سؤال ربه الرؤية لأجلهم. فإن قيل فقوله لن تراني يدل على نفي الرؤية أبدا لأن حرف لن على التأبيد. قيل هو على تأبيد النفي في الدنيا ألا تراه قال: (قُلْ إِنْ كانَتْ لَكُمُ الدَّارُ الْآخِرَةُ عِنْدَ اللهِ خالِصَةً مِنْ دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِنْ كُنْتُمْ صادِقِينَ) (5). ثم قال: (وَلَنْ يَتَمَنَّوْهُ أَبَداً) (6)، يعني في الدنيا لأن الكافر يتمنى في الآخرة الموت ليتخلص به من العذاب. ومما يدل على رؤية الإله عزوجل في الآخرة قوله: (وُجُوهٌ يَوْمَئِذٍ ناضِرَةٌ إِلى رَبِّها ناظِرَةٌ) (7). فإن تأولوا الآية على معنى\r__________________\r(1) [وجوده لأنا نرى المرئيات في الشاهد ولم يجز أن يكون جواز رؤية الجوهر لكونه جوهرا]."], [87, "(2) سورة الأعراف آية 143.\r(3) سورة البقرة آية 55.\r(4) سورة الأعراف آية 138.\r(5) سورة البقرة آية 94.\r(6) سورة البقرة آية 94.\r(7) سورة القيامة آية 22.\r\rالانتظار للثواب فإن نظر الانتظار لا يقرن بحرف إلى ولا بالوجه. فإن قالوا إن ذلك موجود في قول الشاعر:\rوجوه ناظرات يوم بدر ... إلى الرّحمن يأتي بالخلاص\r\rوفي قول الآخر:\rويوم بذي قار رأيت وجوههم ... إلى الموت من وقع السّيوف نواظر"], [88, "قيل أما البيت الأول فقد أبدل فيه يوم بكر بيوم بدر ويوم بكر هو اليوم الذي قتل فيه مسيلمة فذكر الشاعر: إن أصحابه كانوا ينظرون إليه يرجون منه الإتيان بالخلاص. وكان قد سمى نفسه رحمن اليمامة وهذا نظر الرؤية. وكذلك النظر في البيت الثاني بمعنى الرؤية للموت والموت مرئي عندنا ومن رأى الميت فقد رأى موته كما إن من رأى الأسود فقد رأى سواده. فإن قالوا فقد قال في آخر الآية: (وَوُجُوهٌ يَوْمَئِذٍ باسِرَةٌ تَظُنُّ أَنْ يُفْعَلَ بِها فاقِرَةٌ) (1)، فأضاف الظن إلى الوجه فأراد به ظن القلب كذلك أضاف النظر إلى الوجه وأراد به نظر القلب وهو الانتظار. قيل إن قوله تظن ليس بإخبار عن الوجوه وإنما هو خطاب للنبي صلىلله عليه وسلم أي: تظن أنت أي تتيقن أن يفعل بها فاقرة والظن بمعنى اليقين في القرآن كثير؛ على أنّه لا ينكر أن يكون ظن الكافر في الآخرة في وجهه وإن كان ظنه في الدنيا في القلب كما يكون الناطق في جلود قوم وفي أيديهم وأرجلهم في الآخرة وإن كان النطق في الدنيا في اللسان [وكل واحد محمول على ظاهره وفيه سقوط السؤال]. فإن عارضونا بقول الله تعالى: (لا تُدْرِكُهُ الْأَبْصارُ) (2) قلنا لهم ما ذا تقولون أنتم في قوله: (وَهُوَ يُدْرِكُ الْأَبْصارَ). فإن قال البغداديون منهم معناه: إنه يعلم الأبصار، لأن إدراك الإله عندهم بمعنى العلم دون الرؤية. قيل لهم فهلا قلتم في قوله لا تدركه الأبصار إنها لا تعلمه فهذا يوجب عليكم أن لا يكون معلوما وذلك خلاف قولكم. وإن قال البصريون منهم أراد بقوله: (وَهُوَ يُدْرِكُ الْأَبْصارَ)، إنه يراها. قيل لهم ما الأبصار التي\r__________________\r(1) سورة القيامة آية 24.\r(2) سورة الانعام، آية 103."], [89, "يراها الله؟ فإن قالوا هم المبصرون قيل أية خاصية لله تعالى في رؤية المبصرين وقد يراهم غيره وإن قالوا أراد بالأبصار المعاني التي بها تبصر المبصرون قيل فتلك المعاني هي التي لا تدركه دون المبصرين. فإن قيل فقد علمنا بالعقل إن البصر لا يدرك شيئا فلا فائدة لحمل الآية عليه. قيل يجوز ورود القرآن بتأكيد ما دل عليه العقل كقوله: (وَإِلهُكُمْ إِلهٌ واحِدٌ) (1) و (لَيْسَ كَمِثْلِهِ شَيْءٌ) (2) [فإن ذلك نازل لتأكيد ما دل عليه العقل من توحيد الصانع ونفي التشبيه عنه] على إنا نثبت للآية فوائد. منها إثبات أبصارنا أعراضا خلاف قول نفاة الأعراض. ومنها إبطال قول أبي هاشم بن الجبائي إن الإدراك ليس بمعنى. ومنها إثبات رؤية الأعراض خلاف قول من أحال رؤيتها لأن الله سبحانه وتعالى قال وهو يدرك الأبصار وإذا صحت رؤية البصر [التي هي] رؤية صحت رؤية سائر الأعراض [فبطل بهذا سائر تأويلات المخالفين] والحمد لله على ذلك.\rالمسألة السادسة من هذا الأصل\r"]], "pg": [85, 89]}, "540.71": {"x": [[89, "في إرادة الله تعالى ومراداته\rأجمع أصحابنا على أن إرادة الله تعالى مشيئته واختياره وعلى أنّ إرادته للشيء كراهيته لعدم ذلك الشيء كما قالوا إن أمره بالشيء نهي عن ضده وقالوا أيضا إن إرادته صفة أزلية قائمة بذاته وهي إرادة واحدة محيطة بجميع مراداته على وفق علمه بها فما علم منها كونه أراد كونه، خيرا كان أو شرا وما علم أنه لا يكون أراد أن لا يكون. ولا يحدث في العالم شيء لا يريده الله ولا ينتفي ما يريده الله [وهذا معنى قول المسلمين ما شاء الله كان وما لم يشأ لم يكن].\rوالخلاف في هذا من وجوه:\rأحدها مع القدرية الذين منعوا القول بأن الله مريد على الحقيقة كالنظام والكعبي. وقد دللنا قبل هذا على فساد قولهم.\r__________________\r(1) سورة البقرة آية 159.\r(2) سورة الشورى آية 11.\r\rوالخلاف الثاني: مع البصرية من القدرية في قولهم إن إرادة الله حادثة لا في محل. وقد مضى أيضا دليل فساد قولهم."], [90, "والخلاف الثالث: مع الكرّامية في قولها إنّ إرادة الله حادثة في ذاته. وقد دللنا على استحالة كونه محلا للحوادث.\rوالخلاف الرابع: مع القدرية البصرية في قولهم إنّ الله قد يريد ما لا يكون وقد يكون ما لا يريد. وهذا يوجب كونه مقهورا على [مراده] ما كرهه ولأنهم وافقونا على أنه لو أراد من فعل نفسه شيئا فلم يكن، يلحقه النقص والضعف كذلك إذا أراد من غيره ما لا يكون يلحقه النقص كما لو وقع من فعله ما لا يعلمه لحقه النقص كذلك إذا وقع من غيره ما لا يعلمه، لحقه النقص. وعلى العكس من هذا لما جاز أن يقع من غيره ما لم يأمر به جاز أن يقع أيضا من فعله ما لم يأمر به. فإن قالوا لو أراد السفه لكان سفيها لأن مريد السفه منا سفيه. قيل مريد الطاعة منا مطيع ولا يجب أن يكون الله مطيعا وإن أراد الطاعة كذلك مريد السفه منا سفيه ولا يجب أن يكون هو سفيها بإرادة السفه. فإن قيل فكيف يجوز أن يأمر الحكيم بما لا يريده [قيل قد صح ذلك ونطق به القرآن عندنا كما أمر الخليل عليه السلام بذبح ابنه ولم يرده منه وأمر إبليس بالسجدة لآدم ولم يرد منه ذلك ووجدنا] في الشاهد أمثلة: منها إنا لو رأينا حكيما يضرب مملوكا له وادعى أنه إنما ضربه لأنه لا يطيعه في أمره وادعى المضروب أنه مطيع له في كل ما يأمره به فأراد السيد تصديق نفسه فأمره بشيء لا يريده فإنه لا يريد منه ما أمره به لأن ذلك يوجب تكذيبه نفسه ويكون حكيما في أمره إياه بما لا يريده.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [89, 90]}, "540.72": {"x": [[90, "في تفصيل مراداته\rأطلق (1) أصحابنا القول بأن الحوادث كلها بمشيئة الله عزوجل واختلفوا في التفصيل: فقال [شيخنا أبو محمد] عبد الله بن سعيد أقول في الجملة إنّ الله أراد حدوث الحوادث كلها خيرها وشرها ولا أقول في التفصيل إنّه أراد المعاصي وإن\r__________________\r(1) [قد أجمع]."], [91, "كانت من جملة الحوادث التي أراد حدوثها كما أقول في الجملة عند الدعاء: يا خالق الأجسام ولا أقول في الدعاء على التفصيل: يا خالق القرود والخنازير والدم والنجاسات وإن كان هو الخالق لهذه الأشياء كلها. وقال أبو الحسن الأشعري في التفصيل بتقييد فقال: أقول إن الله أراد حدوث المعصية من المعاصي قبيحة منه ولا أقول إنّه أرادها على الإطلاق كما نقول في المؤمن إنّه كافر بالجبت والطاغوت والكافر مؤمن بالصنم على هذا التقييد. وقال بعض أصحابنا من سألنا عن الشرور بلفظ الحوادث قلنا إن الله أراد حدوثها وحدوث جميع الحوادث ولا نقول بلفظ الشرور إنّه أراد الشرور (1) كما أن الليل حجة الله عزوجل فنقول بلفظ الليل إنّها ليلة مظلمة وباردة ولا نقول بلفظ الحجة إنّها حجة مظلمة وباردة كذلك نقول في الإرادة والمراد على هذا التفصيل.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [90, 91]}, "540.73": {"x": [[91, "في صفة حياة الاله سبحانه\r[أجمع أهل الحق] قال أصحابنا (2) إنّ حياته صفة أزلية قائمة من غير روح ولا غداء ولا تنفس خلاف قول الزرارية من الروافض في دعواها إنّ حياته حادثة وإنه لم يكن حيّا حتى أحدث لنفسه حياة وكل فاعل من شرطه أن يكون حيّا. وقد أجاز الصالحي من المعتزلة كون ما ليس بحي عالما قادرا مريدا فلا يكون له على هذا الأصل دلالة على أن الصانع حي. وإذا صح لنا أن الصانع عالم قادر مريد والحياة شرط في هذه الصفات عندنا، صح لنا الاستدلال بذلك على كونه حيّا. والحياة عند أكثر أصحابنا غير الروح، لأن الحياة صفة والارواح أجسام، ولله عزوجل حياة هي صفة له أزلية وليست له روح. فأما الارواح المنسوبة إليه في القرآن فهي من خلقه كعيسى وجبرائيل والملك الذي يقوم في القيامة صفا واحدا. وأرواح الحيوانات أجسام ولو أحيا الله تعالى جسما بلا روح جاز [ولا يجوز ذلك\r__________________\r(1) [ونقول أنه أراد حدوث هذا الحادث الذي هو المعصية].\r(2) [أجمع أهل الحق]."], [92, "على الحياة]. والحياة المحدثة جنس واحد. وكل قائم بنفسه يصح قيام الحياة به عندنا. وزعمت القدرية أنه لا يصح وجود الحياة إلا في بنية مخصوصة. وقد دللنا قبل هذا على فساد قولهم فيه [وإذا ثبت أن الله حي وأن له حياة أزلية قلنا لهم إنّها حياة باقية لا يعقبها موت ولا ضد من أضداد الحياة كما أن القدرة الأزلية لا يعقبها عجز وكذلك في سائر الصفات الأزلية].\rالمسألة التاسعة من هذا الأصل\r"]], "pg": [91, 92]}, "540.74": {"x": [[92, "في كلام الإله\r[أجمع أهل الحق على أن كلام الله] تعالى صفة له أزلية قائمة وهي أمره ونهيه وخبره ووعده ووعيده. وزعمت الكرّامية أن كلامه قدرته على قوله وقوله حادث في ذاته. وزعمت القدرية أن كلام الله حادث في جسم من الاجسام. وزعم أبو الهذيل أن قوله للشيء «كن» عرض حادث لا في محل وسائر قوله حادث في جسم ما [وقد أبطلنا قبل هذا قول الكرّامية بحلول الحوادث وأبطلنا أيضا قول من أجاز وجود قول وإرادة أو شيء من الأعراض لا في محل. والدليل على أن كلام الله صفة له أزلية لا محدثة هو أن كلامه لو كان] ودليلنا على أن كلامه ليس بمحدث أنه لو كان حادثا لم يخل حدوثه فيه لاستحالة كونه محلا للحوادث ويستحيل حدوثه لا في محل لأن العرض لا يكون إلا في محل، ولو حدث كلامه في جسم من الاجسام لكانت الأسماء الصادرة من خصوص أوصاف الكلام راجعة إلى محله به آمرا ناهيا مخبرا كالحياة والقدرة والعلم إذا حدثت في محل كان المحل بها قادرا عالما حيا [وإذا استحال أن يأمر وينهى بكلام الله غيره صح أن كلامه أزلي قائم به لا بغيره]. فإن قالوا أليس قد يحدث الله تعالى في غيره نعمة وفعلا وفضلا ويكون هو المنعم المتفضل الفاعل به دون المحل الذي وقع فيه الفعل والنعمة والفضل [فما أنكرتم أنه يحدث أيضا كلاما في غيره فيكون هو المتكلم به دون المحل]. قيل إنّه الأوصاف الصادرة من خصوص أوصاف هذه الأفعال"], [93, "راجعة إلى محلها لأن الفعل أو النعمة أو الفضل إن كان حياة فالمحل بها حي وإن كان قدرة أو علما أو لذة أو حركة فالمحل بها قادر عالم أو ملتذ متحرك كذلك خصوص أوصاف الكلام يجب أن يرجع إلى محله دون فاعله (وإذا زعمت القدرية أن محل كلام الله لا يرجع إليه شيء من الأوصاف المشتقة من الكلام فقد أبطلوا فائدة حلول الكلام في محله وإذا بطل قولهم من الوجه الذي بيناه صح أن كلام الله سبحانه وتعالى أزلي غير حادث] وإذا استحال وقوع فوائد أوصاف كلام الله تعالى إلى غيره صح قيام كلامه به ووجب أنه صفة أزلية غير مخلوقة ولا حادثة.\rالمسألة العاشرة من هذا الأصل\r"]], "pg": [92, 93]}, "540.75": {"x": [[93, "في بيان وجود كلام الله عزوجل\r[قال أصحابنا] كلام الله تعالى عندنا أمر ونهي وخبر ووعد. ومن فوائد وجوهه العموم والخصوص والمجمل والمفسر. وفي أحكامه ناسخ ومنسوخ ولا ينسخ كلامه لأنه لا يجوز عدمه ورفعه. وقراءة كلامه بالعربية قرآن قراءته بالعبرانية توراة [أو زبور] وبالسريانية إنجيل. والقراءة غير المقروء لأن المقروء كلام الله وليست القراءة كلامه ولأن القراءات سبع والمقروء واحد ويقال قراءة أبي عمرو وقراءة عاصم ولا يقال قرآن أبي عمرو وغيره. ونقول: كلام الله في المصحف مكتوب وفي القلب محفوظ وباللسان متلو (ولا يقال إنّه في المصاحف مطلقا، ولا نقول على الإطلاق إنّ كلام الله سبحانه في محل ولكن نقول على التقييد إنّه مكتوب في المصاحف] ونقول إنّ نظم القرآن معجز خلاف قول النظام إنّ نظم القرآن غير معجز [واختلفوا في وصفه في الأزل فمن أجاز] من أصحابنا خطاب المعدوم [على شرط الوجود والعقل والبلوغ] قال: إن كلام الله لم يزل أمرا ونهيا للمكلفين الذين خلقوا بعد ذلك بشرط أن يفعلوا ما أمروا به بعد الوجود والبلوغ ووفور العقول. ومن لم يجز منهم خطاب المعدوم ولم يتم كلامه قبل وجود الخلق أمرا ونهيا قال: إن كلامه إنما صار أمرا ونهيا عند توجه اللزوم على المكلف."], [94, "المسألة الحادية عشرة من هذا الأصل\r"]], "pg": [93, 94]}, "540.76": {"x": [[94, "في بقاء الإله سبحانه\rقال (1) قدماء أصحابنا: إنّ بقائه صفة له أزلية قائمة به [ولأجلها صح وصفه بأنه باق] وأحال أصحابنا كلهم بقاء الأعراض [لاستحالة قيام البقاء بها]. ومنع القاضي أبو بكر محمد بن الطيب من كون البقاء معنى [أكثر من وجود الشيء] وزعم أن الله باق لنفسه وكل باق يجوز فناؤه إلا الله وصفاته القائمة. [وزعم البصريون من القدرية أن البقاء ليس بمعنى لا في الشاهد ولا في الغائب. وزعم الكعبي أن الباقي في الشاهد يكون باقيا ببقاء والله تعالى باق بلا بقاء. والكلام في إثبات بقاء الله تعالى كالكلام في إثبات علمه وقدرته وسائر صفاته.] وزعمت البيانية من الروافض أن الله تعالى يفنى كله إلا وجهه وقد أبطلنا هذه البدعة.\rالمسألة الثانية عشرة من هذا الأصل\r"]], "pg": [94, 94]}, "540.77": {"x": [[94, "في بقاء صفات الله تعالى\rأجمع أصحابنا على أن لله تعالى صفات أزلية. واختلفوا في وصفها بأنها باقية. فقال عبد الله بن سعيد والقلانسي إنّها أزلية دائمة الوجود ولا نقول إنّها باقية لاستحالة قيام البقاء بها [وإن كانت لا تزال موجودة]. وقال أبو الحسن الأشعري: إنّ صفات الله تعالى باقية ببقاء البارئ وبقاؤه باق لنفسه ونفس بقائه بقاء له ولنفسه ولصفاته الأزلية [وهذا هو المشهور من قول أصحابنا في هذا الباب].\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [94, 94]}, "540.78": {"x": [[94, "في تأويل الوجه والعين من صفاته\rاختلفوا في هذه المسألة فزعمت المشبهة: أن لله وجها وعينا كوجه الإنسان وعينه [وزعم بعضهم أن له وجها وعينا هما عضوان ولكنهما ليسا كوجه الإنسان\r__________________\r(1) [أجمع]."], [95, "وعينه بل هما خلاف الوجه والعيون سواهما]. وزعم بعض الصفاتية أن الوجه والعين المضافين إلى الله تعالى صفات له. والصحيح عندنا أن وجهه ذاته وعينه رؤيته للأشياء. وقوله: (وَيَبْقى وَجْهُ رَبِّكَ) (1) معناه ويبقى ربك ولذلك قال (ذُو الْجَلالِ وَالْإِكْرامِ) (2). بالرفع لأنه نعت الوجه ولو أراد الإضافة لقال ذي الجلال والإكرام بالخفض. وقوله: (وَلِتُصْنَعَ عَلى عَيْنِي) (3) أي على رؤية مني كما قال: (إِنَّنِي مَعَكُما أَسْمَعُ وَأَرى) (4). وقوله في سفينة نوح: (تَجْرِي بِأَعْيُنِنا) (5)، أراد بها العيون التي جرت بها السفينة من الماء لأنه قال: (فَفَتَحْنا أَبْوابَ السَّماءِ بِماءٍ مُنْهَمِرٍ وَفَجَّرْنَا الْأَرْضَ عُيُوناً فَالْتَقَى الْماءُ عَلى أَمْرٍ قَدْ قُدِرَ) (6)، فجرت السفينة بتلك العيون المفجرة والمراد بقوله: (كُلُّ شَيْءٍ هالِكٌ إِلَّا وَجْهَهُ) (7)، بطلان كل عمل لم يقصد به وجه الله تعالى [خلاف البيانيّة من الغلاة في دعواها أن كل شيء من الإله يفنى إلا وجهه، تعالى الله عن ذلك علوا كبيرا].\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [94, 95]}, "540.79": {"x": [[95, "في تأويل اليد المضافة إلى الله تعالى\r[اختلفوا في هذه المسألة فزعمت المشبهة] أن يدي الله تعالى جارحتان وعضوان فيهما كفان وأصابع [ككفّي الإنسان وأصابعه]. وزعم بعض القدرية أن اليد المضافة إليه بمعنى القدرة. هذا التأويل لا يصح على مذهبه مع قوله إنّ الله تعالى قادر بنفسه بلا قدرة. [وزعم الجبائي أن اليد المضافة إليه بمعنى النعمة. وهذا خطأ لأن الله تعالى أخبر أنه خلق آدم بيديه والنعمة مخلوقة والله لا يخلق مخلوقا بمخلوق ولأن الله تعالى خص آدم بهذه الخاصية ولا يجوز عند الجبائي تخصيص بعض المكلفين بنعمة دون بعضهم فبطل تأويله من هذين الوجهين. وزعم بعض القدرية أن اليدين في قوله تعالى\r__________________"], [96, "(1) سورة الرحمن آية 27. (2) سورة طه آية 39. (3) سورة طه آية 46. (4) سورة القمر آية 14. (5) سورة القمر آية 11 و 12. (6) سورة القصص آية 88.\r\r(بِيَدَيَ) صلة ومعناه أنه خلق آدم فحسب. وهذا يوجب إبطال فائدة تخصيص آدم بها لأن الله تعالى خالق كل مخلوق. وزعم بعض أصحابنا أن اليدين صفتان لله سبحانه وتعالى وقال القلانسي هما صفة واحدة] وقد تأول (1) بعض أصحابنا هذا التأويل وذلك صحيح على المذهب إذ أثبتنا لله القدرة وبها خلق كل شيء ولذلك قال في آدم عليه السلام: (خَلَقْتُ بِيَدَيَ) (2)، ووجه تخصيصه آدم بذلك أن خلقه بقدرته لا على مثال له سبق ولا من نطفة ولا نقل من الأصلاب إلى الأرحام كما نقل ذريته من الاصلاب إلى الأرحام [فأما إفساد تأويل المشبهة اليدين على معنى العضوين فقد مضى في الدلالة على أن الله تعالى ليس بجسم والجوارح والأعضاء لا يكون لما ليس بجسم.] وزعم بعض أصحابنا أن يديه صفتان وزعم القلانسي أنهما صفة واحدة. وزعم الجبائي أن يديه نعمتان منه وهذا يبطل فائدة تخصيص آدم بهما عنده لأنه لا يجوّز من الله تخصيص بعض العباد بلطف ونعمة مخصوصة في دار التكليف. وقد أبطلنا قول المشبهة بالجارحة قبل هذا.\rالمسألة الخامسة عشرة من هذا الأصل\r"]], "pg": [95, 96]}, "540.80": {"x": [[96, "في معنى الاستواء المضاف إليه"], [97, "اختلفوا في تأويل قوله تعالى: (الرَّحْمنُ عَلَى الْعَرْشِ اسْتَوى)، فزعمت المعتزلة أنه بمعنى استولى كقول الشاعر: [قد] استوى بشر على العراق أي استولى وهذا تأويل باطل لأنه يوجب أنه لم يكن مستوليا عليه قبل استوائه عليه. وزعمت المشبهة أن استوائه على العرش بمعنى كونه مماسا لعرشه من فوقه وأبدلت الكرّامية لفظ المماسة بالملاقاة. وزعم بعضهم أنه لا يفضل منه على العرش شيء [عن عرض العرش وهذا يوجب كونه في العرش على مقدار عرض العرش]. وزعم آخرون أنه أكبر من العرش وأنه لو خلق عن يمين العرش وعن يساره عرشين آخرين كان ملاقيا بجميعها من فوقها بلا واسطة وهذا يوجب أن\r__________________\r(1) [وتأولهما بعض أصحابنا على معنى القدرة وهذا التأويل].\r(2) سورة ص آية 75.\r\rيكون كل عرش كبعضه فيكون متبعضا. واختلف أصحابنا في هذا فمنهم من قال إنّ آية الاستواء من المتشابه الذي لا يعلم تأويله إلا الله وهذا قول مالك بن أنس وفقهاء المدينة والاصمعيّ. وروي أن مالكا سئل عن الاستواء فقال: الاستواء معقول وكيفيته مجهولة والسؤال عنه بدعة والإيمان به واجب. ومنهم من قال إنّ استواءه على العرش فعل أحدثه في العرش سماه استواء كما أحدث في بنيان قوم فعلا سماه إتيانا ولم يكن ذلك نزولا ولا حركة وهذا قول أبي الحسن الأشعري. ومنهم من قال: إنّ استواءه على العرش كونه فوق العرش بلا مماسة وهذا قول القلانسي وعبد الله بن سعيد ذكره في كتاب الصفات. والصحيح عندنا تأويل العرش في هذه الآية على معنى الملك كأنه أراد أن الملك ما استوى لأحد غيره. وهذا التأويل مأخوذ من [قول] العرب: ثل عرش فلان إذا ذهب ملكه وقال متمم بن نويرة في هذا المعنى:\rعروش تفانوا بعد عزّ وأمّة ... هووا بعد ما نالوا السّلامة والبقاء\r\rوأراد بالعروش ملوكا انقرضوا. وقال سعيد بن زائدة الخزاعي في النعمان بن المنذر:\rقد نال عرشا لم ينله خائل ... جنّ ولا إنس ولا ديّار"], [98, "وأراد بالعرش الملك والسلطان. وقال النابغة:\rبعد ابن جفنة وابن هاتك عرشه ... والحارثين يؤمّلون فلاحا\r\rوأراد بهاتك عرش ابن جفنة سالب ملكه فصح بهذا، تأويل العرش على الملك في آية الاستواء على [ما] بيناه والله الموفق للصواب.\r\rالأصل الخامس\r"]], "pg": [96, 98]}, "540.81": {"x": [[98, "من أصول هذا الكتاب في بيان أسماء الله\rعزوجل وأوصافه\rوفي هذا الأصل خمس عشرة مسألة. هذه ترجمتها: مسألة في معنى الاسم وحقيقته.\rمسألة في بيان مأخذ أسمائه.\rمسألة في أقسام أسمائه.\rمسألة في الأدلة على أسمائه.\rمسألة في عدد أسمائه الواردة في الشرع.\rمسألة في تفسير الخبر الوارد في عدد أسمائه.\rمسألة في تقسيم أسمائه في المعنى.\rمسألة في تفسير ما دل من أسمائه على ذاته.\rمسألة في تفسير ما دل منها على صفاته الأزلية.\rمسألة في تفسير ما دل منها على أفعاله.\rمسألة في بيان ما احتمل من أسمائه معنيين.\rمسألة في بيان ما يجوز تسمية غير الله به.\rمسألة في الفرق بين أوصافه وصفاته.\rمسألة فيما يوصف منه بالفعل دون الاسم.\rمسألة فيما يوصف به مضافا غير مفرد فهذه مسائل هذا الأصل وسنذكر في كل واحدة منها مقتضاها إن شاء الله تعالى.\r\rالمسألة الأولى من هذا الأصل\r"]], "pg": [98, 98]}, "540.82": {"x": [[98, "في معنى الاسم وحقيقته"], [99, "اختلفوا في الاسم: فقال أكثر أصحابنا إنّه المسمى والعبارات عنه تسميات له. وقد نص أبو الحسن الأشعري على هذا القول في كتاب (تفسير القرآن). وذكر في كتاب (الصفات) أن الاسم هو الصفة وقسمه تقسيم الصفات. وزعمت القدرية أن الاسم غير [عين] المسمى وأشاروا به إلى القول الذي سماه أصحابنا تسمية. وقول الله: (ما تَعْبُدُونَ مِنْ دُونِهِ إِلَّا أَسْماءً سَمَّيْتُمُوها) (1) وهم كانوا يعبدون من [دون] الله المسميات، دليل على أن الأسماء ذواتها. وقوله: (سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى،) (2) و (تَبارَكَ اسْمُ رَبِّكَ) (3) دليل على أن اسم الرب هو الرب لأنه هو المتبارك المسبّح. ولأن من قال من القدرية إن الاسم غير المسمى وجب على اصله أن لا يكون لله في الأزل اسم ولا صفة لأن الأسماء والاوصاف عنده تسميات وعبارات ولم يكن شيء منها في الأزل على قولهم، فإذا لم يكن لمعدوم في الأزل اسم ولا صفة، فهذه صفة المعدوم دون الإله. فإن سألونا عن قوله: (وَلِلَّهِ الْأَسْماءُ الْحُسْنى) (4) [قلنا أراد بالأسماء التسميات] فالمراد بها تسمياته لأن العدد يقع عليها لا على المسمى الواحد.\rالمسألة الثانية من هذا الاصل\r"]], "pg": [98, 99]}, "540.83": {"x": [[99, "في بيان مأخذ اسماء الله عزوجل\r[اختلفوا في هذه المسألة فزعم] البصريون من القدرية أن أسماء الله تعالى مأخوذة من الاصطلاح والقياس. وقال (5) أهل السنة إنّها مأخوذة من التوقيف وقالوا:\r__________________\r(1) سورة يوسف آية 40.\r(2) سورة الأعلى آية 1.\r(3) سورة الرحمن آية 78.\r(4) سورة الأعراف آية 179.\r(5) [وأجمع]."], [100, "لا يجوز إطلاق اسم على الله من جهة القياس وإنما يطلق من أسمائه ما ورد به الشرع في الكتاب والسنة الصحيحة أو اجمعت الأمة عليه [وتبعهم الكعبي على ذلك]. واختلف أصحابنا في أسماء المخلوقات: فأجاز الشافعي رضي الله عنه فيها القياس ومنعه بعضهم. والدليل على المنع من القياس في أسماء الله عزوجل، أن العبد لا يضع لمولاه اسما كما لا يضع الولد لأبيه اسما وإنما يضع الأب للولد والسيد للعبد اسما. ولأن الله تعالى موصوف بأسماء لا يوصف بما في معناها نحو صفته بأنه جواد كريم ولا يوصف بأنه سخي ويقال إنه قديم ولا يقال عتيق وإن كان ذلك في معنى القديم (1) وفي هذا دليل بطلان القياس في أسمائه.\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [99, 100]}, "540.84": {"x": [[100, "في بيان أقسام أسمائه\rذكر النحويون أن الأسماء ثلاثة أنواع: اسم متمكن واسم مضمر واسم مبهم. والمتمكن معروف. والمضمر مثل: أنا وأنت وهو، والياء في لي وبي ومنّي وعنّي، والهاء في به وله (2) والمبهم مثل: من وما وأين وحيث ونحوها [وجميع هذه الوجوه الثلاثة داخلة في أسماء الله عزوجل لأن أسماءه التي ورد الشرع بها متمكنة] وأسماء الله عزوجل متمكنة. ويجوز الخبر عنه بالأسماء المبهمة كقوله: (وَلا أَنْتُمْ عابِدُونَ ما أَعْبُدُ) (3) وقول القائل منا لغيره: اعبد من خلقك واشكر من رزقك، ويريد بمن ربّه عزوجل. ويجوز الخبر عنه بالمضمرات أيضا كقوله: (لَهُ ما فِي السَّماواتِ وَما فِي الْأَرْضِ) (4). وكقولنا في الدعاء: اللهم لك الحمد (وأليك) (5) المصير ونحو ذلك. والاسماء المتمكنة [عند اهل اللغة] ثلاثة انواع ثلاثي ورباعي\r__________________\r(1) [ويقال: رحيم ولا شفيق].\r(2) [والتاء في مثل: ضربت وفعلت بالفتح والضم والكسر في خطاب المؤنث، والكاف في نحو أكرمك].\r(3) سورة الكافرون آية 5.\r(4) سورة الشورى الآية (53).\r(5) وردت في المطبوع (وإليه)."], [101, "وخماسي. وكل اسم جاء على حرفين كيد ودم، فقد حذف منه حرف اصلي كحذف الياء من يد [ولذلك رجعت الياء في التصغير والجمع] وإن جاء اسم على أكثر من خمسة أحرف فبعض حروفه زائد. ولا يكون الحروف الأصلية في الاسم أكثر من خمسة. وقد وجدنا كل ما ورد به الشرع من أسماء الله عزوجل ثلاثيا في حروفه الاصلية وما زاد من أسمائه على ثلاثة أحرف فبعض حروفه زائد نحو: المقتدر، فإن الميم والتاء زائدتان [وجملة أسمائه قسمان: مشتق وغير مشتق، فالمشتق منها نوعان أحدهما] مشتق من صفة له قائمة به. وهذا النوع منه اسم له أزلي كالقادر والعالم والحي والسميع والبصير والمريد والمتكلم. والثاني: مشتق له من فعل [وهو ليس بأزلي] وذلك نوعان أحدهما مشتق من فعله كالخالق والرازق والمنعم ونحو ذلك. والثاني مشتق له من فعل غيره كمعبود ومشكور [ونحو ذلك]. وكل ما كان مشتقا له من فعل فليس من أسمائه الأزلية.\rالمسألة الرابعة من هذا الأصل\r"]], "pg": [100, 101]}, "540.85": {"x": [[101, "في بيان الأدلة على أسماء الله تعالى"], [102, "أما دليل العبارة عن أسمائه فليس إلا الشرع. وأما الدليل على معاني أسمائه فإن منها ما يدل عليه فعله نحو كونه قادرا عالما مريدا فإن الفعل لا يقع إلا من قادر ولا يصح كونه محكما متقنا إلا من عالم ولا يصح اختصاص الفعل بحال دون حال إلا ممن يريد تخصيصه به. ومنها ما يدل عليه صفة من صفاته نحو كونه حيا يدل عليه كونه عالما قادرا مريدا لأن هذه الصفات مختصة بالحي [ولا يصح وصف من ليس بحي بها]. وقد أجاز الصالحي كون الميت عالما قادرا مريدا ولا دليل له على أصله على كون الإله حيا. وزعمت الكرّامية أن أوصاف الحي كلها تصح للميت إلا كونه قادرا. فلا يأمنون على هذا الأصل أن يكون كل جماد رأوه عالما مريدا سامعا مبصرا غير أنه لا يقدر على فعل ولا على نطق. ومنها ما يجب إثباته لله عزوجل لأجل نفي النقص عنه نحو كونه سميعا لنفي الصمم عنه وبصيرا لنفي العمى عنه ومتكلما لنفي السكوت والخرس عنه [ومن أصحابنا من قال: إن الكلام\r\rواجب لله تعالى من جهة دلالة فعله عليه كالقسم الأول، لأن إرسال الرسل فعل منه ولا يصح الإرسال ممن لا يكون له قول، لأن المرسل إنما يرسل من يبلغ عنه قوله وأمره ونهيه]. فهذه وجوه الأدلة العقلية على معاني أسماء الله تعالى عندنا [فأما اطلاق التسميات من معاني أسمائه فطريقه الشرع كما بيناه قبل هذا].\rالمسألة الخامسة من هذا الأصل\r"]], "pg": [101, 102]}, "540.86": {"x": [[102, "في عدد أسمائه في الشرع"], [103, "قال الله تعالى: (وَلِلَّهِ الْأَسْماءُ الْحُسْنى فَادْعُوهُ بِها وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمائِهِ) (1). وفي حديث سفيان بن عيينة عن أبي الزناد عن عبد الرحمن بن هرمز عن أبي هريرة مرفوعا: إنّ لله عزوجل تسعا وتسعين اسما من أحصاها دخل الجنة. (2) وفي رواية شعيب بن أبي حمزة عن أبي الزناد عن الاعرج عن أبي هريرة بيان تفصيل تسعة وتسعين اسما. وفي القرآن من أسماء الله تعالى ما لم يذكر في هذا الخبر كرفيع الدرجات ونحو ذلك. وكل ما نطق به القرآن من أسماء الله تعالى أو وردت به السنة الصحيحة أو أجمعت عليه الأمة من أسمائه تعالى فجائز إطلاقه وما خرج من هذه الأقسام فلا يجوز وصف الله عزوجل به. ومن سماه بالقياس صار من القياس في اياس.\rالمسألة السادسة من هذا الأصل\r"]], "pg": [102, 103]}, "540.87": {"x": [[103, "في تفسير الخبر الوارد في عدد أسمائه\rوقد وصف الله تعالى أسماءه (بنعت] الحسنى لأن الأسماء جماعة والجماعة مؤنثة والحسنى بناء على فعلى والألف فيها علامة التأنيث وهذا كقول الله تعالى: (لَقَدْ رَأى مِنْ آياتِ رَبِّهِ الْكُبْرى) (3)، لأن الآيات مؤنثة وتذكير الحسنى والكبرى الأحسن والأكبر. ولو قيل في أسمائه الحسن بضم الحاء وفتح السين لجاز كما قال\r__________________\r(1) سورة الأعراف آية 180.\r(2) أخرجه الحاكم في المستدرك 1/ 16 و 17 وأخرجه الترمذي برقم 3507.\r(3) سورة النجم آية 18."], [104, "الله تعالى: (إِنَّها لَإِحْدَى الْكُبَرِ) (1). وليست الفائدة في حصر أسمائه الحسنى بتسعة وتسعين المنع من الزيادة عليها، لورود الشرع بأسماء له سواها. وإنما فائدته أن معاني جميع أسمائه محصورة في معاني هذه التسعة والتسعين. وقيل إنما حصر (2) أسماءه التي يجب الإيمان بمعانيها [بتسعة وتسعين] لأنها في الجملة مائة اسم والأعظم منها مكتوم لا يطلع (الله] عليه إلا من اكرمه الله عزوجل به وعند العباد منها تسعة وتسعون. وإنما كان الكمال في مائة لأنها منتهى العدد، لأن الأعداد [أربعة أجناس: آحاد وعشرات (ومئات) (3) وألوف، ثم (المئات) (4) ابتداء آحاد لأنها تتبعها عشرات الألوف ومئات الألوف وألوف الألوف ثم الألوف ابتداء ثالث يتبعه عشراته ثم هكذا على التكرير ومن الواحد إلى المائة آحاد وعشرات ومئات لا تكرير في أجناسها وبان بهذا أنّ كمال العدد مائة وقد استأثر الله تعالى بواحد من أسمائه المائة وعرف عباده منها تسعة وتسعين. وقيل] ثلاثة أنواع: آحاد وعشرات (ومئات) (5). ثم الالوف ابتداء ثان يتبعها عشراتها (ومئاتها) (6). وقيل إنّ العدد نوعان: زوج وفرد. والفرد أفضل من الزوج وفي الحديث: «إنّ الله وتر يحبّ الوتر» (7). وإذا صح أن الفرد أفضل من الزوج وأول الأفراد واحد وآخرها تسعة وتسعون، أنعم الله على عباده بأكمل الأفراد عددا من أسمائه [فأمرهم أن يدعوه بها وهي تسعة وتسعون اسما]. وأما قوله: «من أحصاها دخل الجنّة»، فلم يرد به من أحصاها لفظا إذ قد يحصيها المشرك والمنافق وليسا من أهل الجنة وإنما أراد من أحصاها من علمها واعتقدها من قولهم فلان ذو حصاة إذا كان ذا معرفة بالأمور ومنه قول الشاعر:\r__________________\r(1) سورة المدثر آية 35.\r(2) [خص].\r(3) وردت في المطبوع (ومئون).\r(4) وردت في المطبوع (المئون).\r(5) وردت في المطبوع (ومئون).\r(6) وردت في المطبوع (ومئوها).\r(7) أخرجه الترمذي عن علي بن أبي طالب برقم 453."], [105, "وإنّ لسان المرء ما لم يكن له ... حصاة على عوراته لدليل\r\rفكل من عرف أسماء الله تعالى واعتقدها ومات على ذلك فهو من أهل الجنة.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [103, 105]}, "540.88": {"x": [[105, "في أقسام أسمائه من طريق المعنى\rأسماء الله تعالى على ثلاثة أقسام: قسم منها يستحقه لذاته كوصفه بأنه شيء وموجود وذات وغنيّ ونحو ذلك. وقسم منها يستحقه لمعنى قام به كالحي والعالم والقادر والمريد والمتكلم والسميع والبصير. وقسم منها يستحقه لفعل من أفعاله كالخالق والغافر ونحو ذلك. وأما ما اشتق منها عن فعله فليس من أسمائه الأزلية خلاف قول الكرّامية في دعواها إنّ الله عزوجل لم يزل خالقا رازقا قبل وجود الخلق والرزق منه. ووافقونا في أنه لا يجوز أن يقال إنّه لم يزل خالقا للعالم بهذه الاضافة. وقلنا إن أسماءه نوعان أحدهما لازم لا يتعداه والإشارة فيه إلى ذاته كالشيء والحي.\rوالثاني يتعدى كالعالم والقادر والمريد والسميع والبصير، لأنه يتعدى إلى معلوم ومقدور ومراد ومسموع ومرئي. وأسماؤه أيضا نوعان:\rأحدهما مخصوص به كالإله والخالق والرازق والمحيي والمميت ونحو ذلك.\rوالثاني ما يجوز تسمية غيره به كالحي والعالم ونحوه. وأسماؤه نوعان: أحدهما مطلق كالحي والعالم والقادر ونحوه.\rوالثاني لا يطلق إلا مع الإضافة كذي الجلال والإكرام ورفيع الدرجات ومقلب القلوب والأبصار ونحو ذلك.\r\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [105, 105]}, "540.89": {"x": [[105, "فيما دل من أسمائه على ذاته فحسب"], [106, "هذا النوع من أسمائه كثير، منها شيء وموجود وملك وقدوس وعليّ وعظيم وكبير وجليل ومجيد وحق وواحد ومتين وأول وآخر وغني ومتعال [وأصحابنا متفقون على أن الله تعالى ذكره مستحقّ لهذه الأوصاف خلاف قول من قال إنّه موجود] وزعم سليمان بن جرير الزيدي أن الله موجود لمعنى به وأنّ ذلك المعنى لا موجود ولا معدوم. واختلف أصحابنا في معنى الإله: فمنهم من قال إنّه مشتق من الإلهية وهي قدرته على اختراع الاعيان وهو اختيار أبي الحسن الأشعري وعلى هذا الوصف لذاته وهو اختيار الخليل بن أحمد [و] المبرد وبه نقول. واختلفوا أيضا في معنى القديم: فقال عبد الله بن سعيد والقلانسي إنّه قديم بمعنى قائم به. وقال أبو الحسن الأشعري إنّه قديم لذاته وأجمع أصحابنا على أنه باق ببقاء يقوم به غير القاضي أبي بكر بن الطيب فإنه قال بأن الله باق لنفسه وبه نقول.\rالمسألة التاسعة من هذا الأصل\r"]], "pg": [105, 106]}, "540.90": {"x": [[106, "في بيان أسمائه الدالة على صفاته الأزلية\rكل ما كان من أسمائه مشتقا من معنى قائم به فذلك المعنى صفة له أزلية كالحي والقادر والقدير والمقتدر والعالم والعليم والعلّام والسامع والسميع والبصير والمريد والمتكلم والآمر والناهي والمخبر. لأن هذه الأسماء دالة على حياته وقدرته وعلمه وإرادته وكلامه وسمعه وبصره وهذه صفات له أزلية. والقويّ في أسمائه بمعنى القادر. والخبير والشهيد والمحصي بمعنى العليم. والأول والآخر في معنى الباقي، عند أكثر أصحابنا، دليل على بقاء هو صفة له. والودود والحليم والصبور في أسمائه راجع إلى معنى إرادته للإنعام على عبده أو إرادته للعفو عنه. والواعد والموعد والصادق والذاكر من أسمائه راجع إلى معاني كلامه الأزلي [وكل اسم كان مشتقا من صفة له أزلية فذلك الاسم من أسمائه الأزلية، كما بيناه قبل"], [107, "هذا، خلاف قول من زعم من القدرية أن الله تعالى لم يكن له في الأزل اسم ولا صفة ولا يمكن وصف المعدوم باكثر من هذا تعالى الله من قولهم] وقس على هذا ما جرى مجراه.\rالمسألة العاشرة من هذا الاصل\r"]], "pg": [106, 107]}, "540.91": {"x": [[107, "في بيان ما دل من اسمائه على افعاله\rكالبرّ في الدلالة على بره بعباده، والباري: في الدلالة على أنه خالق الخلق، والباسط: في الدلالة على بسط الرزق لمن شاء وعلى أنه بسط الارض ولذلك سماها بساطا خلاف قول من زعم من الفلاسفة والمنجمين أن الارض كرية (1) غير مبسوطة. والباعث من أسمائه دليل على بعثه الرسل عليهم السلام وعلى بعثه الاموات من اللحود. والتّواب دليل على أنه الموفق عباده للتوبة. والجامع من أسمائه فيه إشارة على معنى قوله: (يَوْمَ يَجْمَعُ اللهُ الرُّسُلَ) (2) وقوله: (إِنَّ عَلَيْنا جَمْعَهُ) (3) وقوله: (أَيَحْسَبُ الْإِنْسانُ أَلَّنْ نَجْمَعَ عِظامَهُ) (4). والخافض والرافع دليلان على أنه يخفض من يشاء ويرفع من يشاء فيخفض الكفرة إلى أسفل السافلين ويرفع أولياءه إلى أعلى عليين. والخالق والخلاق من خصوص أسمائه خلاف قول القدرية والثنوية بخالق غير الله تعالى. والدافع من أسمائه فيه اشارة إلى قوله: (وَلَوْ لا دَفْعُ اللهِ النَّاسَ بَعْضَهُمْ بِبَعْضٍ لَفَسَدَتِ الْأَرْضُ) (5). والرب بمعنى المالك للمملوكات كلها وقد يكون بمعنى المصلح للشيء والله خالق كل صلاح على زعم القدرية. والرزاق والرازق: دليلان على أن الارزاق كلها من فعله. والساتر والستار: إشارة إلى ستره ذنوب من يشاء من عباده وإلى ستره عيوب من شاء منهم. والضار والنافع هو سبحانه خلاف قول الثنوية: إنّ خالق الضرر غير\r__________________\r(1) كروية.\r(2) سورة المائدة آية 109.\r(3) سورة القيامة آية 17.\r(4) سورة القيامة آية 3.\r(5) سورة البقرة آية 251."], [108, "خالق النفع. والغفور والغافر من أسمائه دليل على غفرانه لما دون الشرك لمن شاء. وزعمت القدرية أن الله لا يغفر لصاحب الكبيرة ولا يجوز أن يعذب من لا كبيرة له فلا يتحقق على اصولهم لله الوصف بالغفور. والفاطر بمعنى الخالق. والقاهر والغالب دليلان على ابطال قول المجوس إنّ الشيطان غلب الإله حتى تحصّن في السماء. ومعنى الكفيل من أسمائه راجع إلى ضمانه ارزاق عباده. والمصوّر والمعزّ والمذلّ والمغيث والمجيب والمبين والمبدي والمعيد والمحيي والمميت والمقدم والمؤخر والمقسط والمغني والمنتقم والوهاب والهادي كل ذلك من اسمائه دالة على افعال مخصوصة. والوارث: دليل على بقائه بعد فناء خلقه. والنصير: دلالة على نصرته لأوليائه على اعدائه.\rالمسألة الحادية عشرة من هذا الاصل\r"]], "pg": [107, 108]}, "540.92": {"x": [[108, "فيما دل من اسمائه على [معان]\rهذا النوع من أسمائه كثير. منها البديع فإنه يكون بمعنى المبدع للشيء ومنه قوله عزوجل: (بَدِيعُ السَّماواتِ وَالْأَرْضِ) (1)، أي مبدعهما وعلى هذا الوجه يكون هذا الاسم مشتقا من فعله. وقد يكون البديع بمعنى الأول يقال منه بدع وبديع ومنه قوله: (ما كُنْتُ بِدْعاً مِنَ الرُّسُلِ) (2) أي ما كنت أولهم ويكون البديع الذي لا يكون له مثل وعلى هذين الوجهين يكون البديع من أسمائه الأزلية. ومنها الظاهر والباطن إن حملناهما على معنى أنه العالم بظواهر الأمور وبواطنها كانا من أوصافه الأزلية وإن حملناهما على معنى قوله: (وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُ ظاهِرَةً وَباطِنَةً) (3)، كانا مشتقين من فعله. ومنها الجبار، إن تأولناه على معنى القهر لأعدائه أو على معنى جبره للكسير كان مشتقا من فعله وإن تأولناه على معنى [الذي لا يناله الأيدي] من لا ينال، كقولهم: نخلة جبارة إذا لم تنلها الايدي، كان من صفاته الأزلية. ومنها الجميل إن حملناه على نفي العيوب عنه فهو من أوصافه\r__________________\r(1) سورة البقرة آية 117.\r(2) سورة الأحقاف آية 9."], [109, "(3) سورة لقمان آية 20.\r\rالازلية وإن حملناه على معنى المجمل فهو مشتق من فعله. ومنها الحفيظ، إن كان من حفظه خلقه فهو مشتق من فعله وإن كان بمعنى العليم فهو من صفاته الأزلية. ومنها الحميد: إن كان بمعنى المحمود فهو مشتق من فعله وإن كان بمعنى الحامد فهو من صفاته الأزلية لأن الحمد من الله كلامه الأزلي. ومنها الحكيم: إن اخذناه من اتقانه وأحكامه لأفعاله فهو مشتق من فعله وإن حملناه على معنى حكمته وعلمه فهو من صفاته الأزلية. وكذلك الحليم إن تأولناه على تأخيره عقوبة أهل العقوبة فهو مشتق من فعله وإن حملناه على نفي الطيش عنه فهو من صفاته الأزلية. ومنها السلام: إن كان من السلامة عن العيوب فهو من أوصافه الأزلية وإن كان من إنعامه سلامة عباده فهو مشتق من فعله. ومنها الصمد: إن كان من معنى السيد المصمود في النوائب فهو مشتق من فعله وإن اخذناه من الذي لا جوف له فمعناه في الله أنه لا يوصف بالأعضاء ويكون حينئذ من أوصافه الأزلية. والمؤمن من أسمائه، إن كان من بذله الأمان فهو مشتق من فعله وإن كان من الإيمان الذي هو التصديق فتصديقه بقوله الأزلي. وقس على هذا ما جرى مجراه.\rالمسألة الثانية عشرة من هذا الأصل\r"]], "pg": [108, 109]}, "540.93": {"x": [[109, "فيما يجوز تسمية غير الله به من أسمائه\rأما التسمية بالإله والرحمن والخالق والقدوس والرزاق والمحيي والمميت ومالك الملك وذي الجلال والإكرام فلا يليق بغير الله عزوجل. ويجوز تسمية غيره بما خرج من معاني تلك الأسماء الخاصة. ومن أسمائه ما يوصف الله به مدحا ويوصف غيره به ذمّا كالجبّار والمتكبر والمصوّر. ومنها ما يوصف به مطلقا ويوصف غيره به مقيدا بالإضافة كالرب والقابض والباسط والخافض والرافع.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [109, 109]}, "540.94": {"x": [[109, "في الفرق بين صفاته وأوصافه\rاختلفوا في معنى الوصف والصفة: فزعمت الجهمية والقدرية أنهما راجعان إلى وصف الواصف لغيره أو لنفسه ولم يثبتوا لله تعالى صفة أزلية. وقال أبو"], [110, "الحسن الاشعري إنّ الوصف والصفة بمعنى واحد وكل معنى لا يقوم بنفسه فهو صفة لما قام به ووصف له. ويجوز على هذا المذهب وجود صفة لموصوفين كخبر المخبر عن سواد فإنه وصف للسواد وصفة للقائل ويجوز على هذا كون المعدوم موصوفا عند الخبر عنه. وقال أكثر أصحابنا: إن صفة الشيء ما قامت به كالسواد صفة للأسود لقيامه به ووصف الشيء خبر عنه وقول القائل: زيد عالم صفة للقائل لقيامه به ووصف لزيد لأنه خبر عنه. والعلوم والقدر والألوان والأكوان وكل عرض سوى الخبر عن الشيء صفات وليست باوصاف.\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [109, 110]}, "540.95": {"x": [[110, "في بيان ما يوصف به الله تعالى من فعل لا يصدر عنه اسم\rقال الله تعالى: (وَسَقاهُمْ رَبُّهُمْ شَراباً طَهُوراً) (1) ولا يقال له ساق وقال: (اللهُ يَسْتَهْزِئُ بِهِمْ) (2) ولا يقال له مستهزئ وقال أيضا: (سَخِرَ اللهُ مِنْهُمْ) (3) ولا يقال ساخر وقال: (وَغَضِبَ اللهُ عَلَيْهِمْ) (4) ولا يقال غضبان وقال: (إِنَّ اللهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِ) (5) ولا يقال مصلّ [و] (6) قال: (سَأُرْهِقُهُ صَعُوداً) (7) ولا يقال إنّه مرهق. وفي هذا دليل على أن مأخذ اسمائه التوقيف دون القياس.\rالمسألة الخامسة عشرة من هذا الاصل\r"]], "pg": [110, 110]}, "540.96": {"x": [[110, "في بيان أسمائه المضافة التي لا تطلق بغير إضافة\rمن هذا النوع قوله: قابل التوب وشديد العقاب ولا يجوز أن يقال له شديد\r__________________\r(1) سورة الدهر آية 21.\r(2) سورة البقرة آية 15.\r(3) سورة التوبة آية 80.\r(4) سورة الفتح آية 6.\r(5) سورة الأحزاب آية 56.\r(6) زيدت على المطبوع لسياق العبارة.\r(7) سورة المدثر آية 17."], [111, "مفردا ولا يجوز أن يقال في الدعاء: يا شديد العقاب، إلا مقرونا فيقال: يا قابل التوب شديد العقاب. ومنه «رفيع الدرجات» ولا يقال له: رفيع بغير إضافة ويجوز أن يقال له الرافع مطلقا. ومنه «ذو العرش» و «ذو الجلال» و «ذو المعارج» [و] لا يصح شيء منه دون الاضافة. ومنه أيضا «مولج الليل في النهار ومولج النهار في الليل». ومنه مسبب الاسباب ومفتح الأبواب ويقال له الفتاح على الاطلاق.\r\rالأصل السادس\r"]], "pg": [110, 111]}, "540.97": {"x": [[111, "من أصول هذا الكتاب في بيان عدل\rالصانع وحكمته\rوفي هذا الأصل خمس عشرة مسألة هذه ترجمتها:\rمسألة في بيان العدل والظلم.\rمسألة في معنى الخلق والكسب.\rمسألة في أن الله تعالى خالق الاكساب.\rمسألة في إبطال التولد من فعل الانسان.\rمسألة في بيان ما يصح اكتسابه.\rمسألة في أن الهداية والاضلال من فعل الله.\rمسألة في خلق الآجال وتقديرها.\rمسألة [في] خلق الارزاق وتقديرها\rمسألة في نفوذ مشيئة الله فيما أراد.\rمسألة في جواز تخلية العباد عن التكليف.\rمسألة في اجازة الزيادة والنقصان في الشرع.\rمسألة في جواز خلق الكفرة على الانفراد.\rمسألة في جواز إماتة من [علم الله منه الإيمان لو لم يمته] يؤمن، قبل إيمانه.\rمسألة في [الاختصار على خلق الجمادات] جواز خلق الاموات دون الاحياء.\rمسألة في جواز التخصيص بالنعم. فهذه مسائل هذا الاصل.\rوسنذكر في كل مسألة منها مقتضاها ان شاء الله تعالى.\r\rالمسألة الأولى من هذا الاصل\r"]], "pg": [111, 111]}, "540.98": {"x": [[111, "في بيان العدل والظلم"], [112, "اعلم إن العدل في اللغة قد يكون بمعنى المثل كقوله تعالى: (أَوْ عَدْلُ ذلِكَ صِياماً) (1)، أي مثل ذلك. وقد يكون بمعنى العدول عن الشيء ومنه قوله تعالى: (بَلْ هُمْ قَوْمٌ يَعْدِلُونَ،) (2)، أي يعدلون عن الحق إلى الجور. والعدل في الأصل مصدر أقيم المصدر مقام الاسم فقيل للعادل عن الباطل إلى الحق عدل. وعلى هذا يستوي فيه الذكر والانثى والجمع والتثنية والوحدان. وإذا قيل لله سبحانه عدل، فمعناه العادل. وقال سيبويه: معناه ذو العدل كقوله تعالى: (وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ) (3). ولو لا ورود الشرع بتسميته عدلا ما جاز اطلاق المصادر في أسمائه. واختلف أصحابنا في تحديد العدل من طريق المعنى: فمنهم من قال: هو ما للفاعل أن يفعله. فإذا قيل له: يلزمك على هذا أن يكون كل كفر ومعصية عدلا من أجل أنها عندك من أفعال الله تعالى وله أن يفعلها. أجاب عنه بأن كلها عدل منه وإنما هي جور وظلم من مكتسبها. ومنهم من قال: العدل من أفعالنا ما وافق أمر الله عزوجل به والجور ما وافق نهيه (فإن أردت طرد هذا الحد قلت العدل ما لم يوافق نهي الله]. وزعم الكعبي أن العدل هو التسوية بين العباد فيما يحتاجون إليه من إزاحة العلل والتوفيق والهداية. ويلزمه على هذا الأصل أن لا يكون الإنسان عادلا بفعل لا يتعدى منه إلى غيره. ومعنى الظلم في اللغة: وضع الشيء في غير موضعه، وقد يكون بمعنى المنع كقوله تعالى: (كِلْتَا الْجَنَّتَيْنِ آتَتْ أُكُلَها وَلَمْ تَظْلِمْ مِنْهُ شَيْئاً) (4)، أي لم تنقص ولم تمنع منه شيئا. واختلفوا في معنى الظالم من طريق المعنى فقال أصحابنا: حقيقته من قام به الظلم.\r__________________\r(1) سورة المائدة آية 95.\r(2) سورة النحل آية 60.\r(3) سورة الطلاق آية 2.\r(4) سورة الكهف آية 33."], [113, "وزعمت القدرية أن حقيقته فاعل الظلم، وأجازوا أن يكون ظلم الظالم قائما بغيره. واعترضوا على أصحابنا في قولهم أن الظالم من قام به الظلم، بأن قالوا: إنّ الظلم يقوم ببعض الظالم والجملة هي الظالمة. وهذا السؤال ساقط على أصل شيخنا أبي الحسن الاشعري، لأنه يقول: إنّ محل الظلم من الجملة، هو الظالم دون جملته. ومن قال من أصحابنا إنّ الظالم هو الجملة، كما ذهب إليه القلانسي وعبد الله بن سعيد، أجاز أن يقال إنّ الظلم قائم بالظالم وإن قام ببعضه كما يقال (1) عندهم للإنسان بكماله: عالم قادر لقيام العلم والقدرة ببعضه. فإن قالوا: لو كان الظالم من قام به الظلم لوجب أن يكون المشجوج (2) والمقتول ظالمين بما حلّهما من الظلم الذي هو القتل والشجّة. قيل له ليس ما حلّ بالمقتول والمشجوج ظلما عندنا وإنما الظلم عندنا فيهما قائم بالقاتل والشاج عند تحريكه يده بما وقع عقيبه من الآثار الظاهرة في المقتول والمشجوج. ومما يدل على إبطال قولهم، إنّ الكافر من فعل الكفر والظالم من فعل الظلم، اتفاقهم معنا على أن الجهل بالله تعالى كفر به وقد وافقنا القدرية، سوى النظّام والاسواري على أن الله تعالى قادر على أن يخلق في الكافر جهلا به ولو فعل مقدوره من ذلك لكان الجاهل كافرا به ولم يكن فاعلا. وفي هذا بطلان تحديدهم الكافر بفاعل الكفر.\rالمسألة الثانية من هذا الاصل\r"]], "pg": [111, 113]}, "540.99": {"x": [[113, "في بيان معنى الخلق والكسب\rزعمت القدرية أن الكسب الذي يقول به أهل السنة غير معقول لهم وقالوا: لا وجه لنسبة الفعل إلى مكتسبه غير احداثه له. [واختلف أصحابنا في تفسير معنى الكسب فمنهم من قال للقدرية] وقال اصحابنا (3) للقدرية انكم زعمتم ان افعالنا\r__________________\r(1) كما يقال [في الرجل أنه ساكن البلد وإن سكن في بعضه]."], [114, "(2) الشّجاج بالكسر جمع شجة، تقول: شجّه يشجه، بضم الشين وكسرها شجا فهو مشجوج وشجيج ومشجّج أيضا إذا كثر ذلك فيه، ورجل أشجّ بيّن الشّجّة إذا كان في جبينه أثر الشجة.\r(3) [اختلف أصحابنا في تفسير معنى الكسب فمنهم من قال للقدرية ... ].\r\rكانت في حال عدمها قبل حدوثها اشياء واعراضا وان الانسان المكتسب لها لم يجعلها اشياء واعراضا. ونحن نقول إنّ الله عزوجل هو الذي جعل أفعالنا أشياء وأعراضا. وهذا معنى قولنا إنّ الله عزوجل خلق أعمال عباده ومعناه أنه هو الذي جعل اشياء واعراضا. وقد سلمتم لنا أن الانسان لم يجعلها كذلك فالذي نفيتموه عن الإنسان اضفناه إلى الله عزوجل. وقد ضرب بعض أصحابنا للاكتساب مثلا، في الحجر الكبير، قد يعجز عن حمله رجل ويقدر آخر على حمله منفردا به. إذا اجتمعا جميعا على حمله كان حصول الحمل بأقواهما ولا خرج أضعفهما بذلك عن كونه حاملا. كذلك العبد لا يقدر على الانفراد بفعله ولو أراد الله الانفراد بإحداث ما هو كسب للعبد قدر عليه ووجد مقدوره، فوجوده على الحقيقة بقدرة الله تعالى ولا يخرج مع ذلك المكتسب من كونه فاعلا وإن وجد الفعل بقدرة الله تعالى. فهذا قول معقول وإن جهلته القدرية. وإنما المجهول قول ابن الجبائي في هذا الباب، لأنه قال: إنّ الخالق للشيء إنما يخلقه بأن يجعله على حال. ثم لا يصف تلك، بأنها موجودة ولا معدومة، ولا بأنها معلومة ولا مجهولة (فصارت) (1) دعاويه في أحداث الافعال غير معقولة له ولغيره.\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [113, 114]}, "540.100": {"x": [[114, "في بيان أنّ الله تعالى خالق اكساب العباد\rواختلفوا في إكساب العباد وأعمال الحيوانات على ثلاثة مذاهب: أحدها قول أهل السنة إن الله عزوجل خالقها كما أنه خالق الأجسام والألوان والطعوم والروائح؛ لا خالق غيره وإنما العباد مكتسبون لأعمالهم."], [115, "والمذهب الثاني: قول الجهمية أن العباد مضطرون إلى الأفعال المنسوبة إليهم وليس لهم فيها اكتساب ولا لهم عليها استطاعة وإنّ حركاتهم الاختيارية بمنزلة حركة العروق النوابض في اضطرارهم إليها. والمذهب الثالث: قول القدرية الذين زعموا أن العباد خالقون لأكسابهم وكل حيوان محدث لاعماله وليس لله في\r__________________\r(1) وردت في المطبوع «مضار»."], [116, "شيء من أعمال الحيوانات صنع. وذكر أكثرهم أن الله عزوجل غير قادر على مقدور غيره وإن كان هو الذي أقدر القادرين على مقدوراتهم. وزعم المعروف منهم بمعمران الاعراض كلها من أفعال الأجسام إما بالاختيار وإما بالطباع وإن الله تعالى ما خلق لونا ولا طعما ولا رائحة ولا حركة ولا سكونا ولا حياة ولا موتا ولا قدرة ولا عجزا ولا علما ولا صحة ولا سقما ولا سمعا ولا بصرا ولا شيئا من الأعراض. وزعم المعروف منهم ببشر بن المعتمر، أنّ الألوان والطعوم والروائح والرؤية والسمع، منها ما هو من فعل الله عزوجل ومنها ما هو من فعل العبد ومنها ما هو من اجتماع العباد. والدليل على جميع القدرية من القرآن قوله عزوجل: (وَاللهُ خَلَقَكُمْ وَما تَعْمَلُونَ) (1)، فأثبت في هذه الآية للعباد أعمالا خلاف قول الجهمية: إن العبد ليس له عمل وأخبر عن نفسه بأنه خالق أعمال العباد خلاف قول القدرية: إن العباد خالقون لأعمالهم. فدلت الآية على بطلان قول الجهمية والقدرية. فإن قيل أراد بالأعمال الأصنام المعمولة. قيل إن الأصنام لم تكن من عمل العباد وإنما نحتها عملهم والله خالق عملها الذي هو نحتهم لها. ويدل عليه قوله تعالى: (أَمْ جَعَلُوا لِلَّهِ شُرَكاءَ خَلَقُوا كَخَلْقِهِ فَتَشابَهَ الْخَلْقُ عَلَيْهِمْ، قُلِ اللهُ خالِقُ كُلِّ شَيْءٍ وَهُوَ الْواحِدُ الْقَهَّارُ) (2). فأخبر أنه لو كان غير الله خالقا شيئا مثل خلق الله لكان شريكا له. وزعمت القدرية أنهم يخلقون من الحركات والاعتمادات والعلوم والإرادات والآلام مثل ما خلق الله عزوجل منها. وفي هذه الدعوى دعوى المشاركة لله في صنع أكثر أجناس الأعراض. ثم قوله قل الله خالق كلّ شيء دليل على انه خالق كل مخلوق سواء كان من أكساب العباد أو من غير أكسابهم."], [117, "ويدل عليه قوله: (وَأَسِرُّوا قَوْلَكُمْ أَوِ اجْهَرُوا بِهِ إِنَّهُ عَلِيمٌ بِذاتِ الصُّدُورِ أَلا يَعْلَمُ مَنْ خَلَقَ) (3) وفي هذا دليل على أنه خالق سرائر الصدور وعالم بها. وفيه أيضا دليل على أن الخالق للشيء يجب أن يكون عالما به وبتفصيله وقد علمنا أن العباد لا يعلمون تفصيل عدد حركاتهم الكسبية في عضو واحد في زمان متناه. وقد\r__________________\r(1) سورة الصافات آية 96.\r(2) سورة الرعد آية 16.\r(3) سورة الملك آية 13 و 14.\r\rزعمت القدرية أن النائم والساهي يخلقان الكلام والأصوات والحركات والآلام التي لا علم لهم بها. وهذا خلاف حكم الآية التي تلوناها. ويدل على بطلان قولهم من القياس إنّ الخالق للشيء يجب أن يكون قادرا على إعادته كالخالق للأجسام والألوان قادر على إعادتها. وإذ كان الواحد منا لا يقدر على إعادة كسبه بعد عدم الكسب صح أن ابتداء وجود كسبه كان بقدرة غيره وهو الله القادر على إعادته. فإن قالوا لو كان الكسب فعلا لله وللعبد لاشتركا فيه. قيل ليس حدوثه منهما، حتى يكونا شريكين في إحداثه وإنما الله عزوجل خالق الكسب والعبد مكتسب له كما أن الله خالق حركة العبد والعبد متحرك ولا يجب الشركة بمثل هذا. وإنما يتصور الشركة بين صانعين يكون صنع واحد منهما غير صنع صاحبه، في الجنس الواحد، كالخياطين يشتركان في خياطة قميص واحد، لأن خياطة أحدهما غير خياطة الآخر. ومن زعم من القدرية أن صنعه في يديه غير صنع الله فيه فهو الذي ادعى المشاركة المذمومة وكفاهم به خزيا.\rالمسألة الرابعة من هذا الأصل\r"]], "pg": [114, 117]}, "540.101": {"x": [[117, "في إبطال القول بالتولد"], [118, "واختلفوا في التولد: فزعم أكثر القدرية أن الإنسان قد يفعل في نفسه فعلا يتولد منه فعل في غيره ويكون هو الفاعل لما تولّد، كما أنه هو الفاعل لسببه في نفسه [ولذلك زعموا أن ذهاب السهم وإصابته الهدف وهتكه له وقتله لما وراء الهدف، فكل ذلك من فعل الله لأن حركات السهم متولد من تحريكه يده بالسهم والقوس. وكذلك قولهم في انكسار الزجاج بالحجر إذا ألقاه عليه إنسان. وقالوا في الألم الحادث عقيب الضرب إنّه فعل الضارب متولد عن ضربه] وكذلك الضارب متولد عن ضربه. وزعموا أيضا أن فاعل السبب لو مات عقيب السبب ثم تولد من ذلك السبب فعل بعد مائة سنة لصار ذلك الميت فاعلا له بعد موته وافتراق أجزائه بمائة سنة. وأجاز المعروف منهم ببشر بن المعتمر أن يكون السمع والرؤية وسائر الإدراكات وفنون الألوان والطعوم والروائح متولدة عن فعل الانسان [فالمتولد عنه"], [119, "من فعله. ومتى كان السبب من فعل الله عزوجل فالمتولد أيضا من فعله]. وقال أصحابنا أن جميع ما سمّته القدرية متولدا من فعل (1) الانسان وليس الإنسان مكتسبا وإنما يصح من الإنسان اكتساب فعله في محل قدرته. وأجازوا أن يمد الإنسان الوتر بالسهم ويرسل يده ولا يذهب السهم. وأجازوا أيضا أن يقع سهمه على ما أرسله ولا يكسره ولا يقطعه. وأجازوا أيضا أن يجمع الإنسان بين النار (2) [والقطن] والحلفاء (3) فلا تحرقها على نقض العادة كما أجرى العادة بأن لا يخلق الولد إلا بعد وطئ الوالدين ولا السمن إلا بعد العلف ولو أراد خلق ذلك ابتداء لقدر عليه. وزعم بعض القدرية وهو المعروف بثمامة أن الأفعال المتولدة لا فاعل لها. يلزمه على هذا الأصل إجازة حدوث كل فعل لا من فاعل وفيه إبطال دلالة الموحدين على إثبات الصانع. وزعم النظّام منهم أن المتولدات كلها من أفعال الله تعالى بإيجاب الخلقة. وهذا القائل مصيب عندنا في قوله: إن الله خالق المتولدات، ومخطئ في دعواه إيجاب الخلقة على معنى أن الله طبع الحجر على أن لا يقف في الهواء لأن وقوفه في الهواء جائز غير مستحيل عندنا [وقد أكذبه المعتزلة في قوله: إنّ المتولدات من فعل الله تعالى. وقالوا يلزمه أن يكون كلمة الكفر فعلا من الله تعالى. لأن الكلام كله متولد عندهم. وهم الكفرة في هذا دونه. وأما كفر النظّام من غير هذا الوجه وسنذكر بعد هذا إن شاء الله].\rالمسألة الخامسة من هذا الاصل\r"]], "pg": [117, 119]}, "540.102": {"x": [[119, "في الفرق بين ما يصح اكتسابه وبين ما لا يصح اكتسابه\rاجمع أصحابنا على أن الحركة والسكون يصح اكتسابهما وكذلك الإرادة\r__________________\r(1) [الله عزوجل ولا يصح أن يكون الإنسان فاعلا في غير محل قدرته لأنه يجوز ان يمد الانسان وتر قوسه ويرسل السهم من يده فلا يخلق الله تعالى في السهم ذهابا].\r(2) [والقطن].\r(3) الحلفاء: نبت في الماء، قال أبو زيد: واحدتها حلفة كقصبة وطرفة، وقال الأصمعي:\rحليفة بكسر اللام."], [120, "والعلم والاعتقاد والجهل والقول والسكوت [والكفر]. وأجمعوا على أنه لا يصح منا اكتساب الالوان والطعوم والروائح والقدرة والعجز والسمع والصمم والرؤية (1) والعمى والخرس واللذة والشهوة والأجسام [هذا كله قول أصحابنا]. وزعم معمر: إن الأعراض كلها من فعل الأجسام إما طباعا وإما اختيارا. وأجاز بشر بن المعتمر [أن الواحد منا يصح أن يفعل اللون] منا فعل الألوان والطعوم والروائح والإدراكات على سبيل التولد. وكل من زعم من القدرية أن المخلوق يجوز أن يحدث في غيره أعراضا وتأليفا فلا دليل له من طريق العقل على أن الله عزوجل هو الفاعل لتأليف أجزاء السماء وحركات الكواكب لأن ذلك كله يصح عندهم أن يكون فعلا لبعض الملائكة وبعض الجن فلا دليل لهم على أن ذلك من فعل الله تعالى وكفاهم بذلك خزيا.\rالمسألة السادسة من هذا الأصل\r"]], "pg": [119, 120]}, "540.103": {"x": [[120, "في أن الهداية والإضلال من فعل الله عزوجل\rقال أصحابنا: إن الهداية من الله [تعالى] لعباده على وجهين:\r"]], "pg": [120, 120]}, "540.104": {"x": [[120, "أحدهما من جهة إبانة الحق والدعاء إليه وإقامة الأدلة عليه وعلى هذا الوجه يصح إضافة الهداية إلى الرسل وإلى كل داع إلى دين الله عزوجل لأنهم مرشدون إليه وهذا تأويل قول الله عزوجل في رسوله صلىلله عليه وسلم (وَإِنَّكَ لَتَهْدِي إِلى صِراطٍ مُسْتَقِيمٍ) (2)، أي تدعو إليه. والوجه الثاني من هداية الله تعالى لعباده، خلقه في قلوبهم الاهتداء، كما ذكره الله عزوجل في قوله: (فَمَنْ يُرِدِ اللهُ أَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلامِ) (3). فالهداية الأولى من الله تعالى شاملة جميع المكلّفين.\rوالهداية الثانية منه خاصة للمهتدين. وفي تحقيق ذلك نزل قول الله عز\r__________________\r(1) [والبصر].\r(2) سورة الشورى آية 52.\r(3) سورة الأنعام آية 125."], [121, "وجل: (وَاللهُ يَدْعُوا إِلى دارِ السَّلامِ وَيَهْدِي مَنْ يَشاءُ إِلى صِراطٍ مُسْتَقِيمٍ) (1)، يعني به اهتداء القلوب الذي لا يقدر عليه غير الله عزوجل. ولهذا قال في نبيه عليه السلام: (إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلكِنَّ اللهَ يَهْدِي مَنْ يَشاءُ) (2) [وقد وصفه بأنه يهدي إلى صراط مستقيم فالهداية التي أثبتها الله تعالى للرسول صلىلله عليه وسلم من طريق البيان والدعوة. والهداية التي نفاها عنه من جهة شرح الصدور وقبولها للحق]. والإضلال من الله عزوجل لأهل الضلال على معنى خلق الضلالة عن الحق في قلوبهم. وعلى ذلك يحمل قوله: (وَمَنْ يُرِدْ أَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقاً حَرَجاً) (3) وقوله: (يُضِلُّ اللهُ مَنْ يَشاءُ وَيَهْدِي مَنْ يَشاءُ) (4). فمن أضله فبعدله ومن هداه فبفضله هذا قول أهل السنة. وزعمت القدرية أن الهداية من الله تعالى على معنى الإرشاد والدعاء وإبانة الحق وليس إليه من هداية القلوب شيء. وزعموا أن الإضلال منه على وجهين:\rأحدهما: أن يقال إنّه أضل عبدا بمعنى أنه سماه ضالا\rوالثاني: على معنى أنه جازاه على ضلالته. وقد أخطئوا في تأويلهم من طريق اللغة ومن طريق المعنى. أما من طريق اللغة فلأنّ من سمى غيره ضالا أو نسبه إلى الضلالة فإنما يقال فيه إنّه ضلّله بالتشديد ولا يقال أضله. وأما من طريق المعنى فمن جهة أن الإضلال من الله لو كان بمعنى التسمية والحكم لوجب أن يقال إنّ النبي صلىلله عليه وسلم قد أضل الكفرة لأنه سماهم ضالين وحكم بضلالتهم ووجب أن يقال إنّ الكفرة والشياطين قد أضلوا المؤمنين والأنبياء لأنهم قد سموهم ضالين. ولو كان الإضلال من الله عزوجل بمعنى العقاب على الضلالة لكان كل من أقام الحد على الزاني والسارق والقاتل والقاذف وشارب الخمر قد أضلهم، لأنه قد جازاهم على\r__________________\r(1) سورة يونس آية 25.\r(2) سورة القصص آية 56.\r(3) سورة الأنعام آية 125."], [122, "(4) سورة المدثر آية 31.\r\rضلالاتهم وفسقهم. وإذا بطل هذا صح أن الهداية والإضلال من الله تعالى على ما ذهبنا إليه دون ما ذهبت القدرية إليه. [وزعمت الثنوية أن الهداية من النور والضلال من الظلمة. وزعمت المجوس أن الهداية من الإله والإضلال من الشيطان وقد مضى الكلام عليهم في توحيد الصانع. في ذلك كفاية على إبطال قولهم].\rالمسألة السابعة من هذا الأصل\r"]], "pg": [120, 122]}, "540.105": {"x": [[122, "في خلق الآجال وتقديرها.\rقال (1) أصحابنا: [على أن من] كل من (2) مات حتف أنفه أو قتل فإنما مات بأجله الذي جعله الله عزوجل أجلا لعمره. والله قادر على إبقائه والزيادة في عمره لكنه إذا لم يبقه إلى مدة لم يكن المدة التي لم يبق إليها أجلا له، كما أن المرأة التي لم يتزوجها قبل موته لم تكن امرأة له وإن أمكن أن يتزوجها لو لم يمت. واختلفت القدرية في هذه المسألة: فقال أبو الهذيل فيها مثل قولنا وهو أن المقتول لو لم يقتل مات في وقت قتله بأجله [لأن المدة التي لم يعش إليها لم تكن أجلا له ولا من عمره] وقال الجبائي أيضا فيمن علم الله منه أنه يقتل لعشرين سنة أن الوقت الذي يقتل فيه أجل له وهو أجل موته ولا يجوز أن يكون له أجل آخر إلا على تقدير الإمكان. وزعم الباقون من القدرية أن المقتول مقطوع عليه أجله. فجعلوا العباد قادرين على أن ينقصوا مما أجّله الله عزوجل ووقّته. ولو جاز ذلك لجاز أن يزيدوا في أجل من قضى الله له أجلا محدودا. وإذا لم يقدروا على الزيادة في أجل آخر لم يقدروا على النقصان منه. فأما قول نوح عليه السلام: (وَيُؤَخِّرْكُمْ إِلى أَجَلٍ مُسَمًّى) (3)، فإنه لم يقل ويؤخركم إلى أجل لكم. ونحن لا ننكر إمكان البقاء ان لو لم يمت المقتول. ولكنا قلنا إنّ المدة التي قتل قبلها لم تكن أجلا له [احتجوا بقوله تعالى: (وَما يُعَمَّرُ مِنْ مُعَمَّرٍ وَلا يُنْقَصُ مِنْ عُمُرِهِ) (4).\r__________________"], [123, "(1) [أجمع]. 2) [على أن من]. (3) سورة نوح آية 4. (4) سورة فاطر آية 11.\r\rومن فروع هذه المسألة: اختلافهم في المقتول هل هو ميت أم لا. وقد زعم الكعبي أن المقتول غير ميت لأن الموت من [فعل] قبل الله والقتل من [فعل] قبل القاتل. وقال أكثر القدرية: المقتول ميت وفيه معنيان أحدهما موت من فعل الله عزوجل والثاني: قتل هو من فعل القاتل. وقال أصحابنا: القتل غير الموت ولكن المقتول ميت والموت قائم به والقتل يقوم بالقاتل. ومن فروعها [أيضا] الشهادة وقد زعمت القدرية أنها الصبر على ألم الجراح والعزم على ذلك قبل وقوعه ومنعوا تسمية قتل الكافر للمؤمنين شهادة. وقالت الكرّامية الشهادة أن يصيب المؤمن من البلاء [على] ما يوجب تكفير ذنوبه كلها إذا لم يكن من الصديقين، لأن الصديق لا يحتاج إلى تكفير ذنبه. وقال أصحابنا: من قتل مظلوما أو مات من بعض الأمراض المخصوصة كالحريق والغريق وموت المرأة في طلقها ونحو ذلك فهو شهيد. ولو كانت الشهادة في تكفير الذنوب لم يكن من لا ذنب له شهيدا وإن قتله الكفرة في حربها. وإذا صح لنا أن الشهادة ما ذكرنا، فالشهداء عندنا نوعان:\rأحدهما: شهيد يغسل ويصلى عليه وهو الذي مات حتف أنفه موتا يوجب له الشهادة أو جرح في قتال الكفرة أو أهل البغي ومات في غير المعركة.\rوالثاني: شهيد مقتول في المعركة فقد أجمعوا على أنه لا يغسل واختلفوا في الصلاة عليه: فقال الشافعي: لا يصلى عليه وقال أبو حنيفة بالصلاة عليه.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [122, 123]}, "540.106": {"x": [[123, "في الأرزاق وتقديرها"], [124, "زعمت القدرية أن الله عزوجل لم يقسم الأرزاق إلّا على الوجه الذي حكم به من استحقاق المواريث وما فرض من سهام الصدقات لأهلها وما فرض من الغنائم لذوي القربى ومن ذكر معهم. وزعموا أن الإنسان قد يفوته ما رزقه الله عزوجل وأنه قد يأكل رزق غيره إذا غصب شيئا وأكله. وأجازوا أن يزيد الزرق بالطلب وينقص بالتواني. وقال أهل الحق أن كل من أكل شيئا أو شرب فإنما تناول رزق نفسه حلالا كان أو حراما ولا يأكل أحد رزق غيره. ويجب على القدرية في قود\r\rأصلها أن يقولوا، فيمن غصب جارية فأولدها بالحرام ولدا وسقى ذلك الولد ألبانا مغصوبة حتى نشأ، ثم أطعمه بعد ذلك من الحرام إلى أن بلغ وصار لصّا فلم يأكل ولم يشرب طول عمره إلّا من الحرام ثم مات على ذلك، إن الله ما رزقه شيئا. وكذلك الدابة من نتاج مغصوب إذا لم يأكل من غير الحرام لم يكن الله رازقا لها عندهم. وهذا خلاف قول الله عزوجل: (وَما مِنْ دَابَّةٍ فِي الْأَرْضِ إِلَّا عَلَى اللهِ رِزْقُها) (1).\rالمسألة التاسعة من هذا الأصل\r"]], "pg": [123, 124]}, "540.107": {"x": [[124, "في نفوذ مشيئة الله تعالى في مراداته\rأجمع أصحابنا على نفوذ مشيئة الله تعالى في مراداته على حسب علمه بها."], [125, "فما علم منه حدوثه أراد حدوثه خيرا كان أو شرا. وما علم أنه لا يكون أراد أن لا يكون. وكل ما أراد كونه فهو كائن في الوقت الذي أراد حدوثه فيه على الوجه الذي أراد كونه عليه. وكل ما لم يرد كونه فلا يكون سواء أمر به أو لم يأمر به [وهذا قولهم في الجملة. واختلفوا في التفصيل فمنهم من قال أقول في الجملة إنّ الله تعالى أراد حدوث كل حوادث خيرها وشرها ولا أقول في التفصيل إنّه أراد الكفر والمعاصي الكائنة وإن كانت من جملة الحوادث التي قلنا في الجملة إنّه أراد كونها. كما نقول في الجملة عند الدعاء يا خالق الأجسام ويا رازق البهائم والأنعام كلها. ولا نقول يا رازق الخنافس والجعلان (2) وإن كانت هذه الأشياء من جملة ما أطلقنا في الجملة بأنه خالقها ورازقها. كذلك القول في المرادات جملة وتفصيلا على هذا القياس. وهذا قول شيخنا أبي محمد عبد الله بن سعيد وكثير من أصحابنا. ومنهم من أطلق إرادة الله سبحانه في مراداته جملا وتفصيلا ولكنه قيد الإرادة في التفصيل فقال في الجملة إنّ الله تعالى قد أراد حدوث كل ما علم حدوثه من خير وشر. وقال في التفصيل إنّه أراد حدوث الكفر من الكافر بأن يكون كسبا له قبيحا منه. ولم يقل أراد الكفر والمعصية على الإطلاق من غير تقييد له،\r__________________\r(1) سورة هود آية 6.\r(2) دويبة."], [126, "على الوجه الذي ذكرناه. وهذه طريقة شيخنا أبي الحسن رحمه الله، ومنهم من قال: إذا عبرنا عن المعاصي والكفر بأنها حوادث قلنا إنّ الله تعالى أراد حدوثها ولم نقل أراد الكفر والعصيان وإن قلنا أراد حدوث هذا الحادث الذي هو كفر أو معصية. كما أن المخلوقات كلها حجج الله سبحانه ودلائله والليل منها ونقول فيها بلفظ الليل إنّها ليلة مظلمة ولا نقول إنّها حجة مظلمة ولا نقول في الخشبة المنكسرة إنّها حجة منكسرة وهذا القول اختيارنا]. واختلفت القدرية في هذه المسألة فزعم النظام والكعبي أن الله تعالى ليست له إرادة على الحقيقة. وإذا قيل إنّه أراد شيئا من فعله فمعناه أنه فعله وإذا قيل إنّه أراد شيئا من فعل غيره فمعناه أنه أمر به. وزعم البصريون منهم أنه مريد بإرادة حادثة لا في محمل، وقالوا قد يريد ما لا يكون وقد يكره الشيء فيكون [وزعموا أن المعاصي كلها على كراهة منه] وإنه قد شاء هداية كل الناس ولم يشأ ضلال أحد. وقد أكذبهم الله عزوجل في ذلك بقوله: (وَلَوْ شِئْنا لَآتَيْنا كُلَّ نَفْسٍ هُداها وَلكِنْ حَقَّ الْقَوْلُ مِنِّي لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ) (1) [فأخبر أنه ما شاء هداية الكل ولو شاء لآتى كل نفس هداها]. فإن قالوا: إنّ الهدى المذكور في هذه الآية بمعنى الرجوع إلى الدنيا لأنه معطوف على قوله: (وَلَوْ تَرى إِذِ الْمُجْرِمُونَ ناكِسُوا رُؤُسِهِمْ عِنْدَ رَبِّهِمْ رَبَّنا أَبْصَرْنا وَسَمِعْنا فَارْجِعْنا نَعْمَلْ صالِحاً إِنَّا مُوقِنُونَ،) (2)، ثم قال: (وَلَوْ شِئْنا لَآتَيْنا كُلَّ نَفْسٍ هُداها)، يعني ما سألت من الرجعة إلى الدنيا .."], [127, "قيل لهم إنّ رجوعهم إلى الدنيا لا يكون هدى لهم لإمكان وقوع الضلالة منهم بعد ذلك ألا تراه قال: (وَلَوْ رُدُّوا لَعادُوا لِما نُهُوا عَنْهُ) (3)، فدل هذا على أنّ الهدى المذكور في الآية هداية القلوب وإنه لم يردها من جميع المكلّفين [وإنما أرادها من بعضهم]. ويدل عليه قوله تعالى: (لِمَنْ شاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ وَما تَشاؤُنَ إِلَّا أَنْ يَشاءَ اللهُ) (4). وفي هذا دليل على أن من لم يشأ الاستقامة فإن الله ما شاء منه أن يشاء الاستقامة. ولأن القدرية البصرية وافقونا على أن الله عزوجل لو أراد من فعل نفسه\r__________________\r(1) سورة السجدة آية 13. (2) سورة السجدة آية 12. (3) سورة الأنعام آية 28. (4) سورة التكوير آية 28 و 29.\r\rشيئا فلم يقع لحقه سهو أو ضعف. كذلك إذا أراد من غيره ما لا يقع لحقه الضعف والنقص كما أنه لو وقع من فعله شيء بخلاف خبره لحقه الكذب كذلك لو وقع من غيره ما هو خلاف خبره لحقه الكذب. والأمر على عكس هذا لأنه يجوز أن يقع من غيره ما لم يأمر به كما يقع منه ما لم يأمر به [قالوا: لا يلحقه النقص بأن يقع من غيره خلاف مراده لأنه قادر على إلجائه إلى مراده، قيل: إنّ الله تعالى وإن ألجأ إلى فعل ما أراد منه فلا يجب تمام مراده على أصولكم، لأنكم زعمتم أنه أراد منه فعل الإيمان والطاعة اختيارا على وجه يستحق به الثواب، وإذا ألجأ إليه لم يستحق به ثوابا ولا يتم مراده منه. على أن هذا الإلجاء لا يخلو من وجوه أما أن يكون بخلق الإيمان والطاعة فيهم فليس هذا قولكم. أو يكون بسلب قدرة الكفر والمعصية عنهم وفيه سلب قدرة الإيمان والطاعة عندكم على أصلكم في أن القدرة تصلح للضدين. أو بأن يلجئهم بعذاب يخوّفهم به فلا يخلو حينئذ من أن يعلموا أن ذلك العذاب من قبل الله أو يشكوا فيه فإن عرفوا ذلك فقد عرفوا الله ولا يجوز إلجاء من عرفه إلى معرفته. وإن شكوا في ذلك لم ينكروا وقوع المخالفة منهم."], [128, "فلا يكون الإله قادرا على إتمام مراده منهم على أصول القدرية بحال. وإذا بطل ذلك صح أن إرادته نافذة في كل ما يشاء].\rالمسألة العاشرة من هذا الأصل\r"]], "pg": [124, 128]}, "540.108": {"x": [[128, "في جواز تخلية العباد عن التكليف\rقال أصحابنا: كل ما علم الله وجوبه أو تحريمه فالشرع أوجب ذلك فيه. ولو لم يرد الشرع بالخطاب لم يكن شيئا واجبا ولا محظورا وكان جائزا من الله عزوجل أن لا يكلف عباده شيئا. وزعمت البراهمة والقدرية أنه لم يكن جائزا تخلية العباد عن التكليف وقالوا: لو فعل ذلك لكان قد أغراهم بالمعاصي. وهذا كلام لا معنى تحته لأن من علق الحظر والإباحة على الشرع لم يسلم شيئا قبل الشرع معصية وإذا جاز من الله تعالى خلق العصاة ولم يكن ذلك إغراء بالمعصية جاز ترك التكليف ولم يكن ذلك إغراء بالمعصية.\r\rالمسألة الحادية عشرة من هذا الأصل\r"]], "pg": [128, 128]}, "540.109": {"x": [[128, "في جواز الزيادة والنقصان في الشرع\rقال أصحابنا: كل ما ورد به الشرع من صلاة وزكاة وصوم وحج وغير ذلك فقد كان جائزا ورود الشرع بالزيادة فيه وبالنقصان منه. وكذلك لو أباح الشرع ما حرمه وحرم ما أباحه كان جائزا [وإنما خص الله تعالى الشريعة بما استقرت عليه لأنه أراد ذلك ولا مدخل في تقدير شيء منه للعقل]. وزعم المدعون للأصلح من القدرية أنّ ما أوجبه الشرع لم يكن جائزا سقوطه وما أسقطه لم يكن جائزا وجوبه ولا الزيادة فيه ولا النقصان منه. وأسرّت هذه الطائفة إبطال فائدة مجيء الرسل وإن لم يصرحوا به خوفا من الشناعة عند الإشاعة. ثم كيف وجه دلالة العقل على عدد الركعات وعلى السعي بين الصفا والمروة وتحميل العاقلة (1) الدية دون القاتل إلّا أن يراد دلالة العقل على جواز ورود الشرع بذلك فلا ننكره.\rالمسألة الثانية عشرة\r"]], "pg": [128, 128]}, "540.110": {"x": [[128, "في بقاء حكمة الله عزوجل لو لم يخلق الخلق أو لم يخلق غير الكفرة"], [129, "وقال أصحابنا: إنّ الله حكيم في خلق كل خلق. ولو لم يخلق الخلق لم يخرج عن الحكمة ولو خلق أضعاف ما خلق جاز. ولو خلق الكفرة دون المؤمنين أو خلق المؤمنين دون الكفرة جاز. ولو خلق الجمادات دون الأحياء والأحياء دون الجمادات جاز [وكانت كل هذه الوجوه منه صوابا وعدلا وحكمة. خلاف قول من أوجب عليه الفعل من القدرية ليعبدوه ويشكروه وأوجب عليه خلق الأحياء والجمادات معا. وأوجب عليه أن يكون أول خلقه حيا يصح منه الاعتبار كما ذهبت إليه الكرّامية. وإذا جاز كون الخلق مواتا وأمواتا بين النفختين في الصور جاز كونهم كذلك في ابتداء الخلق على الدوام]. وزعم أكثر القدرية أنه كان واجبا عليه خلق الأحياء والجمادات والمؤمنين والكفرة. وأوجب بعض الكرّامية أن يكون\r__________________\r(1) عاقلة الرجل: عصبته وهم القرابة من قبل الأب الذين يعطون دية من قتله خطأ.\r\rأول خلق خلقه الله حيا. وقلنا إذا جاز أن يكون الخلق كله أمواتا بين النفختين في الصور جاز أن يكونوا كذلك في ابتداء الخلق على الدوام.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [128, 129]}, "540.111": {"x": [[129, "في جواز إماتة من علم الله منه الإيمان لو لم يمته"], [130, "أجاز أصحابنا من الله تعالى إماتة من يعلم أنه لو أبقاه لآمن أو ازداد طاعته. وأوجب الكرّامية وطائفة من القدرية إبقاءه. وهذا يوجب عليهم خروجه عن الحكمة بإبقاء الكفرة إلى حين كفرهم. لأنه لو أماتهم صغارا قبل كمال العقل لم يكفروا ولم يستحقوا العقاب. وقلنا لمن يدعي الأصلح من القدرية أخبرنا عن ثلاثة أطفال خلقوا في بطن واحد مات واحد منهم طفلا وبلغ الآخران فكفر أحدهما وآمن الآخر ما حكم هؤلاء في الآخرة؟ فمن قوله: الذي يكفر يكون مخلدا في النار والآخران في الجنة غير أن منزلة من آمن منهما أرفع من منزلة الذي مات طفلا. قيل: فلو طلب من مات طفلا من ربه مثل منزلة أخيه الذي آمن بما ذا يجيبه؟ فإن قال جوابه: إن أخاك نال رفعة المنزلة بعمله ولا عمل لك، قيل: فإنه يقول له: هلا أبقيتني حتى كنت أعمل مثل عمله فما جوابه؟ فإن قال: كانت إماتتك طفلا أصلح لك لأني لو أبقيتك لكفرت قلنا إن كان هذا عذرا صحيحا فإنّ الذي كفر بعد بلوغه منهم يقول له: يا رب إن كنت أمتّ أخي طفلا، لأنك علمت أنك لو أبقيته كفر، فهلا أمتّني طفلا لعلمك بكفري بعد البلوغ. ووجب بهذا على أصل صاحب الأصلح انقطاع ربه عن جواب هذا السائل. تعالى الله عن ذلك علوا كبيرا.\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [129, 130]}, "540.112": {"x": [[130, "في جواز الاقتصار على خلق الجمادات\rأجاز ذلك أصحابنا وأباه جمهور القدرية غير الصالحي منهم وقالوا: لا يجوز أن يخلق الله جسما يعتبر به راء. وسألناهم عن الأجزاء الكامنة في بطون الأحجار. فزعموا أن بعض خلق الله تعالى يراها. وفي هذا بطلان قولهم إنّ\r\rالأجسام التي لا ينفذ فيها الشعاع مانعة من رؤية ما وراءها.\rالمسألة الخامسة عشرة\r"]], "pg": [130, 130]}, "540.113": {"x": [[130, "في جواز التخصيص بالنعم"], [131, "أجاز أصحابنا تخصيص بعض العباد بالنعم سواء كانت دينية أو دنيوية في الدنيا والآخرة. وقالت القدرية: قد سوى الله عزوجل بين العقلاء في النعم الدينية ولم يخص الأنبياء والملائكة بشيء من التوفيق والعصمة ولا بشيء من نعم الدين دون سائر المكلفين. وفي هذا بطلان فائدة دعاء الصالحين أن يوفّقهم الله لما وفّق له الأنبياء. «ولا ييأس من روح الله إلّا القوم الكافرون».\r\rالأصل السابع\r"]], "pg": [130, 131]}, "540.114": {"x": [[131, "من أصول هذا الكتاب في معرفة\rالأنبياء عليهم السلام\rوهذا الأصل خمس عشرة مسألة هذه ترجمتها:\rمسألة في معنى النبوة والرسالة.\rمسألة في جواز التكليف وبعثة الرسل.\rمسألة في معرفة الرسول [بأنه رسول] برسالته.\rمسألة في عدد الأنبياء [والرسل].\rمسألة في أول الرسل وآخرهم.\rمسألة في نبوة موسى عليه السلام.\rمسألة في نبوة عيسى عليه السلام.\rمسألة في نبوة محمد صلىلله عليه وسلم.\rمسألة في كونه خاتم الرسل.\rمسألة في جواز بعثة الرسول إلى قوم مخصوصين.\rمسألة في تفضيل بعض الرسل على بعض.\rمسألة في تفضيل نبينا على سائرهم.\rمسألة في فضل الأنبياء على الملائكة.\rمسألة في فضلهم على الأولياء.\rمسألة في عصمة الأنبياء من الذنوب.\rفهذه مسائل هذا الأصل.\rونذكر في كل واحدة منها مقتضاها إن شاء الله تعالى.\r\rالمسألة الأولى من هذا الأصل\r"]], "pg": [131, 131]}, "540.115": {"x": [[131, "في معنى النبوة والرسالة\rالنبي في اللغة مهموز وغير مهموز. فالمهموز مأخوذ من النبأ الذي هو الخبر. وغير المهموز يحتمل وجهين:\rأحدهما: التخفيف بإسقاط همزته."], [132, "والثاني: أن يكون من النبوة التي هي الرفعة. وهي ما ارتفع من الأرض. وكذلك النباوة ما ارتفع من الأرض. ويقال: نبا الشيء إذا ارتفع. فالنبي على هذا هو الرفيع المنزلة عند الله تعالى. والرسول هو الذي يتتابع عليه الوحي، من رسل اللبن إذا تتابع درّه. وكل رسول الله عزوجل نبي وليس كل نبي رسولا له. والفرق بينهما أن النبي من أتاه الوحي من الله عزوجل ونزل عليه الملك بالوحي. والرسول من يأتي بشرع على الابتداء أو بنسخ بعض أحكام شريعة قبله. وزعمت الكرّامية أن الرسالة والنبوة معنيان قائمان بالرسول والنبيّ غير إرسال الله إياه وغير عصمته وغير معجزته. وفرقوا بين الرسول والمرسل بأن قالوا: إنّ الرسول من فيه ذلك لمعنى ومن كان ذلك فيه وجب على الله إرساله. والمرسل هو الذي أرسله مرسله. وإذا سئلوا عن المعني الذي لأجله يكون رسولا لم يصفوه بأكثر من أنه معنى قائم بالرسول غير إرسال الله إياه وغير عصمته ومعجزته. ولا وجه للكلام معهم في شيء هم لا يعرفون معناه.\rالمسألة الثانية من هذا الأصل\r"]], "pg": [131, 132]}, "540.116": {"x": [[132, "في جواز بعثة الرسل وتكليف العباد\rالخلاف في هذا مع البراهمة الذين جحدوا الرسل وأثبتوا التكليف من جهة العقول والخواطر وأبطلوا الفرائض السمعية وزعموا أن قلب كل عاقل لا يخلو من خاطرين أحدهما: من قبل الله ينبهه (1) على ما يوجبه عقله. والآخر من جهة الشيطان يدعوه إلى معصية الخاطر الأول، وقالوا: إنما مكّن الله الشيطان من إلقاء\r__________________\r(1) [يدعو به الى النظر والاستدلال ومعرفة الإله وتوحيده]."], [133, "الخاطر الداعي إلى الشر في قلب العاقل ليعتدل به دواعيه ويصح منه اختيار أحد الخاطرين، ولو أفرده بالخاطر الأول لكان ملجأ إلى ما يدعوه إليه لأنه ليس في مقابلته ما يدعوه إلى ضده ولا تكليف مع الإلجاء. وزعموا أيضا أن الرسل قد وردوا بإباحة ما حظره العقل من ذبح البهائم وإيلام الحيوان بلا ذنب وتحميل العاقلة الدية وكذّبوهم لأجل ذلك. وساعدت القدرية البراهمة في التكليف من جهة الخواطر وخالفوهم في إجازة بعثة الرسل. غير أن النظام منهم زعم أن الخاطرين كلاهما من قبل الله تعالى، يدعو بأحدهما إلى المعرفة والنظر والاستدلال ليفعل المكلف ذلك. ويدعو بالآخر إلى المعصية لا ليفعل ولكن لاعتدال الدواعي. وزعم الباقون منهم أن الخاطرين أحدهما من قبل الله عزوجل والآخر من قبل الشيطان، سوى من قال منهم إنّ المعارف ضرورية كالجاحظ وثمامة والصالحي فإن هؤلاء زعموا أن لا تكليف إلا على من عرف الله تعالى ومن لم يعرفه لم يكن مكلفا وإنما كان مخلوقا للسخرة والاعتبار به. وهذا القول يوجب على صاحبه أن يكون العوام من عبدة الأصنام والزنادقة والدهرية ناجين من عذاب الآخرة. ومن قال بالتكليف من جهة خاطرين أحدهما من جهة الله تعالى والآخر من جهة الشيطان، يلزمه أن يكون تكليف الشيطان بخاطرين أحدهما من الله والآخر من شيطان آخر ثم كذلك القول في شيطان آخر والثاني والثالث حتى يتسلسل ذلك لا إلى نهاية. ومن قال بقول النظام فقد صرح بأن الله يدعو إلى شيء لا ليفعل ولو جاز ذلك لجاز أن يأمر بما لا يجوز فعله وينهى عما يجوز فعله. فإن قالت البراهمة ليس بحكيم من أرسل إلى من يعلم أنه يكذّب رسوله. قيل إذا جاز أن يخلق الله من يعلم أنه يكذبه ويجحده ويكفر به جاز أيضا أن يرسل إلى من يعلم منه تكذيب رسوله. وكل ما استدلوا به على إبطال التكليف السمعي ينتقض عليهم بما أجازوه من التكليف العقلي.\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [132, 133]}, "540.117": {"x": [[133, "في معرفة الرسول بأنه رسول"], [134, "لا بد للرسول من حجة وبرهان يعلم به أن الله تعالى قد أرسله. ويصح\r\rعلمه بذلك من وجوه: منها أن يخاطبه الله عزوجل بلا واسطة ويخلق في قلبه علما ضروريا يعلم به أن الذي يخاطبه ربه لا غيره، كما خاطب آدم حين نفخ فيه الروح وأعلمه بالضرورة معرفة ربه وأنه هو الذي خلقه وخاطبه. وعلمه في الحال الأسماء كلها علما ضروريا غير مكتسب. ومنها أن يخاطبه بلا واسطة ويظهر في تلك الحال دلالة تدل على أن المخاطب هو الله تعالى من الأدلة الناقضة للعادة كما فعله بموسى عليه السلام عند إرساله إياه إلى فرعون فإنه خاطبه بلا واسطة وأظهر له معجزات، استدل بها على أن الله تعالى هو الذي خاطبه، كحل العقدة من لسانه واليد البيضاء وقلب العصا حية ونحو ذلك. ومنها أن يرسل الله ملكا إلى الرسول ويأمره بالرسالة ويظهر عند إرسال الملك معجزة يعلم بها أن الذي أتاه ملك وليس بشيطان. ومنها أن يصح نبوة بعض الأنبياء بأحد هذه الطرق ثم يقول ذلك النبي لبعض أمته إنّ الله قد أرسلك إلى قوم بأعيانهم فيعلم أنه رسول الله بقول رسول آخر قد تلقى رسالته على لسانه. ومثاله رسالة لوط إلى قوم على لسان إبراهيم عليهما السلام وكذلك كانت قصة الحواريين مع عيسى عليه السلام [فالمعرفة الأولى ضرورية وثانيتها استدلال].\rالمسألة الرابعة من هذا الأصل\r"]], "pg": [133, 134]}, "540.118": {"x": [[134, "في بيان عدد الأنبياء والرسل عليهم السلام"], [135, "أجمع أصحاب التواريخ من المسلمين على أن الأنبياء عليهم السلام مائة ألف وأربعة وعشرون ألفا كما وردت به الأخبار الصحيحة. أولهم أبونا آدم عليه السلام وآخرهم نبينا محمد صلىلله عليه وسلم. وأجمعوا على أن الرسل منهم ثلاثمائة وثلاثة عشر كعدد الذين جاوزوا مع طالوت النهر ولم يشربوا منه وثبتوا معه في قتال جالوت وكذلك كان عدد أصحاب بدر مع النبي صلىلله عليه وسلم يوم بدر. وفي هذه الجملة خلاف من وجوه: أحدها: مع قوم أنكروا جميع الرسل كالبراهمة. والثاني: مع قوم منهم أقروا بنبوة آدم وإبراهيم عليهما السلام وأنكروا نبوة غيرهما. والثالث: مع صابئة واسط أقروا بنبوة آدم وشيث وزعموا أن معهم كتاب شيث وأنكروا من بعدهما. والرابع: مع\r\rاليهود فإنهم أقروا بتسعة عشر نبيا بعد موسى وبمن قبله من الأنبياء وأنكروا عيسى ومحمدا عليهما السلام. والخامس: مع السامرة الذين أقروا بنبوة موسى وهارون ويوشع ومن قبلهم من الأنبياء وأنكروا من كان منهم بعد ذلك. والسادس: مع النصارى في إنكارها نبوة نبينا صلىلله عليه وسلم. والسابع: مع صابئة حران في دعواها نبوة قوم من الفلاسفة. والثامن: مع الخرمدينية الذين زعموا أن الرسل [تترى] غير منقطعة وإنما يدورون على الأدوار. والتاسع: مع من ادعى من غلاة الروافض نبوة علي رضي الله عنه. والعاشر: مع من ادعى منهم نبوة كل إمام في وقته .. [والحادي عشر: مع اليزيدية من الخوارج حيث قالوا إنّ الله يبعث نبيا ينسخ شريعة محمد صلىلله عليه وسلم ويكون صابئا كما يذكر وليس من جملة هؤلاء الصابئين. والكلمة في هذا الباب قد استقصيناها في كتاب دلائل النبوة]. وإذا صح لنا أن الرسل ثلاثمائة وثلاثة عشر قلنا إنّ خمسة منهم من أولي العزم المذكورين في القرآن وهم نوح وإبراهيم وموسى وعيسى ومحمد عليهم السلام. وخمسة منهم من العرب وهم هود وصالح وإسماعيل وشعيب ومحمد عليهم السلام.\rالمسألة الخامسة من هذا الأصل\r"]], "pg": [134, 135]}, "540.119": {"x": [[135, "في ترتيب الرسل"], [136, "وأولهم (1) آدم عليه السلام وآخرهم عند المسلمين محمد صلىلله عليه وسلم. وزعمت صابئة واسط أن آخرهم شيث ولكنهم يظهرون للمسلمين الإيمان بعيسى عليه السلام ليعدّوهم في عدد النصارى. وقد زعمت المجوس أن أول البشر وأول الرسل كيكومرت (2) الملقب بكل شاه أي ملك الطين. وزعموا أن الشيطان قتله فخرج من صلبه نطفة غاصت في الأرض ونبتت منها ريباستان فصارتا ذكرا وأنثى وازدوجا فجميع الناس من نسلهما. فيا عجبا من قوم أنكروا خلق أنثى من ضلع رجل وأجازوا خلقها من ريباسة نابتة. فإن قال قائل إذا قلتم بأن محمدا آخر\r__________________\r(1) [أجمع المسلمون وأهل الكتاب على أن أول من أرسل من الناس آدم عليه السلام].\r(2) [كيومرس].\r\rالرسل فما تقولون في نزول عيسى عليه السلام على أي وجه يكون. قلنا إنّه ينزل على نصرة دين الإسلام فيقتل الدجال والخنزير ويريق الخمر ويحيي ما أحياه القرآن ويميت ما أماته القرآن.\rالمسألة السادسة من هذا الأصل\r"]], "pg": [135, 136]}, "540.120": {"x": [[136, "في صحة نبوة موسى عليه السلام\rأجمع المسلمون وأهل الكتاب على صحة نبوة موسى وهارون ويوشع بن نون. وكل من أقر بنبوة بعض الأنبياء [فإنه] أقر بنبوة موسى عليه السلام إلّا فريقين أحدهما: البراهمة الذين لم يثبتوا نبيا بعد إبراهيم عليه السلام. والفريق الثاني: المانوية فإنهم أقروا بنبوة عيسى وأنكروا نبوة موسى من الله تعالى وزعموا أن الشياطين أرسلوا موسى إلى الناس. وكل دليل يستدل به اليهود على نبوة موسى يلزمهم به صحة نبوة عيسى ومحمد عليهما السلام. فإن قالوا أنتم أقررتم معنا بنبوته. قيل: إنما أقررنا بنبوة موسى الذي أقر بنبوة محمد بعده فإن لم يكن موساكم مقرا به فليس هو الذي أقررنا به. ولا وجه للكلام مع المانوية في نبوة موسى مع الخلاف بيننا وبينهم في حدوث الأجسام وتوحيد الصانع.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [136, 136]}, "540.121": {"x": [[136, "في نبوة عيسى عليه السلام"], [137, "الخلاف في نبوة عيسى عليه السلام من وجوه: أحدها مع المنكرين للنبوات كلها من البراهمة. وقد صححنا جواز صحة النبوة في الجملة قبل هذا.\rوالوجه الثاني: مع اليهود المنكرين لنبوته مع إثباتهم نبوة الأنبياء قبله ووجه الدلالة عليهم في نبوة عيسى عليه السلام تواتر الأخبار في وجود أعلامه الناقضة للعادة كإحياء الموتى وإبراء الأكمه والأبرص. وتكذيب اليهود لذلك كتكذيب الدهرية (1) [الصواب النصارى] والبراهمة لما تواترت به الأخبار في معجزات موسى عليه السلام.\r__________________\r(1) [الصواب: النصارى].\r\rالوجه الثالث من الخلاف في عيسى عليه السلام مع النصارى الذين رفعوا عيسى عن درجة النبوة فادعوا أنه إله أو ابن الإله. ودليل فساد قولهم ما قدمناه من الدلائل على حدوث الأجسام كلها وما ذكرناه من الأدلة على أن الإله لا يحل الأجساد ولا ينتقل في الأماكن. وصح بذلك أن عيسى عليه السلام كان عبدا ولم يكن ربا.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [136, 137]}, "540.122": {"x": [[137, "في نبوة نبينا محمد صلىلله عليه وسلم"], [138, "والخلاف فيه مع البراهمة كالخلاف معهم في سائر الأنبياء. والخلاف فيه مع اليهود كالخلاف معهم في نبوة عيسى عليه السلام. وقد خالفت النصارى أيضا في نبوته. ودليل صحتها تواتر الأخبار عن معجزاته الناقضة للعادة كالقرآن الذي عجزت العرب عن معارضته بمثله وقد تحدّاهم به مع حرصهم على تكذيبه وكذلك سائر معجزاته مثل انشقاق القمر وتسبيح الحصى في يده ونبوع الماء من بين أصابعه وإشباع الخلق الكثير من الطعام اليسير وإقبال الشجرة إليه ورجوعها بأمره إلى مغرسها ونحو ذلك من الأمور الناقضة للعادة الدالة على صدق من ظهرت عليه في دعواه. ومنكر وجود ذلك كله من اليهود يعارض بإنكار من أنكر أعلام موسى عليه السلام. ومن ادعى منهم غلبة السحر والمحرمة والحيلة بمنزلة من ادعى السحر والحيلة على موسى عليه السلام. والكلام في بيان وجوه الدلالة من المعجزات يأتي في مسائل الأصل الثامن من أصول هذا الكتاب إن شاء الله تعالى.\rالمسألة التاسعة من هذا الأصل\r"]], "pg": [137, 138]}, "540.123": {"x": [[138, "في كون نبينا خاتم الأنبياء والرسل عليهم السلام.\rكل من أقر بنبوة نبينا محمد صلىلله عليه وسلم أقر بأنه خاتم الأنبياء والرسل وأقر بتأبيد شريعته ومنع من نسخها وقال إنّ عيسى عليه السلام إذا نزل من السماء ينزل بنصرة\r\rشريعة الإسلام ويحيي ما أحياه القرآن ويميت ما أماته القرآن خلاف فرقة من الخوارج تعرف باليزيدية المنتسبة إلى يزيد بن أنيسة فإنهم زعموا أن الله عزوجل يبعث في آخر الزمان نبينا من العجم وينزل عليه كتابا من السماء ويكون دينه دين الصابئة المذكورة في القرآن لا دين الصابئة الذين هم بواسط أو حرّان وينسخ ذلك الشرع شرع القرآن. وهؤلاء يسألون عن حجة القرآن فإن أنكروها أنكروا نبوة محمد صلىلله عليه وسلم ونوظروا فيها لا في تأبيد شريعته. وإن أقروا بالقرآن ففيه أن محمدا صلىلله عليه وسلم خاتم النبيّين. وقد تواترت الأخبار عنه بقوله: «لا نبي بعدي (1)» ومن رد حجة القرآن والسنة فهو الكافر."], [139, "المسألة العاشرة من هذا الأصل\r"]], "pg": [138, 139]}, "540.124": {"x": [[139, "في التخصيص والتعميم في الرسالة\rيجوز عندنا أن يرسل الله عزوجل إلى قوم دون قوم ويجوز أن يرسل رسولين إلى أمة واحدة. ويجوز أن يرسل أحدهما إلى قوم والآخر إلى قوم آخرين ويجوز إرسال واحد إلى الكافة. وإذا أرسل رسولين إلى أمة واحدة وجب اتفاق الرسولين في أحكام الشريعة. وإن أرسلهما إلى أمتين جاز أن يكون شرع أحدهما في الحلال والحرام غير شرع الآخر ولم يجوّز اختلافهما في موجبات العقول ودلائلها. وقد كان آدم عليه السلام مرسلا إلى جميع ولده الذين أدركوه. وكان إدريس مرسلا إلى جميع من كان من الناس في عصره. وكذلك نوح عليه السلام كان مرسلا إلى جميع أهل عصره وإلى جميع الناس بعد الطوفان إلى أوان النبي الذي كان بعده. وكذلك رسالة الخليل إبراهيم عليه السلام كانت إلى الكافة. ونبينا صلىلله عليه وسلم إلى الكافة في عصره ومن بعده من الجن والإنس إلى القيامة. خلاف قول من زعم من العيسوية أنه كان مبعوثا إلى العرب دون بني إسرائيل. وقلنا لهم قد أقررتم بنبوته والنبي معصوم عن قتال من لا يكون مبعوثا إليه وقد قاتل اليهود وهم بنو إسرائيل ووضع عليهم الجزية واسترق قوما منهم فدل ذلك على أنه كان مبعوثا إليهم كما كان مبعوثا إلى العرب والعجم.\r__________________\r(1) أخرجه الحاكم في المستدرك 2/ 577.\r\rالمسألة الحادية عشرة من هذا الأصل\r"]], "pg": [139, 139]}, "540.125": {"x": [[139, "في جواز تفضيل الرسل بعضهم على بعض"], [140, "وقد أخبر الله تعالى بتفضيل الرسل بعضهم على بعض درجات. فمنهم من خصّه بالإرسال إلى الكافة فكان أفضل ممن أرسل منهم إلى أمة مخصوصة. ومنهم من كلّمه الله عزوجل بلا واسطة فكان أفضل من الذي خاطبه بواسطة. ومنهم من خصّه بالابتداء. ومنهم من خصّه بالخاتمة. وكما تفاضلوا في الدنيا في مراتب النبوة كذلك يكون تفاضلهم في درجات الثواب في الجنة. وزعم قوم من غلاة الروافض أن الأنبياء والأئمة متساوون في الدرجات ولكل منهم في دوره من الفضل ما للآخر في دوره. وخلاف هؤلاء غير معدود في أحكام الشريعة لإلحادهم في صفات الأئمة.\rالمسألة الثانية عشرة من هذا الأصل\r"]], "pg": [139, 140]}, "540.126": {"x": [[140, "في تفضيل نبينا على سائر الأنبياء\rزعم قوم من منتحلي الإسلام أن نبينا صلىلله عليه وسلم لم يكن أفضل من إبراهيم ولا من نوح ولا من آدم عليه السلام لأن هؤلاء الثلاثة آباؤه وامتنعوا من تفضيل الابن على الأب وفضّلوه على موسى وعيسى وكل نبي لم يكن أبا له. وقياسهم يقتضي أن لا يكون أفضل من إدريس ولا من إسماعيل لأنهما أبواه. وزعم ضرار أنه لم يكن بعض الأنبياء أفضل من بعض. واستدل من رأى تفضيله على سائر الأنبياء عليهم السلام، بقوله: «أنا سيد ولد آدم ولا فخر، آدم ومن دونه تحت لوائي (1)». وبقوله: «لو كان موسى حيا ما وسعه إلا اتباعي». وقالوا إنّ الكرامات التي خص بها الأنبياء قد خص نبينا صلىلله عليه وسلم من أجناسها بما هو أعظم منه. وذلك أن الريح إن سخّرت لسليمان فقد سخر له البراق وهو أفضل من الريح. وإن انفجرت الحجارة\r__________________\r(1) أخرج الترمذي أحاديث عدة بألفاظ مقاربة: مراجعة الأحاديث رقم 3615 و 3148 و 2434.\rوأخرجه البخاري في التاريخ الكبير بلفظ مقارب 4/ 1 / 400 وأخرجه الحاكم في المستدرك رواية عن جابر 2/ 605."], [141, "لموسى بالماء فليس ذلك بأعجب من نبوع الماء من بين أصابع النبي صلىلله عليه وسلم لوضوء جيشه. وليس مشي عيسى على الماء بأعجب من مشي النبي صلىلله عليه وسلم في الهواء عند المعراج. وكذلك كل معجزة لغيره فله من جنسها ما هو أعجب منها. وقد خص بمعجزات سماوية كانشقاق القمر ورجم الشياطين بالنجوم وجعلت شريعته مستنبطة من كتابه. والكلام في استقصاء معجزاته يقتضي كتابا مفردا. وفيما ذكرناه منها تنبيه على ما أردناه من تفضيله.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [140, 141]}, "540.127": {"x": [[141, "في تفضيل الأنبياء على الملائكة\rأجمع أصحاب الحديث على أنّ الأنبياء أفضل من الملائكة إلا الحسن بن الفضل البجلي فإنه فضّل الملائكة عليهم. واختلفت القدرية في هذا الباب: فقال بعضهم إن الأنبياء أفضل من الملائكة الذين عصوا ربّهم كهاروت وماروت وإبليس وجعلوا إبليس من جملة الملائكة. وأما الملائكة الذين لا يعصون الله ما أمرهم ويفعلون ما يؤمرون، فهم أفضل من الأنبياء. وقال أكثرهم: إن الملائكة أفضل من جميع الناس وزعموا أن هاروت وماروت كانا علجين من بابل وأن إبليس كان من الجن. وهؤلاء يقتضي قياسهم أن يكون زبانية النار أفضل من الأنبياء عليهم السلام. وقد استدلوا بقوله تعالى: (لَنْ يَسْتَنْكِفَ الْمَسِيحُ أَنْ يَكُونَ عَبْداً لِلَّهِ وَلَا الْمَلائِكَةُ الْمُقَرَّبُونَ) (1). وهذا لا يقتضي تفضيلهم على عيسى عليه السلام لأن مثل هذا الكلام قد يخبر به عن المتساويين فيقال: إنّ زيدا لا يرضى بكذا ولا عمرو. على أن الآية تقتضي أن لا يكون المسيح أفضل من جميع الملائكة وإن كان أفضل من كل واحد منهم كما لا يكون الواحد أعلم من جميع علماء الأرض وإن جاز أن يكون أعلم من كل واحد منهم.\r__________________\r(1) سورة النساء آية 172.\r\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [141, 141]}, "540.128": {"x": [[141, "في تفضيل الأنبياء على الأولياء"], [142, "زعم قوم من الكرّامية أن في الأولياء من هو أفضل من بعض الأنبياء. وزعم جهّالهم أن زعيمهم ابن كرام كان أفضل من عبد الله بن مسعود ومن كثير من الصحابة. وزعم بعض غلاة الروافض أن الإمام أفضل من النبي. وكان هشام بن الحكم الرافضي يشترط العصمة في الإمام ويجيز الخطأ على النبي صلىلله عليه وسلم. ويزعم أنه عصى ربه في أخذ الفداء من أسارى بدر غير أن الله تعالى غفر له ذلك. وفي هذا تفضيل منه للإمام على الرسول. وقال أهل الحق إن كل نبي أفضل من جميع الملائكة (فتفضيله (1)) على من دونهم أولى.\rالمسألة الخامسة عشرة من هذا الأصل\r"]], "pg": [141, 142]}, "540.129": {"x": [[142, "في بيان عصمة الأنبياء عليهم السلام\rأجمع أصحابنا على وجوب كون الأنبياء معصومين بعد النبوة عن الذنوب كلها. وأما السهو والخطأ فليسا من الذنوب فلذلك ساغا عليهم. وقد سها نبينا صلىلله عليه وسلم في صلاته حتى سلم عن الركعتين ثم بنى عليهما وسجد سجدتي السهو. وأجازوا عليهم الذنوب قبل النبوة. وتأولوا على ذلك كل ما حكى في القرآن من ذنوبهم. وأجاز ابن كرام في كتابه الذنوب من الأنبياء من غير تفضيل منه. ولأصحابه اليوم في ذلك تفصيل ويقولون يجوز عليهم من الذنوب ما لا يوجب حدا ولا تفسيقا. وفيهم من يجيز الخطأ في التبليغ ويزعم أنه أخطأ عند تبليغ قوله: (وَمَناةَ الثَّالِثَةَ الْأُخْرى) (2)، حتى قال: تلك الغرانيق العلى شفاعتها ترتجى. وقال أصحابنا إنّ ذلك كان من إلقاء الشيطان في خلال قراءة النبي صلىلله عليه وسلم فظنه المشركون من قراءته. واختلفت القدرية فمنهم من قال إنّ ذنوب الأنبياء خطأ من جهة التأويل والاجتهاد ولم يجوز عليهم أن يفعلوا ما علموا أنه ذنب قصدا. وقالوا\r__________________\r(1) وردت في المطبوع تفضيله.\r(2) سورة النجم آية 20."], [143, "في آدم إنّه قيل له لا تأكل من هذه الشجرة فظن الشجرة بعينها وأكل من شجرة أخرى من جنسها وأراد الله جنسها فأخطأ في التأويل وهذا تأويل الجبائي. وقال ابنه أبو هاشم إنّ ذلك كان ذنبا منه. ثم قال أبو هاشم: يجوز عليهم الصغائر التي لا تنفر. وقال النظّام وجعفر بن مبشر إنّ ذنوبهم على السهو والخطأ وهم مأخوذون بما وقع منهم على هذه الجهة وإن كان ذلك موضوعا عن أممهم. وقال أصحابنا لا معنى لدعوى القدرية عصمة الأنبياء ولا يصح لهم على أصولهم أن يقولوا إنّ الله عصمهم عن شيء من الذنوب لأنه قد فعل بهم ما فعله بسائر المكلفين من النكير والعذر (1) كلها عندهم يصلح للطاعة والمعصية. وإنما هم عصموا أنفسهم عن المعاصي وليس لله في اعتصامهم تأثير. وإنما يصح عصمتهم على أصولنا إذا قلنا إنّ الله عزوجل أقدرهم على الطاعة دون المعاصي فصاروا بذلك معصومين عن المعاصي.\r__________________\r(1) [من التمكين و؟؟؟ قدرة].\r\rالأصل الثامن\r"]], "pg": [142, 143]}, "540.130": {"x": [[143, "من أصول هذا الكتاب في المعجزات والكرامات\rوفي هذا الأصل خمس عشرة مسألة. هذه ترجمتها:\rمسألة في بيان معنى المعجزة والكرامة.\rمسألة في بيان أقسام المعجزات.\rمسألة في بيان ما يحتاج إليه النبي من المعجزة.\rمسألة في بيان من يجوز ظهور المعجزة عليه.\rمسألة في الفرق بين معجزات الأنبياء وكرامات الأولياء.\rمسألة فيما يجب فيه قبول قول النبي.\rمسألة في أن المعجزات كلها من الله تعالى دون غيره.\rمسألة في كيفية الاستدلال بالمعجزة على صدق صاحبها.\rمسألة في بيان طرق العلم بمعجزات الأنبياء.\rمسألة في بيان معجزة كل نبي على التفصيل.\rمسألة في بيان معجزات موسى وصحة نبوته.\rمسألة في بيان معجزة عيسى وصحة نبوته.\rمسألة في معجزة نبينا وصحة نبوته.\rمسألة في بيان وجه إعجاز القرآن.\rمسألة في كرامات الأولياء.\rونحن نذكر في كل مسألة منها مقتضاها إن شاء الله تعالى.\r\rالمسألة الأولى من هذا الأصل\r"]], "pg": [143, 143]}, "540.131": {"x": [[143, "في بيان معنى المعجزة والكرامة"], [144, "المعجزة في اللغة مأخوذة من العجز الذي هو نقيض القدرة. والمعجز في الحقيقة فاعل العجز في غيره وهو الله تعالى كما أنه هو المقدر لأنه فاعل القدرة في غيره. وإنما قيل لأعلام الرسل عليهم السلام معجزات لظهور عجز المرسل إليهم عن معارضتهم بأمثالها. وزيدت الهاء فيها فقيل معجزة للمبالغة في الخبر عن عجز المرسل إليهم عن المعارضة فيها كما وقعت المبالغة بالهاء في قولهم: علامة ونسابة وزاوية. وحقيقة المعجزة على طريق المتكلمين: ظهور أمر خلاف العادة في دار التكليف لإظهار صدق ذي نبوة من الأنبياء أو ذي كرامة من الأولياء مع نكول من يتحدى به عن معارضة [مثله]. وإنما قيدنا هذا الحد بدار التكليف لأن ما يفعله الله تعالى يوم القيامة من أعلامها على خلاف العادة فليست بمعجزة لأحد. وإنما شرطنا في الحد خلاف العادة لأن المعتاد من الأفعال يشترك في دعواها الصادق والكاذب. وإنما اشترطنا فيه إظهاره لصدق نبي أو ولي لجواز ظهور ما يخالف العادة على مدعي الإلهية فلا يكون دلالة على صدقه كالذي يظهر على الدجال في آخر الزمان. وصورته كافية في الدلالة على كذبه فلا ضرر في ظهور ما يخالف العادة عليه. وللمعجزة عندنا شروط:\rأحدها: أن تكون من فعل الله عزوجل أو ما يجري مجرى فعله وإن لم يكن في نفسه فعلا.\rوالشرط الثاني: أن يكون ناقضا للعادة فيمن هو معجز له وحجة عليه.\rوالشرط الثالث: أن يتعذر على المتحدّى به فعل مثله في الجنس أو على الوجه الذي وقع التحدية عليه.\rوالشرط الرابع: أن يكون مطابقا لدعوى من ظهرت عليه على وجه التصديق. فأمّا إن شهدت بتكذيبه فهي خارجة من هذا الباب.\r\rوالشرط الخامس: أن لا يتأخر عن دعواه تأخرا يعلم أنه لا يتعلق بها.\rوالشرط السادس: أن يكون ذلك في زمان التكليف كما بيناه قبل هذا.\rالمسألة الثانية من هذا الأصل\r"]], "pg": [143, 144]}, "540.132": {"x": [[144, "في بيان أقسام المعجزات"], [145, "إن المعجزات على الأعداد كثيرة الإمداد غير أنها في الجملة نوعان: أحدهما: وجود فعل غير معتاد مثله. والثاني: تعجيز الفاعل بشيء معتاد عن فعل مثله، كمنع زكريا عن الكلام ثلاث ليال بعد أن كان معتادا له للدلالة على صحة ما بشّر به من الولد. وما كان منها على الوجه الأول فضربان:\rأحدهما: لا يدخل تحت قدرة من هو معجزة له وفيه ولا تحت قدرة غيره من الخلق ولا يقدر عليه غير الله عزوجل وذلك مثل اختراع الأجسام والألوان والحواس وإحياء الموتى وإبراء الأكمه والأبرص ونحو ذلك.\rوالضرب الثاني منه: لا يدخل تحت قدرة من هو معجزة فيه وله، على الوجه الذي أظهره الله تعالى عليه وإن دخل مثل أبعاضه وجنسه تحت قدرة العباد بأن يكتسبوه في أنفسهم ويستحيل منه فعله في غيرهم لقيام الدلالة عندنا على إبطال التولد. وهذا مثل الكلام المنظوم نظم القرآن في فصاحته وبلاغته المفارقة لبلاغات البلغاء وإن كانت جنس العبارات ومفردات الألفاظ وبعض أنواع التركيب منها مقدورا للعباد. وزعم القائلون بالتولد من القدرية أن المعجزة يجب أن لا تدخل تحت قدرة من يتحدى بمثله على الوجه الذي يفعله الله عزوجل [وأجازوا] كونه مقدورا على ذلك الوجه لمن ليس بمعجز له ولا هو متحدى بمثله وإن من لا يتحدى بمثله قد يقدر على فعل مثله في غيره كما يفعله الله عزوجل في ذلك المحل. وهذا باطل عندنا لقيام الدلالة على بطلان التولد. وزعمت القدرية أن العباد قادرون على مثل القرآن في الفصاحة والنظام غير أنهم كانوا عند التحدي به مصروفين عن فعل ذلك. وزعمت القدرية أيضا أنّ قلب المدن والزلازل من فعل\r\rالله عزوجل عند التحدي بها معجز لمن يتحدى بمثله وهو متعذر عليه أو ممنوع منه وإن صح أن يقدر عليه غيره من الخلق كالملائكة، فلا يكون [معجزا] لهم. وهذا من قولهم مبني على التولد وهو عندنا باطل. وليس لأحد من الجن والملائكة قدرة على فعل يفعله في غيره.\rالمسألة الثالثة من هذا الأصل"]], "pg": [144, 145]}, "540.133": {"x": [[146, "في بيان ما يحتاج النبي إليه من المعجزة\rالنبي لا بدّ له من إظهار معجزة تدل على صدقه. فإذا أتى بها وبان لقومه وجه الإعجاز فيها لزمهم تصديقه وطاعته ولم يكن لهم مطالبته بمعجزة أخرى. فإن طالبوه بأخرى فإن شاء الله عزوجل أظهر الأخرى تأكيدا للحجة عليهم وإن شاء عاقبهم على ترك الإيمان بمن قد دلت المعجزة على صدقه. والمعجزة الواحدة كافية في الدلالة على صدقه ومن لم يؤمن به بعدها استحق العقاب.\rالمسألة الرابعة من هذا الأصل\r"]], "pg": [146, 146]}, "540.134": {"x": [[146, "في بيان من يجوز ظهور المعجزة عليه\rكل من كان صادقا في دعوى النبوة فجائز ظهور معجزة تدل على صدقه. وكل كاذب في دعوى النبوة لا يجوز ظهور معجزة التصديق عليه ويجوز معجزة ظهور التكذيب عليه. وذلك بأن يدعي المتنبي الكاذب أن معجزته نطق إصبعه أو نطق شجرة من الأشجار فينطق الله تعالى ما ادعى الكاذب نطقه بتكذيبه أو نطق عليه خلاف دعواه. مثل أن يدعي أن الله تعالى يخرج له من جوف الحجر أسدا يفترس منكر نبوته فيخرج الله تعالى أسدا يفترس ذلك المدعي ويقتله. أو يظهر عليه أمرا ينقض العادة ويقدر بعض خصومه على معارضته بمثلها في حال دعواه فيها فيعلم بذلك إنه كاذب في دعواه الرسالة. هذا كله في دعوى النبوة. فأما من يدعي الربوبية فإن صورته دالة على حدوثه وعلى كذبه في دعواه فلا يضر العباد ظهور ما ينقض العادة عليه، كما روي من قصة الدجال وما يظهر عليه في آخر الزمان من\r\rنواقض العادات. وليس كذلك النبي والمتنبي لأن الصورة لا توجب تمييزا بينهما فلا بد فيها من علامة ناقضة للعادة تكون مع الصادق دون الكاذب ليقع بها التمييز بينهما.\rالمسألة الخامسة من هذا الأصل\r"]], "pg": [146, 146]}, "540.135": {"x": [[146, "في الفرق بين معجزات الأنبياء وكرامات الأولياء\rاعلم إن المعجزات والكرامات متساوية في كونها ناقضة للعادات. غير أنّ الفرق بينهما وجهان:\rأحدهما: تسمية ما يدل على صدق الأنبياء معجزة وتسمية ما يظهر على الأولياء كرامة للتمييز بينهما."], [147, "والوجه الثاني: إن صاحب المعجزة لا يكتم معجزته بل يظهرها ويتحدى بها خصومه ويقول إن لم تصدقوني فعارضوني بمثلها. وصاحب الكرامة يجتهد في كتمانها ولا يدعي فيها. فإن اطلع الله عليها بعض عباده كان ذلك تنبيها، لما أطلعه الله تعالى عليها، على حسن منزلة صاحب الكرامة عنده أو على صدق دعواه فيما يدعيه من الحال.\rوفرق ثالث: وهو إن صاحب المعجزة مأمون التبديل معصوم عن الكفر والمعصية بعد ظهور المعجزة عليه. وصاحب الكرامة لا يؤمن تبدل حاله فإن بلعم ابن باعورا أوتي من هذا الباب ما لم يؤت غيره ثم ختم له بالشقاء. وأنكرت القدرية كرامات الأولياء لأنهم لم يجدوا في أهل بدعتهم ذا كرامة فأنكروا ما حرموه بشؤم بدعتهم وظنوا أنّ إجازة ظهور الكرامة للأولياء يقدح في دلالة المعجزة على النبوة. وقلنا لهم ليست دلالة المعجزة مقصورة على النبوة. وإنما هي دلالة الصدق فتارة تدل على الصدق في النبوة وتارة تدل على الإخلاص والصدق في الحال وعلى أنّه لا رياء فيها. فإن قيل أجيزوا على هذا القياس ظهورها على الفاسق للدلالة على صدقه في بعض ما يصدق فيه. قيل إن أظهر الله له علامة تدل على\r\rصدقه وبراءة ساحته مما يقذف به جاز ذلك وسميناها حينئذ مغوثة (1). فالمعجزات للأنبياء والكرامات للأولياء والمغوثات (2) لسائر العباد.\rالمسألة السادسة من هذا الأصل\r"]], "pg": [146, 147]}, "540.136": {"x": [[147, "في بيان ما يجب فيه قبول قول النبي"], [148, "زعمت الإباضية وكثير من الخوارج أنّ نفس قول النبي صلىلله عليه وسلم أنا نبي ودعوته إلى ما يدعو إليه حجة ولا يحتاج عليها إلى بينة وبرهان وعلى قومه قبول قوله وإن لم يأت ببرهان، فمن لم يقبله كفر. وقد سرقت الكرّامية هذه البدعة من الإباضية فزعمت أنّ كل من سمع قول الرسول أو سمع الخبر عن ظهوره وعن دعوته لزمه الإقرار والتصديق به سواء علم برهانه وحجته أو لم يعلمها. وقال ثمامة وأتباعه من القدرية لا يحتاج النبي في الحجة على نبوته إلى أكثر من سلامة شرعه وما يأتي به، من التناقض فيه. وقال أصحابنا: إن سلامة معجزته عن المعارضة دليل على صحته. وأما سلامة شرعه عن التخليط والنقض فيه فلا يدل على صحته لأن الكاذب لو شرع شرعا وطرد فيه قياسه لم يجب به تصديقه ولا بد من علامة تدل على صدقه ليجب بها اتباعه. ولو جاز تقليده في دعواه من غير برهان لم يكن لنا دلالة على كذب الكاذب في دعوى النبوة إذا لم يكن معه برهان صحتها. وهذا باطل فما يؤدي إليه مثله.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [147, 148]}, "540.137": {"x": [[148, "في أن المعجزات كلها من الله تعالى دون غيره\rقال أصحابنا: إن أكثر المعجزات من أفعال الله تعالى لا يقدر على جنسها غيره كإحياء الأموات وإبراء الأكمه والأبرص وقلب العصا حية وفلق البحر وإمساك الماء في الهواء وتشقيق القمر وإنطاق الحصى وإخراج الماء من بين الأصابع ونحو ذلك. ومنها ما هو خلق لله اختراعا وكسب لصاحب المعجزة كإقداره إنسانا على\r__________________\r(1) [معونة].\r(2) [والمعونات]."], [149, "الطفر (1) [على الصعود] (2) إلى السماء وعلى قطع المسافة البعيدة في الساعة القصيرة وعلى إطلاق لسان الأعجمي بالعربية ونحو ذلك مما لم يجر العادة به. وزعم معمر شيخ القدرية أن المعجزات ليس شيء منها من فعل الله تعالى. لأنه قال إن الله خلق الأجسام والأجسام خلقت الأعراض في أنفسها وليست المعجزة حدوث جسم وإنما وجه الإعجاز كون الجسم على وجه لم تجر العادة به. وذلك بحصول نوع من الأعراض فيه وليست الأعراض فعلا لله تعالى. وبان من هذا أن ليست المعجزات فعلا لله عنده وإن الله نصب دلالة على صحة نبوة أحد من أنبيائه. وإذا كشفنا عن ضمير معمر في هذا الباب ظهر لنا أن غرضه إبطال الشريعة وأحكامها. وبيان ذلك أنّا إذا سألناه عن قوله في القرآن لم يمكنه أن يقول إنه فعل الله، كما قال إخوانه من القدرية، لدعواه إن الله لم يخلق شيئا من الأعراض. ولم يمكنه أن يقول إن كلام الله صفة من صفاته الأزلية، كقول أصحابنا، لأنه ينفي الصفات الأزلية. فلم يمكنه إثبات كلام الله عزوجل لا على معنى الصفة ولا على معنى الفعل. وإذا لم يكن له كلام لم يكن له أمر ولا نهي ولا خبر ولا شرع ولا حكم. وفي هذا سقوط التكليف عن العباد. وما أراد هذا المبتدع غيره. وكذلك المعروف بثمامة، في قوله إن المتولدات أفعال لا فاعل لها، ما أراد إلا إسقاط التكليف. لأن الكلام عنده متولد وليس هو صفة قائمة بالله عنده لنفيه صفاته ولا يصح منه الفعل على التولد فلا يصح على أصله كونه متكلما ولا آمرا ولا ناهيا ولا يكون له على هذا الأصل شرع ولا حكم ولا تكليف. ويكفي المعتزلة بهذين الشيخين منهما خزيا.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [148, 149]}, "540.138": {"x": [[149, "في كيفية الاستدلال بالمعجزة على صدق صاحبها في دعواه\rإن العلم بصحة نبوة النبي فرع العلم بصحة المعجزة الدالة على صدقه في\r__________________\r(1) الطفرة الوثبة وبابه جلس.\r(2) [على الصعود]."], [150, "دعواه، إذا لم يضطرنا الله تعالى إلى العلم بصدقه. وإذا صحت هذه المقدمة وظهر على مدعي النبوة من فعل الله تعالى ما ينقض العادة عند دعوى المدعي رسالته وكان الذي ظهر مطابقا لدعواه وقد سبق العلم بأن الله كان سامعا لدعواه عليه إرساله إياه وعالما بها وبمعناها ثم ظهر ما ادعاه عليه علم بذلك إنه تعالى قصد بذلك تصديقه في دعواه وصار إظهاره لذلك مطابقا لدعواه بمنزلة [قوله صدقت أو قوله لقوم صدق هو رسولي إليكم على وجه يفهم تصديقه له] بل يكون التصديق له بالفعل أبعد من التهمة لأن قول القائل لغيره صدقت قد يكون على طريق الاستهزاء والتصديق له بالفعل لا يحتمل وجها سوى التصديق ومثاله في الشاهد قول مدعي الرسالة من إنسان إلى غيره: إن كنت رسولك إلى فلان فاكتب إليه بخطك بعض الأسرار التي بينك وبينه أو قال له بحضرتها إن كنت أمرتني بأخذ وديعتك منه فناولني خاتمك فإذا فعل ما سأله علم بذلك أنه قصد بذلك الفعل تصديقه في دعواه وأقام ذلك مقام قوله صدقت وكان الفعل في ذلك أبلغ من هذا القول. فهذا وجه دلالة المعجزة على صدق من ظهرت عليه فيما لا يعرف فيه صدقه ولا كذبه إلا بدلالة.\rالمسألة التاسعة من هذا الأصل\r"]], "pg": [149, 150]}, "540.139": {"x": [[150, "في بيان طريق العلم بمعجزات الأنبياء"], [151, "إن الذين شاهدوا معجزات الأنبياء عند ظهورها عليهم يعرفون وجه الإعجاز فيها بعجز الخصوم عن معارضتها بمثلها مع حرصهم على التكذيب. وأما الذين غابوا عنها فيعرفون وجودها بتواتر الأخبار، الموجبة للعلم الضروري، عنها. فإذا عرفوا وجودها بالتواتر ولم ينقل إليهم معارضة لها علموا أنها كانت في وقتها معجزة ودلالة على صدق من ظهرت عليه. وإنما يخالف في هذا من ينكر وقوع العلم من جهة الأخبار المتواترة كالسمنية. ووافقنا البراهمة على وقوع العلم بالبلدان والأمم الماضية من جهة التواتر وخالفونا في العلم بمعجزات الأنبياء من جهة تواتر الأخبار. والتواتر فيما أنكروه كالتواتر فيما أقروا به. ومن أنكر ذلك توجّه الإلزام عليه بإنكار\r\rالبلدان التي يدخلها الناس مع تواتر الأخبار عنها [و] إنكار أبويه وإن عرفهما بتواتر الأخبار عنها. وهذا ما لا محيص له منه.\rالمسألة العاشرة من هذا الأصل\r"]], "pg": [150, 151]}, "540.140": {"x": [[151, "في بيان معجزة كل نبي على التفصيل\rكانت معجزة آدم عليه السلام علمه بالأسماء من غير درس ولا قراءة كتاب.\rوكانت معجزة نوح الطوفان وخلاصه منه. ومعجزة هود الريح وما كان من شأنها مع قوم عاد. ومعجزة صالح الناقة والصحيحة التي دمرت على القوم. ومعجزة إبراهيم عليه السلام النجاة من النار. ومعجزة موسى اليد البيضاء وقلب العصا حية وحل العقدة من لسانه وسائر الآيات التسع التي كانت له. ومعجزة داود تليين الحديد له. ومعجزة سليمان الريح وتسخير الجن والشياطين له. ومعجزة عيسى إحياء الموتى وإبراء الأكمه والأبرص ونحو ذلك. وكذلك كل نبي له معجزة مخصوصة. واجتمعت لنبينا محمد صلىلله عليه وسلم جميع وجوه المعجزات التي تفرقت في الأنبياء كما بيناها في كتاب الموازنة بين الأنبياء.\rالمسألة الحادية عشرة من هذا الأصل\r"]], "pg": [151, 151]}, "540.141": {"x": [[151, "في نبوة موسى ومعجزته"], [152, "كل من أقر بشريعة من الشرائع أقر بموسى وبنبوته عليه السلام. وزعم ماني أن موسى كان من رسل شياطين الظلمة وأقر بنبوة عيسى عليه السلام. وليس لماني من المقدار ما يناظر لأجله في النبوات مع وقوع الخلاف معه في توحيد الصانع وفي حدوث الأجسام. ومن خالف في الأصل لم يناظر في فرعه. على أنه لا ينفصل من قول من قال في عيسى مثل قوله في موسى. ومعجزات موسى الآيات التسع التي نطق بها القرآن. وتواتر الخبر عنها كتواتر الخبر عن ظهور موسى ودعوته. ومن ادعى أن ذلك الذي ظهر عليه كان سحرا أو مخرقة كمن ادعى مثل هذه الدعاوى في معجزات عيسى عليه السلام.\r\rالمسألة الثانية عشرة من هذا الأصل\r"]], "pg": [151, 152]}, "540.142": {"x": [[152, "في نبوة عيسى ومعجزاته\rوإنما يناظر في هذه المسألة اليهود المنكرون مع إقرارهم بنبوة من قبله.\rوالعلم بمعجزاته من الطرق التي علم بها معجزات موسى. ومن طعن في التواتر عن معجزات عيسى كمن طعن في التواتر عن معجزات موسى عليه السلام. والنقل في أن عيسى ظهر له إحياء الموتى وإبراء الأكمه والأبرص والمشي على الماء كالنقل في فلق البحر لموسى وقلب العصا حية له ونحو ذلك. ومن ادعى في أحدهما السحر كمن ادعاه في الآخر مع عدم النقل في المعارضة.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [152, 152]}, "540.143": {"x": [[152, "في معجزات نبينا صلىلله عليه وسلم\rإن معجزات نبيّنا صلىلله عليه وسلم في الأعداد كثيرة الأمداد. فمنها بشارات الأنبياء به قبله ولذلك أذعن له جماعة من أحبار أهل الكتاب مثل كعب الأحبار (1) ووهب بن منبه (2) وقبلهما عبد الله بن سلام (3) وقبله بحيرا الراهب ثم النجاشي وقبله سيف بن ذي يزن. ولسماع شأنه من أهل الكتاب آمن به العيسوية من اليهود، غير أنهم شكوا في بعثه إلى بني إسرائيل. ومنها الرجوم بالنجوم عند قرب بعثته وذلك كان سبب إسلام قوم من الكهنة. ومنها انشقاق القمر بدعوته وفي ذلك نزل قوله تعالى:\r__________________"], [153, "(1) هو عالم الكتاب والآثار كعب الأحبار، أسلم زمن أبي بكر وروى عن عمر رضي الله عنه.\rتوفي سنة خمس وثلاثين للهجرة ..\r(2) هو أبو عبد الله وهب بن منبه الصنعاني من أبناء الفرس الذين بعث بهم كسرى الى اليمن، روى عن ابن عباس قيل وابي هريرة وغيره من الصحابة وولى القضاء لعمر بن عبد العزيز وكان شديد الاعتناء بكتب الأولين وأخبار الأمم وقصصهم بحيث كان يشبه بكعب الأحبار في زمانه، توفي بصنعاء سنة أربع عشرة ومائة للهجرة.\r(3) هو عبد الله بن سلام الاسرائيلي حليف الأنصار من سبط يوسف بن يعقوب وقصة إسلامه مشهورة في الصحاح وشهد له النبي صلىلله عليه وسلم بالجنة وهو المراد عن بعض المفسرين بقوله تعالى (ومن عنده علم الكتاب) وقوله تعالى (وشهد شاهد من بني اسرائيل على مثله). توفي سنة ثلاث وأربعين للهجرة .."], [154, "(اقْتَرَبَتِ السَّاعَةُ وَانْشَقَّ الْقَمَرُ) (1). ولو لم يقع ذلك لقال له أعداؤه متى كان هذا؟ وهذه معجزة سماوية وكانت معجزات من قبله أرضية. ومنها إشباع الخلق الكثير من الطعام اليسير في مواضع كثيرة. ومنها نبوع الماء من بين أصابعه لوضوء جيشه وذلك أعجب من خروج الماء من الحجر لموسى عليه السلام. ومنها تسبيح الحصى في يده حتى سمع الحاضرون. ومنها حنين الجذع إليه حتى التزمه. ومنها مجيء الشجرة بأمره ورجوعها بأمره إلى مغرسها. ومنها القرآن وهو أفضل المعجزات من وجهين: أحدهما: بقاؤه بعد وفاته ومعجزات غيره لم تبق بعد وفاة أصحابها. والثاني: استنباط جميع أحكام الشريعة منه ولا يستنبط من معجزة غيره حكم الشريعة. والدليل على صحة معجزة القرآن أنه تحدى قومه بسورة مثله فلو عارضوه بها لكذبوه. فلما عدلوا عن المعارضة التي لو تمت لدلت على كذبه إلى قتاله الذي لو تم مرادهم فيه، لم يدل على كذبه علمنا أنهم إنما عدلوا عما يدل على التكذيب إلى ما لا يدل عليه، لعجزهم عما يكون دليلا على ذلك. ولو عارضوه لنقل ذلك لأن الذين لا يتواطئون على الكذب لا يتواطئون على كتمان ما قد علموه بالضرورة. ألا ترى أنه نقل ما عورض به مما لا يشبهه كقول مسيلمة: والطاحنات طحنا والخابزات خبزا، في معارضة: (وَالْعادِياتِ ضَبْحاً) (2). وفي عدم المعارضة دلالة على صحة المعجزة.\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [152, 154]}, "540.144": {"x": [[154, "في بيان وجه إعجاز القرآن\rقال أصحابنا: الإعجاز في القرآن من وجوه: منها نظمه العجيب في البلاغة والفصاحة الخارجة عن العادة في نظم الخطب والشعر والمزدوج من الكلام ونحو ذلك. ومنها ما فيه من الأخبار عن غيوب سالفة وذلك عجيب إذا وردت ممن لم يعرف الكتب ولم يجالس أصحاب التواريخ. ومنها الأخبار عن غيوب كانت في المستقبل كما وقع في الخبر عنها على التفصيل لا على وجه تخمين الكهنة\r__________________\r(1) سورة القمر آية 1.\r(2) سورة العاديات آية 1."], [155, "والمنجمين. وزعم النظام أن الإعجاز في القرآن من جهة ما فيه من الأخبار عن الغيوب ولا إعجاز في نظمه. وزعم مع أكثر القدرية أن الناس قادرون على مثل القرآن وعلى ما هو أبلغ منه في الفصاحة والنظم. وقد أكذبهم الله عزوجل في ذلك بأن تحدى المشركين بأن يأتوا بعشر سور مثله مفتريات ولا يكون في الافتراء تحقيق غيب فدل على أنه إنما أراد به تحقيق إعجازه من جهة النظم والفصاحة. فإن قيل إذا كانت فصاحة القرآن لا يعرفها إلّا العرب فكيف عرفت العجم وجه الإعجاز فيه. قيل إذا علمت العجم أن العرب أهل اللسان وقد عجزوا عن معارضته فيه علموا كونه معجزا كما أن السحرة لما عجزت عن معارضة موسى في عصاه عرف غيرها وجه الإعجاز في العصا وأنها ليست بسحر لأنها لو كانت سحرا لعارضته السحرة بمثلها. كذلك العجم يعلم أن القرآن لو كان من جنس كلام البشر لقدر على مثله أهل اللغة.\rالمسألة الخامسة عشرة من هذا الأصل\r"]], "pg": [154, 155]}, "540.145": {"x": [[155, "في كرامات الأولياء"], [156, "أنكرت القدرية كرامات الأولياء على وجه ينقض العادة وأثبتها الموحدون لاستفاضة الخبر عن صاحب سليمان في إتيانه بعرش بلقيس قبل ارتداد الطرف إليه. ومنها رؤية عمر رضي الله عنه على منبره بالمدينة جيشه بنهاوند، حتى قال: يا سارية الجبل وسمع سارية ذلك الصوت على مسافة زهاء خمسمائة فرسخ حتى صعد الجبل وفتح منه الكمين للعدو وكان ذلك سبب الفتح. ومنها قصة سفينة مولى رسول الله صلىلله عليه وسلم مع الأسد. وقصة عمير الطائي مع الذيب حتى قيل له كليم الذيب وقصة أهبان بن صيفي وأبي ذر الغفاري مع الوحش وما أشبه ذلك كثير مما حرمه أهل القدر بشؤم بدعتهم. وليس في جوازها قدح في النبوات لأن الناقض للعادة دلالة على الصدق فتارة يدل على الصدق في دعوى النبوة وتارة يدل على الصدق في الحال. فإن ألزمونا مثلها في بعض الرعايا أو في بعض الفسقة. قلنا إن ظهر عليه شيء منها كانت مغوثة له في محنة يخلصه الله تعالى بها منها ولم نسمها كرامة وصار الخلاف في التسمية دون المعنى والله أعلم بالصواب.\r\rالأصل التاسع\r"]], "pg": [155, 156]}, "540.146": {"x": [[156, "من أصول هذا الكتاب في بيان معرفة\rأركان الإسلام\rوفي هذا الأصل خمس عشرة مسألة هذه ترجمتها:\rمسألة في الأركان الخمسة.\rمسألة في تفصيل الركن الأول.\rمسألة في تفصيل الركن الثاني.\rمسألة في تفصيل الركن الثالث.\rمسألة في تفصيل الركن الرابع.\rمسألة في تفصيل الركن الخامس.\rمسألة في شروط الأركان الخمسة.\rمسألة في شروط الجهاد والأحكام.\rمسألة في أحكام المعاملات.\rمسألة في أحكام النكاح والفروج.\rمسألة في أحكام الحدود.\rمسألة في أحكام المحرمات والمباحات.\rمسألة في أحكام الأموات في الميراث.\rمسألة في بيان مأخذ الأحكام الشرعية.\rمسألة في الفرق بين الشرعيات والعقليات. فهذه مسائل هذا الأصل وسنذكر في كل واحدة منها مقتضاها إن شاء الله تعالى.\r\rالمسألة الأولى من هذا الأصل\r"]], "pg": [156, 156]}, "540.147": {"x": [[156, "في بيان الأركان الخمسة"], [157, "الأصل فيها قول النبي صلىلله عليه وسلم: بني الإسلام على خمس: شهادة أن لا إله إلّا الله وإقام الصلاة وإيتاء الزكاة وصوم رمضان وحج البيت (1). وجاءت الشريعة بترتيب أحكام كثيرة على خمسة منها الصلاة المفروضة خمس بإجماع السلف عليه. ولا اعتبار فيها بخلاف من قال من الروافض بزيادة صلوات مع تركهم كلها. فأما الوتر فهي عندنا سنة وعند أبي حنيفة واجبة وليست بفريضة. ومنها خمسة أركان فرضها الشافعي رضي الله عنه في الصلاة وهي: التكبيرة الأولى وقراءة الفاتحة والتشهد الأخير والصلاة على النبي صلىلله عليه وسلم بعد التشهد والتسليمة الأولى. ومنها أن الزكاة المفروضة تجب في خمسة أجناس من الأموال.\rأحدها: النعم السائمة من الإبل والبقر والغنم.\rوثانيتها: الأثمان المطلقة من الذهب والورق.\rوثالثها: الحبوب المقتاتة التي يزرعها الناس.\rورابعها: من الثمار التمر والزبيب.\rوخامسها: أموال التجارة. ومنها أن أول نصاب الإبل خمس ثم في كل خمس سائمة شاة إلى أربع وعشرين فإذا بلغت خمسا وعشرين وجبت فيها بنت مخاض (2)، انتقل الفرض فيها بعد ذلك إلى الإبل. ومنها أن نصاب ما يجب فيه\r__________________\r(1) أخرجه الترمذي عن ابن عمر برقم 2609 وأخرجه البخاري في التاريخ برواية عن خليد وعن ابن عمر 2/ 1 / 198.\r(2) المخاض بالفتح وجع الولادة، وقد مخضت الحامل بالكسر مخاضا أي ضربها الطلق فهي ماخض، والمخاض الحوامل من النوق، واحدتها خلفة ولا واحد لها من لفظها، ومنه قيل للفصيل إذا استكمل الحول ودخل في الثانية: ابن مخاض، والأنثى ابنة مخاض لأنه فصل عن أمه وألحقت أمه بالمخاض سواء لقحت أو لم تلقح، وابن مخاض نكرة فإن عرفته قلت: ابن المخاض، وهو تعريف جنس، ولا يقال في جمعه: لا بنات مخاض وبنات لبون وبنات آوى .."], [158, "الزكاة من الحبوب أو التمر أو الزبيب خمسة أوسق. كل خمس منها ستون صاعا (1). ومنها أن أول نصاب الورق في الزكاة خمسة أواق، كل أوقية أربعون درهما، ثم فيما زاد بحسابه. ومنها أن الصيام خمسة أنواع: صوم رمضان وصوم القضاء وصوم النذر وصوم الكفارة وصوم التطوع. ومنها أن الغسل يجب من خمسة أشياء: من إنزال الماء الدافق ومن التقاء الختانين وإيلاج في فرج أو دبر ومن انقطاع دم الحيض ومن انقطاع دم النفاس ومن الموت من غير قتل شهادة في المعركة. ومنها سقوط فرض الجمعة عن خمسة من المكلفين وهم العبد والمرأة والمسافر والمريض والممرض الذي له عذر. ومنها أن دية كل سن للرجل خمس من الإبل. وفي موضحة الرجل خمس من الإبل وفي إحدى أنملتي الإبهام من اليد أو الرجل خمس من الإبل. وفي إصبع المرأة خمس من الإبل وفي هاشمتها خمس من الإبل. ودية الخطأ من خمسة أصناف من الإبل عشرون بنت مخاض وعشرون بنت لبون (2) وعشرون حقة (3) وعشرون جذعة.\rوالسن الخامس (4): اختلفوا فيه: فقال الشافعي عشرون ابن لبون وقال أبو حنيفة عشرون ابن مخاض. وفي الخلقة أخماس كثيرة. منها كل يد خمس أصابع وفي كل رجل كذلك ومنها خمس حواس عليها مدار الإدراكات. الخمس من الأجزاء كثير منها في الركاز (5) ومنها إخراج الخمس من الغنيمة والفيء ثم وجوب قسمة ذلك الخمس بين أهل الخمس على خمسة أسهم. وفي هذا كله دليل على تشريف الله عزوجل الخمسة من وجوه فلذلك بني الإسلام على خمسة أركان.\r__________________\r(1) [كل وسق ستون صاعا].\r(2) ابن لبون: ولد الناقة إذا استكمل السنة الثانية ودخل في الثالثة والانثى ابنة لبون لأن أمه وضعت غيره فصار لها لبن، وهو نكرة ويعرف باللام فيقال: ابن اللبون.\r(3) الحق بالكسر ما كان من الإبل ابن ثلاث سنين وقد دخل في الرابعة والأنثى حقّة وحق أيضا، سمي بذلك لاستحقاقه أن يحمل عليه وأن ينتفع به والجمع حقاف ثم حقق بضمتين مثل: كتاب وكتب.\r(4) [الصنف الخامس]."], [159, "(5) الركاز بالكسر: دفين أهل الجاهلية، كأنه ركز في الأرض وأركز الرجل: وجد الركاز.\r\rالمسألة الثانية من هذا الأصل\r"]], "pg": [156, 159]}, "540.148": {"x": [[159, "في تفصيل الركن الأول من أركان الإسلام\r(اعلموا (1)) إن الركن الأول من أركان الإسلام، كما ورد به الخبر، شهادة أن لا إله إلا الله وأن محمدا رسول الله. ولهذه الشهادة شروط منها أنها لا تقبل ولا يثاب عليها صاحبها إلا إذا عرف صحتها وقالها عن معرفة وتصديق لها بالقلب. فأما إذا أطلقها المنافق الذي يعتقد خلافها فإنه لا يكون عند الله مؤمنا ولا ناجيا من عقاب الآخرة. وإنما يجري عليه في الظاهر حكم الإسلام في سقوط الجزية عنه وفي دفنه في مقابر المسلمين وفي الصلاة عليه وخلفه في الظاهر. هذا كله إذا لم يظهر مع نفاقه الباطن بدعة شنعاء فإن أظهر بدعة نظر فإن كانت بدعته كبدعة القرامطة الباطنية وكبدعة الغلاة من الرافضة الحلولية فإنه مرتد يقتل ولا يصلى عليه ويكون ماله فيئا للمسلمين. وإن كانت بدعته كبدعة القدرية فإن المتكلمين من أصحابنا قالوا بانقطاع التوارث بينهم وبين أهل السنة ولذلك امتنع الحارث المحاسبي (2) عن غنم ميراث أبيه لأن أباه كان معتزليا. وقال الفقهاء من أصحابنا أن قريبه (3) [وارثه] السني يرث منه كما أن أهل الذمة يرث بعضهم بعضا مع اختلافهم في الأديان. وأجمع الفقهاء والمتكلمون من أصحابنا على أنه لا يصح الصلاة خلف المعتزلي ولا عليه ولا يحل أكل ذبيحته ولا رد السلام عليه ورأوا (4) في ذلك قول عبد الله بن عمر في النهي عن ذلك وفي براءته من القدرية. وزعمت الكرّامية أنّ المنافق المضمر الشرك مؤمن حقا وأنّ إيمانه كإيمان جبرائيل وميكائيل والأنبياء أجمعين. والكلام عليهم في ذلك يأتي في باب الإيمان.\r__________________\r(1) زيدت على المطبوع لسياق النص."], [160, "(2) هو الحرث بن أسد المحاسبي الزاهد الناطق بالحكمة صاحب المصنفات في التصرف والأحوال، قال ابن الأهدل: كان أحد الخمسة الجامعين بين العلمين في واحد هو والجنيد وأبو محمد وأبو العباس بن عطاء وعمرو بن عثمان المكي وله مصنفات نفيسة في السلوك والأصول، وهو احد شيوخ الجنيد، توفي سنة ثلاث وأربعين ومائتين للهجرة.\r(3) [وارثه].\r(4) [ورووا].\r\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [159, 160]}, "540.149": {"x": [[160, "في تفصيل الركن الثاني وهو الصلاة\rوالصلوات المفروضات خمس وعدد ركعاتها لمن لا يجوز له القصر سبع عشرة ولمن جاز له القصر في السفر إحدى عشرة. وهذه الخمس من أسقط وجوب بعضها أو أسقط وجوبها كلها كفر. واختلفوا في وجوب الوتر ولا يكفر من أوجبها ولا من أسقط وجوبها. واختلف الفقهاء في بعض أركان الصلاة. ومن أسقط ما اختلفوا في وجوبه منها لم يكفر ومن أسقط وجوب ركن قد أجمع السلف على وجوبه كفر. ولهذا أكفرنا الكرّامية في قولها إن نية الصلاة المفروضة غير واجبة ونية قبول الإسلام في الابتداء كافية. وهذا خلاف قول الأمة كلها. ومن ترك الصلاة مع اعتقاد وجوبها عليه فقد اختلفوا فيه: فقال أحمد بن حنبل إنه يكفر بذلك وقال الشافعي يقتل ولا يكون كافرا وقال أبو حنيفة يضرب على ذلك ولا يقتل. فأما إذا استحلّ ترك الصلاة فهو كافر بلا خلاف. وكل من لا يرى الجمعة وصلاة العيد خلف أهل السنة فإنا أيضا لا نرى الصلاة خلفه ولا عليه إذا مات وحكمه عندنا حكم المرتدين. والجمعة واجبة عندنا على كل مكلف إلا المرأة والعبد والمريض والمسافر والممرض والهارب من ظالم لا يطيقه. والفرائض من الصلوات كلها موقتة ولا يصح شيء منها قبل دخول وقتها. ومن شرط صحة الصلاة الطهارة ودخول الوقت واستقبال القبلة عند الإمكان في فرائضها دون النافلة على الراحلة. وستر العورة عند الإمكان. ومن فاتته الفريضة في وقتها فعليه قضاؤها. ومن فاتته النافلة فليس عليه قضاؤها وإن كان قضاء بعضها مستحبا."], [161, "المسألة الرابعة من هذا الأصل\r"]], "pg": [160, 161]}, "540.150": {"x": [[161, "في تفصيل الركن الثالث (وهو الزكاة) (1)\rوالركن الثالث من أركان الإسلام: الزكاة. والزكاة التي أجمعوا على وجوبها عشر: زكاة البقر وزكاة الغنم وزكاة الزبيب وزكاة التمر وزكاة الحبوب المقتاتة التي يزرعها الآدميون وزكاة التجارة وزكاة الفطر. فمن أسقط وجوب شيء من ذلك كفر\r__________________\r(1) زيدت على المطبوع.\r\rإلا زكاة التجارة فللاجتهاد فيها مجال. واختلفوا في زكاة سائر الثمار وفي زكاة الحلى وزكاة الخيل. وللاجتهاد فيها مجال وكذلك الاختلاف في زكاة البقول والورس (1) والزعفران والعسل. وحكمها مبني على الاجتهاد. وكل زكاة سوى زكاة الفطر وجوبها بشرطين:\rإحداهما: كمال النصاب.\rوالثاني: حئول الحول عليه. واختلفوا في اعتبار السوم في زكاة النعم وفي وجوب الزكاة في مال الصغير والمجنون. وللاجتهاد، في ذلك وفي كل ما اختلف فيه الفقهاء من مسائل الزكاة، مساغ.\rالمسألة الخامسة من هذا الأصل\r"]], "pg": [161, 161]}, "540.151": {"x": [[161, "في تفصيل الركن الرابع من أركان الإسلام (وهو الصيام)\rوالركن الرابع من أركان الإسلام هو صوم رمضان ولا بدّ لكل مكلّف من العلم بوجوب صوم رمضان وبوجوب قضائه على من أفطر فيه لعذر أو لغير عذر ولا بد له من العلم بوجوب صوم المنذور. فأما الصوم في الكفّارات فإنما يعرفه الفقهاء والخواص. ولا بد من العلم بأن صوم رمضان يكون الدخول فيه برؤية هلاله أو باستكمال ثلاثين يوما من شعبان. ومن قال من الروافض بالدخول فيه يوم الشك فلا اعتبار بخلافه في هذا الباب. واليهود يرون وجوب صوم واحد. والنصارى تصوم ثمانية واربعين يوما ابتداؤها فيما بين شباط وآذار. فأما فروع الصوم وأكثر شروطه فمما يختص بمعرفة الفقهاء.\rالمسألة السادسة من هذا الأصل (2)\r"]], "pg": [161, 161]}, "540.152": {"x": [[161, "في تفصيل الركن الخامس وهو الحج\rوجوب هذا الركن في العمر مرة واحدة على من وجد استطاعة. وأركانه\r__________________"], [162, "(1) الورس بوزن الفلس: نبت أصفر يكون باليمن تتخذ منه الغمرة للوجه، تقول منه: وأورس المكان فهو وارس ولا يقال مورس وهو من النوادر، وورس الثوب توريسا صبغه بالورس.\r(2) زيدت على المطبوع.\r\rالواجبة التي لا بد منها عند الشافعي أربعة: وهي الإحرام والوقوف بعرفة والطواف والسعي بين الصفا والمروة. ووقت الوقوف ما بين زوال الشمس من يوم عرفة إلى طلوع الفجر الصادق من يوم النحر. فمن وقف منها ساعة بها فقد أدرك الحج. وأقل ما يجزيه من الطواف في قول الشافعي سبعة أشواط ومن السعي بين الصفا والمروة سبعة أشواط. واختلفوا في وجوب العمرة: فأوجبها الشافعي وجعل أركانها ثلاثة: الإحرام والطواف والسعي. وأسقط أبو حنيفة وجوبها.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [161, 162]}, "540.153": {"x": [[162, "في بيان شروط الأركان الخمسة\rأما الصلاة فمن شرطها الطهارة وستر العورة ودخول الوقت واستقبال القبلة باليقين أو بالاجتهاد عند عدم اليقين إلا في حال التحام القتال، فإنها تصح على حسب الإمكان. وكذلك النافلة على الراحلة سقط فيها فرض الاستقبال. وشروط الطهارة في الوضوء عند أهل الحديث ستة: منها أركانها الأربعة والنية والترتيب. وللغسل شرطان أحدهما النية والثاني إيصال الماء إلى كل بشرة ظاهرة وشعر ظاهر. وشروط الجمعة الحرية والذكورة والبلوغ والعقل والإقامة والصحة. وشروط الزكاة في الغنم: حئول الحول عليها وهي سائمة في ملك مسلم تام الملك وهو مع ذلك نصاب كامل. وشروط الحج والعمرة: وجود الاستطاعة. وهي لمن حضر مكة أو ما يتصل بها بالبدن ولمن بعد عنها بالزاد والراحلة مع أمن الطريق.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [162, 162]}, "540.154": {"x": [[162, "في شرط الجهاد وأحكامه"], [163, "الجهاد واجب مع أعداء الدين على حسب الوسع والطاقة وأصله وجوب الأمر بالمعروف والنهي عن المنكر. والجهاد مع أهل الكفر بالقتال إلى أن يؤمنوا بالله وكتبه ورسله ويقبلوا دين الإسلام بكمال أركانه أو يقبل الجزية ممن يجوز لنا بذل العهد على الجزية. والجهاد مع أهل البدع بالحجاج أوّلا ثم بالاستتابة ثانيا. ومن لم يبلغه دعوة الإسلام فلا يجوز قتله ولا أخذ ماله حتى يدعى إلى الإسلام\r\rويقام عليه الحجة فيه فإن لم يقبل ذلك عومل حينئذ بما يعامل به أهل الكفر. فإن قتله قاتل قبل قيام الحجة فقد اختلفوا فيه. وأوجب أصحابنا على قاتله الكفّارة ودية له كما يليق بدية أهل دينه. وعلى الإمام سد الثغور وإغراء الجيوش واستتابة أهل الردة وأهل البدع وإقامة الحدود وقسمة الفيء والغنيمة بين المستحقين. وإذا وقع النفير العام وجب على جميع المكلفين القيام به. ومتى قام بفرض الجهاد في ناحية بعض الناس سقط فرضه عن غيره. لأن الجهاد من فروض الكفاية.\rالمسألة التاسعة من هذا الأصل\r"]], "pg": [162, 163]}, "540.155": {"x": [[163, "في بيان أحكام المعاملات"], [164, "والمعاملات أنواع: منها البيوع والرهون والديون والضمان والكفالة والوكالة والحوالة والشركة والوديعة والعارية والصلح والشفعة والهبة والأوقاف والإجارات والمزارعات والمساقاة وأحكام الإقرار والتفليس وأحكام اللقطة وإحياء الموات وإقطاع المعادن وسائر الوجوه التي تكتسب منها الأموال فكل ذلك على الإباحة في الجملة. واختلف العلماء في تفصيل فروع بعض منها. ومن حرّم شيئا منها وكان مما قد أجمع سلف الأمة على إباحته كفر، ولذلك أكفرنا الأصم في إنكاره صحة عقد الإجارة التي أجمع سلف الأمة على جوازها. وأكفرناه أيضا في إجازته الوضوء بالخل كما أكفرناه في نفي الأعراض. ومن أنكر منها ما اختلف العلماء في جوازه لم يكفر كعقد المساقاة والمخابرة والمزارعة ورد ما عند المفلس من مال البائع ونحو ذلك. وفي عقود المعاوضة لا بد أن يكون العوض والمعوض معلومين. وكل عقد كان فيه أجل فلا بد من أن يكون الأجل فيه معلوما. ولا يصح شيء من العقود إلا من بالغ عاقل كما لا يتوجه التكليف إلا على عاقل بالغ. والربا في المعاملات حرام. وقد أجمعوا على تحريم الربا في ستة أشياء وهي:\rالذهب والورق والبر والشعير والتمر والملح.\rواختلفوا فيما سواه فأجرى الشافعي تحريم الربا في كل مطعوم. وأجراه مالك في كل مقتات مدخر. وأجراه أبو حنيفة في كل مكيل وموزون. فمن أباح\r\rالربا في الستة التي ذكرناها كفر. ومن أباحه في غيرها لم يكفر لاختلاف الأمة فيه. وللكلام في فروع المعاملات وشروطها كتاب مفرد\rالمسألة العاشرة من هذا الأصل\r"]], "pg": [163, 164]}, "540.156": {"x": [[164, "في بيان أحكام الفروج"], [165, "وأحكام الفروج كثيرة. منها: النكاح والرجعة والطلاق والخلع والظهار والإيلاء والعدة واللعان والرضاع والمهر ونفقات الأزواج ونحوها. والفرج لا يستباح إلا بنكاح أو ملك يمين. وغاية ما ينكح الحر من النسوة، في قول أكثر الأمة، أربع. وأكثر ما ينكح العبد، في قول الأكثر، امرأتان. وأجمعوا على تحريم نكاح الأمهات والبنات والأخوات والعمات والخالات وبنات الأخ وبنات الأخت. والجدات يدخلن في عموم الأمهات وبنات الأولاد وإن سفلن يدخلن في جملة البنات. وكذلك عمات الآباء والأمهات وخالات الصنفين وبنات أولاد الأخوة والأخوات على هذا القياس. هذا إذا كنّ من النسب وأجمعوا على تحريم الأمهات والأخوات من الرضاع. واختلفوا في تحريم العمات والخالات وبنات الأخ وبنات الأخت من الرضاع: فأباحهن أهل الظاهر وأكثر الخوارج وحرمهن أكثر الأمة وذلك هو الصحيح. وأجمعوا على تحريم أمهات النساء وتحريم منكوحات الآباء وحلائل الأبناء بالعقد وعلى تحريم الربائب بشرط الدخول. وأجمعوا على تحريم الجمع بين الأختين بالنكاح واختلفوا في تحريم الاستمتاع بهما بملك اليمين. وكذلك الخلاف في تحريم الجمع بين المرأة وعمتها وخالتها. فكل من خالف في شيء مما اختلف فيه سلف الأمة من أبواب النكاح في تحريم امرأة وإباحتها وفي شرط قد اختلفوا فيه كشهود النكاح ولفظه والولي لم يكفر. ومن نازع فيما أجمعوا عليه منه كفر. ولذلك أكفرنا الميمونية من الخوارج بأن أباحوا نكاح بنات البنات ونكاح بنات البنين. وزعموا أن الآية اقتضت تحريم نكاح بنات الصلب دون بنات الأولاد. وأجمعوا على أن الصداق يجب أن يكون معلوما حلالا فإن كان الصداق مجهولا أو فاسدا فالنكاح صحيح في قول الشافعي رضي الله عنه وأبي حنيفة ويرجع في الصداق إلى مهر المثل. وفي قول مالك يفسد النكاح بفساد الصداق."], [166, "فإن لم يذكر في النكاح صداقا صح النكاح بلا خلاف واستقر فيه مهر المثل بالوطء. والرجعة تكون بعد طلاق رجعي فإن كان الطلاق على عوض أو كان قبل الدخول أو كان ثلاثا لم يكن بعده رجعة بلا خلاف. ولفروع أحكام الفروج كتب مفردة والغرض من جملتها أن من غيّر منها ما أجمعت الأمة عليه عن نص من القرآن أو السنة كفر. ومن خالف في شيء اختلف فيه سلف الأمة لم يكفر.\rالمسألة الحادية عشرة من هذا الأصل\r"]], "pg": [164, 166]}, "540.157": {"x": [[166, "في أحكام الحدود على الجملة\r(اعلموا) (1) أن الحدود نوعان: أحدهما: حق لله عزوجل كحد الزنا وشرب الخمر. والثاني: حق لآدمي كالقصاص وحد القذف. وما كان منها حقا لله عزوجل قد يسقط بالتوبة ومن أقرّ بشيء منها أو قامت البينة عليه وجب على الإمام إقامته وذلك كحد الزنا وحد الخمر وقطع السارق وقتل المرتد والزنديق. وكل حد كان حقا لإنسان فلا يسقط إلا بعفو من له الحق كالقود وحد القذف. وقد أجمعوا على وجوب قتل المرتد إن لم يتب. وإنما اختلفوا في قتل المرتدة إذا ارتدت فأوجب الشافعي قتلها ومنع أبو حنيفة من قتلها ورأى استرقاقها. ويكون مال المرتد إذا قتل أو مات على ردّته فيئا وفيه الخمس، وقال أبو حنيفة: ما اكتسبه قبل ردّته لورثته المسلمين وما اكتسبه بعد ردّته يكون فيئا. وأجمعوا على أن حد البكر الحر في الزنا جلد مائة. واختلفوا في تغريبه فرآه الشافعي سنة وأباه أبو حنيفة. وإن كان الزاني الحر محصنا مسلما رجم. واختلفوا في رجم الذمي المحصن فرآه الشافعي وأباه أبو حنيفة. واختلفوا في حد العبد في الزنا فرآه أكثر الأمة نصف حد الحر وزعم داود أنه مثل حد الحر ووافقنا في أن حد الأمة نصف حد الحرة. وكذلك حد العبد في القذف والخمر حد الحر عند الجمهور. والصحيح من مذهب الشافعي أن حد الخمر أربعون للأحرار وللعبد عشرون. واختلفوا في شرب النبيذ فأوجب الشافعي به الحد سواء كان منه سكر أو لم يكن. وقال أبو حنيفة: لا حدّ فيه إلا إذا\r__________________"], [167, "(1) زيدت على الأصل.\r\rسكر منه الشارب. وقطع السرقة معلق بنصاب من حرز بلا شبهة خلاف قول الأزارقة بوجوب القطع في القليل والكثير. ومن اعتبر فيه النصاب اختلفوا في مقداره: فرآه الشافعي ربع دينار أو قيمته ورآه أبو حنيفة مقدار عشرة دراهم. فإن كان ذلك في المحاربة اجتمع فيها قطع اليد والرجل من خلاف. والمحارب إذا قتل وأخذ المال جاز صلبه. وحد القذف ثمانون للأحرار وأربعون للعبيد والإماء. وأجمعوا على أن الحدود لا تجب على الصبيان والمجانين. واختلفوا في الاقتصاص من المؤمن بالذمي ومن الحر بالعبد فأسقطه الشافعي وأثبته أبو حنيفة. وأجمعوا على أنه لا يقاد الوالد بولده ولا السيد بمملوكه إلا إذا قتل ولده غيلة فإن مالكا رأى فيه القود. وهذه جملة لا يسع جهلها وفروعه مبسوطة في كتب الفقه.\rالمسألة الثانية عشرة (من هذا الأصل) (1)\r"]], "pg": [166, 167]}, "540.158": {"x": [[167, "في المحرمات والمباحات"], [168, "قال أصحابنا إنّ أحكام الشريعة كلها خمسة أقسام: واجب ومحظور ومسنون ومكروه ومباح. فالواجب كل ما يستحق المكلف بتركه عقابا. والمحظور ما يستحق بفعله عقابا والمسنون ما يثاب فاعله ولا يعاقب تاركه. والمكروه ما يثاب تاركه ولا يعاقب فاعله. والمباح من أفعال المكلفين ما لم يكن في فعله ولا تركه ثواب ولا عقاب. وهذا المعنى حاصل في أفعال الصبيان والمجانين والبهائم ولا يقال لها مباحة. والجواز يجمعها كلها. وقد ورد الأمر بالمفروض والمسنون وورد النهي عن المحظور وعن المكروه. ولم يرد بالمباح أمر ولا عنه نهي. هذا قول أصحابنا. وزعم ابن الراوندي وطائفة من القدرية أن الأمر ما ورد إلا بالواجب وأن النوافل غير مأمور بها. ويلزمهم على هذا الأصل أن لا تكون النوافل طاعات ولو صحت طاعة لم يؤمر بها المطيع لصحت أيضا معصية لم ينه عنها العاصي. وزعم بعض المعتزلة البغدادية أنّا مأمورون بالمباح واعتل بأن فاعل المباح يترك به معصية وإذا كان منهيا عن المعصية فهو مأمور بتركها. ويلزمه على هذا الاعتلال أن تكون\r__________________\r(1) زيدت على الأصل.\r\rالمعصية مأمورا بها لأن كل معصية يترك بها فاعلها معصية سواها وكل كفر يترك به كفر سواه. وإذا بطل هذا القول بطل ما يؤدي إليه.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [167, 168]}, "540.159": {"x": [[168, "في أحكام الأموات"], [169, "وللأموات ثلاثة أحكام: منها حكم الكفن والمئونة والغسل والدفن ومنها حكم الديون والوصايا التي تقضى عنهم. ومنها حكم الميراث عنهم. فأما حكم الكفن والمئونة فإنه أول ما يبدأ به من رأس مال الميت قبل الديون والوصايا، من غير إسراف ولا تقصير على حسب العرف والعادة في يساره وإعساره. وإن تطوع أجنبي بكفنه ومئونة دفنه إبقاء لتركه على ديونه لم يجبر ورثته على قبول ذلك. وقيل للمتطوع إن أردت صلة الميت فاقض بعض ديونه. فإن لم يكن للميت مال فكفنه ومئونته على من كان يلزمه نفقته في حياته فإن لم يكن ففي بيت المال. فأما المرأة ذات الزوج فقد قال أبو حنيفة كفنها ومئونتها على الزوج وقال الشافعي: على ذوي الأنساب منها. فإن لم يكونوا أو عجزوا ففي بيت المال. وأما حكم الديون فإن كانت التركة تفيء ولا يفضل منها شيء قضيت الديون منها. وإن كانت تقصر عن الديون نظر فإن كان صاحب الدين واحدا دفعت التركة إليه بعد الكفن والمئونة.\rوإن كانوا جماعة نظر فإن كان بعضهم أولى من بعض كالمرتهن والمجني عليه ورادّ السلعة بالعيب ونحوهم فهو مقدم فيما هو أولى به على غيره. وإن كانت ديونهم في الذمة ولم يكن بعضهم أولى من بعض قسمت التركة بينهم على مقادير ديونهم. ولا فرق في ذلك بين ما ثبت عليه بيّنة وبين ما أقر به قبل موته عند الشافعي. وقدّم أبو حنيفة ما أقر به في حال الصحة على ما أقر به في حال المرض. وأجمعوا على أن ما أقر به الميت قبل موته مقدم في حال المرض. وأجمعوا على أن ما أقر به الميت قبل موته مقدم على ما أقر به الورثة بعد موته. فإن فضل منهم شيء قضي به ما أقر به الوارث. وأما وصاياه فمحدودة بالثلث في قول الأكثرين وللورثة رد ما زاد منها على ثلث الباقي من التركة بعد المئونة والديون. واختلفوا في عطاياه في مرضه الذي مات منه فاعتبرها أكثرهم من الثلث وجعلها أهل الظاهر من رأس"], [170, "المال إلا العتق في المرض فإنهم قالوا إنّه من الثلث. والعطايا في المرض مقدمة على الوصايا ويقدم، من كل واحدة منهما، ما قدمه إذا عجز الثلث عن الكل. وأما حكم الميراث فعلى حسب ما ذكره أهل الفرائض في كتبهم غير أن الذين أجمعوا عليه، الميراث بالفرض والتعصيب. وأجمعوا على أن الفروض ستة:\rالنصف والربع والثمن والثلثان والثلث والسدس.\rوأجمعوا على توريث عشرة من الذكور وهم الابن وابن الابن وإن سفل الأب والجد من قبل الأب وإن علا والأخ من أي وجه كان وابن الأخ لأب وأم أو لأب والعم لأب وأم أو لأب وابن العم لأب وأم أو لأب والزوج والمولى المعتق أو عصبة من الذكور. وأجمعوا على توريث سبع من الإناث الأم والجدة والبنت وبنت الابن والأخت والزوجة ومولاة النعمة. واختلفوا في ميراث ذوي الأرحام وفي مسائل كثيرة من فروع الفرائض. فمن أنكر منها شيئا مما أجمعوا عليه كفر. ومن خالف فيما اختلفوا فيه منها لم يكفر.\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [168, 170]}, "540.160": {"x": [[170, "في بيان مأخذ أحكام الشريعة\rاعلموا إنّ العقول تدل على صحة الصحيح واستحالة المحال وعلى حدوث العالم وتناهيه وجواز الفناء عليه جملة وتفصيلا وعلى إثبات صانعه وتوحيده وصفاته وعلى جواز بعثة الرسل من غير وجوب لذلك وعلى جواز تكليف العباد. ومنها دلالة على أنه لا واجب على أحد قبل ورود الشرع. ولو استدل مستدل قبل ورود الشرع على حدوث العالم وتوحيد صانعه وصفاته وعرف ذلك ما كان يستحق به ثوابا. ولو أنعم الله عليه بعد معرفته به نعما كثيرة كان ذلك تفضلا منه عليه. ولو كفر إنسان قبل ورود الشرع ما كان مستحقا عقابا وإن عذبه عليه كان ذلك عدلا منه كابتدائه [بإيلام] من لا ذنب له من الأطفال والبهائم. فأما الأحكام الشرعية في الوجوب والحظر والإباحة فطريق معرفته ورود الخبر والأمر من الله تعالى فيه بالخطاب أو على لسان رسول دلت المعجزة على صدقه. وكذلك العلم بتأبيد نعيم"], [171, "أهل الجنة وتأبيد عذاب الكفرة طريقه الخبر دون العقل وفي العقل دلالة على جواز ذلك كله. وكذلك بيان ما يجوز إطلاقه على الله تعالى من الأسماء طريقه الشرع دون العقل. وطريق المعرفة بالله تعالى في دار التكليف النظر والاستدلال عليه بدلائل العقول. ووجوب هذا الاستدلال بالشرع. وزعم قوم من الفقهاء أن أفعال العقلاء قبل الشرع على الحظر لا يباح شيء منها إلا بدلالة شرعية. ويلزمهم على هذا القول أن يكون اعتقاد الحظر على الحظر. وزعم أهل الظاهر أن أفعال العقلاء قبل الشرع على الإباحة فلا يحرم شيء منها إلا بشرع. ويلزمهم أن يكون اعتقاد الحظر مباحا وما جاز اعتقاد حظره فهو محظور. واوجبت القدرية الاستدلال والنظر من طريق العقل قبل الشرع من جهة الخواطر وزعموا أن قلب العاقل لا يخلو من خاطرين أحدهما من قبل الله تعالى يدعوه به إلى معرفته والاستدلال عليه. والثاني من قبل الشيطان الداعي له إلى الكفر وزعموا أن التكليف يتوجه عليه بهذين الخاطرين. وقيل لهم إن كان (1) [التكليف لا يتوجه إلا بهذين الخاطرين فإن كان ذلك الشيطان] ذلك الشيطان مكلّفا وجب تكليفه بخاطرين أحدهما من قبل الله تعالى والآخر من جهة شيطان آخر وصار الكلام في الشيطان الثاني كالكلام في الشيطان الأول حتى يتسلسل لا إلى نهاية من الشياطين والخواطر. وإن زعموا أن الشيطان غير مكلف فلم لعنوه وذموه وسموه عاصيا ظالما مستحقا للعقاب، وإن جاز أن يكون الشيطان غير مكلف فهلا جاز أن يكون الإنسان قبل ورود الشرع غير مكلف وهذا ما لا انفصال لهم عنه بحمد الله ومنّه. فإذا صح أن الأحكام الشرعية مدركة من الشرع دون العقل فأدلة الأحكام الشرعية من الشرع أربعة أنواع: القرآن والسنة والإجماع والقياس. والقرآن أدلته مختلفة: نص وظاهر وعموم وخصوص ودليل خطاب ولحن قول وتنبيه بالشيء على غيره وتصريح وتعريض وكناية وتأكيد. وكذلك وجوه الأدلة من السنة. وطريق السنة ثلاثة."], [172, "أحدها: التواتر الموجب للعلم الضروري وبمثله علمنا أعداد الصلوات المفروضة وأعداد ركعاتها وأكثر أركانها ونحو ذلك كثير.\r__________________\r(1) [التكليف لا يتوجه إلا بهذين الخاطرين فإن كان ذلك الشيطان].\r\rوالثاني: خبر جار مجرى التواتر بالاستفاضة يوجب العلم المكتسب كالاخبار الواردة في الرجم والمسح على الخفين وكأخبار الرؤية والحوض والشفاعة وعذاب القبر ونحو ذلك. ولا اعتبار فيه بخلاف أهل الأهواء.\rوالثالث: أخبار آحاد توجب العمل دون العلم بشروط: منها اتصال الإسناد ومنها عدالة الرواة ومنها جواز صحة متن الخبر من طريق العقل من غير استحالة. والقياس الشرعي أنواع: منها الجلي الذي يكون الفرع فيه أولى بالحكم من أصله. ومنها القياس الذي فرعه في معنى أصله؛ ليس أحدهما أولى بالحكم من الآخر. ومنها القياس بغلبة الأشباه والترجيحات. والإجماع المحتج به عندنا إجماع أهل كل عصر على حكم من أحكام الشريعة. وفي الأدلة الشرعية أنواع من الخلاف قد استقصيناها في كتبنا في أصول الفقه. وفيما ذكرناه هاهنا كفاية للمبتدئ في الصناعة.\rالمسألة الخامسة عشرة من هذا الأصل\r"]], "pg": [170, 172]}, "540.161": {"x": [[172, "في وجوه الفرق بين العقليات والشرعيات"], [173, "اعلموا إنّ الأمور العقلية يدل عليها العقل قبل ورود الشرع والأحكام الشرعية لا دليل عليها غير الشرع. والحكم العقلي في الشيء قد يكون لعينه مثل كون العرض سوادا وكون العرض مفتقرا إلى محل. وقد يدل الشيء في العقل لنفسه على غيره كدلالة الفعل لنفسه على فاعل. وكذلك الفعل لنفسه يدل على قدرة فاعله وعلمه به وإرادته له. وقد يكون الشيء في العقل دليلا على غيره لوقوعه على وجه لو وقع على خلافه لم يكن دليلا عليه كدلالة المعجزة، على صدق من ظهرت عليه، لوقوعها ناقضة للعادة. ولو جرت العادة بمثلها ما دلت على صدق الصادق. والأدلة الشرعية إما اسم أو دليل اسم أو معنى مودع في الاسم. ومن وجوه الفرق بين العقليات والشرعيات أن ما جاز فيه النسخ والتبديل في حياة النبي صلىلله عليه وسلم فهو من جملة الأحكام الشرعية وما لم يجز فيه النسخ والتبديل فهو من الأحكام العقلية. وهذه جملة كافية والحمد لله على كل حال.\r\rالأصل العاشر\r"]], "pg": [172, 173]}, "540.162": {"x": [[173, "من أصول هذا الكتاب في معرفة أحكام التكليف\rوالأمر والنهي والخبر\rيقع في هذا الأصل خمس عشرة مسألة. هذه ترجمتها:\rمسألة في بيان معنى التكليف.\rمسألة في بيان أقسامه وأنواعه.\rمسألة في شروط التكليف.\rمسألة في بيان ترتيب التكليف.\rمسألة في بيان أوصاف المكلف.\rمسألة في بيان ما يصح ورود التكليف به.\rمسألة في بيان أقسام الخطاب.\rمسألة في بيان وجوه الأمر والنهي.\rمسألة في بيان أقسام الأخبار.\rمسألة في بيان العموم والخصوص.\rمسألة في بيان المجمل والمفسر.\rمسألة في بيان أحكام المفهوم والدليل.\rمسألة في بيان أحكام الأفعال.\rمسألة في بيان نسخ الخطاب وإثباته.\rمسألة في بيان شروط النسخ وفروعه. فهذه مسائل هذا الأصل وسنذكر في كل [واحدة منها شروطها إن شاء الله تعالى] مسائل هذا الأصل شروطها.\r\rالمسألة الأولى من هذا الأصل\r"]], "pg": [173, 173]}, "540.163": {"x": [[173, "في بيان معنى التكليف"], [174, "التكليف في اللغة مأخوذ من الكلفة وهي التعب والمشقة يقال منه تكلّف الأمر إذا فعله على كلفة ومشقة فهذا أصله في اللغة. ثم أطلق التكليف في الشرع على الأمر والنهي لأن المأمور بالفعل يفعل ما أمر به على كلفة من غير أن يدعوه إليه طبعه. وإذا صحت هذه المقدمة في معنى التكليف قلنا معناه. توجه الخطاب بالأمر والنهي على المخاطب، فإن وجد مثل صيغة الأمر من النائم والمجنون والصبي الذي لا يعقل لم يكن أمرا ولا نهيا ولا تكليفا وإن وجد مثله من صبي يعقل معناه كان أمرا ونهيا وتكليفا ولكن لم يجب به على المخاطب شيء وكذلك تكليف من كلفه غيره فعل معصية لا يجب به شيء. وقد قال أصحابنا إنّ التكليف الذي يجب به شيء أو يحرم به شيء إنما هو أمر الله تعالى ونهيه. ولا يجب بأمر غيره شيء ولا يحرم بنهي غيره شيء. وإنما وجب على كل أمة طاعة نبيها واتباع أمره واجتناب نهيه لأن الله تعالى أمرهم بذلك. وكذلك لزوم طاعة الأبوين فيما أمرا به من أجل أن الله تعالى أمر بها لا من أجل أمرهما ولو لا إيجاب الله ما وجب على أحد شيء ولا حرم على أحد شيء.\rالمسألة الثانية من هذا الأصل\r"]], "pg": [173, 174]}, "540.164": {"x": [[174, "في بيان أقسام التكليف\rاختلف أصحابنا في أقسام التكليف: فمنهم من قال إنّ التكليف مقصور على ثلاثة أوجه: أمر ونهي وخبر. فالتكليف بالأمر كقوله: (أَقِيمُوا الصَّلاةَ) (1) ونحوه والتكليف بالنهي كقوله: (لا تَفْتَرُوا عَلَى اللهِ كَذِباً) (2) والتكليف بالخبر على ضربين: أحدهما في معنى الأمر كقوله تعالى: (وَالْمُطَلَّقاتُ يَتَرَبَّصْنَ\r__________________\r(1) سورة النساء آية 78.\r(2) سورة طه آية 61."], [175, "بِأَنْفُسِهِنَّ ثَلاثَةَ قُرُوءٍ) (1). والثاني خبر في معنى النهي كقوله تعالى: (لا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ) (2) ومنهم من قصر التكليف على الأمر والنهي. فأما الخبر عن وجوب شيء أو عن تحريمه فإنما حمل على معناه، بأمر الله تعالى أن يحمل عليه. ومنهم من قصر التكليف على معنى الأمر وقال إنّ النهي إنما صار تكليفا لأنه أمر بترك المنهي عنه وترك ضد المأمور بفعله. فهذا بيان أقسام التكليف في الجملة. وتفصيله أن التكليف على خمسة أقسام:\rأحدها: موجب وثانيها: محرم وثالثها: دليل على أن ما ورد به سنة ورابعها: دليل على أن ما ورد به مكروه وخامسها: دليل على إباحة ما ورد به من غير وجوب ولا حظر ولا كراهية ولا استحباب. وحقيقة الواجب ما يستحق بتركه العقاب والحرام ما يستحق بفعله العقاب كما بيناه قبل هذا.\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [174, 175]}, "540.165": {"x": [[175, "في بيان شروط التكليف\r(اعلموا) (3) أن التكليف عندنا إنما يحسن ممن لو ابتدأ بالألم لحسن منه. ومن قبح منه الابتداء بالألم من غير استحقاق فليس له تكليف غيره شيئا إلا أن يكون الله قد أمره بتكليف غيره. وزعمت القدرية أن حسن التكليف منوط بالتعريض للثواب وانكروا من الله تعالى ابتداء بإيلام لا على شرط ضمان العوض عليه. ومن شرط الأمر والنهي عندنا ورودهما ممن هو فوق المخاطب بهما ومن شرطهما أيضا بقاؤهما في احوال الوجوب والتحريم ولذلك بقي وجوب الفرائض وتحريم المحرمات إلى القيامة لأن الخطاب، الذي به أوجب الله تعالى الواجبات وبه حرم المحرمات، باق عندنا. ومن زعم من القدرية أنّ كلام الله حادث وأنّه قد فني يلزمه اسقاط وجوب كل واجب وإسقاط تحريم كل ما حرّمه. لأن سبب الشيء إذا بطل ارتفع\r__________________\r(1) سورة البقرة آية 227.\r(2) سورة الواقعة آية 79.\r(3) زيدت على الأصل."], [176, "حكمه. وإن الزمونا فناء أوامر النبي صلىلله عليه وسلم ونواهيه مع بقاء أحكامه علينا. قلنا وجوب اتباعه في ذلك إنما وجب علينا بأمر الله وأمره باق لا يجوز عدمه. وليس من شرط الأمر اقترانه بإرادة المأمور به. وزعمت القدرية البصرية أنّ ذلك من شرطه. وزعم الجبّائي أن الأمر إنما يكون أمرا إذا اقترنت به ثلاث إرادات: إرادة لحدوثه وإرادة لكونه أمرا وإرادة للفعل المأمور به. وهذا باطل بمن ذكر أن عبده لا يطيعه وكذّبه العبد في ذلك فأراد تصديق نفسه فأمره بفعل فإنه لا يريد منه الامتثال. وصح من هذا جواز الأمر بما لا يراد. وليس من شرط الأمر تعلقه بالواجب فحسب كما ذهب إليه ابن الراوندي. ويصح عندنا ورود الأمر بالنوافل لأنها طاعات ولا طاعة إلا مأمور بها كما لا معصية إلا منهي عنها. فأما المباح فغير مأمور به عندنا. وزعم بعض المعتزلة البغدادية أنه مأمور به لأنه يترك به محظور ما. ويلزمه على هذا الاعتلال أن يكون المحظور مأمورا به لأنه يترك به محظور آخر وهو ضده. وهذا مما لا انفصال له عنه.\rالمسألة الرابعة من هذا الأصل\r"]], "pg": [175, 176]}, "540.166": {"x": [[176, "في بيان ترتيب التكليف"], [177, "الصحيح عندنا قول من يقول: إنّ أول الواجبات على المكلّف النظر والاستدلال المؤدي إلى المعرفة بالله تعالى وبصفاته وتوحيده وعدله وحكمته. ثم النظر والاستدلال المؤدي إلى جواز إرسال الرسل منه وجواز تكليف العباد ما شاء. ثم النظر المؤدي إلى وجوب الإرسال والتكليف منه. ثم النظر المؤدي إلى تفصيل أركان الشريعة ثم العمل بما يلزمه منها على شروطه. واختلفت القدرية في هذا الباب. فمن زعم منهم أن المعارف ضرورية زعم أن الله تعالى يخلق في العاقل علما بكل ما يريد أن يكلفه به من أمره فإن لم يخلق له علما بشيء لم يكن مكلفا معرفته ولا الاستدلال عليه. وأما الذين قالوا منهم بأن العلوم بعضها مكتسب فقد اختلفوا في هذا فمنهم من قال: يلزم بأن العاقل بعد معرفته بنفسه أن يوافي بجميع معارف العدل والتوحيد وكل ما كلف الله تعالى بفعله، في الحالة الثانية من معرفته\r\rبنفسه بلا فصل. فإن لم يأت بذلك في تلك الحالة الثانية من معرفته بنفسه صار عدوّا لله كافرا. هذا فيما يعرفه بعقله فأما الذي لا يعرفه إلا بالسمع فعليه أن يوافي بمعرفته في الحال الثانية من حال سماعه للأخبار ولا حجة عليه فيها قبل انتهاء الخبر إليه الذي يقطع العذر. وهذا قول أبي الهذيل. وقال بشر بن المعتمر إنّ الحال الثانية حال فكر واعتبار وعليه أن يأتي بالمعارف العقلية في الحال الثالثة. وزعم أكثرهم أن المعارف الكسبية لا تصاب (1) إلا بعد سبر ونظر ولا بد فيها من إمهال إلى مدة يمكن استدراك (2) تلك المعارف فيها. وهذا قول الإسكافي وجعفر بن حرب وجعفر بن مبشر والكعبي. ويجب على قود أصول جماعتهم أن يبطلوا قولهم بأن أطفال المؤمنين والكافرين يكونون في الجنة لأن الذين ماتوا بعد انقضاء مدة كان يمكنهم فيها الاستدلال فإذا لم ينظروا وجب على أصلهم كفرهم واستحقاقهم العقاب وفي هذا بيان مناقضاتهم (3).\rالمسألة الخامسة من هذا الأصل\r"]], "pg": [176, 177]}, "540.167": {"x": [[177, "في أوصاف المكلّف والمكلّف"], [178, "ومن شرط المكلّف الآمر أن يكون حيّا وعالما بما يأمر به. ولذلك لم يكن النائم آمرا ولا ناهيا وإن تكلم بصيغة تشبه صيغة الأمر والنهي لأنه غير عالم بما قاله. ومن شرطه عندنا أن يكون الآمر بالشيء ناهيا عن ضده ولهذا قلنا إنّ الآمر بالشيء نهى عن ضده خلاف قول القدرية إنّ الأمر بالشيء لا يكون نهيا عن ضده. ومن شرط من يأمر عندنا، مع كونه عالما، أن يكون عارفا بأن المأمور على وصف معه يصح كونه مأمورا. ومن شرط من يحسن الأمر منه منا، أن يكون الله قد أذن له في الأمر بما يأمر به وفي النهي عما ينهى عنه. واختلفوا في صفة المأمور فمن أجاز تكليف العاجز وتكليف المحالات قال يجب (4) أن يكون المأمور كامل\r__________________\r(1) [لا تستفاد].\r(2) [استدلال].\r(3) [في أصولهم].\r(4) [يجب بشرط واحد وهو أن يكون].\r\rالعقل ليصح كونه عالما بأنه مأمور. ومن أحال من أصحابنا تكليف العاجز وتكليف المحالات قال يحتاج المأمور في حال تضييق الوجوب عليه إلى (1) كمال العقل وإلى أن يكون قادرا إما على الفعل وإما على تركه لكي يصح منه الطاعة بفعل المأمور به أو المعصية بتركه. ويجب على هذا القول أن يكون عالما بصفات ما أمر به وشروطه وفي حكم العالم بذلك من يصح منه النظر المؤدي إلى المعرفة. ويجب على هذا القول أن يكون الدليل منصوبا على ما كلف به. وقالت القدرية من شرطه أيضا أن يكون قادرا على المأمور به وعلى جنس ضده في حال ورود الأمر. ولم يوجبوا كونه قادرا عليه في حال وقوعه. وقال أصحابنا بوجوب كونه قادرا على ما أمر به في حال كونه فاعلا له. ولم يوجبوا كونه قادرا عليه قبل ذلك. وأوجبوا أيضا كون المأمور قادرا على فعل الإرادة للفعل المأمور به. وليس هذا من شرطه عندنا لأنه يجوز أن يخلق الله تعالى فيه إرادة ضرورية يريد بها فعل المأمور به.\rالمسألة السادسة من هذا الأصل\r"]], "pg": [177, 178]}, "540.168": {"x": [[178, "في بيان ما يصح ورود التكليف به"], [179, "قال أصحابنا: جائز من الله تعالى أن يأمر بكل ما ورد أمره به ولو نهى عما أمر به جاز وكذلك لو أمر بما نهى عنه جاز. فإذا سئلوا على هذا الأصل هل كان جائزا أن ينهى عن الصلاة والزكاة والصيام قالوا لو نهى عن ذلك لم يكن نهيه عنه أعجب من نهي الحائض والنفساء عن الصلاة ونهي العباد عن الصيام في عيدي الفطر والنحر وفي الليل ولم يكن النهي عن الحج إلى الكعبة أعجب من النهي عن الحج إلى البيت الذي هو بمولتان ونحو ذلك. وإذا قيل لهم هل كان جائزا أمره بما قد نهى عنه من الكبائر. قالوا قد كان شرب الخمر مباحا في أول الإسلام ثم حرّمه. وكان نكاح الأخت مباحا في وقت آدم عليه السلام لأنه زوج بناته من بنيه ثم حرّمه بعد ذلك. وإذا قيل لهم هل كان جائزا ورود الأمر بالكفر، قالوا: إن أردتم بذلك النطق بكلمة الكفر أجزناه كما أباحها حال التقية والإكراه وإن أردتم الأمر باعتقاد الكفر لم يجز ذلك لتناقضه. وذلك أن من شرط المأمور معرفته بتوجه أمر\r__________________\r(1) [الى أربع شرائط: الى كمال العقل].\r\rالآمر عليه ولا يعرف توجه أمر الله عليه إلا من عرف الله ولا يصح منه الجمع بين معرفة الله وتوحيده وبين اعتقاده الكفر به. فلم يصح ذلك للتناقض والاستحالة. وقد بينا قبل هذا أن الوجوب والحظر والاباحة كل ذلك مستفاد بالشرع دون العقل وإن كان العقل دالّا على جواز ورود الشرع. وزعمت القدرية أن الأمر لا يصح وروده من الإله عزوجل إلا بما فيه صلاح المأمور وتعريضه لأسنى المنازل. وقد تكلمنا عليهم في هذه المسألة قبل هذا بما فيه كفاية.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [178, 179]}, "540.169": {"x": [[179, "في بيان أقسام الخطاب"], [180, "قد قسم النحويون الخطاب المفيد من طريق العبارة ثلاثة أقسام: اسما وفعلا وحرفا جاء لمعنى. وحقيقة الاسم عندهم ما صح إسناد الفعل إليه وما صحت إضافته والإضافة إليه وما صح دخول حرف الجر عليه وكل ما دل على معنى مفرد فهو اسم. والفعل لا يصح إضافته ولا دخول حرف الجر عليه ولا يدل على معنى وإنما يدل على معنى وزمان ماض أو مستقبل أو راهن. والحرف كلمة معناها في غيرها ولا تدل بانفرادها على شيء وقسم أصحاب المعاني الخطاب على أربعة أوجه: أمر ونهي وخبر واستخبار، وقالوا: إنّ الطلب والشفاعة داخلان في صيغة الأمر وإن لم يجز تسميتها أمرا، والتمني والتلهف ولفظ النفي والاستثناء والتعجب كل ذلك داخل في أقسام الخبر. ورد بعض أصحابنا الخطاب المفيد إلى ثلاثة أقسام: أمر ونهي وخبر. وقال: الاستخبار طلب الخبر والطلب من فروع صيغة الأمر. وقال آخرون من أصحابنا إنّ الخطاب المفيد كله قسمان: أمر وخبر. لأن الاستخبار طلب في صيغة الأمر. والنهي عندنا داخل في ضمن الأمر. لأن الأمر بالشيء نهي عن ضده والنهي عن الشيء أمر بضد من أضداده فرجع الخطاب كله إلى معاني الأمر والخبر.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [179, 180]}, "540.170": {"x": [[180, "في بيان وجوه الأمر والنهي\rاختلفوا في الأمر إذا ورد ممن يلزم المأمور طاعته. فقال مالك والشافعي وأبو"], [181, "حنيفة وعامة الفقهاء بأن ظاهره يقتضي الوجوب ولا يحمل على غيره إلا بدلالة. وحملته القدرية على الندب. وقالت الواقفية لا يحمل على وجوب ولا على ندب ولا على غيرهما إلا بدلالة. وبه قال أبو الحسن الأشعري وابن الراوندي. والصحيح عندنا أنه للوجوب بظاهره ويصرف بالدلالة عن الوجوب إلى وجوه [ثمانية] منها الندب والترغيب كقوله تعالى: (فَكاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْراً) (1). ومنها الإرشاد إلى الأحوط كقوله: (وَأَشْهِدُوا إِذا تَبايَعْتُمْ) (2). ومنها الإباحة كقوله: (وَإِذا حَلَلْتُمْ فَاصْطادُوا) (3). ومنها الطلب والمسألة كقوله: (رَبَّنا آمَنَّا فَاغْفِرْ لَنا وَارْحَمْنا) (4) ومنها التهديد والوعيد كقوله: (اعْمَلُوا ما شِئْتُمْ) (5). ومنها الإهانة كقوله: (ذُقْ إِنَّكَ أَنْتَ الْعَزِيزُ الْكَرِيمُ) (6). ومنها التأديب كامر النبي صلىلله عليه وسلم بعض الناس أن يأكل من بين يديه. ومنها أمر التكوين كقوله للشيء: (كُنْ فَيَكُونُ) (7). وظاهر النهي للتحريم ولا يصرف إلى معنى التنزيه إلا بدلالة. ومن توقف في الأمر توقف في النهي إلى أن يرد ما يبيّنه. وناقضت القدرية في فرقها بين الأمر والنهي لأنها سلمت لنا أن النهي يقتضي تحريم المنهي عنه وزعمت أن الأمر لا يقتضي وجوب المأمور به. واختلفوا في النهي المحرم هل يقتضي فساد المنهي عنه أم لا. فزعمت القدرية أنه يقتضي التحريم ولا يدل على الفساد إلا بدلالة سواه. وقال جمهور الفقهاء بدلالته على الفساد. وزعم بعض أصحاب الشافعي أن النهي إذا كان لمعنى في المنهي عنه أفسده وإذا كان لحق الغير لم يفسده كالنهي عن الصلاة في الأرض المغصوبة وعن الذبح بالسكين المغصوب والوضوء بالماء المسروق.\r__________________\r(1) سورة النور آية 33.\r(2) سورة البقرة آية 282.\r(3) سورة المائدة آية 2.\r(4) سورة المؤمنون آية 110.\r(5) سورة فصلت آية 40.\r(6) سورة الدخان آية 49.\r(7) سورة يس آية 82."], [182, "المسألة التاسعة من هذا الأصل\r"]], "pg": [180, 182]}, "540.171": {"x": [[182, "في بيان أقسام الأخبار\rالخبر لا يخلو من أن يكون صدقا أو كذبا، والصدق منه ما وافق مخبره والكذب منه ما كان خلاف مخبره. ولا يجوز أن يكون خبر واحد صدقا وكذبا إلّا في مسألة واحدة وهي رجل لم يكذب قط [ثم] قال: إني كاذب فإن هذا الخبر كذب منه وهو به كاذب وصادق من حيث أن الكاذب إذا أخبر عن نفسه بأنه كاذب كان صادقا. وفي هذا إبطال قول الثنوية إنّ فاعل الصدق لا يفعل الكذب وفاعل الكذب لا يفعل الصدق وإن النور هو الذي يفعل الصدق والظلام هو الذي يفعل الكذب. فسألناهم عن فاعل الخبر الذي هو صدق وكذب فأي الفاعلين نسبوه إليه بزعمهم لزمهم نسبة الصدق والكذب معا إليه وهذا خلاف بقولهم. وصيغة الخبر لا يفترق فيها المخبرون باختلاف أحوالهم في كونه صدقا أو كذبا. هذا أصلنا في هذا الباب. وزعمت الديصانية من الثنوية أن الكذب يصح من غير قصد إليه ولا علم به والصدق لا يصح إلّا من عالم به قاصد إليه. وزعم المتأخرون من القدرية أن خبر النائم لا يكون صدقا ولا كذبا لأنه خال عن قصده. وللكرّامية في هذه المسألة بدع ما سبقوا إليها. منها أن بعضهم زعم أن حقيقة الصدق هو الخبر الذي تحته معنى والكذب هو الخبر الذي لا معنى تحته. وزعم المعروف منهم بالشورميني أن الصدق هو الخبر الذي لك أن تخبر به والكذب ما لا يجوز لك الإخبار به. وزعم أن السعاية والنميمة كذب وإن كان على ما أخبر عنه. وزعم بعض الكرّامية أن الصدق هو الخبر والكذب في صورة الخبر وليس بخبر. وهذه أقوال خارجة عن إجماع المتكلمين قبلهم ولا يستحق الكلام عليها.\rالمسألة العاشرة من هذا الأصل\r"]], "pg": [182, 182]}, "540.172": {"x": [[182, "في بيان أقسام العموم والخصوص\rالعموم ما ينتظم جمعا من الأسماء أو المعاني ومعناه الشمول. ومعنى الخصوص الأفراد. وهو على وجهين أحدهما: يتناول شيئا بعينه، والآخر: خصوص بالإضافة إلى ما هو أعم منه وإن كان عموما في نفسه كالحيوان خصوص"], [183, "في الأجسام وعموم في أنواعه. والأسماء المحمولة على العموم كثيرة منها اللفظ الموضوع للجمع بلا علامة للجمع وهذا نوعان، أحدهما: ماله واحد من لفظه كالناس والأنس والجن. والثاني: ما ليس له واحد من لفظه كالخيل والإبل والبقر والغنم والنساء. ومنها اسم موضوع للجمع بعلامة الجمع التي هي الواو والنون والياء والنون في الذكور العقلاء والألف والتاء في جمع الإناث وما لا يعقل. ومنها اسم الجنس المفرد إذا دخل عليه لام التعريف من غير إشارة إلى معهود قد سبق ذكره كقوله: (وَالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُوا أَيْدِيَهُما) (1). وقوله: (الزَّانِيَةُ وَالزَّانِي فَاجْلِدُوا كُلَّ واحِدٍ مِنْهُما مِائَةَ جَلْدَةٍ) (2). ومنها الأسماء المبهمة مثل من وما وأين وكيف ومتى وأي. ومنها ألفاظ يؤكد بها العموم مثل كل واجمعون واكتعون وابصعون. وقد اختلفوا في صيغة الجمع إذا كانت مطلقة عن قرينة التخصيص منها: فتوقفت الواقفية فيها إلى أن يكشف الدليل عن المراد بها من عموم أو خصوص وحملها أصحاب الخصوص على ثلاثة وتوقفوا في الزيادة عليها إلى أن يكشف الدليل عن المراد بها. وحملها جمهور الفقهاء وكثير من المتكلمين من أصحابنا وغيرهم على العموم في جنسها ولم يخصوا شيئا منها إلّا بدلالة. واختلفوا في أقل الجمع العددي، فزعم أهل الظاهر أنه اثنان، وقال الشافعي ومالك وأبو حنيفة أنه ثلاثة. وأجمع أصحابنا على جواز تخصيص القرآن بالقرآن وعلى جواز تخصيصه بالخبر المتواتر والخبر المستفيض الذي يجري مجرى المتواتر. وأجمعوا على تخصيص السنة بالقرآن والسنة بالسنة. وأما تخصيص القرآن بخبر الواحد فقد أجازه أكثر أصحابنا وأباه بعض المتأخرين منهم. والقياس إذا كان جليا أو في معنى أصله جاز تخصيص العموم به. وأما القياس الخفي فالخلاف في تخصيص العموم به كالخلاف في تخصيص العموم بخبر الواحد.\rالمسألة الحادية عشرة من هذا الأصل\r"]], "pg": [182, 183]}, "540.173": {"x": [[183, "في بيان المجمل والمفرد"], [184, "قال أصحابنا: إن المجمل الذي يحتاج إلى تفسير على أقسام [سبعة]:\r"]], "pg": [183, 184]}, "540.174": {"x": [[184, "__________________\r(1) سورة المائدة آية 38. (2) سورة النور آية 2.\r\rأحدها: أن يكون الإجمال واقعا في الحكم والمحكوم فيه كقول القائل: لفلان في بعض أموالي حق. فالحق الذي هو الحكم مجمل لأنه لا يعلم وصفه ولا مقداره والمال الذي هو المحكوم فيه مجمل أيضا. والقسم الثاني: أن يكون الحكم مجملا والمحكوم فيه معلوما كقوله تعالى: (وَآتُوا حَقَّهُ يَوْمَ حَصادِهِ) (1). فالحق مجمل لا يعلم وصفه ولا مقداره والمحكوم فيه معلوم وهو الزرع الموصوف بالحصاد. وكذلك قوله: (حَتَّى يُعْطُوا الْجِزْيَةَ عَنْ يَدٍ وَهُمْ صاغِرُونَ) (2)، لأن الجزية غير معلوم عن الآية وصفها ومقدارها والمحكوم عليه بالجزية معلوم وهو الكتابي (3) [ومن معناه]. والقسم الثالث: أن يكون المحكوم فيه مجملا والحكم معلوما كقول الرجل: طلقت إحدى نسائي وأعتقت إحدى ممالكي (4) [مماليكي]، فالحكم معلوم وهو الطلاق والعتق والمحكوم فيه (5) [عليه] بالطلاق والعتق مجمل. والقسم الرابع أن يكون الحكم والمحكوم له مجملين والمحكوم عليه معلوما كقوله: (وَمَنْ قُتِلَ مَظْلُوماً فَقَدْ جَعَلْنا لِوَلِيِّهِ سُلْطاناً) (6)، فالقاتل معلوم وهو المحكوم عليه والولي محكوم له وسلطانه حكمه وهما مجملان.\rوالقسم الخامس: أن يكون الإجمال في اللفظ من جهة صلاحه لمعنيين. أجمعت الأمة على أن المراد به أحدهما كآية القرء لوقوع القرء على الحيض والطهر. لكن لما أجمعوا على أن المراد به أحدهما صار مجملا يعلم المراد منه بدلالة سواه.\rوالقسم السادس: أن يكون اللفظ في نفسه معلوما وصار مجملا باستثناء\r__________________\r(1) سورة الأنعام آية 141.\r(2) سورة التوبة آية 30.\r(3) [ومن معناه].\r(4) مماليكي].\r(5) [عليه].\r(6) سورة الإسراء آية 33."], [185, "مجمل لحق به كقوله: (أُحِلَّتْ لَكُمْ بَهِيمَةُ الْأَنْعامِ إِلَّا ما يُتْلى عَلَيْكُمْ) (1). ونظيره من السنة قوله صلىلله عليه وسلم: أمرت أن اقاتل الناس حتى يقولوا لا إله إلّا الله فإذا قالوها عصموا منّي دماءهم وأموالهم إلّا بحقّها (2).\rوالقسم السابع: أن يكون اللفظ معقول المعنى في اللغة وضمت الشريعة إليه شروطا كلفظ الصلاة والزكاة والصوم والحج والعمرة ونحوها. فهذه اقسام المجملات في القرآن والسنة وفي كلام الناس. وكل نوع منها يصير معلوما بدليله الكاشف عن المراد به. ولا يجوز الاستدلال به الا مقرونا بما يدل على المراد به. وإذ قد بينا [من] حكم المجمل والمفسر بابا نعطف (3) عليه بيان حكم المحكم والمتشابه من القرآن. وقد اختلفوا في ذلك فزعم قوم من القدرية مثل واصل بن عطاء وعمرو بن عبيد [إلى] أن المحكمات من القرآن ما فيه من وعيد الفساق بالعقاب والمتشابهات ما أخفى الله عزوجل عن العباد عقابه وقد حرّمه كالنظرة والكذبة وهي التي لا يعلم تأويلها إلا الله أي لا يعلم أحد هل يقع العقاب على الصغيرة أم لا، إلّا الله، وهذا قول فاسد لأنه يوجب أن تكون الآيات التي ليس فيها ذكر وعد ولا وعيد لا محكمة ولا متشابهة. وزعم الأصم أن المحكمات هي التي احتج الله عزوجل بها على المقرين بوجودها كاحتجاجه على أهل الكتاب بما في كتبهم من أخبار الأمم الماضية وعقابها على عصيانها وكفرها. وكذلك احتجاجه على المشركين بأنه خلقهم من الماء ونقلهم من الاصلاب إلى الأرحام وبأنهم يموتون ونحو ذلك مما شاهدوه. والمتشابه ما احتج به على المشركين في البعث والنشور ونحو ذلك مما يعرف بالنظر والاستدلال فابتغوا فيه الفتنة. وهذا القول أيضا يوجب أن تكون الآيات التي نزلت في بيان الأحكام لا على طريق الاحتجاج لا محكمة ولا متشابهة. وزعم الاسكافي أن المحكمات كل آية لها\r__________________\r(1) سورة المائدة آية 1."], [186, "(2) أخرجه الترمذي عن أبي هريرة برقم 2606 و 2607 وأخرجه الحاكم في المستدرك عن أبي هريرة 1/ 387 وعن جابر 2/ 522.\r(3) [فلنعطف].\r\rمعنى لا يحتمل غيره والمتشابه ما احتمل تأويلين أو أكثر واختلف أصحابنا في إدراك علم تأويل الآيات المتشابهة. فذهب الحارث المحاسبي وعبد الله بن سعيد وأبو العباس القلانسي إلى أن المتشابه هو الذي لا يعلم تأويله إلا الله. وقالوا منها حروف الهجاء في أوائل السور. وهذا قول مالك والشافعي وأكثر الأمة. ومن قال بهذا وقف على قوله: (وَما يَعْلَمُ تَاوِيلَهُ إِلَّا اللهُ) (1)، ثم ابتدأ من قوله: (وَالرَّاسِخُونَ فِي الْعِلْمِ يَقُولُونَ آمَنَّا بِهِ كُلٌّ مِنْ عِنْدِ رَبِّنا) (2). وكان شيخنا أبو الحسن الأشعري يقول: لا بد من أن يكون في كل عصر من العلماء من يعلم تأويل ما تشابه من القرآن. وإليه ذهبت المعتزلة ووقفوا من الآية على قوله والراسخون في العلم والوقف الأول أصح عندنا وبه قال ابن عباس وابن مسعود وأبيّ بن كعب. وفي مصحف أبيّ: وما يعلم تأويله إلّا الله ويقول الرّاسخون في العلم آمنّا به. وكذلك روى عبد الرزاق عن معمر عن طاوس عن ابن عباس. وفي مصحف ابن مسعود: «ابتغاء الفتنة وابتغاء تأويله وإن تأويله إلّا عند الله» ثم قال: «والراسخون في العلم، برفع الراسخين دون كسره. وكل ذلك تأكيد للوقف الذي أخبرناه (3) وهو أيضا اختيار أكثر النحويين كيحيى بن يعمر وأبي عبيدة والأصمعي وثعلب.\rالمسألة الثانية عشرة من هذا الأصل\r"]], "pg": [184, 186]}, "540.175": {"x": [[186, "في بيان المفهوم ودليل الخطاب\rمفهوم الخطاب عبارة عما يدل عليه الخطاب، من حكم ما لا يدخل في لفظه، بموافقته [لكن يوافقه] في معناه كقول الله تعالى (فَلا تَقُلْ لَهُما أُفٍ) (4) ومفهومه أن ضربهما وشتمهما أولى بالتحريم. وكذلك قوله: (فَإِنْ أَتَيْنَ بِفاحِشَةٍ فَعَلَيْهِنَّ نِصْفُ ما عَلَى الْمُحْصَناتِ مِنَ الْعَذابِ) (5)، مفهومه أن تنصيف حد العبد\r__________________"], [187, "(1) سورة آل عمران آية 7.\r(2) سورة آل عمران آية 7.\r(3) [اخترناه].\r(4) سورة الإسراء آية 23.\r(5) سورة النساء آية 24.\r\rكتنصيف حد الأمة. وكل ما لحق الخطاب في موافقة حكمه فمفهوم الخطاب دليل عليه وإن لم يكن منظومه دليلا عليه. وأما دليل الخطاب فهو عند أصحاب الشافعي عبارة عن دلالة الخطاب على خلاف حكمه في غير ما تناوله الخطاب. وذلك أن الخطاب قد يعلق على عدد وعلى غاية وعلى صفة؛ فإن علق على عدد فتارة يدل على أن ما دونه بخلافه كقوله: «إذا بلغ الماء قلتين لم يحمل خبثا» (1)، دليل على أن ما دون القلتين ينجس بكل نجاسة وقعت فيه. وتارة يدل على أن ما زاد عليه بخلافه كتحديد الحدود دليل على أنه لا يجوز الزيادة عليها. وأما الصفة فإن علق الحكم على الوصف الأعلى كان الوصف الأدنى بخلافه كقول النبي صلىلله عليه وسلم: في سائمة الغنم زكاة، دليل على أن المعلوفة لا زكاة فيها. وإن علق الحكم على الوصف الأدنى كان الوصف الأعلى بذلك [الحكم] أولى. فلو ورد الخبر بإيجاب الزكاة في المعلوفة لكانت السائمة بوجوب الزكاة فيها أولى. ولهذا قال الشافعي رضي الله عنه إن الله تعالى لما أوجب الكفارة بالقتل خطأ كان العمد بوجوب الكفارة فيه أولى. وإن علق الحكم على الغاية دل على أن ما وراءها بخلافها. وقد اتفق أهل الرأي والحديث في الغاية. وإنما منع أهل الرأي دليل الخطاب في الوصف والسلم.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [186, 187]}, "540.176": {"x": [[187, "في بيان أحكام الأفعال [أفعال النبي عليه السلام]\rالمقصود من هذه المسألة معرفة أحكام أفعال النبي صلىلله عليه وسلم. وهي على عشرة أقسام:\rأحدها: ما فعله ممتثلا لأمر قد أمر به كوضوئه وصلاته ونحوهما. وهذا النوع منه تابع للأمر فإن كان الأمر به على الوجوب ففعله على الوجوب وإن كان على الندب ففعله على الندب. والثاني: أن يكون فعله بيانا لجملة مجملة وهو على\r__________________"], [188, "(1) أخرجه الحاكم في المستدرك عن عبد الله بن عمر وأوله: «إذا بلغ الماء قلتين أو ثلاثا» 1/ 134.\r\rالوجوب إن كان ذلك المجمل واجبا وعلى الندب أن أمرنا به ندبا. وهذا كبيانه في أركان الصلاة وأركان الحج بفعله ولذلك قال: صلّوا كما رأيتموني وخذوا عنّي مناسككم».\rوالثالث: ما يفعله من المباحات من أكل وشرب وحركة وقيام وقعود [ونحو ذلك] فهو على الإباحة.\rوالرابع: قضاؤه بين خصمين في شيء فهو على الوجوب\rوالخامس: ما فعله بين شخصين على التوسط بينهما فيكون ذلك على الاستحباب.\rوالسادس: إقامته للحدود والعقوبات وذلك كله على الوجوب.\rوالسابع: ما كان تصرفا منه في ملك غيره فذلك موقوف على معرفة سببه.\rوالثامن: ما كان من بيان فعله بفعله كما روي: إن آخر الفعلين منه ترك الوضوء مما مسّته النار وفيه دليل على نسخ وجوب الوضوء منه.\rوالتاسع: تركه إنكار ما فعل بحضرته فيكون ترك النكير دليلا على إباحته.\rوالعاشر: أفعاله التي تجري مجرى القرب مما ليس فيه نص على حكمه. وقد اختلف أصحابنا في ذلك: فمنهم من قال إنها على الوجوب إلا ما علم بالدلالة أنه أراد به غير الوجوب. ومنهم من توقف فيها ولم يحملها على وجوب ولا ندب ولا إباحة إلّا بدلالة.\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [187, 188]}, "540.177": {"x": [[188, "في بيان نسخ الخطاب\rوحكم النسخ عندنا على ضربين:\rأحدهما: نسخ جميع الحكم كنسخ وجوب الوصية للوالدين والأقربين بميراثهم."], [189, "والثاني: نسخ بعض حكم الشيء كالصلاة إلى بيت المقدس نسخ منها التوجه [إليه بالتوجه إلى الكعبة] إلى الكعبة. ومعنى النسخ عندنا بيان انتهاء مدة العبادة. فإن ورود الأمر بالعبادة يوقت بغاية فذلك بيان نهاية وليس بيان انتهاء. وزعم أكثر اليهود أن الأمر إذا ورد مطلقا لم يجز ورود نسخ حكمه بعده. وأجاز آخرون منهم النسخ من طريق العقل وقالوا إنما [لم نقل] بنسخ شريعة موسى عليه السلام لأنه أمرنا بالتمسك بها أبدا. وزعم بعض القدرية من أهل عصرنا أنه ليس في القرآن آية منسوخة ولا آية ناسخة وهو أبو مسلم الأصبهاني ولا اعتبار بخلافه في هذا الباب مع تكذيبه لقول الله تعالى: (ما نَنْسَخْ مِنْ آيَةٍ أَوْ نُنْسِها نَاتِ بِخَيْرٍ مِنْها أَوْ مِثْلِها) (1). ومن أنكر جواز النسخ عقلا زعم أنه يوجب البداء وأن يكون القبيح حسنا والعدل جورا. وهذا غلط منهم لأن الذي يجوز عليه البداء من خفي عليه العواقب فأما عالم الغيوب فإنه إذا أمر بشيء مطلقا ثم نسخه علمنا بنسخه أن مراده بالأمر الأول إنما كان إلى الوقت الذي نهى عن فعل مثله ولم يظهر له شيء كان مستورا عنه ولم ينه في الثاني عما أمر به في الأول وإنما نهى عن فعل مثله فلم تكن الطاعة معصية ولا العدل جورا ولكن ما كان طاعة في وقت صار مثله بعد النسخ معصية وهذا غير مستحيل في العقل.\rالمسألة الخامسة عشرة من هذا الأصل\r"]], "pg": [188, 189]}, "540.178": {"x": [[189, "في بيان شروط النسخ\rشروط النسخ كثيرة منها: أن يكون الناسخ منفصلا عن المنسوخ. فإن كان توقيت العبادة مبيّنا في الأمر بها فليس توقيتها نسخا لها [بل هو بيان نهاية]. وإن كان الحكم معلقا بغاية مجهولة كان بيان تلك الغاية بعدها نسخا [كقول الله: (حَتَّى يَتَوَفَّاهُنَّ الْمَوْتُ)] (2) كما لو قال: افعلوه إلى أن أنسخه عنكم. ومنها أن لا يعلم المنسوخ إلا بنص يرد فيها. فأما الغاية التي يعلم سقوط الفرض عندها بلا نص\r__________________\r(1) سورة البقرة آية 106."], [190, "(2) سورة النساء آية 15.\r\rفليست بنسخ ولذلك لم يكن سقوط الفرض بالعجز والموت نسخا له. ومنها أن يكون الناسخ والمنسوخ في رتبة واحدة من جهة إيجاب العلم والعمل (1) أو يكون (2) الناسخ أقوى في ذلك من المنسوخ (3) فعلى هذا الأصل يجوز نسخ القرآن بالقرآن ونسخ السنة بالقرآن. واختلفوا في نسخ القرآن بالسنة فأجاز أصحاب الرأي نسخة بالسنة المتواترة. ومنع أصحاب الشافعي من نسخ القرآن بالسنة. ويجوز نسخ خبر الواحد بمثله وبالمتواتر ولا يجوز نسخ المتواتر بخبر الواحد ويجوز بمثله. ولا يجوز نسخ شيء من القرآن والسنة بالقياس. واجمع الفقهاء على جواز تخصيص العموم بالقياس الجلي إلّا من لا يقول بالقياس. واختلف أهل القياس في تخصيص العموم بالقياس الخفي فأجازه أكثرهم وأباه قوم منهم والجواز أصح.\r__________________\r(1) [أو العمل].\r(2) [ولم يكن].\r(3) [فإن كان مما يوجب العلم والعمل كان الناسخ أيضا مثله وإن كان المنسوخ موجبا للعمل دون العلم جاز نسخه بما يوجب العمل وكان نسخه بما يوجب العلم والعمل أولى بالجواز].\r\rالأصل الحادي عشر\r"]], "pg": [189, 190]}, "540.179": {"x": [[190, "من أصول هذا الكتاب\rفي معرفة أحكام العباد في المعاد\rهذا الأصل مشتمل على خمس عشرة مسألة هذه ترجمتها:\rمسألة في إجازة فناء الحوادث.\rمسألة في بيان كيفية الفناء على ما يفنى.\rمسألة في إجازة إعادة ما يفنى.\rمسألة في نفس ما يصح إعادته.\rمسألة في بيان ما يعاد من الأجسام والأرواح.\rمسألة في بيان ما يعاد من الحيوانات.\rمسألة في أن الإعادة هل هي واجبة أم جائزة.\rمسألة في خلق الجنة والنار.\rمسألة في دوامهما ودوام ما فيهما.\rمسألة في أن الله تعالى فاعل نعيم أهل الجنة وعذاب أهل النار.\rمسألة في أن الله قادر على الزيادة في النعيم والعذاب.\rمسألة في تعويض البهائم في الآخرة.\rمسألة في حكم أهل الوعيد ومن يرد عذابه.\rمسألة في إثبات الشفاعة."], [191, "مسألة في إثبات الحوض والصراط والميزان وسؤال منكر ونكير وعذاب القبر وما يجري مجرى ذلك. فهذه مسائل هذا الأصل وسنذكر في كل واحدة منها مقتضاها إن شاء الله تعالى.\r\rالمسألة الأولى من هذا الأصل\r"]], "pg": [190, 191]}, "540.180": {"x": [[191, "في إجازة فناء الحوادث\rأجاز أصحابنا وأكثر الأمة فناء جميع العالم جملة وتفصيلا وقالوا إن الذي خلقها قادر على إفناء جميعها وقادر على إفناء بعضها. وهذا التجويز إنما هو في الأجسام فأما في الأعراض فكل عرض واجب عدمه في الثاني من حال حدوثه لاستحالة بقائه عندنا. وخالفنا في هذه الجملة فرق إحداها: الدهرية القائلة بقدم الأجسام فإنهم أحالوا عدمها كما أحالوا حدوثها. والفرقة الثانية: فرقة أخرى من الدهرية أحالوا عدم الأعراض كما أحالوا عدم الأجسام وزعموا أن الأعراض مجتمعة في الأجسام إذا ظهر بعضها في الجسم كمن فيه ضده. وقد بيّنا بطلان قول هاتين الفرقتين في أبواب حدوث العالم. والفرقة الثالثة: فرقة ضالة انتسبت إلى الإسلام وأقرت بحدوث الأجسام وأنكرت جواز عدمها وزعمت أنها لا تفنى وإنما تتغير من حال إلى حال باختلاف الأعراض عليها. وهذا قول حكاه ابن الراوندي عن الجاحظ وبه قال قوم من الكرّامية. وزعم أكثرهم أن الحوادث التي تحدث، بزعمهم، في القديم لا يجوز عدم شيء منها. وفي هذا تصريح بأن الله يحدث شيئا ولا يقدر على إفنائه. فقلنا كل ما صح حدوثه صح عدمه بعد حدوثه كالأعراض التي في الأجسام. فإن سألونا على هذا عن فناء الجنة والنار قلنا إن فناءهما جائز في العقل وإن قلنا بدوامهما من طريق الخبر والشرع.\rالمسألة الثانية من هذا الأصل\r"]], "pg": [191, 191]}, "540.181": {"x": [[191, "في كيفية فناء ما يفنى"], [192, "أجمع أصحابنا على أن الأعراض لا يصح بقاؤها فإن كل عرض يجب عدمه في الثاني من حال حدوثه. واختلفوا في كيفية فناء الأجسام: فقال أبو الحسن الأشعري: إن الله يفني الجسم بأن لا يخلق فيه البقاء في الحال التي يريد أن يكون فانيا فيه. لأن الباقي عنده يكون باقيا ببقاء فإذا لم يخلق الله البقاء في الجسم فني. وإلى هذا القول ذهب ضرار بن عمرو. وقال شيخنا أبو العباس"], [193, "القلانسي رحمه الله: إنما يفني الله الجوهر بفناء يخلقه فيه فيفنى الجوهر في الحال الثانية من حال حدوث الفناء فيه. وقال قاضينا أبو بكر محمد بن الطيب الأشعري [الباقلاني] إنما يكون فناء الجوهر بقطع الأكوان عنه؛ فإذا لم يخلق الله في الجوهر كونا ولونا فني وكان لا يثبت البقاء معنى غير الباقي. فهذا قول أصحابنا. واختلفت القدرية فيه: فزعم معمر أن خلق الشيء غيره وكذلك بقاؤه وفناؤه غيره. وزعم أن للبقاء بقاء ولكل بقاء بقاء لا إلى نهاية وكذلك لكل فناء فناء لا إلى نهاية وأحال أن يفني الحوادث كلها. وزعم محمد بن شبيب أن الفناء عرض غير الفاني وأنه يحلّ في الجسم فيفنى الجسم به في الثاني من حال حلوله فيه. وهذا مثل قول القلانسي غير أن القلانسي أثبت بقاء الجسم معنى غير الجسم وزعم ابن شبيب أن البقاء ليس غير الباقي. وذهب الكعبي منهم إلى مثل شيخنا أبي الحسن فأثبت البقاء معنى ولم يثبت الفناء معنى وقال بأن الأعراض لا تبقى وأن الجسم يفنى إذا لم يخلق الله فيه البقاء. وزعم الجبّائي وابنه [وأكثر القدرية] أن الله تعالى إذا أراد فناء الأجسام خلق فناء لها لا في محل وكان ذلك الفناء عرضا ضدا للاجسام كلها فيفني به جميع الأجسام. وأحالا فناء بعض الأجسام مع بقاء بعض منها. وفي هذا القول مخالفة لقواعد دين الإسلام من وجوه: منها أن إجازة وجود عرض لا في محل يؤدي إلى إجازة وجود كل عرض لا في محل وذلك يمنع تعاقبها على الأجسام وفي هذا إبطال دلالة الموحدين على حدوث الأجسام. ومنها أنّه يوجب أن يكون الله عزوجل قادرا على إفناء جميع الأجسام ولا يكون قادرا على إفناء بعضها."], [194, "ومنها إحالة بقاء الإله منفردا كما لم يزل منفردا لأن الأجسام إذا لم تفن إلا بضدّ وضدّها أيضا لا يفنى إلا بضد آخر فلا يخلو الباري عن حادث يكون ضدا لما فني به قبله [من الأعراض فيتسلسل إلى ما لا نهاية] وهذا يوجب استحالة تعريه في الأزل عن تلك الأضداد والحوادث كما ألزمنا الدهرية إذا أقروا بأن الأجسام لا تخلوا عن الأكوان المتضادة وإنها لم تخل منها فيما مضى ووجب أنّها محدثة لأنها لم تسبق الحوادث. وقد ألزم الجبائي وابنه مثل ذلك إذ أحالا أن يخلو الإله في المستقبل عن حوادث من الأجسام أو من الفناء الذي هو ضدها وكفاهما بذلك خزيا.\r\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [191, 194]}, "540.182": {"x": [[194, "في جواز إعادة ما يفنى"], [195, "أجمع المسلمون وأهل الكتاب والبراهمة على إعادة الخلق وجوازها بعد الفناء في الجملة وان اختلفوا في التفصيل. وخالفهم في هذه الجملة فرق: إحداها: الدهرية المنكرة لحدوث العالم. والثانية: قوم من الفلاسفة أقروا بحدوث العالم وأنكروا الإعادة بعد العدم. والثالثة: فرقة من عبدة الأصنام الذين كانوا في عهد النبي صلىلله عليه وسلم أقروا بحدوث العالم وأنكروا البعث والقيامة والجنة والنار: وقالوا (ما هِيَ إِلَّا حَياتُنَا الدُّنْيا نَمُوتُ وَنَحْيا وَما يُهْلِكُنا إِلَّا الدَّهْرُ) (1). والرابعة: فرقة من غلاة الروافض المنصورية والجناحية الذين أنكروا القيامة [والجنة والنار] وأسقطوا فروض العبادات وقالوا إن الفرائض والشريعة كناية عن الأئمة الذين أمرنا باتباعهم وموالاتهم من أهل البيت وأباحوا المحرمات كلها وزعموا أن المحرمات المذكورة في القرآن كناية عن قوم أمرنا ببغضهم من النواصب كأبي بكر وعمر. وهؤلاء اتباع منصور العجلي واتباع عبيد الله بن معاوية بن عبد الله بن جعفر. وقد مضى الكلام على منكري حدوث العالم بما فيه كفاية. وأما الكلام على من أقر بالحدوث وأنكر الإعادة فوجه الاستدلال عليه أن يقاس الإعادة على الابتداء فإن القادر على إيجاد الشيء عن العدم ابتداء، بأن يكون قادرا على إعادته، أولى إذا لم يلحقه عجز. وفي هذه الطائفة أنزل الله: (وَضَرَبَ لَنا مَثَلاً وَنَسِيَ خَلْقَهُ قالَ مَنْ يُحْيِ الْعِظامَ وَهِيَ رَمِيمٌ. قُلْ يُحْيِيهَا الَّذِي أَنْشَأَها أَوَّلَ مَرَّةٍ) (2).\rالمسألة الرابعة من هذا الأصل\r"]], "pg": [194, 195]}, "540.183": {"x": [[195, "في نفس ما يصح إعادته\rقال شيخنا أبو الحسن الأشعري رحمه الله: كل ما عدم بعد وجوده صحت إعادته جسما كان أو عرضا. وقال القلانسي من أصحابنا: يصح إعادة الأجسام ولا\r__________________\r(1) سورة الجاثية آية 24.\r(2) سورة يس آية 78/ 79."], [196, "يصح إعادة الأعراض. وبناه على أصله في أن المعاد يكون معادا لمعنى يقوم به ولا يصح قيام معنى بالعرض فلذلك أنكر إعادته. وذهب أبو الحسن إلى أن الإعادة ابتداء ثان فكما أن الابتداء الأول صح على الجسم والعرض من غير قيام معنى بالعرض فكذلك الابتداء الثاني صحيح عليه من غير قيام معنى به. وأنكر الكعبي وأتباعه من القدرية إعادة الأعراض. وقال الجبّائي، الأعراض نوعان: باق وغير باق. وما صح بقاؤه منها صحت إعادته بعد الفناء وما لا يصح بقاؤه فلا تصح إعادته. وأجاز ابنه أبو هاشم إعادة جميع الأعراض إلا ما يستحيل عليه البقاء عنده أو كان من مقدور العباد. ويصح عنده إعادة ما هو من جنس مقدور العباد إذا كان من فعل الله تعالى. وقال أبو الهذيل: كل ما أعرف كيفيته من الأعراض فلا يجوز أن يعاد وكل ما لا أعرف كيفيته فجائز أن يعاد. وقالت الكرّامية ما عدم بعد وجوده فلن يجوز أن يعاد جسما كان أو عرضا وإنما يجوز أن يخلق مثله. وتأولوا ما في القرآن من إعادة الخلق على معنى أنّهم يركّبون ثانيا وأجسامهم لم تعدم وإنما تفرقت أجزاؤهم. وتركيبها ثانيا هو الإعادة. وكفّرتهم الأمة كلها في هذا لأنه ليس ما ذهبوا إليه قولا لأحد من سلف هذه الأمة. وعلة التسوية بين الحوادث كلها في جواز إعادتها اشتراكها في الحدوث فلا ينكر حدوثها ثانيا كما لم يستحلّ حدوثها أوّلا.\rالمسألة الخامسة من هذا الأصل\r"]], "pg": [195, 196]}, "540.184": {"x": [[196, "في بيان ما يعاد من الأجسام والأرواح"], [197, "اختلفوا في هذه المسألة: فقال المسلمون واليهود والسامرة بإعادة الأجساد والأرواح وردّ الأجساد إلى الأرواح على التعيين؛ برجوع كل روح إلى الجسد الذي كان فيه. وأنكرت الحلولية وأكثر النصارى إعادة الأجساد والأرواح وزعموا أن الثواب والعقاب إنما يكون للأرواح. وزعم أهل التناسخ أن الإعادة إنما يكون بكرور الأرواح في أجساد مختلفة وذلك كله في الدنيا وإن كل روح أحسنت في قالبها أعيدت في قالب يتنعم فيه وكل روح اساءت في قالبها أعيدت في قالب\r\rيؤذيها. وزعموا أن أرواح الحيّات والعقارب كانت قد أساءت في بعض القوالب فعذبت في قوالب الحيّات والعقارب. فيقال لهم: هل تثبتون لكون الروح في القالب ابتداء لم يكن قبله في غيره؟ فإن قالوا: لا، صاروا إلى قول الدهرية القائلة بقدم الأجسام وقد أفسدنا قولهم قبل هذا، وإن قالوا نعم، قيل: فما أنكرتم أن ليس كون الروح الآن في هذا القالب جزاء له على عمل كان قبل ذلك كما لم يكن كونها في القالب الأول جزاء له على عمل كان قبل ذلك. والعجب من إنكار أهل التناسخ قول المسلمين بأخذ الميثاق عليهم في الذّرّ الأول لهم لو كان ذلك صحيحا لكنّا نذكره وهم يدّعون أن روح كل إنسان كانت فيما مضى في قالب آخر وعملت فيه طاعات أو معاصي فلحقها الجزاء في هذا القالب ولا يذكر ذلك أحد منهم ولا منّا. فمن أجاز هذا وأنكر ذلك فإنما يسخر من نفسه.\rالمسألة السادسة من هذا الأصل\r"]], "pg": [196, 197]}, "540.185": {"x": [[197, "في بيان ما يعاد من الحيوانات"], [198, "قد ورد الخبر بإعادة البهائم واقتصاص بعضها من بعض كاقتصاص الجماء من القرناء. وهذا في العقل جائز غير واجب. وإذا أعادها الله جاز أن يفنيها بعد الإعادة وجاز أن يجعلها بعد الإعادة ترابا. وفي بعض الروايات أن الله تعالى يجعلها ترابا فيقول الكافر حينئذ: (يا لَيْتَنِي كُنْتُ تُراباً) (1) أي ليتني صرت ترابا. وقيل إنّ الكافر هنا إبليس ومعناه أنه يقول: ليتني كنت في الأصل من تراب كما كان آدم من تراب ولم أستكبر عليه عند الأمر بالسجود له. وزعم النظام أن الله تعالى يعيد جميع الحيوانات ويجعلها كلها في الجنة. وقد رضينا له أن يكون في الجنة التي يأوي إليها الكلاب والخنازير والحيّات والعقارب والحشرات مع قتله لها في الدنيا ومنعه إياها عن كنيف (2) داره فضلا عن بستانه. وزعم المعروف بأبي كلدة من القدرية بأن الحيوانات الحسنة التي [فيها] منافع في الدنيا تعاد إلى الجنة\r__________________\r(1) سورة النبإ آية 40.\r(2) الكنيف: الساتر.\r\rوالحيوانات المؤذية القبيحة المناظر يحشر إلى جهنم زيادة في عذاب أهلها من غير أن ينالها في أنفسها العذاب. وعلى هذا الأصل ينبغي أن يحصل ما حسنت صورته وكان مؤذيا وما قبح منظره وكان نافعا بين الباب والدار لا في الجنة ولا في النار.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [197, 198]}, "540.186": {"x": [[198, "في أن الإعادة، هل هي واجبة أم لا"], [199, "قال أصحابنا: إنّها من طريق العقل جائزة ومن طريق الخبر واجبة. وزعم المدعون للأصلح من القدرية مع الكرّامية أنها واجبة على الله تعالى من طريق العقول للتفرقة بين المحسن والمسيء بالثواب والعقاب. فقلنا للقدرية إذا جاز تعجيل الثواب والعقاب قبل الموت فلو عجلهما سقط وجوب الإعادة. وقلنا للكرّامية إذا جاز عندنا وعندكم العفو عن جميع العصاة بطل وجوب الإعادة لأجل العقاب والثواب حتى لو ابتدأ الله بأمثالها جاز ولو كان الثواب واجبا عليه ولم يكن فضلا منه لم يستحق به شكرا وإسقاط شكر الله على الثواب كفر. فما يؤدي إليه مثله.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [198, 199]}, "540.187": {"x": [[199, "في خلق الجنة والنار\rوهما عندنا مخلوقتان. وزعمت الضرارية والجهمية وطائفة من القدرية أنهما غير مخلوقتين فإن آدم عليه السلام إنما كان في جنة من بساتين الدنيا وقال الكعبي: يجوز أن تكونا مخلوقتين ويجوز أن تكونا غير مخلوقتين وإن كانتا مخلوقتين جاز فناؤهما وإعادتهما في القيامة ولا يجوز فناؤهما بعد [دخول] أهلهما. ودليلنا على وجودهما إخبار الله تعالى عن الجنة أنها أعدت للمتقين وعن النار أنها أعدت للكافرين. ويدل على وجودهما ما تواترت به الأخبار، التي كفرت القدرية بها، في قصة المعراج وسائر ما ورد في صفات الجنة والنار.\r\rالمسألة التاسعة من هذا الأصل\r"]], "pg": [199, 199]}, "540.188": {"x": [[199, "في دوام الجنة والنار وما فيهما من نعيم وعذاب\rأجمع أهل السنة وكل من سلف من أخيار الأمة على دوام بقاء الجنة والنار وعلى دوام نعيم أهل الجنة ودوام عذاب الكفرة في النار. وزعم قوم من الجهمية أن الجنة والنار تفنيان. وزعم أبو الهذيل أن أهل الجنة والنار ينتهون إلى حال يبقون فيها خمودا ساكنين سكونا دائما لا يقدر الله تعالى حينئذ على شيء من الأفعال ولا يملك لهم حينئذ ضرا ولا نفعا. وكفاه بدعواه فناء مقدورات الله تعالى خزيا مع تكذيبه إياه في قوله: (أُكُلُها دائِمٌ) (1).\rالمسألة العاشرة من هذا الأصل"]], "pg": [199, 199]}, "540.189": {"x": [[200, "في أن الله تعالى خالق نعيم أهل الجنة وعذاب أهل النار\rأجمعت الأمة قبل معتمر والجاحظ أن الله تعالى يخلق لذّات أهل الجنة وآلام أهل النار. وزعم معتمر أنه ليس شيء من الأعراض فعلا لله تعالى وإنما الأعراض من فعل الأجسام إما طباعا وإما اختيارا. ولا يخلق الله ألما ولا لذة ولا صحة ولا سقما ولا شيئا من الأعراض. وزعم الجاحظ أن الله تعالى لا يعذب أحدا بالنار ولا يدخل أحدا النار وإنما النار تجذب أهلها إلى نفسها بطبعها وتمسكهم على التأبيد بطبعها. وهذا القول يوجب انقطاع الرغبة إلى الله تعالى في الإنقاذ منها. لا أنقذ الله منها من قال بذلك.\rالمسألة الحادية عشرة من هذا الأصل\r"]], "pg": [200, 200]}, "540.190": {"x": [[200, "في أن الله تعالى قادر على أن يزيد في نعيم،\rأهل الجنة وعلى أن يزيد في عذاب، أهل النار\rقالت الأمة بأسرها قبل طبة النظام أن الله تعالى قادر على أن يزيد في نعيم أهل الجنة وعلى أن يزيد في عذاب أهل النار أكثر مما قضاه لكل صنف منهم. وزعم\r__________________\r(1) سورة الرعد آية 35.\r\rالنظام أنه لا يقدر على ذلك وزعم أيضا أن طفلا لو وقف على شفير جهنم لم يكن الله عزوجل قادرا على إلقائه فيها وقدر غيره على إلقائه فيها. فوصف الإنسان بالقدرة على ما لم يصف الله بالقدرة عليه ولا على جنسه. وكفاه بهذا خزيا.\rالمسألة الثانية عشرة من هذا الأصل\r"]], "pg": [200, 200]}, "540.191": {"x": [[200, "في تعويض البهائم في الآخرة"], [201, "قال أصحابنا: إن الآلام التي لحقت البهائم والأطفال والمجانين عدل من الله تعالى وليس واجبا [عليه] تعويضها على ما نالها في الدنيا من الآلام فإن أنعم الله عليها في الآخرة نعما كانت فضلا منه. وزعمت البراهمة والقدرية أن تعويض البهائم على ما نالها في الدنيا من الآلام واجب على الله في الآخرة، وقالوا: إنما حسن منه إيلامها للعوض المضمون لها في الآخرة كالطبيب يؤلم المريض ليوصله بذلك الإيلام إلى نفع أعظم منه. فقلنا: لو كان إيلامه للبهائم إنما حسن منه لأجل العوض في الآخرة لوجب أن لا يحسن ذلك منه مع قدرته على إيصال أمثال تلك الأعواض إليهم من غير إيلام. والطبيب الذي ذكرتموه إنما حسن منه إيلام لا يقدر على نفع من آلمه إلّا به ولأنه كان حسن ذلك لأجل العوض الذي ذكروه لوجب أن يحسن منا إيلام غيرنا من غير استحقاق، لأجل نفع نوصله إليه بعد الألم. فإن قالوا: إنما لا يحسن ذلك منا لأنا لا نعرف مقدار عوض كل ألم والله عالم به فحسن ذلك منه، قيل: قد عرّفنا الله تعالى أعواض بعض الآلام كالقصاص والدية ومع ذلك لا يحسن من أحدنا أن يقطع يد من لا ذنب له ثم يقول: أردت إيصال عوض اليد إليك فخذ مني عوضه؛ إن شئت القصاص وإن شئت الدية وضعفها. فإن قالوا إن ذلك بعض عوض القطع الأول، قيل: إن يكن كذلك لزمكم على أصلكم تجوير البارئ تعالى بأن أوجب على الجاني أقل من حق المجني عليه. فإن قالوا إن الله متمّ له مقدار عوضه في الآخرة. قيل إن الذي يفعله الله من ذلك إذا لم يكن واجبا عليه كان فضلا منه ومن أصلكم أن التفضل لا ينوب عن الاستحقاق ولا يكون بمنزلته. فإن قالوا إنما حسن من الله إيلام من لا ذنب له"], [202, "في الدنيا بعلتين إحداهما: العوض الذي ذكرناه والثانية: وقوع اعتبار معتبر به قيل أما علة العوض فقد نقضناها عليكم وأما الاعتبار فمنقلب عليكم. لأنه وإن اعتبر قوم بذلك اعتبار خير، فقد اعتبر به قوم فصاروا من اعتبارهم بذلك إلى قول الدهرية أو إلى قول التناسخ. وذلك أنّ الدهرية قالت في اعتلالها لو كان للعالم صانع حكيم لما آلم من لا ذنب له. وقال أهل التناسخ: لمّا رأينا الله عزوجل يؤلم الأطفال بالأمراض وبالصاعقة ويؤلم البهائم التي لا ذنب لها ولم يجز أن يكون ظالما لها بالإسلام علمنا أن أرواح البهائم والأطفال كانت قبل هذا الدور في قوالب قد أساءت فيها فعوقبت في هذه القوالب بهذه الآلام، فإن وجب ذلك لاعتبار حسن وجب تركه لاعتبار قبيح به. وإذا بطل هذا كله وضح أن الإيلام من الله ليس للعلة التي ذكروها وإنما هي لأنه متصرف في ملكه يفعل ما يشاء ويحكم ما يريد.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [200, 202]}, "540.192": {"x": [[202, "في بيان أجل الوعيد"], [203, "اختلفوا في هذه المسألة فقال أصحابنا: إن تأبيد العذاب إنما يكون لمن مات على الكفر أو على البدعة التي يكفر بها صاحبها كالقدرية والخوارج وغلاة الروافض ومن جرى مجراهم. فأما أصحاب الذنوب من المسلمين إذا ماتوا قبل التوبة فمنهم من يغفر الله عزوجل له قبل تعذيب أهل العذاب. ومنهم من يعذّبه في النار مدة ثم يغفر له ويردّه إلى الجنة برحمته. وزعمت الخوارج أن مخالفيهم كفرة مخلدون في النار. وقالوا في أصحاب الذنوب من موافقيهم إنهم قد كفروا واستحقوا الخلود في النار. وزعمت القدرية أن مخالفيهم كفرة وأنّ أهل الذنوب من موافقيهم يخلدون في النار، إلا ابن شبيب والخالدي منهم، فإنهما أجازا المغفرة لأهل الكبائر من موافقيهم. وقال أصحابنا: إن أصحاب الوعيد من الخوارج والقدرية يخلدون في النار لا محالة. وكيف يغفر الله تعالى لمن يقول ليس لله أن يغفر له ويزعم أن عفو الله عن صاحب الكبيرة سفه وخروج عن الحكمة. وقال أصحابنا: إن الناس في الآخرة ثلاثة أصناف: سابقون مقرّبون،"], [204, "وأصحاب اليمين، وأصحاب الشمال. فالسابقون: هم الذين يدخلون الجنة من أطفال المؤمنين والسقط ومن جرى مجراه. ومنهم سبعون ألفا من هذه الأمة كل واحد منهم يشفع في سبعين ألفا كما ورد في الخبر وذكر فيهم عثمان بن عفان وعكاشة بن محصن. وأصحاب الشمال كلهم كفرة. وأصحاب اليمين كلهم مؤمنون لأن الله تعالى وصف أصحاب الشمال بأنهم كذبوا بالقيامة وأنهم ظنوا أن لن يحوروا وأنهم شكّوا في البعث. وصاحب الذنب من المسلمين غير مكذّب بذلك ولا شاكّ فيه فلا بد أن يكون إما من أصحاب اليمين وإما من السابقين وكلاهما يصير إلى الجنة برحمة الله تعالى، غير أن من أصحاب اليمين من يحاسب حسابا يسيرا، فإن أصاب أحدهم عذاب ففي مدة الحساب اليسير ثم ينقلب إلى أهله مسرورا. وقد قال الله تعالى: (إِنَّ اللهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ ما دُونَ ذلِكَ لِمَنْ يَشاءُ) (1) وكل آية في الوعيد بإزائها نظيرها في الوعد فإن قوله: (وَإِنَّ الْفُجَّارَ لَفِي جَحِيمٍ) (2)، بإزائه قوله: (إِنَّ الْأَبْرارَ لَفِي نَعِيمٍ) (3) وقوله: (وَمَنْ يَعْصِ اللهَ) (4)، بإزاء قوله: (وَمَنْ يُطِعِ اللهَ) (5). وإذا تعارضت الآيات في الوعد والوعيد خصصنا آيات الوعيد بآيات الوعد أو جمعنا بينهما. فيعذب العاصي مدة ثم يغفر له ويدخل الجنة لأجل الثواب بعد أن استوفى حظه من العذاب إذ لا يجوز أن يثاب في الجنة ثم يرد إلى النار. وقول القدرية، إن صاحب الكبيرة لا نسميه برّا على الإطلاق وإنما يقال إنه برّ في كذا على الإضافة، يعارضه قول من قال من المرجئة إنه لا يقال له فاجر ولا فاسق على الإطلاق وإنما يقال إنه فسق في كذا على الإضافة. وقولهم: إن ذنبه الواحد أحبط جميع طاعاته، خلاف قول الله تعالى: (إِنَّ الْحَسَناتِ يُذْهِبْنَ السَّيِّئاتِ) (6). وقال في من يكفر بالإيمان: (فَقَدْ حَبِطَ\r__________________\r(1) سورة النساء آية 116.\r(2) سورة الانفطار آية 14."], [205, "(3) سورة المطففين آية 22.\r(4) سورة النساء آية 14.\r(5) سورة النساء آية 13.\r(6) سورة هود آية 113.\r\rعَمَلُهُ) (1) وقال [قوله] أيضا: (وَمَنْ يَرْتَدِدْ مِنْكُمْ عَنْ دِينِهِ فَيَمُتْ وَهُوَ كافِرٌ فَأُولئِكَ حَبِطَتْ أَعْمالُهُمْ) (2)، فأخبر أن إحباط الحسنات إنما يكون بالموت على الكفر ووجب من هذا أنّ ما سواه من السيئات تذهبه الحسنات. ومن لم يقل بهذا فلا غفران لسيئاته وكفاه بذلك خزيا.\rالمسألة الرابعة عشر من هذا الأصل\r"]], "pg": [202, 205]}, "540.193": {"x": [[205, "في إثبات الشفاعة\rأثبت أهل السنة الشفاعة للأنبياء عليهم السلام وللمؤمنين بعضهم في بعض على قدر منازلهم. وقال المفسّرون في تفسير المقام المحمود انه الشفاعة. وفي الحديث: «ادّخرت شفاعتي لأهل الكبائر من أمتي». وروي أنّ النبي صلىلله عليه وسلم خيّر بين أن يدخل نصف أمته الجنة وبين الشفاعة فاختار الشفاعة وأخبر أن سبعين ألفا يدخلون الجنة بلا حساب كل واحد منهم يشفع في سبعين ألفا، وسأله عكاشة (3) بن محصن أن يدعو الله أن يجعله منهم فدعا له: وأنكرت الخوارج والقدرية الشفاعة في أهل الذنوب وهم صادقون في أن لا حظّ لهم منها. وسألونا في هذا الباب عن رجل حلف بطلاق امرأته وعتق مماليكه أو حلف بالله تعالى أن يعمل عملا يستحق به الشفاعة وقالوا لنا: ما الذي يلزم هذا الحالف؟ فإن قلتم نأمره باجتناب المعاصي، فمن اجتنبها لا يحتاج إلى الشفاعة. وإن قلتم نأمره بالمعاصي خالفتم الإجماع في هذا. وجوابنا عن هذا السؤال أن الحالف إن حلف على أن يعمل عملا يستحق به الشفاعة حانث في يمينه لأن من نال الشفاعة في الآخرة فإنما ينالها بفضل من الله تعالى بلا استحقاق. وإن حلف أن يعمل عملا يصير به من أهل الشفاعة أمرناه بأن يعتقد أصولنا في التوحيد والنبوات وأن يجتنب البدع الضالّة وأن\r__________________\r(1) سورة المائدة آية 5.\r(2) سورة البقرة آية 217."], [206, "(3) هو عكاشة الأسدي أحد السبعين ألفا الذين يدخلون الجنة بغير حساب. توفي في السنة الحادية عشرة للهجرة.\r\rيتبرّأ من أهل البدع على العموم وممن لا يرى الشفاعة على الخصوص وأن يلعن منكري الشفاعة من الخوارج والقدرية، فإنه إذا اعتقد ذلك برّ في يمينه وكان ممن يجوز الشفاعة إن كان له ذنب وجاز أن يكون هو شفيعا لغيره. جعلنا الله من أهلها برحمته.\rالمسألة الخامسة عشرة من هذا الأصل\r"]], "pg": [205, 206]}, "540.194": {"x": [[206, "في إثبات الحوض والصراط والميزان وسؤال الملكين في القبر\rأنكر ذلك الجهمية وأنكرت الضرارية أكثر ذلك. وزعم بعض القدرية أن سؤال الملكين في القبر إنما يكون بين النفختين في الصّور وحينئذ يكون عذاب قوم في القبر. وقالت السالمية بالبصرة: إن الكفار لا يحاسبون في الآخرة. وزعم قوم يقال لهم الوزنية: أن لا حساب ولا ميزان. وأقرت الكرّامية بكل ذلك كما أقر به أصحابنا غير أنهم زعموا أن منكرا ونكيرا هما الملكان اللذان وكّلا بكل إنسان في حياته. وعلى هذا القول يكون منكر ونكير كل إنسان غير منكر ونكير صاحبه. وقال أصحابنا إنهما ملكان غير الحفيظين على كل إنسان. وقالت الكرّامية في وزن الأعمال: إنها توزن أجسام يخلقها الله عزوجل بعدد الأعمال. وأجاز أصحابنا ذلك من طريق العقول غير أنّهم قالوا: إن الوزن يكون للصحف، التي كتب فيها أعمال بني آدم، لآثار رويت في ذلك. وقلنا في منكري الحوض لا سقاهم الله منه. ومنكر الصراط يزلّ عن الصراط إلى النار لا محالة. فأما الحال بين النفختين فإن الملائكة تموت في تلك الحال فكيف يصح السؤال فيها من بعضهم. وطريق إثبات ما ذكرناه من هذه المسألة الأخبار المستفيضة التي أجمع أهل النقل على صحتها. ولا اعتبار فيها بخلاف من ليس الحديث من صفته بعد ثبوت جواز ذلك كله في العقل. وفي إسقاط ابن سالم حساب الكفرة في الآخرة ردّ لقول الله عزوجل فيهم: (إِنَّ إِلَيْنا إِيابَهُمْ ثُمَّ إِنَّ عَلَيْنا حِسابَهُمْ) (1).\r__________________"], [207, "(1) سورة الغاشية آية 25 و 26.\r\rالأصل الثاني عشر\r"]], "pg": [206, 207]}, "540.195": {"x": [[207, "من أصول هذا الكتاب في بيان أصول الإيمان\rومسائل هذا الأصل تشتمل على خمس عشرة مسألة هذه ترجمتها: مسألة في حقيقة الإيمان والكفر.\rمسألة في حقيقة الطاعة والمعصية.\rمسألة في زيادة الإيمان ونقصانه.\rمسألة في جواز الاستثناء في الإيمان.\rمسألة في إيمان من اعتقد تقليدا.\rمسألة في إيمان الصبيان ووقت وجوب الإيمان.\rمسألة في حكم من مات من ذراري المشركين.\rمسألة في بيان حكم من لم تبلغه دعوة الإسلام.\rمسألة في بيان من يقطع بإيمانه.\rمسألة في الأفعال الدالة على الكفر.\rمسألة في أديان الأنبياء قبل النبوة.\rمسألة في بيان من يصح منه الطاعة ومن لا تصح منه.\rمسألة في أقسام الطاعات والمعاصي.\rمسألة في شرط الإيمان ومقدماته.\rمسألة في حكم الدار وبيان ما يفصل بين داري الكفر والإيمان. فهذه مسائل هذا الأصل وسنذكر في كل واحدة منها مقتضاها إن شاء الله تعالى.\r\rالمسألة الأولى من هذا الأصل\r"]], "pg": [207, 207]}, "540.196": {"x": [[207, "في بيان حقيقة الإيمان والكفر\rأصل الإيمان في اللغة: التصديق، يقال منه آمنت به وآمنت له إذا صدقته ومنه قوله تعالى: (وَما أَنْتَ بِمُؤْمِنٍ لَنا) (1)، أي بمصدّق. فالمؤمن بالله هو المصدّق لله في خبره وكذلك المؤمن بالنبي مصدق له في خبره. والله مؤمن لأنه يصدق وعده بالتحقيق. وقد يكون المؤمن في اللغة مأخوذا من الأمان والله مؤمن أولياءه من العذاب. وفي معنى المسلم في اللغة قولان.\rأحدهما: إنه المخلص لله العبادة من قولهم قد سلم هذا الشيء لفلان إذا خلص له."], [208, "والثاني: المسلم بمعنى المستسلم لأمر الله تعالى كقوله: (إِذْ قالَ لَهُ رَبُّهُ أَسْلِمْ قالَ أَسْلَمْتُ لِرَبِّ الْعالَمِينَ) (2) أي استسلمت لأمره. ومعنى الكفر في اللغة الستر وإنما سمّي جاحد ربّه والمشرك به كافرين، لأنهما سترا على أنفسهما نعم الله تعالى عليهما وسترا طريق معرفته على الأغمار. والعرب تقول: كفرت المتاع في الوعاء أي سترته [فيه]. وسمّي الليل كافرا لأنه يستر كل شيء بظلمته [قال الشاعر: في ليلة كفر النّجوم غمامها. ومنه سميت] الكفّارة لأنها تغطي الإثم وتستره وسمي الحراث كافرا لأنه يستر البذر في الأرض. فهذا أصل الإيمان والكفر في اللغة. فأما حقيقتهما على لسان أهل العلم فإن أصحابنا اختلفوا فيهما على ثلاثة مذاهب: فقال أبو الحسن الأشعري إن الإيمان هو التصديق لله ولرسله عليهم السلام في أخبارهم ولا يكون هذا التصديق صحيحا إلا بمعرفته. والكفر عنده هو التكذيب، وإلى هذا القول ذهب ابن الراوندي والحسين بن الفضل البجلي (3). وكان عبد الله بن سعيد يقول: إن الإيمان هو الإقرار بالله عزوجل وبكتبه وبرسله إذا كان ذلك عن معرفة وتصديق بالقلب، فإن خلا الإقرار عن المعرفة بصحته لم\r__________________\r(1) سورة يوسف آية 16.\r(2) سورة البقرة آية 131.\r(3) هو الحسين بن الفضل بن عمير البجلي الكوفي المفسر نزيل نيسابور كان آية في معان ـ"], [209, "يكن إيمانا. وقال الباقون من أصحاب الحديث: إن الإيمان جميع الطاعات فرضها ونفلها. وهو على ثلاثة أقسام: قسم منه يخرج [صاحبه] به من الكفر ويتخلص به من الخلود في النار إن مات عليه. وهو معرفته بالله تعالى وبكتبه ورسله وبالقدر خيره وشره من الله مع إثبات الصفات الأزلية لله تعالى ونفي التشبيه والتعطيل عنه ومع إجازة رؤيته واعتقاد سائر ما تواترت الأخبار الشرعية به. وقسم منه يوجب العدالة وزوال اسم الفسق عن صاحبه ويتخلص به من دخول النار وهو أداء الفرائض واجتناب الكبائر. وقسم منه [يوجب] كون صاحبه من السابقين الذين يدخلون الجنة بلا حساب وهو أداء الفرائض والنوافل مع اجتناب الذنوب كلها. وزعمت الجهمية أن الإيمان هو المعرفة وحدها. وروي عن أبي حنيفة إنه قال: الإيمان هو المعرفة والإقرار. وقالت النجارية: الإيمان ثلاثة أشياء: معرفة وإقرار وخضوع. وقالت القدرية والخوارج برجوع الإيمان إلى جميع الفرائض مع ترك الكبائر وافترقوا في صاحب الكبيرة: فقالت القدرية إنه فاسق لا مؤمن ولا كافر بل هو في منزلة بين المنزلتين. وقالت الخوارج كل من ارتكب ذنبا فهو كافر. ثم افترقوا بينهم: فزعمت الأزارقة منهم إنه كافر مشرك بالله. وقالت النجدات منهم إنه كافر بنعمة وليس بمشرك. وزعمت الكرّامية: أن الإيمان إقرار فرد وهو قول الخلائق، بلى، في الذر الأول حين قال الله تعالى لهم: (أَلَسْتُ بِرَبِّكُمْ قالُوا بَلى) (1). وزعموا أن ذلك القول باق في كل من قاله مع سكوته وخرسه إلى القيامة لا يبطل عنه إلا بالردة. فإذا ارتد ثم أقرّ ثانيا كان إقراره الأول بعد الردة إيمانا وزعموا أن تكرير الإقرار ليس بإيمان. وزعموا أن المنافقين كإيمان الأنبياء والملائكة وسائر المؤمنين. وزعموا أيضا أن المنافقين مؤمنون حقا وأجازوا أن يكون مؤمن حقا مخلدا في النار كعبد الله بن أبيّ (2) رئيس المنافقين وأن يكون\r__________________"], [210, "ـ صاحب فنون وتعبد قيل إنه كان يصلي في اليوم والليلة ستمائة ركعة وعاش مائة وأربع سنين وروى عن يزيد بن هارون والكبار توفي سنة اثنتين وثمانين ومائتين للهجرة.\r(1) سورة الأعراف آية 171.\r(2) هو عبد الله بن أبي بن سلول رأس المنافقين وهو القائل: لئن رجعنا الى المدينة ليخرجن الاعز منها الأذل، فلما رجعوا من غزوة تبوك منعه ابنه عبد الله المفلح الصالح من دخول ـ"], [211, "كافر حقا في الجنة كعمّار بن ياسر في حال ما أكره على كلمة الكفر لو مات فيه. واستدل من جعل جميع الطاعات إيمانا بظواهر الكتاب والسنة، منها قول الله تعالى: (وَما كانَ اللهُ لِيُضِيعَ إِيمانَكُمْ) (1) أي صلواتكم إلى بيت المقدس، فدل هذا على أن الصلاة إيمان. وفي آيات كثيرة دلالة على أن أصل الإيمان في القلب خلاف قول الكرّامية، منها قوله تعالى: (قالَتِ الْأَعْرابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلكِنْ قُولُوا أَسْلَمْنا وَلَمَّا يَدْخُلِ الْإِيمانُ فِي قُلُوبِكُمْ) (2)، وقال: (يا أَيُّهَا الرَّسُولُ لا يَحْزُنْكَ الَّذِينَ يُسارِعُونَ فِي الْكُفْرِ مِنَ الَّذِينَ قالُوا آمَنَّا بِأَفْواهِهِمْ وَلَمْ تُؤْمِنْ قُلُوبُهُمْ) (3). وقال النبي صلىلله عليه وسلم: ليس الإيمان بالتحلّي ولا بالتمنّي ولكن ما وقر في القلب وصدّقه العمل. والدليل على أن المنافقين غير مؤمنين خلاف قول الكرّامية قوله تعالى: (لا تَجِدُ قَوْماً يُؤْمِنُونَ بِاللهِ وَالْيَوْمِ الْآخِرِ يُوادُّونَ مَنْ حَادَّ اللهَ وَرَسُولَهُ) (4) وكان المنافقون يوادّون من حاد الله ورسوله، فدل على أنّهم لم يكونوا مؤمنين. وقال: (وَمَنْ يُؤْمِنْ بِاللهِ يَهْدِ قَلْبَهُ) (5) وفيه دليل على أن من لا هداية في قلبه فليس بمؤمن بربه. وفي رواية أهل البيت عن علي عن النبي صلىلله عليه وسلم: «الإيمان معرفة بالقلب وإقرار باللسان وعمل بالأركان». وتواترت الرواية عنه صلىلله عليه وسلم بأن (الإيمان بضع وسبعون شعبة، أعلاها شهادة أن لا إله إلّا الله وأدناها إماطة الأذى عن الطريق). وقد استقصينا هذه المسألة في كتاب مفرد في الإيمان.\rالمسألة الثانية من هذا الأصل\r"]], "pg": [207, 211]}, "540.197": {"x": [[211, "في بيان حقيقة الطاعة والمعصية\rقال أصحابنا: إن الطاعة هي المتابعة. واختلف المتكلمون في حقيقتها؛\r__________________\rـ المدينة حتى يأذن له النبي صلىلله عليه وسلم توفي في ذي القعدة من السنة التاسعة للهجرة."], [212, "(1) سورة البقرة آية 143.\r(2) سورة الحجرات آية 14.\r(3) سورة المائدة آية 41.\r(4) سورة المجادلة آية 22.\r(5) سورة التغابن آية 11.\r\rفقالت القدرية البصرية: إنها موافقة الإرادة وإن كل من فعل مراد غيره فقد أطاعه. وألزم الجبّائي على هذا كون الباري تعالى مطيعا لعبده إذا فعل مراده فالتزم ذلك وكفرته الأمة. وقال أصحابنا إن الطاعة موافقة الأمر فكل من امتثل أمر غيره صار مطيعا له. وسؤالنا ربّنا ليس بأمر، فلذلك لم يكن مطيعا لنا وإن أجابنا فيما سألناه. وللعصيان في اللغة معنيان أحدهما: معنى الذنب والخروج عن الطاعة الواجبة. والثاني الامتناع عن الشيء. والمعصية نقيض الطاعة فكما إن الطاعة موافقة الأمر كذلك المعصية مخالفة الأمر وإن شئت قلت موافقة النهي.\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [211, 212]}, "540.198": {"x": [[211, "كافر حقا في الجنة كعمّار بن ياسر في حال ما أكره على كلمة الكفر لو مات فيه. واستدل من جعل جميع الطاعات إيمانا بظواهر الكتاب والسنة، منها قول الله تعالى: (وَما كانَ اللهُ لِيُضِيعَ إِيمانَكُمْ) (1) أي صلواتكم إلى بيت المقدس، فدل هذا على أن الصلاة إيمان. وفي آيات كثيرة دلالة على أن أصل الإيمان في القلب خلاف قول الكرّامية، منها قوله تعالى: (قالَتِ الْأَعْرابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلكِنْ قُولُوا أَسْلَمْنا وَلَمَّا يَدْخُلِ الْإِيمانُ فِي قُلُوبِكُمْ) (2)، وقال: (يا أَيُّهَا الرَّسُولُ لا يَحْزُنْكَ الَّذِينَ يُسارِعُونَ فِي الْكُفْرِ مِنَ الَّذِينَ قالُوا آمَنَّا بِأَفْواهِهِمْ وَلَمْ تُؤْمِنْ قُلُوبُهُمْ) (3). وقال النبي صلىلله عليه وسلم: ليس الإيمان بالتحلّي ولا بالتمنّي ولكن ما وقر في القلب وصدّقه العمل. والدليل على أن المنافقين غير مؤمنين خلاف قول الكرّامية قوله تعالى: (لا تَجِدُ قَوْماً يُؤْمِنُونَ بِاللهِ وَالْيَوْمِ الْآخِرِ يُوادُّونَ مَنْ حَادَّ اللهَ وَرَسُولَهُ) (4) وكان المنافقون يوادّون من حاد الله ورسوله، فدل على أنّهم لم يكونوا مؤمنين. وقال: (وَمَنْ يُؤْمِنْ بِاللهِ يَهْدِ قَلْبَهُ) (5) وفيه دليل على أن من لا هداية في قلبه فليس بمؤمن بربه. وفي رواية أهل البيت عن علي عن النبي صلىلله عليه وسلم: «الإيمان معرفة بالقلب وإقرار باللسان وعمل بالأركان». وتواترت الرواية عنه صلىلله عليه وسلم بأن (الإيمان بضع وسبعون شعبة، أعلاها شهادة أن لا إله إلّا الله وأدناها إماطة الأذى عن الطريق). وقد استقصينا هذه المسألة في كتاب مفرد في الإيمان.\rالمسألة الثانية من هذا الأصل\rفي بيان حقيقة الطاعة والمعصية\rقال أصحابنا: إن الطاعة هي المتابعة. واختلف المتكلمون في حقيقتها؛\r__________________\rـ المدينة حتى يأذن له النبي صلىلله عليه وسلم توفي في ذي القعدة من السنة التاسعة للهجرة."], [212, "(1) سورة البقرة آية 143.\r(2) سورة الحجرات آية 14.\r(3) سورة المائدة آية 41.\r(4) سورة المجادلة آية 22.\r(5) سورة التغابن آية 11.\r\rفقالت القدرية البصرية: إنها موافقة الإرادة وإن كل من فعل مراد غيره فقد أطاعه. وألزم الجبّائي على هذا كون الباري تعالى مطيعا لعبده إذا فعل مراده فالتزم ذلك وكفرته الأمة. وقال أصحابنا إن الطاعة موافقة الأمر فكل من امتثل أمر غيره صار مطيعا له. وسؤالنا ربّنا ليس بأمر، فلذلك لم يكن مطيعا لنا وإن أجابنا فيما سألناه. وللعصيان في اللغة معنيان أحدهما: معنى الذنب والخروج عن الطاعة الواجبة. والثاني الامتناع عن الشيء. والمعصية نقيض الطاعة فكما إن الطاعة موافقة الأمر كذلك المعصية مخالفة الأمر وإن شئت قلت موافقة النهي.\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [211, 212]}, "540.199": {"x": [[212, "في زيادة الإيمان ونقصانه\rكل من قال: إن الطاعات كلها من الإيمان أثبت فيه الزيادة والنقصان. وكل من زعم: أن الإيمان هو الإقرار الفرد منع من الزيادة والنقصان فيه. وأما من قال إنه التصديق بالقلب فقد منعوا من النقصان فيه. واختلفوا في زيادته: فمنهم من منعها ومنهم من أجازها. ودليل الزيادة فيه قول الله تعالى: (الَّذِينَ قالَ لَهُمُ النَّاسُ إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزادَهُمْ إِيماناً) (1) وقوله: «(وَإِذا تُلِيَتْ عَلَيْهِمْ آياتُهُ زادَتْهُمْ إِيماناً) (2) وقوله: (فَأَمَّا الَّذِينَ آمَنُوا فَزادَتْهُمْ إِيماناً) (3) وقوله: (وَما زادَهُمْ إِلَّا إِيماناً وَتَسْلِيماً) (4) وقال: (لِيَزْدادُوا إِيماناً مَعَ إِيمانِهِمْ) (5) وقال أيضا: (لِيَسْتَيْقِنَ الَّذِينَ أُوتُوا الْكِتابَ وَيَزْدادَ الَّذِينَ آمَنُوا إِيماناً) (6). ففي هذه الآيات السّتّ تصريح بأن الإيمان يزيد وإذا صحت الزيادة فيه كان الذي زاد إيمانه قبل الازدياد أنقص إيمانا منه في حال الازدياد.\r__________________\r(1) سورة آل عمران آية 173."], [213, "(2) سورة الانفال آية 2.\r(3) سورة التوبة آية 124.\r(4) سورة الأحزاب آية 22.\r(5) سورة الفتح آية 4.\r(6) سورة المدثر آية 31.\r\rالمسألة الرابعة من هذا الأصل\r"]], "pg": [212, 213]}, "540.200": {"x": [[213, "في جواز الاستثناء في الإيمان\rكل من قال في الإيمان بقول الخوارج أو القدرية أو المجسمة الكرّامية فإنه لا يستثني في الإيمان في الحال وإنما استثنى فيه في المستقبل. والقائلون بأن الإيمان هو التصديق من أصحاب الحديث مختلفون في الاستثناء فيه: فمنهم من يقول به، وهو اختيار شيخنا أبي سهل محمد بن سليمان الصعلوكي وأبي بكر محمد بن الحسين بن فورك. ومنهم من ينكره وهذا اختيار جماعة من شيوخ عصرنا: منهم أبو عبد الله بن مجاهد والقاضي أبو بكر محمد بن الطيب الأشعري وأبو إسحاق إبراهيم بن محمد الأسفرايني وكل من قال من أهل الحديث بأن جملة الطاعات من الإيمان قال بالموافاة وقال كل من وافى ربه على الإيمان فهو المؤمن ومن وافاه بغير الإيمان الذي أظهره في الدنيا علم في عاقبته إنه لم يكن قط مؤمنا. والواحد من هؤلاء يقول: أعلم أنّ الإيمان حق وضده باطل وإن وافيت ربي عليه كنت مؤمنا حقا فيستثني في كونه مؤمنا ولا يستثني في صحته إيمانه واستدلّوا بأن الله تعالى ما أمر بإيمان ينقطع وإنما أمر بإيمان يدوم إلى آخر العمر وإذا قطع القاطع إيمانه علم أنّ الذي أظهره قبل القطع لم يكن الإيمان المأمور به كما إن الصلاة التي يقطعها صاحبها قبل تمامها لا تكون صلاة على الحقيقة وإنما تكون صلاة إذا تمت على الصحة. وقد روي عن ابن أبي مليكة أنه قال: أدركت أكثر من خمسمائة من أصحاب النبي صلىلله عليه وسلم كل منهم يخشى على نفسه النفاق لأنه لا يدري ما يختم له.\rالمسألة الخامسة من هذا الأصل\r"]], "pg": [213, 213]}, "540.201": {"x": [[213, "في إيمان من اعتقد تقليدا"], [214, "قال أصحابنا: كل من اعتقد أركان الدين تقليدا من غير معرفة بادلتها ننظر فيه، فإن اعتقد مع ذلك جواز ورود شبهة عليها وقال: لا آمن أن يرد عليها من الشّبه ما يفسدها فهذا غير مؤمن بالله ولا مطيع له بل هو كافر وإن اعتقد الحقّ ولم يعرف دليله واعتقد مع ذلك انه ليس في الشبه ما يفسد اعتقاده فهو الذي اختلف فيه\r\rأصحابنا: فمنهم من قال هو مؤمن وحكم الإسلام له لازم وهو مطيع لله تعالى باعتقاده وسائر طاعاته وإن كان عاصيا بتركه النظر والاستدلال المؤدي إلى معرفة أدلة قواعد الدين. وإن مات على ذلك رجونا له الشفاعة وغفران معصية برحمة الله وإن عوقب على معصيته لم يكن عذابه مؤبدا وصارت عاقبة أمره الجنة بحمد الله ومنّه. هذا قول الشافعي ومالك والأوزاعي والثوري وأبي حنيفة وأحمد بن حنبل وأهل الظاهر وبه قال المتقدمون من متكلمي أهل الحديث كعبد الله بن سعيد (1) والحارث المحاسبي (2) وعبد العزيز المكي (3) والحسين بن الفضل البجلي (4) وأبي عبد الله الكرابيسي وأبي العباس القلانسي وبه نقول. ومنهم من قال إن معتقد الحقّ قد خرج باعتقاده عن الكفر، لأن الكفر واعتقاد الحق في التوحيد والنبوات ضدان لا يجتمعان، غير أنه لا يستحق اسم المؤمن إلّا إذا عرف الحق في حدوث العالم وتوحيد صانعه وفي صحة النبوة ببعض أدلته سواء أحسن صاحبها العبارة عن الدلالة أو لم يحسنها. وهذا اختيار الأشعري وليس المعتقد للحق بالتقليد عنده مشركا ولا كافرا وإن لم يسمّه على الإطلاق مؤمنا وقياس أصله يقتضي جواز المغفرة له لأنه غير مشرك ولا كافر. واختلفت المعتزلة في هذا الباب: فمن زعم منهم أن المعارف ضرورية زعم أن معتقد الحق إذا اعتقده عن ضرورة ولم يخلطه بفسق فهو مؤمن ولو خلطه بفسق فهو فاسق وليس بمؤمن ولا كافر. وان اعتقده لا عن ضرورة فليس بمكلّف. واختلف الذين قالوا\r__________________"], [215, "(1) هو ابو سعيد الأشجّ عبد الله بن سعيد الكندي الكوفي الحافظ صاحب التصانيف، روى عن هشيم وعبد الله بن ادريس وخلف، وكان ثقة حجة. قال ابو حاتم: هو امام اهل زمانه وقال محمد بن أحمد الشطوي، ما رأيت احفظ منه. توفي في ربيع الأول سنة سبع وخمسين ومائتين وقد جاوز التسعين.\r(2) مرت ترجمته.\r(3) هو عبد العزيز بن يحيى الكتاني المكي، سمع من سفيان بن عيينة وناظر بشر المريسي في مجلس المأمون بمناظرة عجيبة غريبة فانقطع بشر وظن عبد العزيز ومناظرتهما مشهورة مسطورة، وعبد العزيز هو صاحب كتاب الحيدة وهو معدود في أصحاب الشافعي توفي سنة أربعين ومائتين.\r(4) مرت ترجمته.\r\rمنهم: إن المعرفة بالله وكتبه ورسله اكتساب عن [غير نظر] واستدلال، فيمن اعتقد الحق تقليدا: فمنهم من قال إنه فاسق بتركه النظر والاستدلال فالفاسق عندهم لا مؤمن ولا كافر. ومنهم من زعم إنه كافر لم يصح توبته عن كفره لتركه بعض فروضه. وزعم أبو هاشم أن الكافر لو اعتقد جميع أركان دين الإسلام واعتقد جميع أصول أبي هاشم وعرف دليل كل أصل له، إلا أصلا واحدا جهل دليله، من أصول العدل والتوحيد عنده فهو كافر ومقلدوه كلهم كفرة عنده. وهو صادق عندنا في هذا وإن كان كاذبا في أصوله.\rالمسألة السادسة من هذا الأصل\r"]], "pg": [213, 215]}, "540.202": {"x": [[215, "في إيمان الأطفال"], [216, "اختلفوا في وقت وجوب الإيمان: فزعم من قال باكتساب المعارف، من المعتزلة، إن وقت وجوب الإيمان وقت صحته فكل من صح [منه] الإيمان وجب عليه الإيمان وذلك عند تمام العقل الذي صح معه الاستدلال المؤدي إلى المعرفة وليس البلوغ شرطا فيه. ثم إن النظام والاسكافي وجعفر بن حرب قالوا واجب على من خلقه الله عاقلا ورأى نفسه وغيره من العالم، أن يعلم أن له وللعالم صانعا. ثم إن خطر بباله بعد ذلك هل صانعه جسم أم لا، هل يجوز أن يرى أم لا، أو هل له شبه أم لا، أو هل خلق الخلق لمنفعة أو لا، فعليه بعده النظر والاستدلال وإن خطر بباله هل لصانعه أن يعاقبه إن عصاه وهل له أن يديم عقابه أم لا؟ فعليه أن يجيز ذلك ولا يقطع عليه. وقال جعفر بن مبشر بمثل قول النظام في جميع ذلك إلّا في الوعيد فإنه أوجب على المفكّر أن يعلم أنّه إن عصى ربه ولم يعرفه عاقبه دائما. وزعم أنّ دوام الوعيد يعرف بالعقل. وقال بشر بن المعتمر بوجوب المعرفة والإيمان على العاقل من غير خاطر، إلا أنه أوجب النظر والاستدلال في المعرفة. وقال أبو العباس القلانسي ومن تبعه من أصحابنا بوجوب المعارف العقلية على العاقل من جهة العقل. وقال شيخنا أبو الحسن وضرار وبشر بن غياث: وقت صحة الإيمان والمعرفة وقت كمال العقل ووقت وجوبهما عند اجتماع العقل والبلوغ ولا"], [217, "وجوب إلا من جهة الشرع. وزعمت الكرّامية أن الإيمان قد وجد من الكل في الذر الأول. ثم اختلفوا فيما بينهم: فزعم المعروف منهم بالأصرم إن الذرية لم يكونوا يومئذ مأمورين بالإيمان وإنما سئلوا عن التوحيد فأجابوا وصارت إجابتهم إيمانا ولم تكن طاعة. وقال أكثرهم كانوا مأمورين وكان الجواب منهم طاعة. فقد فهم لو كان ذلك إيمانا وولدوا عليه لم يجز للمسلمين استرقاق أولاد المشركين لأنه لم يظهر من أطفالهم شرك بعد الإيمان الأول. ثم الدليل على تعليق الوجوب بالبلوغ والعقل قول النبي صلىلله عليه وسلم: «رفع القلم عن الصبي حتى يبلغ وعن المجنون حتى يفيق وعن النائم حتى يستيقظ». (1) ثم الكلام في إيمان الأطفال مبني على الخلاف الذي ذكرناه: فالكرّامية تزعم أنهم يولدون مؤمنين بالإقرار السابق منهم في الذر الأول سواء ولدوا من مؤمن أو كافر فإن بلغ الواحد منهم وكفر نظر فإن كان أبواه كافرين أقرّ على كفره وإن كان أبواه أو أحدهما مؤمنا صار مرتدا عن الدين. فقلنا لهم على هذا القول لو كان الطفل، الذي أبواه كافران، مؤمنا لوجب إذا مات قبل البلوغ أن يدفن في مقابر المسلمين وإن يغسل ويصلى عليه كما يفعل ذلك لأطفال المؤمنين ووجب أن يكون ماله للمسلمين دون الكافرين ووجب أيضا أن لو بلغ واختار دين أبويه أن يكون مرتدا يقتل بردته ولا يقبل منه الجزية. وزعمت الغيلانية من القدرية أنّ الطفل إذا عرف حدوث العالم وتوحيد صانعه ضرورة وأقرّ بذلك وبما جاء من عند الله فهو مؤمن وإن اعتقد ضدّ ذلك أو أقرّ بضده فهو كافر. وقال الباقون من المعتزلة إن الطفل قبل كمال عقله ليس بمؤمن ولا كافر، لكنه إن مات على ذلك دخل الجنة. واختلفوا فيه إذا كمل عقله قبل البلوغ: فمنهم من قال يلزمه بعد معرفته بنفسه أن يأتي بجميع معارف العدل والتوحيد وكل ما كلّف بعقله في الحال الثانية من معرفته بنفسه، فإن لم يأت بذلك في الحال الثانية من معرفته بنفسه صار عدوّا لله كافرا."], [218, "وأما الذي لا يعلم إلا بالشرع فعليه أن يأتي بمعرفته في الحال الثانية من حال سماع الأخبار على وجه يقطع\r__________________\r(1) أخرجه الترمذي عن علي بلفظ: رفع القلم عن ثلاثة ـ 1423 وأخرجه الحاكم في المستدرك عن عائشة بلفظ رفع القلم عن ثلاثة 2: 59 و 4: 389 ورواه عن علي بلفظ:\rرفع القلم عن ثلاثة 1: 258 و 4: 389.\r\rالعذر. وهذا قول أبي الهذيل. وقال بشر بن المعتمر إنّ الحال الثانية حال فكر واعتبار وإنما يجب ذلك عليه في الحال الثالثة. واعتبر الاسكافي وجعفر بن حرب وجعفر بن مبشر مهلة يمكن فيها الاستدلال. وعلى أصول أصحابنا لا يجب على الطفل قبل بلوغه وتمام عقله شيء. فإن أظهر طفل من أطفال المشركين كلمة الإسلام ومات عليه فقد قال أبو حنيفة: إنه مات مسلما، وقال أصحابنا أمره إلى الله لكنّا ندفنه في مقابر المسلمين ونحول بينه وبين أبويه قبل موته لئلا يفتناه عن الدين ولكنا نجعل ماله لأبويه. ولو لم يمت وبلغ واختار دين أبويه لم نجعله مرتدا وجعله أبو حنيفة مرتدا. وأجمع الفقهاء على أن الطفل من أولاد المسلمين لو أظهر كلمة الردة لم يكن مرتدا فإن مات على ذلك ورثه المسلمان من أبويه ودفن في مقابر المسلمين. واختلفوا في الطفل إذا كان أبواه كافرين فأسلم أحدهما فقال أصحابنا: يصير مسلما بإسلام أحدهما وبه قال الشافعي وأبو حنيفة. واعتبر مالك فيه دين أبيه كما اعتبر نسبه بأبيه.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [215, 218]}, "540.203": {"x": [[218, "في بيان من مات من ذراري المشركين"], [219, "اختلفوا فيهم: فزعمت الكرّامية أن الأطفال كلهم مؤمنون بقولهم بلى في الذر الأول ومن مات منهم قبل بلوغه دخل الجنة لإيمانه السابق. وزعمت الأزارقة من الخوارج أن أطفال المشركين مشركون وأنّهم في النار مع آبائهم. وكذلك قالوا في أطفال مخالفيهم من أهل ملة الإسلام. وقالوا في أطفال موافقيهم إذا ماتوا إنهم في الجنة. واختلف هؤلاء في الطفل إذا مات في حال شرك أبويه ثم أسلم أبواه وصار موافقا لهم. فمنهم من قال يصير تابعا لأبويه في الآخرة. ومنهم من قال يكون حكمه في الآخرة حكم المشركين لأنه مات في حال شرك أبويه. وزعم قوم من العجاردة في الأطفال إن البراءة منهم واجبة قبل البلوغ فإذا مات طفلا فقد مات على وجوب البراءة منه. وقالت الصلتية منهم بمثل ذلك في أطفال موافقيهم. وقالت فرقة أخرى من العجاردة ليس للاطفال قبل البلوغ حكم إيمان ولا حكم كفر ولا حكم ولاية ولا حكم عداوة. وقد ألزم هؤلاء أن لا ينزّلوهم إذا ماتوا أطفالا جنة"], [220, "ولا نارا. وأما الروافض فإن الشيطانية (1) منهم زعموا أن المعارف ضرورية والعبد مأمور بالإقرار. وقالوا إذا أقرّ الطفل بالله تعالى وبمعالم دين الإسلام فهو مؤمن وإن مات قبل الإقرار به لم يكن مؤمنا ولا كافرا ولا مستحقا للعذاب. وقال أبو مالك الحضرمي إن عرف الطفل ربّه عزوجل وأقرّ به ثم مات فقد مات مؤمنا وإن عرف ولم يقرّ مات كافرا مستحقا لعذاب الكفر وإن لم يعرف ولم يقرّ لم يكن مؤمنا ولا كافرا وإن أقرّ ولم يعرف كان مسلما ولم يكن مؤمنا. وأما المعتزلة فقد أفشوا في الناس قولهم بأن من مات طفلا كان من أهل الجنة لكنهم ناقضوا في ذلك بإيجاب القائلين منهم، بأن المعارف الدينية اكتساب على الطفل إذا كمل عقله، جميع المعارف العقلية، حتى إن مات بعد توجه وجوب المعرفة عليه وقبل حصولها له مات كافرا مستحقا للخلود في النار. ومنهم من أوجب هذه المعرفة عليه في الحال الثانية من معرفته بنفسه وبه قال أبو الهذيل. ومنهم من أوجبها عليه في الحال الثالثة من معرفته بنفسه وبه قال بشر بن المعتمر. ومنهم من اعتبر فيها مدة يمكن النظر والاستدلال على ذلك. وكلهم يقول إن تلك المدة إذا مضت ولم يستدل مات كافرا مستحقا (2) الخلود دون أن لم يكن (3) قد بلغ الحلم ولا السن الذي يكون بلوغا عند أئمة المسلمين. وفي هذا بطلان تمويههم عند العامة بأنهم يقولون: إن الأطفال في الجنة. وأما أهل السنة فإنهم أجمعوا إن مات من ذراري المؤمنين صغيرا أو بلغ مجنونا ومات كذلك يكون مع المؤمنين في الجنة. وتوقف المتحرجون منهم في أطفال المشركين لاختلاف الأخبار فيهم. فروي فيهم قول النبي صلىلله عليه وسلم «لو شئت لأسمعتك تضاغيهم في النار». وفي خبر آخر إنهم خدم أهل الجنة."], [221, "وعن ابن عباس أنه يوقد لهم نار فيؤمرون باقتحامها فمن اقتحمها لم يضرّه النار شيئا وصار منها إلى الجنة وعسى هؤلاء هم الذين روي فيهم أنّهم خدم أهل الجنة ومن لم يقتحمها عصى ربه ودخل النار وعسى هؤلاء هم الذين روي تضاغيهم في\r__________________\r(1) [السلطانية].\r(2) [للخلود في النار].\r(3) [وإن لم يكن].\r\rالنار. واختلفوا في الأعضاء المقطوعة من الإنسان فقال أصحابنا إنها في الآخرة مردودة على أصحابها. واختلفت القدرية في هذا فقال منهم عباد بن سليمان بمثل قولنا. ومنهم من قال: يد المؤمن التي قطعت في حال كفره قبل الإيمان لمن مات كافرا بعد قطع يده مؤمنا ويجعل يد هذا لذلك على البدل فإن لم يتفق البدل في ذلك جعلت يد الذي قطعت يده مؤمنا ثم كفر زيادة في جسم مؤمن مات مؤمنا لا على أن يكون يدا ثالثة له ولكن زيادة في بدنه وكذلك يد قطعت من كافر ثم أسلم يصير زيادة في جسم كافر مات على كفره. هذا قول الكعبي وكذلك قوله فيما سقط بالهزال. وقال أبو هاشم ابن الجبائي يجوز أن يعاد له تلك اليد بعينها ويجوز إبدالها بغيرها لأنه لا معتبر بالأطراف وإنما الواجب أن يعاد منه القدر الذي لا يبقى حيّا دونه. وإلى هذا القول ذهب بعض الكرّامية وهو المعروف منهم بالمازني. وقال بعضهم: إنما يجب إعادة ما هو أصل بنيته فأما الزيادة فإنما تعاد من باب الأولى إذا لم يكن سبب مانع، فأما إن كان سبب مانع، كأن يكون قد اتصل بجسم حيوان آخر فصار بعضا له، جاز أن يعاد في أحدهما دون الآخر وجاز أن يعاد في واحد منهما. وأرادت هذه الطائفة من الكرّامية بأصل البنية الجزء الذي قال في الذر الأول بلى وحكاية هذه البدعة تغني عن نقضها لوضوح فسادها.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [218, 221]}, "540.204": {"x": [[221, "في بيان حكم من لم يبلغه دعوة الإسلام"], [222, "الكلام في هذه المسألة مبني على الخلاف في وجوب المعارف العقلية. فمن زعم إنها ضرورية، قال فيمن لم تبلغه دعوة الإسلام: إن كان قد عرف توحيد ربه وصفاته وعدله وحكمته بالضرورة فحكمه حكم المسلمين وهو معذور في جهله بالنبوة وأحكام الشريعة وإن لم يعرف التوحيد وعدل الصانع بالضرورة فلا تكليف عليه وليس له في الآخرة ثواب ولا عذاب. ومن ذهب إلى أن الواجب من المعارف العقلية مكتسب اختلفوا فيمن لم تبلغه الدعوة: فزعمت المعتزلة من هذه الفرقة أن من كمل عقله واعتقد الحق في العدل والتوحيد فهو معذور في جهله بالرسل والشرائع ومن زاغ منهم عن اعتقاد الحق فهو كافر مستحق للوعيد. وقال أصحابنا:"], [223, "إن الواجبات كلها معلوم وجوبها بالشرع. وقالوا فيمن كان وراء السد أو في قطر من الأرض ولم تبلغه دعوة الإسلام ينظر فيه فإن اعتقد الحق في العدل والتوحيد وجهل شرائع الأحكام والرسل فحكمه حكم المسلمين وهو معذور فيما جهله من الأحكام لأنه لم يقم به الحجة عليه. ومن اعتقد منهم الإلحاد والكفر والتعطيل فهو كافر بالاعتقاد وينظر فيه فإن كان قد انتهت إليه دعوة بعض الأنبياء عليهم السلام فلم يؤمن بها كان مستحقا للوعيد على التأبيد. وإن لم تبلغه دعوة شريعة بحال لم يكن مكلفا ولم يكن له في الآخرة ثواب ولا عقاب فإن عذبه الله في الآخرة كان ذلك عدلا منه ولم يكن عقابا له كما إن إيلام الأطفال والبهائم في الدنيا عدل من الله تعالى وليس بعقاب لهم على شيء. وإن أنعم عليه في الآخرة فهو فضل منه وليس بثواب له على الطاعة كما إن إدخاله ذراري المسلمين الجنة فضل منه وليس بثواب على طاعة وإن كان هذا الذي لم تبلغه دعوة الإسلام غير معتقد كفرا ولا توحيدا فليس بمؤمن ولا كافر فإن شاء الله عذبه في الآخرة عدلا وإن شاء أنعم عليه فضلا. وليس لأحد لقي أحدا لم تبلغه الدعوة قتله حتى تقوم الحجة عليه فإن قتله فقد قال أهل العراق لا دية عليه. وأوجب عليه الشافعي رضي الله عنه دية مع الكفّارة. فإن كان على شريعة لأهل الذمة فديته دية ذمي وإن لم يكن على شرع ما فقد قيل [فيه دية مسلم] وقيل فيه بأقل الديات وهو دية مجوسي في قول الشافعي وأصحابه.\rالمسألة التاسعة من هذا الأصل\r"]], "pg": [221, 223]}, "540.205": {"x": [[223, "في بيان من يقطع بإيمانه من أهل الإيمان"], [224, "أجمع أصحابنا على القطع بإيمان الملائكة والأنبياء عليهم السلام وعلى أن كل واحد منهم مختوم له بالإيمان يوافي ربه عزوجل به ويكون معصوما عن التبديل والكفر والنفاق. وقالوا في هاروت وماروت إنهما كانا ملكين وتابا عن ذنبهما وسيختم لهما بالسعادة إن شاء الله. وأبطلوا قول من زعم إنهما كانا علجين من بابل لأنهما مذكوران في القرآن بأنهما ملكان. وقالوا بأن العشرة من أهل بيعة الرضوان كلهم من أهل الجنة. وكذلك كل من شهد بدرا مع النبي صلىلله عليه وسلم. وكذلك"], [225, "كل من شهد أحدا إلا رجلا اسمه قزمان وهو الذي قتل نفسه لما لحقه ألم الجراح. وكذلك كل من كان مع النبي صلىلله عليه وسلم يوم الحديبية فهو من أهل الجنة غير رجل واحد كان على جمل أورق فإن النبي صلىلله عليه وسلم استثناه منهم. وقالوا في سبعين ألفا من هذه الأمة يدخلون الجنة بلا حساب كل واحد منهم يشفع في سبعين ألفا منهم عكاشة بن محصن. وقالوا في أويس القرني (1) رضي الله عنه إنّه من أهل الجنة لورود الخبر، بأنه خير التابعين. وقالوا في الحسن والحسين وأولاد النبي صلىلله عليه وسلم من صلبه: إنهم في الجنة. وكذلك محمد بن علي الباقر لخبر روي عن جابر أنه أبلغه سلام رسول الله صلىلله عليه وسلم وكذلك أزواجه كلهن في الجنة معه كما ورد به الخبر. وقالوا في الأئمة الذين تدور عليهم الفتاوى في الحلال والحرام، من الصحابة والتابعين ومن بعدهم كمالك والشافعي والأوزاعي والثوري وأبي حنيفة وسائر من خاض في بيان أحكام الشريعة ولم يشب مذهبه بدعة من بدع الخوارج والرافضة أو القدرية أو الجهمية أو النجارية أو المشبهة الجسمية، إنهم كلهم من أهل الإيمان لإجماع الأمة على موالاتهم وترك تفسيقهم. وأرادوا بهذا الإجماع إجماع أهل السنة دون إجماع أهل الأهواء فإن من أهل الأهواء من كفّر الصحابة كلهم بعد النبي صلىلله عليه وسلم بتركهم عليّا (2) وكفر عليّا بتركه قتالهم كما ذهب إليه الكاملية. ومنهم من كفر أهل السنة وسائر مخالفيه كما نثبته (3) بعد هذا. وقلنا في عوام المسلمين وكل من لم نعرف منه بدعة إنه على ظاهر الإيمان وحكمه حكم المؤمنين والله أعلم بعاقبة أمره ونستثني في إيمان كل من لم نعلم عاقبة أمره والله أعلم.\r__________________"], [226, "(1) [هو أويس بن عامر المرادي القرني ذو المناقب الشهيرة من أمر النبي صلىلله عليه وسلم عمر وعليا إذا لقياه أن يطلبا منه الدعاء، وهو سيد زهاد زمنه، كان يلتقط ما على المزابل فإذا نبحه كلب قال: كل مما يليك وآكل مما يليني إن تجاوزت الصراط فأنا خير منك وإلا فأنت خير مني. وجد في قتلى أصحاب علي سنة سبع وثلاثين].\r(2) [بيعة علي].\r(3) [بنينه].\r\rالمسألة العاشرة من هذا الأصل\r"]], "pg": [223, 226]}, "540.206": {"x": [[226, "في بيان الأفعال الدالة على الكفر\rقال أصحابنا: إن أكل الخنزير من غير ضرورة ولا خوف وإظهار زيّ الكفرة في بلاد المسلمين من غير إكراه عليه والسجود للشمس أو للصنم وما جرى مجرى ذلك من علامات الكفر وإن لم يكن في نفسه كفرا إذا لم يضامّه عقد القلب على الكفر ومن فعل شيئا من ذلك أجرينا عليه حكم أهل الكفر وإن لم نعلم كفره باطنا. وأما تارك الصلاة فإن تركها عن استحلال فهو كافر وإن تركها عن كسل فقد اختلفوا فيه: فقال أحمد بن حنبل إنه كافر. وقال الشافعي رضي الله عنه: إنه يؤمر بالصلاة فإن صلى وإلّا قتل وأجاز الصلاة عليه لأنه ليس بكافر. وقال أبو حنيفة: يؤدب حتى يصلّي ولا يقتل. وكفرته الخوارج بذلك وقالت القدرية إنه لا مؤمن ولا كافر كما بيّنا قبل هذا.\rالمسألة الحادية عشرة من هذا الأصل\r"]], "pg": [226, 226]}, "540.207": {"x": [[226, "في أديان الأنبياء عليهم السلام قبل النبوة\rقال أصحابنا: كل نبي كان قبل نبوته مؤمنا بربه عارفا بتوحيده إمّا على حكم الدلائل العقلية وإما على شريعة نبي قبله. وقالوا في نبينا عليه السلام إنه كان قبل نزول الوحي عليه على ملة إبراهيم عليه السلام (1). وزعمت الكرّامية أنه كان على شريعة عيسى عليه السلام. وهذا من طريق العقل جائز ولكن لم يرد الخبر به.\rالمسألة الثانية عشرة من\r"]], "pg": [226, 226]}, "540.208": {"x": [[226, "في بيان من يصح منه الطاعة ومن لا يصح منه"], [227, "كل من عرف حدوث العالم وتوحيد صانعه وصفاته وعدله وحكمته وعرف شروط النبوة وأصول الشريعة صحت منه الطاعة لله تعالى ومن جهل هذه الأصول أو بعضها لم يصح منه الطاعة لله تعالى إلا واحدة وهي النظر والاستدلال على\r__________________\r(1) [وهذا من طريق العقل جائز، ولكن لم ترد الجزية].\r\rمعرفة الله تعالى، فإن ذلك طاعة ممن استدل عليه قبل معرفته به لأنه مأمور بذلك. وأجاز أبو الهذيل من الكافر كثيرا من الطاعات مع جهلة بالله عزوجل. وقال أصحابنا أن مخالفينا من القدرية والخوارج والرافضة والجهمية والنجارية والجسمية (1) لا يصح لأحد منهم طاعة لله عزوجل لأنهم يقصدون بما يزعمون أنها طاعات معبود ليس هو الإله عندنا. وقلنا للجبائي إذا زعمت أن الطاعة موافقة الإرادة فقد يحصل من مخالفيك كثير مما أراد الله عزوجل منهم فوجب عليك أن يكون مخالفوك مطيعين لله عزوجل. ونحن نقول إنّ الطاعة موافقة الأمر وليس شيء من أفعالك وأفعال أهل الأهواء عندنا موافقا لأمر الله عزوجل على الوجه الذي أمر به ولذلك لم يكن أحد منكم مطيعا لله تعالى.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [226, 227]}, "540.209": {"x": [[227, "في بيان أقسام الطاعات والمعاصي\rالطاعات عندنا أقسام: أعلاها يصير بها المطيع عند الله مؤمنا وتكون عاقبته لأجلها الجنة إن مات عليها. وهي معرفة أصول الدين في العدل والتوحيد والوعد والوعيد والنبوّات والكرامات ومعرفة أركان شريعة الإسلام وبهذه المعرفة يخرج عن الكفر.\rوالقسم الثاني: إظهار ما ذكرناه باللسان مرّة واحدة وبه يسلم من الجزية والقتال والسبي والاسترقاق وبه تحل المناكحة واستحلال الذبيحة والموارثة والدفن في مقابر المسلمين والصلاة عليه وخلفه.\rوالقسم الثالث: إقامة الفرائض واجتناب الكبائر وبه يسلم من دخول النار ويصير به مقبول الشهادة.\rوالقسم الرابع: منها زيادة النوافل وبها يكون له الزيادة في الكرامة والولاية."], [228, "والمعاصي أيضا أقسام: قسم منها كفر محض كعقد القلب على ما يضادّ\r__________________\r(1) [والمجسمة].\r\rالقسم الأول من أقسام الطاعات أو الشكّ فيها أو في بعضها ومن مات على ذلك كان مخلّدا في النار.\rوالقسم الثاني: منها ركوب الكبائر أو ترك الفرائض من غير عذر وذلك فسق سقط به الشهادة وفيه ما يوجب الحد أو القتل أو التعذير وهو مع ذلك مؤمن إن صح له القسم الأول من الطاعات خلاف قول الخوارج إنه كافر وخلاف قول القدرية إنه لا مؤمن ولا كافر. وربما غفر الله تعالى له بلا عقاب وإن عاقبه على ذنبه لم يكن عقابه مؤبّدا ومآل أمره الثواب في الجنة بفضل الله ورحمته.\rوالقسم الثالث: منها ما يسمّيه بعض المتكلمين صغائر وليس فيها ترك فريضة راتبة ولا ارتكاب ما يوجب حدّا. وأصحابنا لا يسمونه صغيرة والأمر فيها إلى الله تعالى يفعل فيها ما يشاء.\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [227, 228]}, "540.210": {"x": [[228, "في بيان شروط الإسلام ومقدماته\rمن شرط صحة الإيمان عندنا تقدم المعرفة بالأصول العقلية في التوحيد والحكمة والعدل وثبوت النبوة والرسالة واعتقاد أركان شريعة الإسلام. ومن شرطه معرفة صحة ذلك كله بأدلته المشهورة وإن لم يعلم دليل فروعها صح إيمانه. واختلفوا في صحة الإيمان بالله مع الجهل ببعض صفاته الأزلية أو الجهل ببعض أسمائه: فقال أصحابنا من علم صفاته الأزلية وصحة عدله في كل أفعاله صح إيمانه وإن لم يعرف أسماءه. وزعمت المعلومية من الخوارج أنّ من لم يعرف الله بجمع أسمائه فهو جاهل والجاهل به كافر. وهذا خلاف الجمهور ويجب على القائل به أن لا يعرف ربه من لا يعرف لغة العرب وإن كان موافقا لهذا القائل في أصوله كلها.\rالمسألة الخامسة عشرة من هذا الأصل\r"]], "pg": [228, 228]}, "540.211": {"x": [[228, "في بيان ما يفرق به بين دار الإسلام ودار الكفر\rكل دار ظهرت فيه دعوة الإسلام من أهله بلا خفير ولا مجير ولا بذل جزية"], [229, "ونفذ فيها حكم المسلمين على أهل الذمة إن كان فيهم ذمّيّ ولم يقهر أهل البدعة فيها أهل السنة فهي دار الإسلام. واللقيطة فيها حر بحكم الدار ومسلم لأجلها واللقطة فيها تعرف سنة على شروطها. وإذا كان الأمر على ضد ما ذكرناه في الدار فهي دار الكفر. وزعم أكثر المعتزلة أن البلدان التي غلبت عليها أهل السنة دار كفر. وزعم بعضهم أنها دار فسق وجعل للفسق دارا كما جعل الفاسق في منزلة بين المنزلتين. وقالت الأزارقة بأن الدنيا كلها دار شرك وحرب إلا موضع عسكرهم فإنها دار إيمان. وقد استقصينا هذه المسألة في كتاب الإيمان.\r\rالأصل الثالث عشر\r"]], "pg": [228, 229]}, "540.212": {"x": [[229, "من أصول هذا الكتاب في بيان\rأحكام الإمامة وشروط الزعامة\rوفي هذا الأصل خمس عشرة مسألة هذه ترجمتها:\rمسألة في وجوب الإمامة.\rمسألة في حال نصب الإمام.\rمسألة في عدد الأئمة.\rمسألة في بيان جنس الإمام وقبيلته.\rمسألة في شروط الإمامة.\rمسألة في عصمة الإمام وتسديده.\rمسألة في بيان ما يثبت به الإمامة.\rمسألة في تعيين الإمام بعد النبي صلىلله عليه وسلم.\rمسألة في الوصية والتوارث فيها.\rمسألة في صحة إمامة عمر وعثمان.\rمسألة في صحة إمامة علي رضي الله عنه.\rمسألة في قتلة عثمان وخاذليه.\rمسألة في حكم أهل الصفّين والجمل.\rمسألة في حكم الخوارج والحكمين.\rمسألة في إمامة المفضول وبيان الأفضل من الصحابة رضي الله عنهم. فهذه مسائل هذا الأصل وسنذكر في كل واحدة منها مقتضاها إن شاء الله تعالى.\r\rالمسألة الأولى من هذا الأصل\r"]], "pg": [229, 229]}, "540.213": {"x": [[229, "في بيان وجوب الإمامة"], [230, "اختلفوا في وجوب الإمامة وفي وجوب طلب الإمام ونصبه. فقال جمهور أصحابنا من المتكلمين والفقهاء، مع الشيعة والخوارج وأكثر المعتزلة، بوجوب الإمامة وإنها فرض واجب (1) إتباع المنصوب له وإنه لا بد للمسلمين من إمام ينفّذ أحكامهم ويقيم حدودهم ويغزي جيوشهم ويزوّج الأيامى ويقسم الفيء بينهم. وخالفهم شرذمة من القدرية كأبي بكر الأصم وهشام الفوطي فإن الأصم زعم أن الناس لو كفّوا عن التظالم (2) لاستغنوا عن الإمام. وزعم هشام أن الأمة إذا اجتمعت كلمتها على الحق احتاجت حينئذ إلى الإمام وأما إذا عصت وفجرت وقتلت الإمام لم يجب حينئذ على أهل الحق منهم إقامة إمام. واختلف الذين رأوا الإمامة من الفروض اللازمة في علة وجوبها. فزعم المدعون اللطف من المعتزلة أنها إنما وجبت لكونها لطفا في إقامة الشرائع. وقال أبو الحسن إنّ الإمامة شريعة من الشرائع يعلم جواز ورود التعبد بها بالعقل ويعلم وجوبها بالسمع. فقد اجتمعت الصحابة على وجوبها ولا اعتبار بخلاف الفوطي والأصم فيها مع تقدم الإجماع على خلاف قولهما. وقد وردت الشريعة بأحكام لا يتولّاها إلّا إمام أو حاكم من قبله كإقامة الحدود على الأحرار مع اختلافهم في إقامة السادة الحدود على المماليك وكتزويج من لا ولي لها في قول أكثر الأمة وكإقامة الجماعات والأعياد في قول أهل العراق. وأما قول الأصم أن الأمة إذا تناصفت استغنت عن الإمام فإنهم مع التناصف لا بد لهم من قائم بحفظ أموال اليتامى والمجانين وتوجيه السرايا إلى حرب الأعداء والذبّ عن البيضة ونحوها من الأحكام التي يتولّاها الإمام أو منصوب من قبله. وأما قول الفوطي بسقوط الإمامة عند الفتنة فضيره في هذا القول إبطال إمامة علي رضي الله عنه لأنها عقدت له في حال قتل عثمان\r__________________\r(1) [إقامته وواجب].\r(2) [المظالم].\r\rووقوع الفتنة فيه. وعليّ هو الإمام حقّا على رغم الفوطي واتباعه.\rالمسألة الثانية من هذا الأصل"]], "pg": [229, 230]}, "540.214": {"x": [[231, "في حال نصب الإمام\rقال أصحابنا بوجوب نصب الإمام في كل حال لا يكون فيها إمام ظاهر ووجوب طاعته إن كان ظاهرا ولم يجيزوا أن يأتي على الناس زمان فيه إمام واجب الطاعة وهو غائب غير ظاهر. وأجازت الروافض غيبته عن جميع الناس وأوجبوا انتظاره ولم يجيزوا نصب إمام في حال انتظارهم من ينتظرونه. وافترقوا في ذلك فرقا: فرقة من الزيدية ينتظرون محمد بن عبد الله بن الحسن بن الحسين بن علي بن أبي طالب (1) ويزعمون أنه حيّ لم يمت وقد تواتر الخبر في قتله بالمدينة في أيام المنصور. وفرقة منهم ينتظرون محمد بن القاسم صاحب الطالقان. وفرقة منهم ينتظرون يحيى بن عمر، صاحب الكوفة في أيام الطاهرية، مع تواتر الخبر بقتله. والكيسانية من الروافض ينتظرون محمد بن الحنفية ويزعمون أنه لم يمت وأنه بجبل رضوى إلى أن يأذن الله له بالخروج. وفرقة من الإمامية ينتظرون جعفر بن محمد الصادق ويزعمون أنه لم يمت وهؤلاء يعرفون بالياءوسية. وقوم منهم يقال لهم المباركية ينتظرون محمد بن اسماعيل بن جعفر ولا يصدقون بموته. وفرقة منهم ينتظرون موسى بن جعفر وهم يشاهدون مشهده ببغداد. وفرقة منهم ينتظرون محمد بن علي بن موسى وهم على انتظاره من وقت المأمون إلى يومنا هذا. وجميع المنتظرين منهم لمن انتظروه اليوم في حيرة من الدين لدعواهم أن القرآن والسنن قد وقع فيهما تحريف وتبديل ولا يعرف منهما تحقيق أحكام الشريعة على التفصيل إلا من عند الإمام المعصوم إذا ظهر. ويدّعون أنهم اليوم في التيه وكفاهم بهذا خزيا.\r__________________\r(1) قتل لثنتي عشرة ليلة من رمضان سنة خمس واربعين وله اثنتان وخمسون سنة وقبره بالبقيع مشهور.\r\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [231, 231]}, "540.215": {"x": [[231, "في عدد الأئمة في كل وقت"], [232, "اختلف الموجبون للامامة في عدد الأئمة في كل وقت: فقال أصحابنا لا يجوز أن يكون في الوقت الواحد إمامان واجبا الطاعة وإنما تنعقد إمامة واحد في الوقت ويكون الباقون تحت رايته. وإن خرجوا عليه من غير سبب يوجب عزله فهم بغاة إلّا أن يكون بين البلدين بحر مانع من وصول نصرة أهل كل واحد منهما إلى الآخرين فيجوز حينئذ لأهل كل واحد منهما عقد الإمامة لواحد من أهل ناحيته. وقالت الرافضة: لا يجوز أن يكون في الوقت الواحد إمامان ناطقان. ويصح أن يكون في الوقت إمامان أحدهما ناطق والآخر صامت. وزعموا أن الحسين بن علي كان صامتا في وقت الحسن ثم نطق بعد موته. وزعم قوم من الكرّامية أنه يجوز أن يكون في وقت واحد إمامان وأكثر. وقالت جماعة منهم إنّ عليّا ومعاوية كانا إمامين في وقت واحد إلا أن عليّا كان إماما على وفق السنة وكان معاوية إماما على خلاف السنة وكان واجبا على أتباع كل واحد منهما طاعة صاحبها. فيا عجبا من طاعة واجبة في خلاف السنة. ولو جاز إمامان وأكثر لجاز أن ينفرد كل ذي صلاح بالإمامة فيكون كل واحد منهم بولاية محلته وعشيرته. وهذا يؤدي إلى سقوط فرض الإمامة من أصلها.\rالمسألة الرابعة من هذا الأصل\r"]], "pg": [231, 232]}, "540.216": {"x": [[232, "في بيان جنس الإمام وقبيلته\rاختلفوا في هذه المسألة: فقال أصحابنا إنّ الشرع قد ورد بتخصيص قريش بالإمامة ودلت الشريعة على أن قريشا لا تخلو ممن يصلح للإمامة فلا يجوز إقامة الإمام للكافّة من غيرهم. وقد نص الشافعي رضي الله عنه على هذا في بعض كتبه. وكذلك رواه زرقان عن أبي حنيفة. وقالت الضرارية بصلاح الإمامة في غير قريش مع وجود من يصلح لها من قريش. وزعم الكعبيّ أن القرشي أولى بها من الذي يصلح لها من غير قريش، فإن خافوا الفتنة جاز عقدها لغيره. وقال ضرار:"], [233, "إذا استوى الحال في القرشي والأعجمي، فالأعجميّ أولى بها والمولى أولى بها من الصميم. وزعمت الخوارج أن الإمامة صالحة في كل صنف من الناس وإنما هي للصالح الذي يحسن القيام بها ولهذا بايعوا نافع بن الأزرق ثم لقطريّ بن الفجاءة ولنجدة وعطيّة وليس واحد منهم قريشا. وزعمت الزيدية من الروافض أنها لا تكون من قريش إلا في ولد عليّ رضي الله عنه ومن خرج من ولد الحسن أو الحسين شاهرا سيفه وفيه آلات الإمامة فهو الإمام. وزعمت الإمامية أنها اليوم في أحد مخصوص من أولاد علي رضي الله عنه واختلفوا في ذلك الذي ينتظرون خروجه. وقالت الغلاة من الروافض إنّ الإمامة في الأصل في عليّ وولده. ثم أخرجوها إلى جماعة من غير قريش إمّا بدعواهم وصية بعض الأئمة إليه وإمّا بدعواهم تناسخ الروح من الإمام إلى من زعموا أن الإمامة انتقلت إليه، كالبيانية في دعواها انتقال روح الإله من أبي هاشم بن محمد بن الحنفية إلى بيان وكدعوى من ادعى أن الروح انتقلت إلى الخطاب الأسدي وكدعوى المنصورية نبوّة أبي منصور العجلي وإمامته. ودليل أهل السنة على أن الإمامة مقصورة على قريش قول النبي صلىلله عليه وسلم: «الأئمة من قريش». ولهذا الخبر سلّمت الأنصار الخلافة لقريش (1) يوم السقيفة فحصل الخبر وإجماع الصحابة دليلين على أن الخلافة لا تصلح لغير قريش وقد اختلف النسّابون في قريش من هم؟ فذهب أكثرهم إلى أنهم ولد النضر بن كنانة بن خزيمة بن مدركة بن الياس بن مضر بن نزار بن معد بن عدنان فكل من كان من ولد النضر فهو قرشي. وهذا اختيار أبي عبيدة معمر بن المثنى وأبي عبيد القاسم بن سلام وبه قال الشافعي رضي الله عنه وأصحابه. وقالت التميمية قريش [من] ولد الياس بن مضر وأدخلوا أنفسهم في جملة قريش لأنهم من ولد الياس بن مضر. وهذا اختيار أبي عمرو بن العلاء وأبي الحسن الأخفش وحماد بن سلمة الفقيه (2) وعبيد الله بن الحسن القاضي وسوار بن\r__________________"], [234, "(1) [ولا اعتبار بخلاف من خالف الاجماع بعد حصوله، وإذا صح ان الخلافة في قريش].\r(2) [هو حماد بن سلمة بن دينار البصري الحافظ، سمع قتادة وأبا حمزة الضبعي وطبقتهما وكان سيد أهل وقته، قال وهيب بن خالد: حماد بن سلمة سيدنا وأعلمنا، وقال ابن المديني، ـ\r\rعبد الله (1) وروى مثله عن أبي الأسود الدؤلي (2). وقالت القيسية إنّ قريشا هم جميع ولد مضر بن نزار فأدخلت قيس غيلان في هذه الجملة وبه قال من الفقهاء مسعر بن كدام (3) وقد روى مثله عن حذيفة بن اليمان (4) والقول الأول أصح.\rالمسألة الخامسة من هذا الأصل\r"]], "pg": [232, 234]}, "540.217": {"x": [[234, "في شروط الإمامة [الأئمة]\rقال أصحابنا إنّ الذي يصلح للإمامة ينبغي أن يكون فيه أربعة أوصاف: أحدها: العلم وأقل ما يكفيه منه أن يبلغ فيه مبلغ المجتهدين في الحلال والحرام وفي سائر الأحكام.\rوالثاني: العدالة والورع وأقل ما يجب له من هذه الخصلة أن يكون ممن يجوز قبول شهادته تحمّلا وأداء. والثالث: الاهتداء إلى وجوه السياسة وحسن التدبير بأن يعرف مراتب الناس فيحفظهم عليها ولا يستعين على الأعمال الكبار بالعمّال الصغار ويكون عارفا بتدبير الحروب.\r__________________\rـ كان عند يحيى بن ضريس عن حماد بن سلمة عشرة آلاف حديث. وقال شهاب البلخي: كان حماد بن سلمة يعد من الأبدال توفي سنة سبع وستين ومائة.\r(1) هو سوار بن عبد الله بن سوار التميمي العنبري البصري ابو عبد الله قاضي الرصافة ببغداد، روى عن يزيد بن زريع وطبقته، قال في المغني: سوار بن عبد الله بن قدامة العنبري ليس بشيء. وكان من الشعراء المجيدين توفي سنة خمس واربعين ومائتين.\r(2) هو أبو حرب بن أبي الأسود الدؤلي البصري روى عن عبد الله بن عمر وجماعة، توفي سنة عشر ومائة."], [235, "(3) هو مسعر بن كدام الحافظ ابو سلمة الهلالي الكوفي الأحول أحد الأعيان يسمى المصحف من إتقانه ويدعى الميزان لنقده وتحرير لسانه قاله ابن ناصر الدين، وقال في العبر: أخذ عن الحكم وقتادة وخلف وكان عنده نحو ألف حديث، قال يحيى القطان: ما رأيت أثبت منه، وقال أبو نعيم: مسعر أثبت من سفيان وشعبة. توفي سنة خمس وخمسين ومائة.\r(4) هو حذيفة بن اليمان العيسي صاحب السر المكنون في تمييز المنافقين ولذلك كان عمر لا يصلي على ميت حتى يصلي عليه حذيفة يخشى ان يكون من المنافقين وسمي ابن اليمان لأن جده حالف بني عبد الأشهل وهم من اليمن. توفي سنة ست وثلاثين.\r\rوالرابع: النسب من قريش وزادت الشيعة في هذه الشروط العصمة من الذنوب والكلام فيها يأتي بعد هذه المسألة.\rالمسألة السادسة من هذا الأصل\r"]], "pg": [234, 235]}, "540.218": {"x": [[235, "في ذكر العصمة في الإمامة\rقال [أصحابنا مع] أكثر الأمة إنّ العصمة من شروط النبوّة والرسالة وليست من شروط الإمامة وإنما يشترط فيها عدالة ظاهرة فمتى أقام في الظاهر على موافقة الشريعة كان أمره في الإمامة منتظم. ومتى زاغ عن ذلك كانت الأمة عيارا (1) عليه في العدول به من خطئه إلى صواب أو في العدول عنه إلى غيره. وسبيلهم معه فيها كسبيله مع خلفائه وقضاته وعمّاله وسعاته؛ إن زاغوا عن سننه عدل بهم أو عدل عنهم. وقالت الشيعة كلها بوجوب عصمة الإمام في الجملة وهم مناقضون لهذه الدعوى في التفصيل لأنهم ثلاث فرق: زيدية وإمامية وغلاة.\rفالزيدية فرق: منها الجارودية وهي تزعم أن عليّا والحسن والحسين كانوا أئمة معصومين عن الخطأ والمعصية. فإذا سئلوا عن بيعة الحسن لمعاوية لم يمكنهم أن يقولوا إنها كانت صوابا لأن هذا القول يوجب تصحيح ولاية معاوية وهو عندهم ظالم كافر. ولم يمكنهم أن يقولوا إنها كانت خطأ فيبطلوا عصمة الحسن.\rوالبترية من الزيدية تقول بإمامة عثمان ست سنين ولا تكفّره بالأحداث التي كانت منه بل يتوقف فيه فهذا إمام قد توقّفوا فيه."], [236, "والسليمانية من الزيدية تكفّر عثمان بعد الأحداث التي نقموها منه، فهذا إمام قد أخرجوه من العصمة. والإمامية كلها تدعى عصمة الإمام، ثم تزعم أن الإمام يجوز أن ينكر إمامة نفسه في حال التقية حتى يقول لمن يخاف منه إني لست بالإمام هذا كذب قد أجازوه عليه. وإن زعموا أن قوله لست بإمام صدف منه فما أنكروا أن قوله أنا الإمام كذب منه.\rوالكاملية من الإمامية قد أكفروا عليّا بقعوده عن قتال أبي بكر وعمر.\r__________________\r(1) [مختارا].\r\rوزعمت الكيسانية منهم أن محمد بن الحنفية هو الإمام المنتظر وأنه الآن محبوس في جبل رضوى عقوبة له على خروجه إلى يزيد بن معاوية وخروجه إلى عبد الملك بن مروان. وكيف يصح دعوى العصمة لمن يستحق العقوبة بزعمهم. والكلام مع غلاتهم في عصمة الإمام فضل مع قولهم بالتشبيه وبإلهية الأئمة. ثم لو اشترطت عصمة الإمام لاشترطت عصمة خلفائه وأعوانه ولو كان كل واحد منهم معصوما لاستغنوا عن إمام معصوم يقيمهم على منهج الصواب.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [235, 236]}, "540.219": {"x": [[236, "في بيان ما يثبت به الإمامة للإمام"], [237, "واختلفوا في طريق ثبوت الإمامة من نص أو اختيار: فقال الجمهور الأعظم من أصحابنا ومن المعتزلة والخوارج والنجارية أن طريق ثبوتها الاختيار من الأمة باجتهاد أهل الاجتهاد منهم واختيارهم من يصلح لها. وكان جائزا ثبوتها بالنص غير أن النص لم يرد فيها على واحد بعينه فصارت الأمة فيها إلى الاختيار. وزعمت الإمامية والجارودية من الزيدية والرّاوندية من العباسية أن الإمامة طريقها النص من الله تعالى على لسان رسوله صلىلله عليه وسلم على الإمام ثم نص الإمام على الإمام بعده. واختلف هؤلاء في علة وجوب النص عليه، فمنهم من بناه على أصله في إبطال الاجتهاد. ومنهم من بناه على أصله في وجوب عصمة الإمام. وزعم أن العصمة لا تعرف بالاجتهاد وإنما يعرف المعصوم بالنص. فأما البترية والجريرية من الزيدية فقد وافقوا الفريق الأول في الاختيار وإنما خالفوهم في تعيين الأولى بالإمامة. ودليل الجمهور أن النص على الإمام لو كان واجبا على الرسول صلىلله عليه وسلم بيانه لبيّنه على وجه تعلمه الأمة علما ظاهرا لا يختلفون فيه، لأن فرض الإمامة يعمّ الكافة معرفته كمعرفة القبلة وأعداد الركعات. ولو وجد النص منه هكذا لنقلته الأمة بالتواتر ولعلموا صحته بالضرورة كما اضطروا إلى سائر ما تواتر الخبر فيه. فلما كنا مع كثرة عددنا وزيادتنا على جميع فرق المدّعين للنص غير مضطرّين إلى العلم بذلك علمنا أن النص، على واحد بعينه للإمامة، لم يتواتر النقل فيه. وإنما روي فيه"], [238, "أخبار أحاد من جهة الروافض وليست لهم معرفة بشروط الأخبار ولا رواتهم ثقات وبإزائها أخبار أشهر منها في النص على غير من يدّعون النص عليه وكل منها غير موجب للعلم. وإذا لم يكن فيه ما يوجب العلم صارت المسألة اجتهادية وصح فيها الاختيار والاجتهاد. فإذا صح لنا ثبوت الإمامة من طريق الاختيار فقد اختلف أهل الاختيار في عدد المختارين للإمام: فقال أبو الحسن الأشعري إنّ الإمامة تنعقد لمن يصلح لها بعقد رجل واحد من أهل الاجتهاد والورع، إذا عقدها لمن يصلح لها، فإذا فعل ذلك وجب على الباقين طاعته. وإن عقدها مجتهد فاسق أو عقدها العالم الورع لمن لا يصلح لها، لم ينعقد تلك الإمامة كما أن النكاح ينعقد بولي واحد عدل ولا ينعقد بالفاسق عند هؤلاء. وقال سليمان بن جرير الزيدي وطائفة من المعتزلة أقل من يعقد الإمامة رجلان من أهل الورع والاجتهاد كعقد النكاح لا يثبت بأقل من شاهدين. وقال القلانسي ومن تبعه من أصحابنا تنعقد الإمامة بعلماء الأمة [بعلماء بلد الإمام] الذين يحضرون موضع الإمام وليس لذلك عدد مخصوص. فإن عقد الإمامة واحد أو جماعة لواحد وعقدها آخرون لآخر وكل واحد منهما يصلح لها صح العقد السابق فإن عقدا في وقت واحد أو لم يعرف السابق منهما استؤنف العقد لأحدهما أو لغيرهما والله أعلم.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [236, 238]}, "540.220": {"x": [[238, "في تعيين الإمام بعد النبي صلىلله عليه وسلم"], [239, "اختلفت الأمة بعد وفاة النبي صلىلله عليه وسلم وبعد الفتنة بقتل عثمان رضي الله عنه في تعيين الإمام بعد النبي صلىلله عليه وسلم: فذهب الجمهور إلى تصحيح إمامة أبي بكر رضي الله عنه وعلى هذا مضى أئمة الجمهور إلى الأعصار. وزعمت طائفة من الراوندية أن الإمامة بعد النبي صلىلله عليه وسلم كانت لعمّه العباس. وقالت الشيعة بإمامة عليّ بعده. ودليل من قال بإمامة أبي بكر؛ أن الناس افترقوا في هذه المسألة ثلاث فرق: فرقة تقول بإمامة أبي بكر. وفرقة تقول بإمامة علي. وفرقة تقول بإمامة العباس ووجدنا عليّا والعباس قد بايعا أبا بكر وانقادا لأمره في كافة المسلمين وإن كانا قد توقّفا عن"], [240, "البيعة له أياما فإنهما دخلا بعدها في البيعة له مع سائر الأمة. ولا يجوز لمدّع أن يدعي أن باطنهما في هذه البيعة كان بخلاف ظاهرهما لأن المدعي لذلك لا ينفصل من الخوارج إذ ادّعت أن باطن علي في البيعة للنبي صلىلله عليه وسلم كان بخلاف ظاهره. وإذا بطل هذا فكانت الإمامة حينئذ لواحد من هؤلاء الثلاثة واثنان منهم قد بايعا الثالث صحت إمامة من بايعاه ووجب لزوم طاعته. ومما يدل على إمامة أبي بكر وعمر من القرآن قول الله تعالى (قُلْ لِلْمُخَلَّفِينَ مِنَ الْأَعْرابِ سَتُدْعَوْنَ إِلى قَوْمٍ أُولِي بَاسٍ شَدِيدٍ تُقاتِلُونَهُمْ أَوْ يُسْلِمُونَ فَإِنْ تُطِيعُوا يُؤْتِكُمُ اللهُ أَجْراً حَسَناً وَإِنْ تَتَوَلَّوْا كَما تَوَلَّيْتُمْ مِنْ قَبْلُ يُعَذِّبْكُمْ عَذاباً أَلِيماً) (1). ولا يجوز أن يكون الداعي لهم إلى قتال أولي بأس شديد رسول الله صلىلله عليه وسلم لأنه كان قال لهم: (لَنْ تَخْرُجُوا مَعِيَ أَبَداً وَلَنْ تُقاتِلُوا مَعِيَ عَدُوًّا إِنَّكُمْ رَضِيتُمْ بِالْقُعُودِ أَوَّلَ مَرَّةٍ فَاقْعُدُوا مَعَ الْخالِفِينَ) (2). فوجب أن يكون الداعي لهم بعد النبي صلىلله عليه وسلم إلى قتال أولي بأس شديد أبا بكر أو عمر وأيهما كان دلت الآية على وجوب طاعته. وقد اختلفوا في أولي البأس الشديد. فمنهم من قال: هم أهل اليمامة وأصحاب مسيلمة الكذاب فإنهم قتلوا في حربهم من أصحاب النبي صلىلله عليه وسلم زهاء على ألف ومائتي رجل أكثرهم حفاظ القرآن حتى قال الشاعر في ذلك.\rقتلت حنيفة والحوادث جمّة ... أهل القرآن فدمعنا يتذرّف"], [241, "ومنهم من قال: هم الروم الذين حاربهم المسلمون في مواضع من الشام في وقائع شديدة يضرب بها المثل منها حربهم بالجابية ومنها حربهم على باب دمشق ومنها حربهم بأجنادين مع مائة ألف من الروم ومنها حربهم بأرض تحل التي قتل فيها من الروم ألف بطريق سوى من قتل منها من إفناء الجند ومنها حربهم على نهر اليرموك مع أربعمائة ألف فارس من الروم حتى قتل منهم سبعون ألفا في المعركة. ومنهم من قال إنّ أولي البأس الشديد هم الفرس بالقادسية بجلولاء (3)\r__________________\r(1) [سورة الفتح آية 16].\r(2) [سورة التوبة آية 83].\r(3) [وبحلوان].\r\rوبنهاوند وغيرها. فإن كان المراد بأولي البأس الشديد أصحاب مسيلمة الكذاب فالداعي إلى قتالهم أبو بكر وصاحب جيشه، في ذلك وفي حروب أكثر أهل الردّة، خالد بن الوليد. وإن كان المراد بهم الروم فأبو بكر هو الذي جهز إليهم الجيوش مع أبي عبيدة بن الجراح وخالد بن الوليد وعمرو بن العاص ويزيد بن أبي سفيان وغيرهم وفتح في أيامه من أرض الشام إلى باب دمشق وتمت فتوح الشام والجزيرة في أيام عمر رضي الله عنه. وإن كان المراد بهم الفرس فأبو بكر أوّل من أنفذ إليهم الجيش مع العلاء بن الحضرمي ثم أنفذ خالدا على جادّة القادسية حتى فتح من أرض الأيلة إلى سواد القادسية وتمت فتوح العراق وفارس وأصبهان إلى أطراف خراسان في أيام عمر رضي الله عنه وإذا صحت بذلك إمامة عمر صحت إمامة من استخلف عمر وهو أبو بكر. ولا يجوز تأويل أولي البأس الشديد على أهل صفّين والجمل، الذين دعا عليّ إلى قتالهم، لأن الله تعالى قال تقاتلونهم أو يسلمون وما قاتل عليّ أصحاب الجمل وأهل صفين ليسلموا وإنما قاتلهم لبغيهم عليه ولذلك قال لأصحابه: لا تبدءوهم بقتال حتى يبدءوكم ونهى عن اتباع من أدبر منهم وعن أن يذفّف على جريح منهم وهذه خصال لا يجوز فعلها بأهل الكفر، فبطل هذا التأويل وصح بما ذكرناه إمامة أبي بكر وعمر.\rالمسألة التاسعة من هذا الأصل"]], "pg": [238, 241]}, "540.221": {"x": [[242, "في التوارث والوصية في الإمامة\rاختلفوا في الإمامة هل تكون موروثة: فكل من قال بإمامة أبي بكر قال إنها لا تكون موروثة. وأما الراوندية القائلة بإمامة العباس فمختلفون: منهم من زعم أن العباس استحق الإمامة بنص النبي صلىلله عليه وسلم. لا بالوراثة من النبي صلىلله عليه وسلم ومنهم من زعم أنه استحقها بالوراثة من النبي صلىلله عليه وسلم لأنه كان عصبته دون بني أعمامه. والقائلون بإمامة علي مختلفون أيضا: فالزيدية والجارودية تزعم أن النبي صلىلله عليه وسلم نصّ على إمامة علي بالوصف دون الاسم. ثم ورثها عن علي ابناه الحسن والحسين ثم إنها على الميراث في هذين البطنين لا في واحد بعينه ولكن من خرج منهم شاهرا سيفه\r\rيدعو إلى سبيل ربه وكان عالما صالحا فهو الإمام. وزعم أكثر الإمامية أن الإمامة موروثة. وهذا خطأ على أصولهم لقولهم بأن الإمامة بعد علي كانت للحسن وبعده للحسين فلو كانت ميراثا لصارت بعد الحسن لابنه دون أخيه. وزعمت الكيسانية أن الإمامة بعد الحسن (1) لأخيه محمد بن الحنفية. وهذا أيضا خلاف الميراث لأن الابن أحق بالميراث من الأخ. واختلفوا أيضا في الوصية بالإمامة إلى واحد بعينه يصلح لها: فقال أصحابنا مع قوم من المعتزلة والمرجئة والخوارج أن الوصية بها صحيحة جائزة غير واجبة. وإذا أوصى بها الإمام إلى من يصلح لها وجبت على الأمة إنفاذ وصيته كما أوصى بها أبو بكر إلى عمر وأجمعت الصحابة على متابعته فيها. وإن جعلها الإمام شورى بين قوم بعده جاز كما فعله عمر رضي الله عنه وزعم سليمان بن جرير أن الإمام له الوصية بالإمامة إلى واحد بعينه ولكن لا يلزم الأمة تنفيذ وصيته فيه إلا بعد الشورى فيه. وقصة أبي بكر وعمر تشهد ببطلان قوله مع قوله بصحة إمامتهما. وزعم قوم من الإمامية أن لا مدخل للوصية في الإمامة وأنّ طريقها النص من الإمام على من يكون بعده. وهذا لو عقلوه تحقيق للوصية بها إليه والله أعلم."], [243, "المسألة العاشرة من هذا الأصل\r"]], "pg": [242, 243]}, "540.222": {"x": [[243, "في صحة إمامة عمر وعثمان رضي الله عنهما\rكل من أنكر إمامة أبي بكر من الروافض فهو منكر لإمامة عمر وعثمان. وزادت الكاملية منهم على تكفيرها أبا بكر وعمر وعثمان تكفيرها عليّا لتركه قتال أبي بكر وعمر. وكل من قال بإمامة أبي بكر نصّا أو اختيارا قال بإمامة عمر من جهة وصية أبي بكر إليه. واختلف المثبتون لإمامة أبي بكر وعمر في إمامة عثمان: فأثبتها الجمهور منهم. وزعم الخوارج أن أبا بكر وعمر كانا إمامي حقّ وإن عثمان كان على الخلافة ست سنين وادّعوا إنه كفر بعدها بالأحداث التي نقموها منه. وقالوا إن عليّا كان على الحق إلى وقت تحكيم أبي موسى وعمرو بن العاص وإنه كفر\r__________________\r(1) [الحسين].\r\rبعد ذلك. وقد مضى الكلام في صحة إمامة أبي بكر ومضى الكلام في صحة الوصية بالإمامة. وأما الكلام في براءة عثمان مما قذف به فسيأتي بعد هذا إنشاء الله تعالى.\rالمسألة الحادية عشر من هذا الأصل\r"]], "pg": [243, 243]}, "540.223": {"x": [[243, "في إمامة علي رضي الله عنه\rأجمع أهل الحق على صحة إمامة عليّ رضي الله عنه وقت انتصابه لها بعد قتل عثمان رضي الله عنه. وخالفهم في ذلك طوائف أولاها الكاملية من الروافض فإنهم أكفروا عليّا بتركه قتال أبي بكر وعمر. والطائفة الثانية الخوارج فإنهم قالوا إنّ عليّا كان على حق إلى وقت خروج الحكمين للحكم بينه وبين معاوية ثم كفر وكفر معاوية وأتباعهما. والطائفة الثالثة أصمّية القدرية فإن الأصم زعم أن الإمامة لا تنعقد إلا بالإجماع على المعقود له ولا يثبت بالشورى واختيار بعض الأمة. ونتيجة هذا القول الطعن في إمامة عثمان وعلي. أما عثمان فلأنّ إمامته كانت بعقد بعض أهل الشوري له وهو عبد الرحمن بن عوف. وأمّا علي فلأنّ أهل الشام ثبتوا على خلافه إلى أن مضى لسبيله. وكان الأصم يقول بإمامة معاوية لإجماع الأمة عليه بعد علي وكفاه خزيا ردّ إمامة عليّ مع إثباته إمامة معاوية والكلام على الخوارج يأتي بعد هذا."], [244, "المسألة الثانية عشرة من هذا الأصل\r"]], "pg": [243, 244]}, "540.224": {"x": [[244, "في قتلة عثمان وخاذليه\rأجمع أهل السنة على أن عثمان كان إماما على شرط الاستقامة إلى أن قتل. وأجمعوا على أن قاتليه قتلوه ظلما فإن كان فيهم من استحلّ دمه فقد كفر. ومن تعمّد قتله من غير استحلال كان فاسقا غير كافر والذين هجموا عليه واشتركوا في دمه معروفون يقطع بفسقهم منهم محمد بن أبي بكر (1) ورفاعة بن رافع\r__________________\r(1) هو محمد بن أبي بكر الصديق، وكان علي ولاه على مصر وكان علي قد تزوج بأمه أسماء بنت عميس ولما استقر في مصر جهز معاوية جيشا وأمر عليهم معاوية بن خديج الكندي ـ"], [245, "والحجاج بن غزنة وعبد الرحمن بن خصل الجمحي وكنانة بن بشر النجيبي وسندان بن حمران المرادي وبسرة بن رهم ومحمد بن أبي حذيفة وابن عيينة وعمرو بن الحمق الخزاعي. وأما الذين قعدوا عن نصرة عثمان فهم فريقان: فريق كانوا معه في الدار فدفعوا عنه، كالحسن بن علي بن أبي طالب وعبد الله بن عمر والمغيرة بن الأخنس وسعيد بن العاص وسائر من كان في الدار من موالي عثمان، إلى أن أقسم عليهم عثمان بترك القتال وقال لغلمانه: من وضع سلاحه فهو حرّ، فهؤلاء أهل طاعة وبر وإحسان. والفريق الثاني من القعدة عن نصرته فريقان فريق أرادوا نصرة عثمان فنهاهم عثمان عنها، كعلي بن أبي طالب وسعد بن أبي وقاص وأسامة بن زيد ومحمد بن مسلمة وعبد الله بن السلام، فهؤلاء معذورون لأنهم قعدوا عنه بأمره. والفريق الثاني قوم من السّوقة أعانوا الهاجمين فشاركوهم في الفسق والله حسبهم. واختلفت القدرية في هؤلاء: فتوقف واصل بن عطاء وعمرو بن عبيد في عثمان وقاتليه وخاذليه لأن أحد الفريقين عندهم فاسق كما أن أحد المتلاعنين فاسق والفاسق عندهم لا مؤمن ولا كافر. وقال أبو الهذيل: أتولّى عثمان على حياله وقتلتهم على حيالهم. وقال الجبائي وابنه بموالاة عثمان والبراءة من قاتليه. وزعم المعروف منهم بالمراد (1) أن عثمان فسق وأن قاتليه فسقوا أيضا لأن فسق عثمان لم يوجب قتله. فعلى قوله يكون كلا الفريقين في النار. ودليلنا على براءة عثمان مما قذف به ورود الروايات الصحيحة بشهادة الرسول له صلىلله عليه وسلم بالجنة عند تجهيز جيش العسرة وما روي من أنه يدخل الجنة بلا حساب ولا يدخل الجنة إلا مؤمن. وقد روي أن النبي صلىلله عليه وسلم صعد جبل حراء ومعه أبو بكر وعمر وعثمان وعليّ فقال: «اسكن حراء فما عليك إلا نبي أو صديق أو شهيد» (2) وفي هذا دليل على أن عثمان قتل شهيدا سعيدا. ودليل صحة إمامته\r__________________"], [246, "ـ فالتقيا فانهزم عسكر محمد واختفى هو في بيت امرأة فدلت عليه فقتل واحرق وقيل قتله عمرو بن العاص أو عمرو بن عثمان سنة ثمان وثلاثين ..\r(1) [بالمردار].\r(2) أخرجه النسائي بلفظ: اسكن ثبير فإنما عليك نبي وصديق وشهيدان. 6/ 236. كما ـ\r\rإجماع الأمة بعد قتل عمر (1) [على] أن الإمامة لواحد من أهل الشورى وكانوا ستة فاجتمع خمسة عليه فحصل إجماع الأمة على إمامته.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [244, 246]}, "540.225": {"x": [[246, "في حكم أهل صفين والجمل\rأجمع أصحابنا على أن عليّا رضي الله عنه كان مصيبا في قتال أصحاب الجمل وفي قتال أصحاب معاوية بصفّين. وقالوا في الذين قاتلوه بالبصرة إنهم كانوا على الخطأ. وقالوا في عائشة وفي طلحة والزبير إنهم أخطئوا ولم يفسقوا لأنّ عائشة قصدت الإصلاح بين الفريقين فغلبها بنو ضبّة وبنو الأزد على رأيها فقاتلوا عليّا فهم الذين فسقوا دونها. وأما الزّبير فإنه لما كلمه عليّ يوم الجمل عرف أنه على حق فترك قتاله وهرب من المعركة راجعا إلى مكة فأدركه عمرو بن جرموز بوادي السّباع فقتله وحمل رأسه إلى علي فبشّره عليّ بالنار. وأما طلحة فإنه لما رأى القتال بين الفريقين همّ بالرجوع إلى مكة فرماه مروان بن الحكم بسهم فقتله فهؤلاء الثلاثة بريئون من الفسق والباقون من أتباعهم الذين قاتلوا عليّا فسقة. وأما أصحاب معاوية فإنهم بغوا وسماهم النبي صلىلله عليه وسلم بغاة في قوله لعمّار: «تقتلك الفئة الباغية (2)» ولم يكفروا بهذا البغي، لأن عليّا قال: إخواننا بغوا علينا ولأنه قال لأصحابه لا تتبعوا مدبرا ولا تذفّفوا على جريح فلو كانوا كفرة لأباح ذلك فيهم. وزعمت الروافض أن طلحة والزبير وعائشة وأتباعهم يوم الجمل كفروا في قتالهم عليّا وكذلك قالوا في معاوية وأصحابه بصفين. وكذلك قول الخوارج في أصحاب الجمل وأصحاب معاوية. وزعم قوم أن الفريقين كانوا على الخطأ وإنما أصاب\r__________________"], [247, "ـ أخرجه البخاري بلفظ: اسكن أحد فإنما عليك نبي وصديق وشهيدان. وفي رواية اسكن أحد ... كما أخرجه الترمذي بلفظ: اسكن ثبير فإنما عليك ... ورواه عن ثمامة بن حزن برقم 3703.\r(1) [علي].\r(2) أخرجه الحاكم في المستدرك عن خزيمة وعن عمرو بن حزم بلفظ: تقتل عمارا الفئة الباغين 3: 397، وبلفظ تقتلك الفئة الباغية 3: 386."], [248, "القعدة عن القتال في ذلك الزمان كسعد بن أبي وقّاص وعبد الله بن عمر ومحمد بن سلمة الأنصاري وأسامة بن زيد. وقال أكثر الكرّامية بتصويب الفريقين يوم الجمل. وقال آخرون منهم: إنّ عليّا أصاب في محاربة أهل الجمل وأهل صفين ولو صالحهم على شيء أرفق بهم لكان أولى وأفضل، فأما محاربته للخوارج فقد كانت فرضا عليه. وقال واصل بن عطاء وعمرو بن عبيد والنظّام وأكثر القدرية نتولّى عليّا وأصحابه على انفرادهم ونتولى طلحة والزبير وأتباعهما على [انفرادهم] ولكن لو شهد علي مع رجل من أصحابه قبلت شهادتهما ولو شهد طلحة أو الزبير مع واحد من أصحابه قبلت شهادتهما ولو شهد عليّ مع طلحة على باقة بقل لم نحكم بشهادتهما لأن أحدهما فاسق والفاسق مخلد في النار وليس بمؤمن ولا كافر. وزعم بكر بن أخت (1) عبد الواحد أن عليّا ومخالفيه مثل طلحة والزبير صاروا مشركين غير أنهم في الجنة لأنهم شهدوا بدرا وفي الحديث: أن الله تعالى قال لأهل بدر اعملوا ما شئتم فقد غفرت لكم. وقال حوشب وهشام الأوقص وأتباعهما من القدرية سلم (2) القادة وهلك الأتباع. وقال الأصم في عليّ ومعاوية أقوالا جعل معاوية فيها أحسن حالا من علي. وسخنت عيون الرافضة المعتزلة بشيوخها في الاعتزال مع أقوال المعتزلة في عليّ كما بيناه. والدليل على صحة إيمان عليّ وطلحة والزبير كونهم من أهل بيعة الرضوان وقد أخبر الله بأنه رضي عنهم ورضاء الله تعالى إنما يكون على العاقبة دون الحال فصح بهذا أن عاقبة هؤلاء كلهم الجنة. ولو كانت عائشة كافرة كما زعمت الخوارج لم يخل أن تكون كافرة قبل القتال أو في حال القتال ولو كانت كافرة قبل القتال لزم أن يكون النبي صلىلله عليه وسلم قد تزوج كافرة ولم يكن له نكاح الكافرة وإن كانت ارتدت زمان القتال كان جائزا سبيها وكان عليّ يرى استرقاق المرتدات فلما لم يسترقّها دل على أنها كانت مسلمة مؤمنة على رغم مبغضيها.\r__________________\r(1) [عبد الله]."], [249, "(2) [نجت].\r\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [246, 249]}, "540.226": {"x": [[249, "في حكم الخوارج والحكمين\rزعمت الخوارج أن تحكيم أبي موسى وعمرو بن العاص كان كفرا من عليّ ومعاوية وإن الحكمين كفرا بما صنعا. واختلف هؤلاء فيما بينهم: فمنهم من قال إنّ كفر عليّ والحكمين كفر شرك وهذا قول الأزارقة منهم. ومنهم من قال إنّ ذلك كفر نعمة وليس بشرك وهذا قول الأباضية منهم. واختلفت الرافضة في ذلك: فمنهم من قال أصاب عليّ وكفر الحكمان بالتبديل. ومنهم من قال أخطأ عليّ ولم يفسق بخطئه. وقال إبراهيم النظّام وبشر بن المعتمر بتصويب عليّ وهلاك الحكمين بالفسق والفاسق عندهما لا مؤمن ولا كافر وهو مخلد في النار. وقال الجبّائي بصحة توبة أبي موسى. وزعم الأصم أن أبا موسى أصاب في خلع عليّ حتى يجتمع الناس على إمام. وقال أصحابنا في تصويب علي في قتاله وفي التحكيم وقالوا بتخطئة الحكمين إلا أن خطأ أبي موسى من وجه واحد وهو خلعه عليّا مع علمه بأنه أفضل أهل زمانه. وخطأ عمرو بن العاص من وجهين: أحدهما في خلعه عليّا، والثاني: في عقده الخلافة لمعاوية. وقالوا بتكفير الخوارج في تكفيرهم عليّا وأصحابه وفي تكفيرهم أصحاب الذنوب كلها. فأما اعتلالهم في تكفير عليّ رضي الله عنه بأنه رضي بالحكمين في حق له فليس ذلك بأعظم من أمر الله تعالى بإخراج حكمين في الشقاق بين الزوجين وأمره بالرجوع إلى حكم ذوي عدل في جزاء الصيد. وقد قالت. الخوارج لعليّ: إنّا قاتلنا معك يوم الجمل فلما ظفرنا منعتنا عن سبي النساء والذرّية فقال: أيكم كان يأخذ عائشة في سهمه فسكتوا فقال لهم: إن النساء والذرية كانوا على أصل الفطرة ولم يرتدوا ولم يقاتلوا وبمثل هذا يفسد جميع شبه الخوارج على ذلك.\r\rالمسألة الخامسة عشرة من هذا الأصل\r"]], "pg": [249, 249]}, "540.227": {"x": [[249, "في جواز إمامة المفضول"], [250, "اختلفوا في جواز إمامة المفضول بعد أن يكون صالحا لها لو لم يكن الأفضل منه موجودا. فقال أبو الحسن الأشعري: يجب أن يكون الإمام أفضل أهل زمانه في شروط الإمامة ولا تنعقد الإمامة لأحد مع وجود من هو أفضل منه فيها. فإن عقدها قوم للمفضول كان المعقود له من الملوك دون الأئمة. ولهذا قال في الخلفاء الأربعة: أفضلهم أبو بكر ثم عمر ثم عثمان ثم علي. واختار شيخنا أبو العباس القلانسي جواز عقد الإمامة للمفضول إذا كانت فيه شروط الإمامة مع وجود الأفضل منه. وبه قال الحسين بن الفضل ومحمد بن إسحاق بن خزيمة وأكثر أصحاب الشافعي رضي الله عنه. ولم يختلف هؤلاء في تقديم أبي بكر وعمر على سائر الصحابة ولا في تفضيل أبي بكر على عمر. وإنما اختلفوا في عليّ وعثمان: فذهب الحسين بن الفضل وابن خزيمة إلى تفضيل عليّ، وقال القلانسي في بعض كتبه: لا أدري أيهما أفضل. وقال النظّام والجاحظ إنّ الإمامة لا يستحقها إلّا الأفضل ولا يجوز صرفها إلى المفضول. وقال الباقون من المعتزلة الأفضل أولى بها، فإن عرض للأمة خوف فتنة من عقدها للافضل جاز لهم عقدها للمفضول. واجتمعت الروافض على أنه لا يجوز إمامة المفضول إلا سليمان بن جرير الزيدي فإنه قال بإمامة عثمان ست سنين مع كون عليّ أفضل منه عنده. ودليل قول من أجاز إمامة المفضول مبني على صحة إمامة أبي بكر وعمر فإذا صحت إمامة عمر فقد قال في أهل الشورى: لو كان أبو عبيدة بن الجراح حيّا لولّيته عليكم، مع علمه بأن عليّا أفضل منه. وفي هذا دليل على أن الصحابة كانوا يرون جواز إمامة المفضول.\r\rالأصل الرابع عشر\r"]], "pg": [249, 250]}, "540.228": {"x": [[250, "من أصول هذا الكتاب\rفي بيان أحكام العلماء والأئمة\rيقع في هذا الأصل خمس عشرة مسألة هذه ترجمتها:\rمسألة في تفضيل الأنبياء على الملائكة.\rمسألة في إبليس هل كان من الملائكة أم من غيرهم.\rمسألة في تفضيل بعض الأنبياء على بعض.\rمسألة في تفضيل الأنبياء على الأولياء.\rمسألة في معرفة مراتب الصحابة."], [251, "مسألة في بيان الأفضل من الصحابة.\rمسألة في مراتب التابعين وأتباعهم.\rمسألة في تفضيل مراتب النساء.\rمسألة في بيان أفضلهن في الرتبة.\rمسألة في ترتيب أئمة الدين في علم الكلام.\rمسألة في ترتيب أئمة الفقه من أهل السنة.\rمسألة في ترتيب الأئمة في علم الحديث.\rمسألة في معرفة أئمة التصوف والزهد.\rمسألة في ترتيب أئمة اللغة والنحو.\rمسألة في تحقيق السنة في أهل الجهاد والثغور. فهذه مسائل هذا الأصل وسنذكر في كل واحدة منها مقتضاها إن شاء الله تعالى.\r\rالمسألة الأولى من هذا الأصل\r"]], "pg": [250, 251]}, "540.229": {"x": [[251, "في تفضيل الأنبياء على الملائكة"], [252, "اختلفوا في هذه المسألة: فقال جمهور أصحابنا بتفضيل الأنبياء على الملائكة وأجاز بعضهم أن يكون في المؤمنين من هو أفضل من الملائكة ولم يشر بذلك إلى واحد بعينه. ولم يقل أحد من أهل الحديث بتفضيل الملائكة على الأنبياء غير الحسين بن الفضل البجلي. واختلفت المعتزلة في هذا: فزعم أكثرهم أن الملائكة أفضل من الأنبياء حتى فضّلوا زبانية النار على كل نبي. وزعم آخرون منهم أن من لا معصية له من الملائكة أفضل من الأنبياء، فأما من عصى منهم أدنى معصية كهاروت وماروت فإن الأنبياء أفضل منهم وهذا قول الأصم منهم. وزعمت الإمامية أن الأئمة أفضل من الملائكة. وزعمت الغلاة منهم في أنفسهم أنهم أفضل من الملائكة وهذا قول البزيغية من الخطابية. واستدل من قال بتفضيل الملائكة على الأنبياء عليهم السلام بقول الله تعالى: (لَنْ يَسْتَنْكِفَ الْمَسِيحُ أَنْ يَكُونَ عَبْداً لِلَّهِ وَلَا الْمَلائِكَةُ الْمُقَرَّبُونَ) (1). وهذا لا يدل على ما قصدوه لأنه قد يقال مثل هذا فى المتساويين. على أنه جمع الملائكة ونحن لا نقول في أحد من الأنبياء إنه أفضل من الملائكة بأجمعها وإن قلنا فيه أفضل من كل واحد منهم كما لا نقول في النبي عليه السلام إنه أعلم من جميع الملائكة وإن كان جائزا أن يكون أعلم من كل واحد منهم. واستدلوا بقوله: (ما نَهاكُما رَبُّكُما عَنْ هذِهِ الشَّجَرَةِ إِلَّا أَنْ تَكُونا مَلَكَيْنِ أَوْ تَكُونا مِنَ الْخالِدِينَ) (2). وهذا يحتمل أن يكون معناه أنه منعكما منها لأنه يريد أن يجعلكما ملكين وعلما أنهما أفضل من الملائكة فرغبا عن سقوط درجتيهما فلذلك أقدما على الأكل من الشجرة. وقد روى أصحابنا عن ابن عباس وأعلام الصحابة تفضيل الأنبياء على الملائكة فلا اعتبار بخلاف المعتزلة بعدهم.\r__________________\r(1) سورة النساء آية 271.\r(2) سورة الأعراف آية 20.\r\rالمسألة الثانية من هذا الأصل\r"]], "pg": [251, 252]}, "540.230": {"x": [[252, "في بيان جنس إبليس اللعين"], [253, "قال أكثر أصحابنا مع البهشمية والأصمّية من المعتزلة إنّ إبليس كان من الجن، لقوله تعالى: (وَإِذْ قُلْنا لِلْمَلائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ كانَ مِنَ الْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِ) (1) ولأنه أخبر أنه خلقه من النار وقد روي في الخبر أن الملائكة مخلوقون من النور دون النار. وزعم الجاحظ أنه كان من الملائكة لأن الله تعالى قد استثناه منهم ومنع أن يكون الاستثناء من غير جنس المستثنى منه وقلنا إنما استثناه منهم لأنه كان حينئذ معهم فخالف الأمر وعصى واستكبر وأبى وكفر. وقد أجاز النحويون استثناء الشيء من غير جنسه وتكلموا في إعرابه وسماه البصريون منهم استثناء منقطعا واختلف فيه الفقهاء: فأجازه الشافعي في جميع وجوهه حتى قال: لو قال في إقراره له عليّ ألف إلا درهما أو إلا دينارا وفسّر الألف بما ليس من جنس استثناه قبل ذلك منه بعد أن يكون قيمة المستثنى منه أكثر من الاستثناء. وقال أبو حنيفة: إن كان الاستثناء مكيلا أو موزونا وجب أن يكون من جنس المستثنى منه وإن كان مذروعا أو معدودا جاز أن يكون من غير جنسه. وليس للجاحظ علم بما أجمع عليه النحويون والفقهاء فلا اعتبار بخلافه لهم.\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [252, 253]}, "540.231": {"x": [[253, "في تفضيل بعض الأنبياء على بعض\rكان ضرار بن عمرو يقول: لا يجوز تفضيل بعضهم على بعض بعينه واسمه. وقال أصحابنا مع أكثر الأمة بتفضيل بعضهم على بعض وقالوا إنّ نبينا صلىلله عليه وسلم أفضلهم وأولو العزم من الرسل أفضل من غيرهم وهم خمسة: نوح وإبراهيم وموسى وعيسى ومحمد عليهم السلام. ومن بعث منهم إلى الكافة أفضل ممن بعث منهم إلى قوم مخصوصين. وقد قال نبينا صلىلله عليه وسلم: «أنا سيد ولد آدم» (2). وقال\r__________________\r(1) سورة الكهف آية 50.\r(2) رواه الحاكم في المستدرك عن جابر 2: 605 ورواه الترمذي عن أبي سعيد برقم 3148 و 3615 وعن أبي هريرة برقم 2434."], [254, "أيضا: «آدم ومن دونه تحت لوائي». وقال: «لو كان موسى حيّا ما وسعه إلا اتباعي».\rالمسألة الرابعة من هذا الأصل\r"]], "pg": [253, 254]}, "540.232": {"x": [[254, "في تفضيل الأنبياء على الأولياء\rأجمع أصحابنا مع أكثر الأمة على أن كل نبي أفضل من كل ولي ليس بنبي. وزعمت الغلاة من الروافض أن الأئمة أفضل من الأنبياء. وزعمت الخطابية منهم أن أبا الخطاب كان أفضل من جعفر الصادق مع قولهم بنبوّة جعفر وقول بعضهم بإلهيته. وزعمت الكرّامية أن في الأولياء من هو أفضل من بعض الأنبياء. ومنهم من ادعى فضل زعيمهم ابن الكرّام على ابن مسعود وكثير من الصحابة ولم يجسر على تفضيله على الأنبياء خوفا من السيف. وهذا قول لا يستحق صاحبه الكلام عليه.\rالمسألة الخامسة من هذا الأصل\r"]], "pg": [254, 254]}, "540.233": {"x": [[254, "في معرفة مراتب الصحابة رضوان الله عليهم\rالصحابة رضي الله عنهم على مراتب؛ أعلاهم رتبة السابقون منهم إلى الإسلام. وأوّل من سبق منهم من الرجال أبو بكر ومن أهل البيت علي ومن النساء خديجة ومن الموالي زيد بن حارثة ومن الحبشة بلال ومن الفرس سلمان. واختلفوا في علي وأبي بكر فأكثر أصحاب التواريخ على أن عليّا أسلم قبل أبي بكر بيوم. وإنما اختلفوا في سنّه وبلوغه عند إسلامه. وأجمعوا على أن أوّل من أسلم من تميم واقد بن عبد الله التميمي وهو أول مسلم قتل كافرا في دولة الإسلام لأنه قتل عمرو بن الحضرمي قبل وقعة بدر. وقال محمد بن إسحاق بن يسار: أول ذكر من الناس آمن برسول الله صلىلله عليه وسلم علي بن أبي طالب ثم أسلم زيد بن حارثة مولى رسول الله صلىلله عليه وسلم ثم أسلم أبو بكر ثم دعا أبو بكر إلى الإسلام من وثق به فأسلم على يديه عثمان بن عفان وطلحة بن عبيد الله والزبير بن العوام وعبد الرحمن بن عوف وسعد بن أبي وقاص فجاء بهم إلى النبي صلىلله عليه وسلم فأسلموا وصلّوا معه ثم أسلم أبو"], [255, "عبيدة عامر بن عبد الله بن الجراح ثم دخل الناس إرسالا في دين الإسلام. وأوّل من أسلمت من النساء خديجة رضي الله عنها وكان إسلامها قبل إسلام علي وأبي بكر. ثم عاتكة بنت الخطاب أخت عمر بن الخطاب وأسماء بنت أبي بكر وعائشة بنت أبي بكر وأسماء بنت عميس امرأة جعفر بن أبي طالب بعد إسلام زوجها جعفر.\rوالطبقة الثانية من الصحابة: هم الذين أسلموا عند إسلام عمر وذلك أن عمر لمّا أسلم حمل رسول الله صلىلله عليه وسلم إلى دار الندوة فبايعه قوم من أهل مكة ويقال أصحاب دار الندوة.\rوالطبقة الثالثة: منهم أصحاب الهجرة الأولى إلى الحبشة وأول من هاجر منهم إلى الحبشة عثمان بن عفان مع امرأته رقية بنت رسول الله صلىلله عليه وسلم وأبو حذيفة ابن عتبة بن ربيعة والزبير بن العوّام وحمزة بن عبد المطلب وجعفر بن أبي طالب مع امرأته أسماء بنت عميس وولدت له بها عبد الله بن جعفر ومصعب بن عمير وعبد الرحمن بن عوف وكان جميع من لحق بالحبشة وهاجر إليها هربا من أذى المشركين، سوى أبنائهم الذين خرجوا معهم صغارا وولدوا بها، اثنين وثمانين رجلا.\rوالطبقة الرابعة: منهم أصحاب العقبة الأولى التي بايعه عليها جماعة يقال فيهم فلان عقبي. وفيهم اثنا عشر رجلا من الأنصار منهم أبو إمامة وأسعد بن زرارة وعوف ومعوذ ابنا الحرث بن رفاعة وهما ابنا عفراء ورافع بن مالك بن العجلان وذكوان بن عبد قيس وعبادة بن الصامت الخزرجي ويزيد بن ثعلبة وعباس بن عبادة بن نضلة وعقبة بن عامر بن نافر وعيينة بن عامر وحارثة بن ثعلبة الأوسي وأبو الهيثم وعويم بن ساعدة وجماعة من أهل مكة. فلما بايعه هؤلاء الاثنا عشر من الأنصار بعث معهم رسول الله صلىلله عليه وسلم بمصعب بن عمير ليصلي بهم بالمدينة ويقرئهم القرآن وهو أول مقرئ بالمدينة وأول أمير وردها من المسلمين ونزل على أسعد بن زرارة."], [256, "والطبقة الخامسة: أصحاب العقبة الثانية وأكثرهم من الأنصار وفيهم البراء بن معرور وكعب بن مالك الشاعر وعبد الله بن عمرو بن حرام وهو الذي أسلم ليلة هذه العقبة وكانت الليلة الوسطى من ليالي أيام التشريق وكانوا سبعين رجلا من الأنصار ومعهم امرأتان وهما نسيبة بنت كعب وأسماء بنت عمير بن عدي وحضرهم رسول الله صلىلله عليه وسلم ومعه عمّه العباس وهو على دين قومه إلا أنه هو الذي أخذ عليهم الميثاق لرسول الله صلىلله عليه وسلم. وأوّل من بايع منهم رسول الله صلىلله عليه وسلم في هذه الليلة البراء بن معرور وأخذ بيده وقال والذي بعثك بالحق لنمنعنّك مما نمنع منه اذرنا. ثم بايعه أبو الهيثم بن التّيهان وقال لهم رسول الله صلىلله عليه وسلم أخرجوا إليّ منكم اثني عشر نفسا كفلاء على قومهم بما فيهم فأخرجوا منهم اثني عشر نقيبا تسعة من الخزرج وثلاثة من الأوس وقال رسول الله صلىلله عليه وسلم لهؤلاء النقباء أنتم على قومكم كفلاء ككفالة الحواريين لعيسى ابن مريم وأنا كفيل على قومي قالوا نعم. وكان سعد بن عبادة والمنذر بن عمرو من جملة النقباء وكذلك أسيد بن حضير وسعد بن خثيمة وأسعد بن زرارة وسعيد بن الربيع الخزرجي ورافع بن مالك بن العجلان والبراء بن معرور وعبد الله بن عمرو بن حرام وعبادة بن الصامت.\rوالطبقة السادسة: منهم المهاجرون مع رسول الله صلىلله عليه وسلم إلى المدينة ومن أدركه منهم بقباء قبل دخوله المدينة وكان أبو بكر ممن صحبه في الهجرة مع مولاه عامر بن فهيرة ودليلهما على الطريق عبد الله بن أريقط وكان على دين قومه. وأبو بكر ثانيه في الغار وحده وكان عليّ رضي الله عنه قد خلفه بمكة على رد الودائع التي كانت عنده ثم لحق به بقباء.\rوالطبقة السابعة: المهاجرون بين دخول رسول الله صلىلله عليه وسلم المدينة وبين بدر."], [257, "والطبقة الثامنة: منهم البدريون وهم ثلاثمائة وثلاثة عشر رجلا كعدد الرسل من الأنبياء عليهم السلام وكعدد من ثبت مع طالوت في حرب جالوت. وقد ورد [روي] في أهل بدر أن الله قال فيهم: اعملوا ما شئتم فقد غفرت لكم.\rوالطبقة التاسعة: منهم أصحاب أحد غير رجل منهم اسمه قزمان فإنه كان منافقا وقتل يومئذ جماعة من المشركين وقتل. وفيه قال رسول الله صلىلله عليه وسلم: «إنّ الله\r\rتعالى يؤيد هذا الدين بالرجل الفاجر». والباقون منهم من أهل الجنة وهم مقدار سبعمائة رجل.\rوالطبقة العاشرة: منهم أصحاب الخندق وعبد الله بن عمر معدود فيهم.\rوالطبقة الحادية عشرة: هم المهاجرون بين الخندق والحديبية.\rوالطبقة الثانية عشرة: أصحاب بيعة الرضوان بالحديبية عند الشجرة وكانت بالقرب من بئرها وفقدت بعد ذلك.\rوالطبقة الثالثة عشرة: المهاجرون بين الحديبية وبين فتح مكة منهم أبو هريرة ومنهم خالد بن الوليد وعمرو بن العاص وعبد الله بن عثمان بن طلحة وآخرهم العباس عمّ رسول الله صلىلله عليه وسلم فإنه استقبله سنة الفتح بالأبواء فقال له يا عمّ ختمت بك الهجرة كما ختمت بي النبوة ولم يكن لأحد بعد الفتح أجر الهجرة وإن كان له أجر الإسلام.\rوالطبقة الرابعة عشرة: الذين أسلموا يوم فتح مكة وفي ليلته منهم أبو سفيان بن حرب وحكيم بن حزام وأبو سفيان بن الحارث. وعكرمة بن أبي جهل وصفوان بن أمية أسلما بعد ذلك بأيام.\rوالطبقة الخامسة عشرة: الذين دخلوا في دين الله أفواجا بعد ذلك ونزل فيهم: (إِذا جاءَ نَصْرُ اللهِ وَالْفَتْحُ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللهِ أَفْواجاً) (1).\rوالطبقة السادسة عشرة: صبيان أدركوا رسول الله صلىلله عليه وسلم وقلّت روايتهم عنه كسبطيه الحسن والحسين رضي الله عنهما وكعبد الله بن الزبير."], [258, "والطبقة السابعة عشرة: صبيان حملوا إليه عام حجة الوداع وقبيل ذلك ليست لهم روايات صحيحة كمحمد بن أبي بكر والسائب بن يزيد وعبد الله بن ثعلبة بن أبي صعتر وعبد الله بن عامر بن كريز ومن هذه الطبقة قوم رأوا رسول الله صلىلله عليه وسلم\r__________________\r(1) سورة النصر آية 1 و 2.\r\rفحسب، كأبي الطفيل وأبي جحيفة فإنهما رأياه في الطواف وعند زمزم. فأما المخضرمون الذين أدركوا الجاهلية والإسلام ولم يرزقوا رؤية رسول الله صلىلله عليه وسلم فمنهم أبو عمرو سعد بن إياس الشيباني وسويد بن غفلة الكندي وشريح بن هانئ الحارثي وعمرو بن ميمون الأودي والأسود بن يزيد النخعي ومسعود بن حراش أخو ربعي وأبو عثمان النهدي وأبو رجاء العطاردي وأبو الحلال العتكي وجبير بن نفير والأحنف بن قيس ومن جرى مجراهم وهؤلاء عدادهم في التابعين.\rالمسألة السادسة من هذا الأصل\r"]], "pg": [254, 258]}, "540.234": {"x": [[258, "في بيان الأفضل من الصحابة\rأصحابنا مجمعون على أن أفضلهم الخلفاء الأربعة ثم الستة الباقون بعدهم إلى تمام العشرة وهم طلحة والزبير وسعد بن أبي وقاص وسعيد بن زيد بن عمرو بن نفيل وعبد الرحمن بن عوف وأبو عبيدة بن الجراح ثم البدريون ثم أصحاب أحد ثم أهل بيعة الرضوان بالحديبية. واختلف أصحابنا في تفضيل عليّ وعثمان فقدم الأشعري عثمان وبناه على أصله في منع من إمامة المفضول. وقال محمد بن إسحاق بن خزيمة والحسين بن الفضل البجلي بتفضيل علي رضي الله عنه. وقال القلانسي: لا أدري أيهما أفضل وأجاز إمامة المفضول.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [258, 258]}, "540.235": {"x": [[258, "في بيان مراتب التابعين"], [259, "وفائدة هذه المسألة أن من لم يعرف مراتب التابعين ربما التبس عليه أمر بعضهم فظنه صحابيا وجعل مرسله مسندا وربما ظنه من أتباع التابعين فبخس حظه. وهم على خمس عشرة طبقة أعلاهم طبقة [أعلامهم طبقة من أدرك العشرة الذين شهد لهم رسول الله صلىلله عليه وسلم بالجنة أو أدرك أكثرهم ومن هذه الطبقة أبو الرجاء] أبو رجاء العطاردي وأبو عثمان النهدي وسعيد بن المسيب وقيس بن أبي حازم وأبو ساسان حضير بن المنذر وأبو وائل شقيق بن سلمة وآخرهم في الطبقة من لقي"], [260, "أنس بن مالك من أهل البصرة أو عبد الله بن أبي أوفى من أهل الكوفة أو السائب بن يزيد من أهل المدينة أو عبد الله بن الحرث بن جزّ من أهل الحجاز أو أبا إمامة الباهلي من أهل الشام. ومن المخضرمين الدين أدركوا الجاهلية والإسلام ولم يرزقوا لقاء النبي صلىلله عليه وسلم أبو رجاء العطاردي وأبو وائل الأسدي وأبو عثمان النهدي وأبو عمرو سعد بن إياس الشيباني وأبو عبد الله عمرو بن ميمون الأودي وأبو رافع الصائغ وأبو الحلال العتكي وأبو أمية سويد بن غفلة الكندي وشريح بن هانئ الحارثي والأسود بن يزيد النخعي والأسود بن هلال المخارقي (1) والمعرور بن سويد وعبد خير بن يزيد الخيواني ومسعود بن حراش أخو ربعي بن حراش ومالك بن عمير وغنيم بن قيس. وقد عدّ في التابعين قوم ولدوا في زمان النبي صلىلله عليه وسلم ولم يسمعوا منه كيوسف بن عبد الله بن سلام ومحمد بن أبي بكر وسهل بن حنيف وعبد الله بن عامر بن ربيعة وعبيد الله بن ثعلبة بن أبي صعتر وأبي عبد الله الصّنابحي وعمرو بن سلمة الجرمي وعبيد الله بن عمير وسلمان بن ربيعة الباهلي وطبقة بعدهم قوم من التابعين ولم يصح سماع أحد منهم عن أحد من الصحابة كإبراهيم بن سويد النخعي وبكير بن أبي الشّميط وبكير بن عبد الله بن الأشج وثابت بن عجلان الأنصاري وسعيد بن عبد الرحمن الرقاشي وأخيه واصل بن حرة. وطبقة بعدهم قوم من أتباع التابعين وقد لقوا بعض الصحابة كأبي الزناد عبد الله [وعبد الله] بن ذكوان وهشام بن عروة وموسى بن عقبة.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [258, 260]}, "540.236": {"x": [[260, "في تفصيل مراتب النساء\rفي الحديث: أن سيدة نساء العالمين أربع وإنهن أفضل نساء العالمين وخيرهن وهن: آسية امرأة فرعون ومريم بنت عمران وخديجة بنت خويلد وفاطمة بنت رسول الله صلىلله عليه وسلم.\r__________________\r(1) [المحاربي].\r\rالمسألة التاسعة من هذا الأصل\r"]], "pg": [260, 260]}, "540.237": {"x": [[260, "في فضل عائشة وفاطمة"], [261, "واختلفوا في فضل عائشة وفاطمة فكان شيخنا أبو سهل محمد بن سليمان الصعلوكي وابنه سهل بن محمد يفضّلان فاطمة على عائشة. وهذا هو الأشبه بمذهب شيخنا أبي الحسن الأشعري وبه قال الشافعي. وللحسين بن الفضل رسالة في ذلك. وزعمت البكرية أن عائشة أفضل من فاطمة. والقول الأول هو الصحيح عندنا للخبر الوارد في أن أفضل النساء وخيرهن أربع وأفضل النساء بعد فاطمة وخديجة عائشة ثم أم سلمة ثم حفصة بنت عمر ثم الله أعلم بالأفضل منهن بعد ذلك (1). وقد قيل إن بنات كل نبي أفضل من زوجاته.\rالمسألة العاشرة من هذا الأصل\r"]], "pg": [260, 261]}, "540.238": {"x": [[261, "في ترتيب أئمة الدين في علم الكلام\rأول متكلمي أهل السنة من الصحابة علي بن أبي طالب لمناظرته الخوارج في مسائل الوعد والوعيد ومناظرته القدرية في القدر والقضاء والمشيئة والاستطاعة. ثم عبد الله بن عمر في كلامه على القدرية وبراءته منهم ومن زعيمهم المعروف بمعبد الجهني. وادّعت القدرية أن عليّا كان منهم وزعموا أن زعيمهم واصل بن عطاء الغزّال أخذ مذهبه من محمد وعبد الله ابني علي رضي الله عنه. وهذا من بهتهم ومن العجائب أن يكون ابنا علي قد علّما واصلا ردّ شهادة علي وطلحة والشكّ في عدالة علي. أفتراهما علماه إبطال شفاعة علي وشفاعة صهر المصطفى (2) صلىلله عليه وسلم. وأول متكلمي أهل السنة من التابعين عمر بن عبد العزيز وله رسالة بليغة في الرد على القدرية. ثم زيد بن علي بن الحسين بن علي بن أبي طالب وله كتاب في الرد على القدرية من القرآن؟. ثم الحسن البصري وقد ادّعته القدرية فكيف يصح لها هذه الدعوى مع رسالته إلى عمر بن عبد العزيز في ذم القدرية ومع طرده واصلا عن\r__________________\r(1) [أخرجه الحاكم في المستدرك 2: 597 كما أخرجه البخاري]\r(2) [أفتراهما علماه ابطال شهادة طلحة وصهر النبي]."], [262, "مجلسه عند إظهاره بدعته. ثم الشعبي وكان أشد الناس على القدرية. ثم الزهري وهو الذي أفتى عبد الملك بن مروان بدماء القدرية. ومن بعد هذه الطبقة جعفر بن محمد الصادق وله كتاب في الرد على القدرية وكتاب في الرد على الخوارج ورسالة في الرد على الغلاة من الروافض هو الذي قال: أرادت المعتزلة أن توحّد ربّها فألحدت وأرادت التعديل فنسبت البخل إلى ربها. وأول متكلميهم من الفقهاء وأرباب المذاهب أبو حنيفة والشافعي فإن أبا حنيفة له كتاب في الرد على القدرية سمّاه كتاب الفقه الأكبر وله رسالة أملاها في نصرة قول أهل السنة إنّ الاستطاعة مع الفعل ولكنه قال: إنها تصلح للضدين وعلى هذا قوم من أصحابنا. وقال صاحبه أبو يوسف في المعتزلة إنّهم زنادقة. وللشافعي كتابان في الكلام أحدهما في تصحيح النبوة والرد على البراهمة والثاني في الرد على أهل الأهواء. وذكر طرفا من هذا النوع في كتاب القياس وأشار فيه إلى رجوعه عن قبول شهادة المعتزلة وأهل الأهواء. فأما المريسي من أصحاب أبي حنيفة فإنما (فإنه] وافق المعتزلة في خلق القرآن وأكفرهم في خلق الأفعال. ثم من بعد الشافعي تلامذته الجامعون بين علم الفقه والكلام كالحارث بن أسد المحاسبي وأبي علي الكرابيسي وحرملة البويطي وداود الأصبهاني. وعلى كتاب الكرابيسي في المقالات معوّل المتكلمين في معرفة مذاهب الخوارج وساير أهل الأهواء. وعلى كتبه في الشروط وفي علل الحديث والجرح والتعديل معوّل الفقهاء وحفّاظ الحديث. وعلى كتب الحارث بن أسد في الكلام والفقه والحديث معوّل متكلمي أصحابنا وفقهائهم وصوفيتهم. ولداود صاحب الظاهر كتب كثيرة في أصول الدين مع كثرة كتبه في الفقه وابنه أبو بكر جامع بين الفقه والكلام والأصول والأدب والشعر."], [263, "وكان أبو العباس بن شريح أنزع الجماعة في هذه العلوم وله نقض كتاب الجاروف على القائلين بتكافؤ الأدلة وهو أشبع من نقض ابن الراوندي عليهم، فأما تصانيفه في الفقه فالله يحصيها. ومن متكلمي أهل السنة في أيام المأمون عبد الله بن سعيد التميمي الذي دمّر على المعتزلة في مجلس المأمون وفضحهم ببيانه وآثار بيانه في كتبه وهو أخو يحيى بن سعيد القطان وارث علم الحديث وصاحب الجرح والتعديل."], [264, "ومن تلامذة عبد الله بن سعيد عبد العزيز المكي الكتاني الذي فضح المعتزلة في مجلس المأمون. وتلميذه الحسين بن الفضل البجلي صاحب الكلام والأصول وصاحب التفسير والتأويل وعلى نكته في القرآن معوّل المفسرين وهو الذي استصحبه عبد الله بن طاهر والي خراسان إلى خراسان فقال الناس إنّه قد أخرج علم العراق كله إلى خراسان. ومن تلامذة عبد الله بن سعيد أيضا الجنيد شيخ الصوفية وإمام الموحدين وله في التوحيد رسالة على شرط المتكلمين وعبارة الصوفية. ثم بعدهم شيخ النظر وإمام الآفاق في الجدل والتحقيق أبو الحسن علي بن إسماعيل الأشعري الذي صار شجا في حلوق القدرية والنجارية والجهمية والجسمية والروافض والخوارج وقد ملأ الدنيا كتبه وما رزق أحد من المتكلمين من التّبع ما قد رزق لأن جميع أهل الحديث وكل من لم يتمعزل من أهل الرأي على مذهبه. ومن تلامذته المشهورين أبو الحسن الباهلي وأبو عبد الله بن مجاهد وهما اللذان أثمرا تلامذة هم إلى اليوم شموس الزمان وأئمة العصر كأبي بكر محمد بن الطيب قاضي قضاة العراق والجزيرة وفارس وكرمان وسائر حدود هذه النواحي. وأبي بكر محمد بن الحسين بن فورك وأبي إسحاق إبراهيم بن محمد المهراني. وقبلهم أبو الحسن علي بن مهدي الطبري صاحب الفقه والكلام والأصول والأدب والنحو والحديث. ومن آثاره تلميذ مثل أبي عبد الله الحسين بن محمد البزازي صاحب الجدل والتصانيف في كل باب من الكلام. وقبل هذه الطبقة شيخ العلوم [على الخصوص والعموم] أبو علي الثقفي وفي زمانه كان إمام أهل السنة أبو العباس القلانسي الذي زادت تصانيفه في الكلام على مائة وخمسين كتابا. وتصانيف الثقفي ونقوضه على أهل الأهواء زائدة على مائة كتاب."], [265, "وقد أدركنا منهم في عصرنا أبا عبد الله بن مجاهد ومحمد بن الطيب قاضي القضاة ومحمد بن الحسين بن فورك وإبراهيم بن محمد المهراني والحسين بن محمد البزازي وعلى منوال هؤلاء الذين أدركناهم شيخنا وهو لإحياء الحق كلّ وعلى أعدائه غلّ.\r\rالمسألة الحادية عشرة من هذا الأصل\r"]], "pg": [261, 265]}, "540.239": {"x": [[265, "في ترتيب أئمة الفقه من أهل السنة والجماعة"], [266, "مضى فقهاء الصحابة رضي الله عنهم على مذهب أهل السنة والجماعة. والعشرة الذين شهد لهم النبي صلىلله عليه وسلم بالجنة كانوا فقهاء. وأربعة من الصحابة تكلّم في جميع أبواب الفقه وهم: عليّ وزيد وابن عباس وابن مسعود. وهؤلاء الأربعة متى أجمعوا في مسألة على قول فالأمة فيها مجمعة على قولهم، غير مبتدع لا يعتبر خلافه في الفقه. وكل مسألة اختلف فيها هؤلاء الأربعة فالأمة فيها مختلفة. وكل مسألة انفرد فيها عليّ بقول عن سائر الصحابة تبعه فيها ابن أبي ليلى والشعبيّ وعبيدة السلماني. وكل مسألة انفرد فيها زيد بقول اتّبعه مالك والشافعي في أكثره ويتبعه خارجة بن زيد لا محالة. وكل مسألة انفرد فيها ابن عباس بقول تبعه فيها عكرمة وطاوس وسعيد بن جبير. وكل مسألة انفرد فيها ابن مسعود بقول تبعه فيها علقمة والأسود وأبو ثور. ثم من بعد الصحابة الفقهاء السبعة من أهل المدينة وهم: سعيد بن المسيّب وعروة بن الزبير وخارجة بن زيد والقاسم بن محمد بن أبي بكر وسليمان بن يسار وعبيد الله بن عبد الله وعتبة بن مسعود وأبو بكر بن عبد الرحمن بن الحرب بن هشام. وقد عدّ مالك قول هؤلاء السبعة إجماعا إذا اجتمعوا على قول واحد. ومن بعدهم أئمة الأمة في الفقه مثل الأوزاعي ومالك والثوري والشافعي وأبي ثور وأحمد بن حنبل وإسحاق بن راهويه وداود صاحب الظاهر وتلامذة هؤلاء في الفقه على سمت الحديث. فأما الذين وافقوهم في أصول الكلام وخالفوهم في فروع الأحكام فأبو حنيفة وابن أبي ليلى ومن في طبقتهما من أهل الرأي. وأصل أبي حنيفة في الكلام كأصول أصحاب الحديث إلا في مسألتين إحداهما أنه قال في الإيمان إنه إقرار ومعرفة والثانية قوله بأن لله مائيّة لا يعرفها إلا هو، كما ذهب إليه ضرار."], [267, "وقد دمّر أبو حنيفة في كتابه الذي سماه بالفقه الأكبر على المعتزلة ونصر فيه قول أهل السنة في خلق الأفعال وفي أن الاستطاعة مع الفعل [مع الفعل إلا أنه يصلح للضدين وهذا قول بعض أصحابنا] وقال أبو يوسف في المعتزلة إنهم زنادقة وقال محمد بن الحسين: من صلّى\r\rخلف القدري القائل بخلق القرآن يعيد صلاته، وردّ مالك شهادة أهل الأهواء كلهم. وقد أشار الشافعي إلى ذلك في كتاب القياس.\rالمسألة الثانية عشرة من هذا الأصل\r"]], "pg": [265, 267]}, "540.240": {"x": [[267, "في ترتيب أئمة الحديث والإسناد\rهؤلاء على طبقات في طبقة التابعين منهم أربعة وهم الزهري وسعيد بن جبير وهشام بن عروة وموسى بن عقبة. وقد عدّ فيهم أبو الزناد أيضا وكان قد أدرك أنس بن مالك وعبد الله بن عمر. والفقهاء السبعة من التابعين من هذه الجملة فإنهم كانوا مع فقههم أئمة في الحديث. وفي طبقة اتباع التابعين منهم مالك بن أنس وسفيان الثوري وسعيد بن الحجاج العتكي وابن جريج وسفيان بن عيينة وعبد الله بن المبارك ويحيى بن سعيد القطان التميمي."], [268, "وفي الطبقة التي بعدهم الشافعي وأحمد بن حنبل وإسحاق بن راهويه ويحيى بن يحيى بن التميمي وعبد الرحمن بن مهدي وعلي بن المديني. وهؤلاء أئمة الجرح والتعديل وقد ذكر الشافعي أصل هذا العلم في كتاب الرسالة وصنفه لعبد الرحمن بن مهدي. وعلي بن المديني هو الذي أكثر تصانيفه في هذا الباب، فمنها: كتاب الأسامي والكنى وكتاب الضعفاء وكتاب المدلّسين وكتاب الطبقات وكتاب علل المسند وكتاب الوهم الخطأ وكتاب قبائل العرب وكتاب التاريخ وكتاب الثقات وكتاب اختلاف الحديث وكتاب الأسامي الشاذّة وكتاب تفسير غريب الحديث وكتاب مذاهب المحدثين. وعلى كتب يحيى بن معين معوّل أهل الحديث في الجرح والتعديل. وإسحاق بن راهويه هو الذي أملى مسنده الكبير من حفظه فلم يخطئ في متن الحديث ولا في إسناده. ومنهم محمد بن يحيى الذهلي الذي قيل فيه إنّه وارث علم الزهري. ومنهم محمد بن إسماعيل البخاري صاحب المسند الصحيح والتاريخ الكبير وكتاب الضعفاء وما كان في عصره ولا بعده مثله. ومنهم أبو زرعة الرازي الذي قال فيه أحمد بن حنبل إنّه يحفظ ستمائة ألف حديث بأسانيدها. وأبو حاتم محمد بن إدريس الحنظلي من أقران أبي زرعة وابنه"], [269, "عبد الرحمن بن أبي حاتم إمام في الفقه والحديث والورع. ومنهم إبراهيم بن إسحاق الحربي إمام في الفقه والحديث والنحو واللغة ومن آثاره تلميذ مثل ثعلب النحوي. ومنهم مسلم بن الحجاج النيسابوري صاحب المسند الصحيح والكتب العشرة والطبقات والأقران والعلل والأسماء والكنى والتواريخ ونحوها. ومنهم محمد بن إبراهيم بن عبدة البوسنجي وتلامذته، مثل أبي عثمان والخفاف وأبي بكر الجارودي وإبراهيم بن أبي طالب ومحمد بن إسحاق بن خزيمة، كانوا يأخذون بركابه إذا ركب وكل واحد منهم إمام زمانه. ومنهم عثمان بن سعيد الدارمي الذي أخذ النحو واللغة عن ابن الأعرابي والفقه عن البويطي والحديث عن يحيى بن معين وعلي بن المديني وكان في كل نوع منه إماما. ومنهم محمد بن نصر المروزي صاحب إختلاف العلماء وإمام الفقه والكلام والحديث وكتابه في إختلاف العلماء يشتمل على أربعين مجلدة. ومن بركة آثاره تلميذ مثل أبي علي الثقفي. ومنهم محمد بن إسحاق بن خزيمة إمام الفقه والحديث مع ما كان فيه من مكابدة المتكلمين ثم إنه رجع إلى موافقة منه لهم. وأدركنا في عصرنا [رجالا] منهم أبو أحمد عبد الله بن عدي الحافظ الجرجاني وأبو أحمد محمد بن أحمد الحافظ وأبو عبد الله بن عبد الله البيّاع وأبو الحسين الحجاجي بنيسابور وأبو الحسن الدار قطني وابن شاهين وابن المظفّر وابن بكير بالعراق. وأقران هؤلاء جماعة يطول الكتاب بذكرهم. وكل من ذكرناهم وجدناهم مكفّرين لأهل القدر وسائر أهل الأهواء والبدع.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [267, 269]}, "540.241": {"x": [[269, "في ترتيب أئمة التصوف والإشارة\rهؤلاء منهم إبراهيم بن أدهم وإبراهيم بن سعيد العلوي صاحب الكرامات وإبراهيم الخواص وإبراهيم بن شيبان وأبو سليمان الداراني وأحمد بن أبي الحواري وأحمد بن عاصم الأنطاكي وأبو سعيد أحمد بن عيسى الخراز والفضيل بن عياض والجنيد وأبو الحسين النوري وأبو القاسم الحكيم وبشر"], [270, "الحافي وإدريس بن يحيى الخولاني وبنان الحمال وذو النون المصري وسري السقطي وأبو تراب النخشبي وجعفر الخصاف وجعفر الخلدي وحاتم الأصم وحمدون القصار ومعروف الكرخي وأبو علي الروذباري والمزين وخير النساج وابن عطاء والجريري والشبلي ورويم وسهل بن عبد الله التّستري وأبو حفص الحداد النيسابوري وأبو عثمان الخيبري وأبو يزيد البسطامي وعمرو بن عثمان المكي ويوسف بن الحسين وقبلهم الحارث بن أسد المحاسبي. وقد اشتمل كتاب تاريخ الصوفية لأبي عبد الرحمن السلمي على زهاء ألف شيخ من الصوفية ما فيهم واحد من أهل الأهواء بل كلهم من أهل السنة سوى ثلاثة منهم. أحدهم أبو حلمان الدمشقي فإنه تستر بالصوفية وكان من الحلولية. والثاني الحسين بن منصور الحلاج وشأنه مشكل. وقد رضيه ابن عطاء وابن خفيف وابن القاسم النصرآباذي. والثالث القنّاد اتهمته الصوفية بالاعتزال فطردوه لأن الطيب لا يقبل الخبيث.\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [269, 270]}, "540.242": {"x": [[270, "في ترتيب أئمة النحو واللغة من أهل السنة\rهؤلاء فريقان في المذهب: بصرية وكوفية. والكوفية منهم كالمفضّل الضبيّ وابن الأعرابي والكسائي والفرّاء والأحمر واللحياني وأبي عمرو الشيباني وإبراهيم الحرثي وثعلب وابن الأنباري وأبو مقسم وكلهم من أهل السنة ولإبراهيم الحرثي كتب في الرد على القدرية وأهل الأهواء. وللفراء كتاب في ذم القدرية. والبصريون منهم أوّلهم أبو الأسود الدّؤلي وله رسالة في ذم القدرية مع انتسابه إلى الشيعة. وبعده يحيى بن يعمر وعيسى بن عمر الثقفي وعبد الله بن إسحاق الحضرمي وكانا يذمّان القدرية وذمّا واصل بن عطاء في شكّه في شهادة علي وطلحة. وبعدهما أبو عمرو بن العلاء والخليل بن أحمد وخلف الأحمر. ولأبي عمرو بن العلاء كلام كثير في ذم القدرية وذمّ عمرو بن عبيد. وبعدهما الأصمعي وهو الذي طرد الجاحظ عن مجلسه وقنّعه بنعله وقال نعم قناع القدري النعل. والأخفشان أبو"], [271, "الخطاب وأبو الحسن سعيد بن مسعدة سنيّان والزجاج سنّيّ ومعانيه في القرآن أعلى مذهب أهل السنة. وبعدهما ابن دريد ونفطويه وكانا على مذهب الشافعي وقبلهما أبو حاتم السجستاني شيخ السنة شديد على القدرية. وكان سيبويه تلميذ حمّاد بن سلمة الذي كان سيفا على القدرية. وإنما نسب المبرد إلى الاعتزال لمجالسته الجاحظ وليس في كتبه شيء يدل على اعتزاله. وفي هذا دليل على أن جميع أئمة الدين في جميع العلوم من أهل السنة.\rالمسألة الخامسة عشرة من هذا الأصل\r"]], "pg": [270, 271]}, "540.243": {"x": [[271, "في تحقيق أهل السنة لأهل الثغور\rبيان هذا واضح. في ثغور الروم والجزيرة وثغور الشام وثغور أذربيجان وباب الأبواب كلهم على مذهب أهل الحديث من أهل السنة. وكذلك ثغور إفريقية وأندلس وكل ثغر وراء بحر المغرب أهله من أصحاب الحديث وكذلك ثغور اليمن على ساحل الزنج. وأما ثغور أهل ما وراء النهر في وجوه الترك والصّين فهم فريقان: إما شافعية وإما من أصحاب أبي حنيفة وكلهم يلعنون القدرية وأهل الأهواء. وقد قال الله تعالى: (وَالَّذِينَ جاهَدُوا فِينا لَنَهْدِيَنَّهُمْ سُبُلَنا) (1) والجهاد بالحجة والاستدلال من أهل السنة ظاهر على مخالفيهم من أهل الأهواء والجهاد مع الكفرة في الثغور منهم. وليس لأهل الأهواء ثغر، فصح أن أهل السنة هم المهتدون.\r__________________\r(1) سورة العنكبوت آية 69.\r\rالأصل الخامس عشر\r"]], "pg": [271, 271]}, "540.244": {"x": [[271, "من أصول هذا الكتاب\rفي بيان أحكام الكفر وأهل الأهواء والبدع\rيقع في هذا الأصل خمس عشرة مسألة [ويشتمل هذا الأصل على خمس عشرة مسألة كل واحدة منها كتاب يقوم بذاته وهذه ترجمتها:\rمسألة في حكم الكفرة الذين لا يؤخذ منهم الجزية.\rمسألة في حكم من يؤخذ منه الجزية.\rمسألة في حكم من لم يبلغه الدعوة.\rمسألة في حكم المرتدين.\rمسألة في حكم الغلاة من الباطنية.\rمسألة في حكم الغلاة من الروافض.\rمسألة في حكم الخوارج.\rمسألة في حكم الجهمية.\rمسألة في حكم النجّارية.\rمسألة في حكم المعتزلة القدرية."], [272, "مسألة في حكم المشبهة الجسمية.\rمسألة في حكم البكرية والضرارية.\rمسألة في مبايعة أهل الأهواء.\rمسألة في نكاحهم وذبائحهم ومواريثهم.\rمسألة في حكم دور أهل الأهواء. فهذه مسائل هذا الأصل وسنذكر في كل واحدة من هذه المسائل مقتضاها على التفصيل إن شاء الله تعالى.\r\rالمسألة الأولى من هذا الأصل\r"]], "pg": [271, 272]}, "540.245": {"x": [[272, "في حكم الكفرة الذين لا يؤخذ منهم الجزية\rاختلفوا في الفرق بين من يؤخذ منه الجزية وبين من لا يقبل منه: فقال أبو حنيفة: إنها مقبولة من كل من بذلها من الكفرة إلا مشركي العرب فإنها لا تقبل منهم.\rوقال الشافعي: إنّها لا تقبل إلا من أهل الكتاب وهم اليهود والنصارى والصابئون والسامرة. ولما وجد السلف مختلفين في المجوس جعلهم في الجزية كأهل الكتاب وفي النكاح والذبيحة كأهل الأوثان وجعل ديتهم خمس دية اليهود والنصارى ودية اليهود والنصراني ثلث دية المسلم عنده. وإذا صحت هذه المقدمة فالكفرة الذين لا تؤخذ منهم الجزية ويقتلون إن لم يسلموا ولم يكن لهم أمان خمسة عشر صنفا:\rأحدها السوفسطائية الذين قالوا لا علم ولا حقيقة لشيء وفيهم من قال لا أدري هل للأشياء حقائق أم لا حقائق لها. وفيهم من زعم أن حقائق الأشياء تابعة للاعتقادات وكل من اعتقد شيئا فهو على دين صحيح وما اعتقده على ما اعتقده دهريا كان أو موحّدا. وهؤلاء يلزمهم تصحيح قول نفاة الحقائق لأنهم قد اعتقدوا ذلك. ويقال لنفاة الحقائق منهم هل لنفي الحقائق حقيقة؟ فإن قالوا نعم، ناقضوا قولهم: لا حقيقة. وإن قالوا: لا، قيل إذا لم يكن لنفيها حقيقة فلإثباتها حقيقة."], [273, "والصنف الثاني منهم الدهرية الذين زعموا أن العالم قديم على صورته التي هي عليه في أرضه وهوائه وسمائه ونجومه وإنه لا إنسان إلا من نطفة ومن إنسان قبله لا إلى نهاية ولا سنبلة إلّا من حبّة وسنبلة قبلها. وفيهم من قال بهذا المذهب وزعم مع ذلك أن الأرض تهوي أبدا ولزمهم على هذا الأصل أن لا يلحق الحجر المطروح الأرض لأن الخفيف لا يلحق ما هو أثقل منه في انحداره إن لم يكن للأثقال وقفة.\rوالصنف الثالث منهم السّمنيّة وقولها في العالم كقول الدهرية وزادوا عليهم\r\rالقول بتكافؤ الأدلة وإبطال النظر والاستدلال وزعموا أنه لا يعلم شيء إلّا بالحواس الخمس.\rوالصنف الرابع منهم أصحاب الهيولى وقد زعم أكثرهم أن للعالم هيولى قديمة وأعراضها حادثة وزعم بعضهم أن لكل جنس من العالم هيولى مخصوصة [فهيولى الذهب غير هيولى الخشب].\rوالصنف الخامس منهم أصحاب الطبائع الذين قالوا بقدم العناصر الأربعة وهي الأرض والماء والنار والهواء وقالوا فيها أربع طبائع قديمة وهي الحرارة والبرودة والرطوبة واليبوسة وزعموا أن جميع أنواع النبات والجواهر والحيوانات مركب من هذه الأصول الأربعة وإنما اختلفت الصّور فيها لاختلاف المزاج في التركيب. وفيهم من ادّعى قدم الأفلاك معها وزعم أنها طبيعة خامسة غير قابلة للاستحالة والتغير. وفيهم من قال بقدم العالم والطبائع الأربع وقال مع ذلك بصانع قديم كما ذهب إليه ابن قيس وذهب عليه من جهله وجوب كون الفاعل سابقا لفعله."], [274, "والصنف السادس منهم أصناف من الفلاسفة قالوا بقدم العالم ونفي الصانع وصنف منهم قالوا بأن الصانع متصوّر بالعقل. وفيهم من قال العالم قديم وله علة قديمة وهذا قول أرسطاطاليس. والصنف السابع منهم: كفرة المنجمين فمنهم من قال بقدم الأفلاك والكواكب وزعم أن حركاتها هي الموجبة لوقوع الحوادث في العالم. ومنهم من قال بإلهية الشمس وعبدها. وعليه كان قوم بلقيس قبل الآية إسلامهم مع سليمان. وفيهم من عبد الشمس والقمر وقال لأحدهما سلطان الليل وللآخر سلطان النهار. ومنهم من عبد الكواكب السبعة وزعم أنها مدبّرات العالم. ومنهم من قال بقدم زحل وحده لأنه أعلى الكواكب السبعة بزعمه.\rوالصنف الثامن: منهم الذين عبدوا إنسانا محدودا واتخذوه إلها معبودا كالذين عبدوا جمشيد قبل الطوفان والذين عبدوا فرعون ونمروذ بن كنعان وزوج الهندي بعد الطوفان. والصنف التاسع: منهم قوم يعبدون رأسا مخصوصة من\r\rرءوس الناس ويكتمون دينهم إلّا ممن كان منهم ويأخذون إنسانا فيغمسونه في الزيت أياما فينخلع رأسه مع عروقه عن بدنه فيعبدون ذلك الرأس. وقيل إن قوما منهم بحران وآخرين بآذربيجان وأمرهم مكتوم عن العامة.\rوالصنف العاشر: منهم الذين عبدوا الملائكة وهم فريقان أحدهما قوم من الهند كانوا في زمان يوذاسف الهندي ثم نقلهم يوذاسف إلى عبادة الأصنام. والفريق الثاني منهم قوم من العرب في الجاهلية زعموا أن الملائكة بنات الله فعبدوها لتشفع لهم إلى الله وأنزل الله فيهم: (وَيَجْعَلُونَ لِلَّهِ الْبَناتِ سُبْحانَهُ وَلَهُمْ ما يَشْتَهُونَ) (1) وقال أيضا: (أَفَأَصْفاكُمْ رَبُّكُمْ بِالْبَنِينَ وَاتَّخَذَ مِنَ الْمَلائِكَةِ إِناثاً) (2) وقال أيضا: (إِنَّ الَّذِينَ لا يُؤْمِنُونَ بِالْآخِرَةِ لَيُسَمُّونَ الْمَلائِكَةَ تَسْمِيَةَ الْأُنْثى) (3)"], [275, "والصنف الحادي عشر: منهم الحلولية الذين عبدوا كل صورة حسنة بدعواهم أن الإله قد حلّ فيه، كما حكي عن أبي حلمان الدمشقي. وفيهم من قال إنّ روح الله قد حلّ في بعض [الصور] فاتخذوه إلها. ومن غلاة الروافض من زعم أن روح الله حلّ في الأنبياء ثم في الأئمة وفيهم من ادعى ذلك في بيان بن سمعان التميمي وفيهم من ادعاه في أبي الخطاب الأسدي وفيهم من قال بذلك في أبي مسلم صاحب دولة بني العباس ومن هذه الطائفة كان المقنع بما وراء النهر ثم ادعى في نفسه مثل هذه الدعوى وزعم أن روح الإله انتقل إليه من أبي مسلم.\rوالمبيضة الذين بما وراء النهر في جبال إيلاق على هذا المذهب وهم يستحلون الميتة وذوات المحارم وكل منهم يستمتع بامرأة صاحبه، ليس لهم في ذلك غيرة ولا حميّة.\rوالصنف الثاني عشر: منهم أهل التناسخ الذين زعموا أن الأرواح تنتقل في الأجساد ويكون ثوابها وعقابها في قوالب سوى القوالب التي أطاعت أو عصت\r__________________\r(1) [سورة النحل آية 57].\r(2) [سورة الإسراء آية 40].\r(3) [سورة النجم آية 27].\r\rفيها. وعلى هذا القول كان سقراط في زمان الفلاسفة وإليه صار من القدرية أحمد بن حائط وعلي بن بانوش وهما من تلامذة النظّام، فكل نوع من أنواع البدع والضلالة قد صار إليه قوم من القدرية.\rوالصنف الثالث عشر: منهم الخرمدينية الذين أباحوا كلّ ما يميل إليه الطبع من نكاح المحارم وغيرهم ومن الخمر والميت ومن كل ما فيه طيب ولذّة وأسقطوا وجوب الصلوات وسائر الفرائض وهذا دين المزدكية، اتباع مزدك الذي قتله أنو شروان وإلى هذا القول ذهبت المنصورية من الروافض اتباع عبد الله بن معاوية بن عبد الله بن جعفر منهم."], [276, "والصنف الرابع عشر: منهم الباطنية وقد كانوا في الأصل مجوسا وثنوية ثم أظهر دعاتهم كعبد الله بن ميمون القداح وحمدان بن قرمط تأويل شرائع الإسلام على وفق مذاهب المجوس في أيام المأمون ودعوا إلى صانعين سمّوهما الأوّل والثاني. وهذا معنى قول الثنوية بالنور والظلمة ومعنى قول المجوس بيزدان واهرمن وهم الآن شر أصناف الكفرة وأعظمهم على المسلمين بلاء.\rوالصنف الخامس عشر: منهم البراهمة الذين أقرّوا معنا بحدوث العالم وتوحيد صانعه وعدله وحكمته غير أنهم انكروا النبوّات والشرائع وأثبتوا تكليف المعرفة من جهة خواطر العقول وزعموا أن الله تعالى إنما كلّف العباد أن يعرفوه بعقولهم وأن يشكروه على نعمه عليهم وأن لا يظلم بعضهم بعضا وحرّموا ذبح البهائم وإيلامها بلا ذنب وقالوا إنّ إيلام الله تعالى لها في الدنيا لأجل عوض يوصله إليها في الآخرة. فهؤلاء أصناف الكفرة الذين لا يقبل منهم الجزية ولا يحلّ ذبائحهم ولا نكاح نسائهم وينظر فيهم فإن كان بعضهم في دار الإسلام استتيب فإن تاب وإلّا قتل وإن كان في دار منيعة فحكمه حكم أهل الحرب دون أهل الذمة وكذلك حكم الثنوية القائلة بقدم النور والظلمة من المانوية والديصانية والمرقونية وكذلك عبدة الأصنام المنحوتة والأوثان المصوغة ولا دية ولا قصاص ولا كفارة على من قتل واحدا منهم.\r\rالمسألة الثانية من هذا الأصل\r"]], "pg": [272, 276]}, "540.246": {"x": [[276, "في بيان حكم الذين تقبل منهم الجزية\rهؤلاء أصناف منهم الصابئة وهم فرق:"], [277, "إحداها فرقة من اليونانية قالت بحدوث العالم وإثبات صانعه وأنه لا يشبه شيئا وزعموا أن الصانع خلق الفلك حيّا ناطقا سميعا بصيرا مدبّرا للعالم وسمّوا الكواكب ملائكة. وفرقة منهم قالت بحدوث العالم وتوحيد الصانع ولم يصفوه بأوصاف الإثبات ووصفوه بنفي النقائص عنه فقالوا: لا نقول إنّه حيّ عالم قادر ولكن نقول: إنه ليس بميت ولا جاهل ولا عاجز. وزعم هؤلاء أن هرمس المنجم كان نبيا وقالوا بثلاث صلوات مفروضة في كل يوم منها ثماني ركعات في كل ركعة ثلاث سجدات قبل زوال الشمس ومثلها عند غروب الشمس. وأوجبوا الوضوء للصلاة وأوجبوا صيام ثلاثين يوما أولها لثمان مضين من أذار وذبحوا من ذوات الأربع الذكور من البقر والضأن والمعز ومن سائر ذوات الأربع غير الجزور ما ليس له أسنان في الشّدقين ومن الطير ما ليس له مخلب ولا يذبحون ما لا رئة له وحرّموا لحم الخنزير والكلب والحمار والجزور والحمام وما له مخلب وحرموا المسكر من الشراب وحرموا الاختتان وأوجبوا الغسل من الجنابة ومن مس الميت والحائض وأوجبوا مجانبة الأبرص والمجذوم وكل ذي عاهة تعدى وقالوا لا طلاق إلا بحكم حاكم أو بينة عن فاحشة ولا يرون رجعة ولا جمعا بين امرأتين. وفرقة منهم بناحية واسط العراق دينهم خلاف دين صابئة حران في أكل الخنزير وفي صلاتهم إلى القطب الشمالي والحرانية تصلي والقطب وراءها. وزعمت الواسطية أنهم على دين شيث بن آدم وإنّ صحفه معهم فهؤلاء أصناف الصابئة عند الجمهور. وزعمت اليزيدية من الخوارج أن الصائبة المذكورة في القرآن لم يوجدوا بعد وأنّ الله يبعث رسولا من العجم وينزل عليه كتابا من السماء جملة واحدة ويكون دينه دين الصابئة وينسخ بها شريعة محمد صلىلله عليه وسلم وهؤلاء عندنا أكفر من الصابئة الأصلية. والصنف الثاني من أهل الجزية: اليهود وهم اليوم فرق: عنانية وربانية وسامرة وشاذانية."], [278, "وهؤلاء الشاذانية فيهم كأهل الأهواء في المسلمين، وجمهورهم الأكبر ربانية وبين الفريقين منهم خلاف في إباحة الخمر. وتوراة السامرة منهم خلاف توراة الجمهور الأعظم منهم في مواضع كثيرة. وادعى الجمهور الأكبر منهم تسعة عشر نبيا بعد موسى عليه السلام وأقرّت السامرة بثلاثة منهم فحسب. وهم في النسخ على قولين منهم من يأباه عقلا ومنهم من يجيزه عقلا ويدعي تأبيد شرع موسى عليه السلام خبرا. وكلهم ينكرون نبوّة نبينا محمد صلىلله عليه وسلم إلا فرقة منهم يقال لها العيسوية فإنها أقرت بنبوّته وزعمت أنه كان مبعوثا إلى العرب دون بني إسرائيل. والصنف الثالث من أهل الجزية النصارى وهي كلها مشركة بالله تعالى ليس فيها موحّد غير أن منهم من زعم أن المسيح ابن الإله ومنهم من زعم أنه هو الإله وكلها يقول بثلاثة أقانيم جوهر واحد. وفيهم من زعم أن الاتحاد كظهور النقش في الطين والشمع. ومنهم من زعم أنه كظهور الشعاع على ما ظهر عليه. ومنهم من زعم أنه اتحاد على الحقيقة بأن صار الاثنان واحدا وكلهم من أهل الجزية. والصنف الرابع من أهل الجزية: المجوس وقد أشكل أمرهم. وقال بعض السلف إنّهم كانوا أهل كتاب فلما أحدثوا القول بصانعين أحدهما يخلق الخير والآخر يخلق الشرّ أسري (1) بكتابهم. وقال آخرون كانوا في الأصل ثنويّة من أصحاب النور والظلمة فانتقلوا إلى القول بيزدان وأهرمن واقرّوا بحدوث أهرمن ودانوا بعبادة النار ودعاهم إليها زرداشت في أيام كشتاسب وإسفنديار. فلما وقع الإشكال في أمرهم وروي عن عبد الرحمن بن عوف: أن النبي صلىلله عليه وسلم أخذ الجزية من مجوس هجر، جعلوا في الجزية كأهل الكتاب وفي النكاح والذبيحة كأهل الأوثان. واختلفوا في دياتهم:\rفقال أبو حنيفة: دية الواحد منهم كدية المسلم وأجاز قتل المسلم بالواحد من أهل الجزية.\rوقال الشافعي ومالك: لا يقتل المسلم بالذمي بحال."], [279, "واختلفا في ديته: فقال مالك دية اليهودي والنصراني نصف دية المسلم وقال\r__________________\r(1) [أي رفع].\r\rالشافعي ديتهما ثلث دية المسلم ودية المجوس خمس دية اليهودي والنصراني وهي مثل خمس ثلث دية المسلم.\rالمسألة الثالثة من هذا الأصل\r"]], "pg": [276, 279]}, "540.247": {"x": [[279, "في بيان حكم من لم يبلغه دعوة الإسلام\rإن كان وراء السدّ أو في طرف من أطراف الأرض ناس لم يبلغهم دعوة الإسلام نظر فيهم، فإن كانوا معتقدين لما دلّ عليه العقل من حدوث العالم وتوحيد صانعه وصفاته فهم كالمسلمين ويجب على من طرأ عليهم من المسلمين أن يدعوهم إلى أحكام شريعة الإسلام فإن امتنعوا من قبولها ولم يكونوا على شرع من شرائع أهل الكتاب صاروا حينئذ كالوثنية الذين لا يقبل منهم الجزية وإن كانوا أهل كتاب من اليهود والنصارى أو الصابئين ولم يكن دعوة الإسلام بالغة إليهم وامتنعوا من قبولها بعد أن بلغتهم صاروا من أهل الجزية كاليهود والنصارى ولا يجوز قتل أحد منهم قبل دعوته إلى الإسلام وإقامة الحجة عليه. فإن قتل المسلم واحدا منهم قبل ذلك فقد اختلفوا فيه: فقال أبو حنيفة: لا دية عليه وقال الشافعي: بوجوب ديته. واختلف أصحابه في مقداره: فمنهم من قال: كدية المسلم ومنهم من قال: كدية أهل دينه فإن لم يكن على شيء من الأديان فكدية المجوس.\rالمسألة الرابعة من هذا الأصل\r"]], "pg": [279, 279]}, "540.248": {"x": [[279, "في بيان حكم المرتدين\rأجمعوا على أن الرجل المرتد يستتاب فإن تاب وإلّا قتل ولا يقبل منه الجزية. واختلفوا في المرأة المرتدة:\rفقال الشافعي: إن تابت وإلّا قتلت كالرجل ولا تسترق بحال.\rوقال أبو حنيفة: لا تقتل فإن لحقت بدار الحرب جاز استرقاقها بعد السبي.\rوفي أولاد المرتدين إذا لحقوا بدار الحرب خلاف بين الفقهاء: فقال أبو"], [280, "حنيفة يجوز استرقاقهم. واختلف فيهم أصحاب الشافعي: فمنهم من أباه ومنهم من أجاز ذلك واستدل بأن عليّا رضي الله عنه استولد خولة الحنفية وكانت من سبي بني حنيفة بعد ارتدادهم. وأجمعوا على أنه لا يحل ذبيحة المرتد ولا نكاحه ولا دية ولا قصاص على قاتله. واختلفوا في الزوجين إذا ارتدّا معا: فأبقاهما أبو حنيفة على النكاح. وقال الشافعي إن كانت ردتهما قبل الدخول بها انفسخ النكاح كما لو ارتد أحدهما. وإن كانت بعد الدخول يوقف النكاح على العدة، فإن انقضت عدتها قبل رجوعهما إلى الإسلام انفسخ النكاح. وإن أسلما قبل انقضاء العدة بقيا على النكاح الأول. واختلفوا أيضا في قضاء الصلوات والصوم المتروكين في حال الردة: فقال الشافعي بوجوب قضائها، وقال أبو حنيفة: لا قضاء عليه في ذلك وأوجب عليه قضاء الحج الذي كان أتى به قبل ردته وقال الشافعي لا يقتضي ذلك. وأجمعوا على أن ارتداد الصبي غير صحيح واختلفوا في إسلامه: فصحّحه أبو حنيفة حتى إن رجع عنه بعد بلوغه صار مرتدا. وقال الشافعي إن أظهر الصبي الإسلام فرّق بينه وبين أبويه الكافرين لئلا يفتناه عن دين الإسلام وأخذا بالاتفاق عليه. فإذا بلغ وثبت على الإسلام فالحمد لله على ذلك وإن رجع إلى دين أبويه كان من أهل الجزية ولم يكن في حكم المرتدين.\rالمسألة الخامسة من هذا الأصل\r"]], "pg": [279, 280]}, "540.249": {"x": [[280, "في حكم الباطنية"], [281, "إن الباطنية خارجة عن فرق الأهواء وداخلة في فرق الكفر الصريح لأنها لم تتمسك بشيء من أحكام الإسلام [لا] في أصوله ولا في فروعه [وإنما هم] دعاة المجوس بالتمويه إلى دين الثنوية. وسبب ذلك أن المجوس في زمان المأمون تشاوروا في استدراك ملكهم فعلموا عجزهم عن قهر المسلمين فدبّروا في تأويل أركان الشريعة على وجوه تؤدي إلى رفعها وانتدب لذلك حمدان بن قرمط زعيم القرامطة وعبد الله بن ميمون القداح جد زعيم الباطنية بمصر. وخالفا مع أتباعهما المسلمين في التوحيد والنبوات وفي تأويل الآثار والآيات. فقالوا في التوحيد: إنّ"], [282, "الإله هو الأول الذي خلق شيئا ثانيا فهو مع الثاني مدبّران للعالم وهذا بعينه قول المجوس: إنّ الإله خلق الشيطان ثم إنّه مع الشيطان مدبران للعالم فهو مدبر الخيرات والشيطان مدبر الشرور. وقالوا في النبوات برفع المعجزات الناقضات للعادات وأنكروا نزول الملائكة من السماء. وقالوا (1) الملائكة على دعاتهم إلى بدعتهم وزعموا أن كبراءهم هم المسمّون بجبرائيل وميكائيل وإسرافيل. وتأولوا الشياطين على مخالفيهم وزعموا أن علماء مخالفيهم هم الأبالسة. وقالوا إن الأنبياء ساسة احتالوا للزعامة على العامة بالنواميس وكل واحد منهم صاحب دور، إذا مضى من دوره سبعة انقضى دوره واستؤنف بغير أمره وقالوا في تأويل الصلاة إنّها الثناء على الإمام والزكاة دفع الخمس إليه والصوم الإمساك عن إفشاء أسرارهم عند مخالفيهم والزنا إفشاء أسرارهم بغير عهد. وأسقطوا العبادات [والحدود] وأباحوا الخمر ونكاح ذوات المحارم وهذا هو التمجّس بعينه. واختلف أصحابنا في حكمهم: فمنهم من قال هم مجوس وأجاز أخذ الجزية منهم وحرم ذبائحهم ونكاحهم. ومنهم من قال حكمهم حكم المرتدين، إن تابوا وإلّا قتلوا. وهذا هو الصحيح عندنا. وقال مالك في الباطني والزنديق إن جاءا تائبين ابتداء قبلنا التوبة منهما وإن أظهرا التوبة بعد العثور عليهما لم يقبل التوبة منهما. وهذا هو الأحوط فيهم.\rالمسألة السادسة من هذا الأصل\r"]], "pg": [280, 282]}, "540.250": {"x": [[282, "في حكم الغلاة من الروافض\rهؤلاء فرق: إحداها البيانية الذين ادعوا (2) أن الله على صورة إنسان وأنه يفنى كله إلّا وجهه. وزعموا أن بيان بن سمعان تحوّل إليه روح الإله فصار إلها.\rوالفرقة الثانية منهم المغيرية الذين زعموا أن الله له أعضاء على صور حروف الهجاء وشبّهوا الهاء بالفرج وزعموا أن الله تعالى خلق الشمس والقمر من عيني\r__________________\r(1) [وتأولوا].\r(2) [زعموا].\r\rظله. وفيهم من ادعى حلول روح الإله في زعيمهم المغيرة بن سعيد العجلي."], [283, "والفرقة الثالثة أتباع عبد الله بن معاوية بن عبد الله بن جعفر زعموا أن زعيمهم عبد الله حلّ فيه تلك الروح وإنه أباح لهم المحرمات وأسقط عنهم العبادات.\rوالفرقة الرابعة منهم المنصورية زعموا أن زعيمهم أبا منصور العجلي عرج به إلى السماء وأن الله سبحانه مسح بيده على رأسه فقال يا بني بلّغ عني وأنزله بعد ذلك إلى الأرض فهو الكسف الساقط من السماء واستحلّ هؤلاء خنق مخالفيهم.\rوالفرقة الخامسة منهم الخطابية أتباع أبي الخطاب الأسدي الذين زعموا أن جعفرا الصادق إله على قول الحلولية ثم ادعى إلهية نفسه ورأى شهادة الزور لموافقيه على مخالفيه.\rوالفرقة السادسة منهم أتباع المقنع الذي ادعى أن روح الإله حل فيه بعد أبي مسلم صاحب دعوة بني العباس.\rوالفرقة السابعة منهم السبائية أتباع ابن سبأ الذي ادعى إلهية علي رضي الله عنه في حياته وزعم أنه في السحاب وأن الرعد صوته والبرق سوطه. ومنهم فرقة يقال لها الكاملية أكفروا الصحابة بتركهم بيعة عليّ وأكفروا عليّا بتركه قتالهم فهؤلاء كلهم مرتدون عن الدين وحكمهم حكم أهل الردة.\rالمسألة السابعة من هذا الأصل\r"]], "pg": [282, 283]}, "540.251": {"x": [[283, "في بيان حكم الخوارج والشراة\rإن الحكمة الأولى من الخوارج قالوا بتكفير علي وعثمان وطلحة والزبير وعائشة وأصحاب الجمل وبتكفير معاوية والحكمين وتكفير أصحاب الذنوب من هذه الأمة وما زادوا [وما زاد] على ذلك حتى ظهرت الأزارقة منهم، فزعموا أن مخالفيهم مشركون وكذلك أهل الكبائر من مرافقيهم واستحلوا قتل النساء والأطفال من مخالفيهم وزعموا أنهم مخلّدون في النار وكفروا القعدة منهم عن الهجرة"], [284, "إليهم. وزعم النجدات منهم أن مخالفيهم كفرة غير مشركين وعذروا بالجهالة في الفروع وأسقطوا حدّ الخمر. وقالت الميمونية من الخوارج بالقدر على مذاهب المعتزلة فصاروا خوارج قدرية. وفي أمثالهم ضرب المثل فقيل: مع كفره قدريّ. وأباحت الميمونية نكاح بنات البنات دون بنات الصلب وأنكروا سورة يوسف. وزعمت اليزيدية منهم أن الله سيبعث رسولا من العجم وينزل عليه كتابا من السماء ويكون ملّته الصابئة [المذكورة] في القرآن وينسخ بشريعته شريعة محمد صلىلله عليه وسلم فهذه الفرقة منهم مع الميمونية في إعداد المرتدين. وسائر أصنافهم كفرة في السر، لكن لا يتعرض لهم ما لم يتعرضوا للمسلمين، فإن قاتلونا قاتلناهم لما روي أن عليا رضي الله عنه سمع واحدا منهم يقول: لا حكم إلّا لله، فقال كلمة حق أريد بها باطل، ثم قال: لكم علينا ثلاث: لا نبدؤكم بقتال ولا نمنعكم من الفيء ما دامت أيديكم مع أيدينا ولا نمنعكم مساجد الله أن تذكروا فيها اسم الله.\rالمسألة الثامنة من هذا الأصل\r"]], "pg": [283, 284]}, "540.252": {"x": [[284, "في حكم الجهمية\rهؤلاء أتباع جهم بن صفوان الذي قال بالجبر وزعم: أن العباد مضطرّون إلى أنواع تصرفهم كما يضطرّ الريح إلى حركتها. ولم يثبتوا للعبد كسبا ولا استطاعة. وهذا القول وإن كان فاسدا فإنه لا يوجب عندنا تكفيرا لأنه خلاف في وصف العبد. وإنما يكفر الجهمية في شيئين: أحدهما قولهم بأن الجنة والنار تفنيان. والثاني قولهم بحدوث علم الله تعالى، لأن هذا يوجب أن لا يكون عالما قبل حدوث علمه. ولأجل هذه البدعة قتل جهم بن صفوان بمرو قتله مسلم بن أحرز المازني مازن تميم في آخر زمان بني أميّة.\rالمسألة التاسعة من هذا الأصل\r"]], "pg": [284, 284]}, "540.253": {"x": [[284, "في حكم النجارية\rهؤلاء أتباع الحسين بن محمد النجار وهم اليوم زهاء عشر فرق بالري كل"], [285, "فرقة منها تكفّر سائرها ويجمعها القول بحدوث كلام الله تعالى ونفي صفاته الأزلية وإحالة رؤيته فهم في هذه الأصول الثلاثة كالقدرية. وانفرد النجار بأن قال إنّ كلام الله جسم إذا كتب وعرض إذا قرئ. وزعم النجّار وضرار أن الجسم أعراض مجتمعة. والزعفرانية منهم بالري يقولون: القرآن غير الله وكل ما هو غير الله مخلوق، ثم يقولون مع ذلك إنّ الكلب خير ممن يقول: إنّ القرآن مخلوق. والمستدركة منهم بالري يقولون: القرآن مخلوق. وهم في ذلك فرقتان: فرقة منهم يزعمون أن النبي صلىلله عليه وسلم قد قال إنّ القرآن مخلوق بهذه اللفظة على ترتيب حروفها. ومن لم يقل إنّ النبي صلىلله عليه وسلم قال ذلك بترتيب حروفه فهو كافر. وفرقة منهم قالوا إنّ النبي صلىلله عليه وسلم لم يقل ذلك بحروفه ولكنه دل عليه بدلائل من استدل بها علم أن القرآن مخلوق، ومن قال إنّ النبي صلىلله عليه وسلم قال ذلك فهو كافر. فهذه أصولها التي نكفّرهم فيها، فأما قولهم في خلق أفعال العباد وفي أن الاستطاعة مع الفعل وفي أنه لا يكون إلّا ما أراد الله تعالى وفي باب الوعد والوعيد فكقول أهل السنة سواء.\rالمسألة العاشرة من هذا الأصل\r"]], "pg": [284, 285]}, "540.254": {"x": [[285, "في حكم المعتزلة القدرية"], [286, "اعلم إنّ تكفير كل زعيم من زعماء المعتزلة واجب من وجوه: أما واصل بن عطاء فلأنه كفر في باب القدر بإثبات خالقين لأعمالهم سوى الله تعالى وأحدث القول بالمنزلة بين المنزلتين في الفاسق، ولهذه البدعة طرده الحسن البصري عن مجلسه. ثم إنّه شك في شهادة عليّ وعدالته وأجاز أن يكون هو وأصحابه الفسقة وأجاز أن يكون الفسقة أصحاب الجمل فشك في الفرقتين: ولذلك قال: لو شهد عليّ وطلحة عندي على باقة بقل لم أحكم بشهادتهما. وزاد عليه عمرو بن عبيد حيث ردّ شهادة عليّ مع واحد من أصحابه كأنه حكم بفسقه ومن قال بفسق علي فهو الكافر الفاسق دونه. وأما زعيمهم أبو الهذيل فإنه قال بفناء مقدورات الله تعالى حتى لا يكون بعدها قادرا على شيء. وأما زعيمهم النظّام فهو الذي نفى نهاية"], [287, "الجزء (1) وأبطل بذلك إحصاء الباري تعالى لأجزاء العالم وعلمه بكمّية أجزائه. وزعم أن الإنسان هو الروح وأن أحدا ما رأى إنسانا قط وإنما رأى قالبه وزعم أن الأعراض كلها حركات وأنّها جنس واحد وأنّ الإيمان من جنس الكفر وأنّ فعل النبي صلىلله عليه وسلم من جنس فعل إبليس وقال بالطفرة وادعى حشر الكلاب والخنازير وسائر السباع الهمج إلى الجنة وأنكر وقوع الطلاق بالكنايات وإن قارنتها نية الطلاق. وزعم المعروف منهم بمعمّر أن الله تعالى ما خلق لونا ولا طعما ولا رائحة ولا حرارة ولا برودة ولا رطوبة ولا يبوسة ولا حياة ولا موتا ولا صحة ولا سقما ولا قدرة ولا عجزا ولا ألما ولا لذة ولا شيئا من الأعراض وإنما خلق الأجسام فقط وخلقت الأجسام الأعراض في أنفسها وزعم أن الإنسان غير هذا الجسد وأنّه عالم حكيم مدبر للجسم (2) وليس بمتحرك ولا ساكن ولا ذي لون ووزن ولا حالا في الجسد ولا متمكنا فيه ولكنه مدبر له. فوصف الإنسان بما يصف به ربه عزوجل وقال مع ذلك بإثبات أعراض لا نهاية لها وأنّ كل عرض يحل محله لمعنى سواه لا إلى نهاية. وزعم المعروف منهم ببشر بن المعتمر أن الإنسان قد يخلق الألوان والطعوم والروائح والرؤية والسمع والبصر وسائر الإدراكات على سبيل التولد. وزعم الجاحظ منهم أن لا فعل للإنسان إلّا إرادة وأنّ المعارف كلها ضرورية ومن لم يضطر إلى معرفة الله لم يكن مكلّفا ولا مستحقا للعقاب. وزعم أيضا أن الله لا يدخل أحدا النار وإنما النار تجذب أهلها إلى نفسها وتمسكهم فيها على التأبيد بطبعها. وزعم ثمامة أن المعارف ضرورية وأن عامة الدهرية وسائر الكفرة يصيرون في الآخرة ترابا لا يعاقب واحد منهم. وحرّم السبي واستفراش (3) الإماء وقال بأن الأفعال المتولدة لا فاعل لها. وزعم البغداديون منهم أن الله لا يرى شيئا ولا يسمع شيئا إلا على معنى العلم بالمسموع والمرئي. وزعم الجبّائي منهم أن الله مطيع عباده\r__________________"], [288, "(1) [الجسم].\r(2) [الجسد].\r(3) [استرقاق].\r\rإذا فعل مرادهم. وقال ابنه أبو هاشم باستحقاق العقاب والذم لا على ذنب وقال أيضا بأحوال لله تعالى لا موجودة ولا معدومة ولا معلومة ولا مجهولة وأنواع كفرهم لا يحصيها إلّا الله تعالى. وقد اختلف أصحابنا فيهم: فمنهم من قال حكمهم حكم المجوس لقول النبي صلىلله عليه وسلم: القدرية مجوس هذه الأمة. ومنهم من قال حكمهم حكم المرتدين كما نبينه بعد هذا إن شاء الله تعالى.\rالمسألة الحادية عشرة من هذا الأصل\r"]], "pg": [285, 288]}, "540.255": {"x": [[288, "في حكم المجسمة والمشبهة\rكل من شبّه ربه بصورة الإنسان من البيانية والمغيرية والجواربية المنسوبة إلى داود الجواربي والهشامية المنسوبة إلى هشام بن سالم الجواليقي فإنما يعبد إنسانا مثله ويكون حكمه في الذبيحة والنكاح كحكم عبدة الأوثان فيها. وكذلك من زعم أن بعض الناس إله وادعى حلول روح الإله فيه على مذهب الحلولية، كما قالته الخطابية في جعفر الصادق وكما قالته الرزامية في أبي مسلم صاحب دعوة بني العباس وكما قالته المبيضة في المقنع، فهو عابد وثن.\rوأما جسميّة خراسان من الكرّامية فتكفيرهم واجب لقولهم: بأن الله له حدّ ونهاية من جهة السفل ومنها يماسّ عرشه ولقولهم: بأن الله محل للحوادث وإنما يرى الشيء برؤية تحدث فيه ويدرك ما يسمعه بإدراك يحدث فيه ولو لا حدوث الإدراك فيه لم يكن مدركا لصوت ولا مدركا لمرئي وقد أفسدوا بإجازة حلول الحوادث في ذات الله تعالى لأنفسهم دلالة الموحّدين على حدوث الأجسام بحلول الحوادث. وإذا لم يصح على أصولهم حدوث العالم لم يكن لهم طريق إلى معرفة صانع العالم وصاروا جاهلين به وكيف يحكم بإيمانهم وهم يقولون إنه ليس في قلب أحد منهم إيمان. وكيف يكون مؤمنا من يقول إنّ إيمانه كإيمان المنافقين الكفرة باعتقاد الكفر. وسائر فرق الأمة يكفّرونهم وهم يرون جميع فرق الأمة من أهل الجنة ويزعمون أن أهل الأهواء بعد العقاب يصيرون إلى الجنة ولا"], [289, "يدوم عقابهم وجميع مخالفيهم على أنهم من أهل النار فصاروا عن هذه الجهة شرّ الفرق عند الأمة.\rالمسألة الثانية عشرة من هذا الأصل\r"]], "pg": [288, 289]}, "540.256": {"x": [[289, "في بيان حكم البكرية والضرارية\rأما البكرية فأتباع بكر ابن أخت عبد الواحد بن زيد وكان يوافق النظّام في أن الإنسان غير الجسد ووافق أصحابنا في إبطال القول بالتولد وانفرد بأشياء، أكفرته الأمة فيها، منها قوله: إنّ الله يرى في القيامة في صورة يخلقها وإنه يكلم عباده في تلك الصورة. ومنها قوله في الكبائر: إنها نفاق وإن صاحب الكبيرة من أهل القبلة منافق وعابد للشيطان وإنه مع كونه منافقا مكذب لله تعالى جاحد له وإنه في الدرك الأسفل من النار مخلد فيها وهو مع ذلك مسلم مؤمن. ثم إنّه طرد قوله في هذه البدعة بأن قال في علي وطلحة والزبير: إنّ ذنوبهم كانت كفرا وشركا غير أنهم مغفور لهم لورود الخبر بأن الله تعالى أطلع على أهل بدر فقال: اعملوا ما شئتم فقد غفرت لكم. ومنها قوله في الأطفال: إنهم لا يألمون في المهد وإن قطعوا وأحرقوا ولعلهم يكونون عند ضربهم متلذّذين وإن صاحوا وقال: لو لحقهم الألم بلا جرم منهم لكان ذلك ظلما من الله تعالى. ومنها قوله بتحريم أكل الثوم والبصل ووجوب الوضوء من قرقرة البطن وهذه بدع قد أكفرتها الأمة فيها. وأما الضرارية فأتباع ضرار ابن عمرو وقد وافق أصحابنا في أن أفعال العباد مخلوقة لله تعالى وفي إبطال القول بالتولد. ووافق المعتزلة في أن الاستطاعة قبل الفعل وزاد عليهم القول بأنها مع الفعل أيضا وإنها بعض المستطيع ووافق النجّار في أن الجسم أعراض مجتمعة من لون وطعم ورائحة وحرارة أو ضدها ونحو ذلك من الأعراض التي لا يخلو منها الجسم."], [290, "وانفرد بأشياء منها قوله: إنّ الله يرى بحاسة [زائدة] يرى بها المؤمنون ماهية الإله ووصف الله بالماهية كما قال أبو حنيفة وحفص الفرد ومنها أنه أنكر حرف أبيّ بن كعب وحرف ابن مسعود في القرآن [وقال] إنّ الله لم ينزلهما ونسب هذين الإمامين إلى الضلال في مصحفيهما. ومنها أنه شك في جميع عامة المسلمين وقال لا أدري لعل سرائر العامة كلها كفر وشرك. وأكفرته\r\rالأمة فيما انفرد به وأكفره أصحابنا في نفيه عن الله تعالى صفاته الأزلية ودعواه أنّ معنى وصف الله تعالى بأنه حيّ قادر عالم، هو أنه ليس بميت ولا عاجز ولا جاهل. وهذا يوجب عليه أن يكون العرض حيّا عالما قادرا لأنه ليس بميت ولا عاجز ولا جاهل. فهذا قول ضرار بن عمرو وليس هو ضرار بن صرد المعروف بأبي نعيم القرضي المعدود خلافه في الفقه والأصول فاعلم ذلك.\rالمسألة الثالثة عشرة من هذا الأصل\r"]], "pg": [289, 290]}, "540.257": {"x": [[290, "في مبايعة أهل الأهواء\rأجاز أصحابنا مبايعة أهل الأهواء في البياعات وكذلك أجازوا سائر عقود المعاوضة معهم لأنّا وإن أوجبنا قتلهم بعد امتناعهم من التوبة فإنما نوجب ذلك على السلطان وليس للرعية إقامة الحد على المرتد. وإنما اختلف الفقهاء في إقامة السيد حدّ الزنا وشرب الخمر على مملوكه: فأجازه الشافعي وأباه أبو حنيفة. على أن أهل الأهواء في هذا كأهل الحرب ويجوز للمسلم مبايعة أهل الحرب وكذلك القول في أهل الأهواء.\rالمسألة الرابعة عشرة من هذا الأصل\r"]], "pg": [290, 290]}, "540.258": {"x": [[290, "في أنكحة أهل الأهواء وذبائحهم ومواريثهم"], [291, "أجمع أصحابنا على أنه لا يحلّ أكل ذبائحهم وكيف نبيح ذبائح من لا يستبيح ذبائحنا. وأكثر المعتزلة مع الأزارقة من الخوارج يحرّمون ذبائحنا وقولنا فيهم أشدّ من قولهم فينا. ولا يجوز عندنا تزويج المرأة المسلمة من واحد منهم فإن عقد العقد فالنكاح مفسوخ. وإن لم تعلم المرأة ببدعة زوجها حتى وطئها فعليها العدة ولها مهر المثل بالوطء دون المهر المسمى. والمرأة منهم إن اعتقدت اعتقادهم حرم نكاحها وإن لم نعتقد اعتقادهم لم يحرم نكاحها لأنها مسلمة بحكم دار الإسلام. وقد شاهدنا قوما من عوامّ الكرّامية لا يعرفون من الجسم إلا اسمه ولا يعرفون أن خواصّهم يقولون بحدوث الحوادث في ذات الباري تعالى فهؤلاء يحل"], [292, "نكاحهم وذبائحهم والصلاة عليهم. وأجمع أصحابنا على أن أهل الأهواء لا يرثون من أهل السنة. واختلفوا في ميراث السنّيّ منهم: فمنهم من قطع التوارث من الطرفين وبه قال الحارث المحاسبي ولذلك لم يأخذ ميراث والده لأن والده كان قدريا. ومنهم من رأى توريث السني منهم وبناه على قول معاذ بن جبل: إنّ المسلم يرث من الكافر وإنّ الكافر لا يرث من المسلم. على قول أبي حنيفة: يرث السني من المبتدع الضال ما اكتسبه قبل بدعته، كما قال في المسلم: يرث من المرتد ما اكتسبه قبل ردته ويكون كسبه بعد الردة فيئا للمسلمين. وعلى قول الشافعي يكون مال الزنديق وكل كافر ببدعة فيئا فيه الخمس. وقال مالك إنّه فيء ولا خمس فيه. وأما قبول شهادة أهل الأهواء فقد اختلفوا فيه: فردّها مالك وأشار الشافعي وأبو حنيفة إلى قبولها، سوى الخطابية التي ترى شهادة الزور، ثم إنّ الشافعي وقف على كفر غلاة الروافض فأشار في كتاب القياس إلى رجوعه عن قبول شهادة أهل الأهواء. وأوجب أصحاب الشافعي ومالك وداود وأحمد بن حنبل وإسحاق بن راهويه إعادة صلاة من صلى خلف القدري والخوارج [والخارجي] والرافضي وكلّ مبتدع تنافي بدعته التوحيد. وروى هشام بن عبيد الله عن محمد بن الحسن: أن من صلى خلف من يقول بخلق القرآن يعيد الصلاة. وقال أبو يوسف القاضي في المعتزلة إنّهم زنادقة. وكل من لا يجوز الصلاة خلفه لا يجوز الصلاة عليه إذا مات. وهذه جملة كافية في هذا الباب.\rالمسألة الخامسة عشرة من هذا الأصل\r"]], "pg": [290, 292]}, "540.259": {"x": [[292, "في حكم دور أهل الأهواء"], [293, "كل دار غلب عليها بعض الفرق الضالّة ينظر فيها فإن كان أهل السنة فيها ظاهرين يظهرون السنة بلا خفير ولا جوار من مجير ولا خوف على النفس والمال فهي دار إسلام. واللقيط فيها حر مسلم لا يسترق ويجب تعريف اللقطة فيها. وإن لم يقدر أهل السنة على إظهار الحق إلّا بجوار أو مال يبذلونه فهي دار حرب وكفر. واللقيط فيها كاللقيط في دار الحرب وما يوجد فيها فهو فيء يخمس. واختلف\r\rأصحابنا في حكم أهل هذه الدار: فمنهم من حرم ذبائحهم ونكاح نسائهم وأجاز وضع الجزية عليهم وأجراهم في هذا مجرى المجوس وهذا اختيار الأستاذ أبي إسحاق إبراهيم بن محمد الأسفرائني. ومنهم من جعلهم مرتدين ولم يقبل منهم الجزية [ولم يجز استرقاقهم وبهذا نقول وعلى هذا القول يكون في استرقاق أولادهم خلاف]. وفي استرقاق أولادهم خلاف بين أصحابنا وقد أجاز أبو إسحاق المروزي استرقاق أولاد المرتدين وبه قال أبو حنيفة ومنع من ذلك بعض أصحابنا. وأما الشاك في كفر أهل الأهواء فإن شكّ في أن قولهم هل هو فاسد؟ أم لا فهو كافر. وإن علم أن قولهم بدعة وضلال وشكّ في كونه كفرا فبين أصحابنا في تكفير هذا الشاكّ خلاف وقد قال أكثر المعتزلة بتكفير الشاك في كفر مخالفيهم ونحن بتكفير الشاك في كفرهم أولى. والحمد لله على عصمته إيانا من بدع أهل الأهواء بفضله ورحمته وصلّى الله على محمد وآله أجمعين الطيبين الطاهرين."]], "pg": [292, 293]}}, "units": {"1": {"tit": "أصول الإيمان للتميمي (429)", "lvl": 1, "pg": [1, 293]}}};
